const SAVE_FILE_VERSION: SaveFileVersion = SaveFileVersion::new(1, 0, 0);
const MOUSE_DRAG_THRESHOLD: f32 = 6.0;
/// C4Menu::DoDragging starts a menu-element drag at `>= C4MC_DragSensitivity`,
/// unlike world-origin mouse drags, which use `> C4MC_DragSensitivity`.
const MENU_DRAG_THRESHOLD: f32 = 5.0;
/// The SDL/X11 application paths synthesize LeftDouble when the second press
/// arrives less than 400 ms after the first (C4FullScreen.cpp:327-350;
/// C4Viewport.cpp:657-676).
const CPP_DOUBLE_CLICK_INTERVAL: Duration = Duration::from_millis(400);

fn classic_press_is_double_click(last_click: &mut Option<Instant>, now: Instant) -> bool {
    if last_click.is_some_and(|last| {
        now.saturating_duration_since(last) < CPP_DOUBLE_CLICK_INTERVAL
    }) {
        *last_click = None;
        true
    } else {
        *last_click = Some(now);
        false
    }
}

static APP_PATH_CACHE: Mutex<Option<std::result::Result<Arc<AppPaths>, PathsError>>> =
    Mutex::new(None);

fn sprite_map_key(definition_id: &str, graphics_name: Option<&str>) -> String {
    match graphics_name {
        Some(name) if !name.is_empty() => {
            format!("{}::{}", definition_id, name.to_ascii_lowercase())
        }
        _ => definition_id.to_string(),
    }
}

fn particle_sprite_map(engine: &Engine) -> HashMap<String, ParticleRenderDefinition> {
    engine
        .particle_render_catalog()
        .iter()
        .filter_map(|definition| {
            let graphics = definition.graphics.as_ref()?;
            Some((
                definition.core.name.clone(),
                ParticleRenderDefinition {
                    image: ImageData::from_arc(
                        graphics.image.width(),
                        graphics.image.height(),
                        graphics.image.clone_pixels(),
                    ),
                    facet: ParticleFacet::new(
                        graphics.facet.x,
                        graphics.facet.y,
                        graphics.facet.width,
                        graphics.facet.height,
                    ),
                    length: definition.length,
                    aspect: definition.aspect,
                    core: definition.core.clone(),
                    draw_proc: definition.draw_proc,
                },
            ))
        })
        .collect()
}

