    fn startup_reference_query_row(
        &self,
        address: &str,
        state: &StartupDirectReferenceQueryState,
        query_resource: &str,
        query_fallback: &str,
    ) -> lc_frontend::startup_netdlg::NetDlgGameEntry {
        let query_name = startup_resource_string(
            self.app_paths.as_ref(),
            query_resource,
            query_fallback,
        );
        let title_template = startup_resource_string(
            self.app_paths.as_ref(),
            "IDS_NET_CLIENTONNET",
            "%s on %s",
        );
        let title = format_resource_string(title_template, &[&query_name, address.trim()]);
        let details = match state {
            StartupDirectReferenceQueryState::Pending => startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_INFOQUERY",
                "Querying game infos...",
            ),
            StartupDirectReferenceQueryState::Empty => startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_INFONOGAME",
                "No games found.",
            ),
            StartupDirectReferenceQueryState::Failed(error) => error.clone(),
        };
        lc_frontend::startup_netdlg::NetDlgGameEntry {
            title,
            details,
            address: Some(address.to_string()),
            joinable: true,
            extra_lines: Vec::new(),
            status_icons: Vec::new(),
            row_icon: match state {
                StartupDirectReferenceQueryState::Pending => {
                    lc_frontend::startup_netdlg::NetDlgRowIcon::Query
                }
                StartupDirectReferenceQueryState::Empty => {
                    lc_frontend::startup_netdlg::NetDlgRowIcon::QueryStatic
                }
                StartupDirectReferenceQueryState::Failed(_) => {
                    lc_frontend::startup_netdlg::NetDlgRowIcon::Error
                }
            },
        }
    }

    fn startup_masterserver_display_name(address: &str) -> String {
        let authority = address
            .trim()
            .split_once("://")
            .map_or(address.trim(), |(_, remainder)| remainder)
            .split(['/', '?', '#'])
            .next()
            .unwrap_or_default()
            .rsplit('@')
            .next()
            .unwrap_or_default();
        if let Some(ipv6) = authority.strip_prefix('[') {
            return ipv6
                .split_once(']')
                .map_or(ipv6, |(host, _)| host)
                .to_string();
        }
        authority
            .rsplit_once(':')
            .filter(|(_, port)| {
                !port.is_empty() && port.bytes().all(|byte| byte.is_ascii_digit())
            })
            .map_or(authority, |(host, _)| host)
            .to_string()
    }

    fn startup_masterserver_query_entry(
        paths: Option<&AppPaths>,
        address: &str,
    ) -> lc_frontend::startup_netdlg::NetDlgMasterserverEntry {
        let query_name = startup_resource_string(
            paths,
            "IDS_NET_QUERY_MASTERSRV",
            "Internet server",
        );
        let server_name = Self::startup_masterserver_display_name(address);
        lc_frontend::startup_netdlg::NetDlgMasterserverEntry {
            title: format_resource_string(
                startup_resource_string(paths, "IDS_NET_CLIENTONNET", "%s on %s"),
                &[&query_name, &server_name],
            ),
            details: startup_resource_string(
                paths,
                "IDS_NET_INFOQUERY",
                "Querying game infos...",
            ),
            extra_lines: Vec::new(),
            row_icon: lc_frontend::startup_netdlg::NetDlgRowIcon::Query,
        }
    }

    fn startup_masterserver_reply_entry(
        paths: Option<&AppPaths>,
        address: &str,
        reply: &lc_network::MasterserverReplyInfo,
    ) -> lc_frontend::startup_netdlg::NetDlgMasterserverEntry {
        use lc_frontend::startup_netdlg::{NetDlgRowIcon, NetDlgTextLine};

        let mut entry = Self::startup_masterserver_query_entry(paths, address);
        let game_count = reply.game_count.to_string();
        let player_count = reply.player_count.to_string();
        entry.details = if reply.game_count == 0 {
            startup_resource_string(paths, "IDS_NET_INFONOGAME", "No games found.")
        } else {
            format_resource_string(
                startup_resource_string(paths, "IDS_NET_INFOGAMES", "%d game(s) found."),
                &[&game_count, &player_count],
            )
        };
        entry.extra_lines.clear();
        if !reply.motd.is_empty() {
            entry.extra_lines.push(NetDlgTextLine::Plain(
                format_resource_string(
                    startup_resource_string(
                        paths,
                        "IDS_NET_MOTD",
                        "Message of the day: %s",
                    ),
                    &[&reply.motd],
                ),
            ));
        }
        if !reply.motd_url.is_empty() {
            entry.extra_lines.push(NetDlgTextLine::Hyperlink {
                label: reply.motd_url.clone(),
                url: reply.motd_url.clone(),
            });
        }
        entry.row_icon = NetDlgRowIcon::QueryStatic;
        entry
    }

    fn reset_startup_masterserver_entry(&mut self) {
        let settings = load_network_search_settings(self.app_paths.as_ref());
        let entry = Self::startup_masterserver_query_entry(
            self.app_paths.as_ref(),
            &settings.master_server_url,
        );
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.set_masterserver_entry(entry);
        }
    }

    fn set_startup_masterserver_error(&mut self, message: String) {
        self.startup_masterserver_next_query_at =
            Instant::now().checked_add(lc_network::GAME_SEARCH_INTERVAL);
        let settings = load_network_search_settings(self.app_paths.as_ref());
        let mut entry = Self::startup_masterserver_query_entry(
            self.app_paths.as_ref(),
            &settings.master_server_url,
        );
        entry.details = message;
        entry.row_icon = lc_frontend::startup_netdlg::NetDlgRowIcon::Error;
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.set_masterserver_entry(entry);
        }
    }

    fn apply_startup_masterserver_reply(
        &mut self,
        reply: lc_network::MasterserverReplyInfo,
    ) -> Result<(), EngineError> {
        self.startup_masterserver_next_query_at =
            Instant::now().checked_add(lc_network::GAME_SEARCH_INTERVAL);
        let settings = load_network_search_settings(self.app_paths.as_ref());
        let entry = Self::startup_masterserver_reply_entry(
            self.app_paths.as_ref(),
            &settings.master_server_url,
            &reply,
        );
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.set_masterserver_entry(entry);
        }

        if self.startup_network_dialog.is_none()
            || self.startup_network_ignore_redirect
            || reply.league_server_redirect.trim().is_empty()
            || self.message_dialogs.iter().any(|dialog| {
                matches!(
                    &dialog.continuation,
                    MessageDialogContinuation::NetworkServerRedirect { .. }
                )
            })
        {
            return Ok(());
        }
        let Some(paths) = self.app_paths.as_ref() else {
            return Ok(());
        };
        let config = load_native_config_bytes(Some(paths));
        let use_alternate_server = native_config_text(&config, "Network", "UseAlternateServer")
            .as_deref()
            .map(parse_config_bool)
            .unwrap_or(false);
        let server_address = native_config_text(&config, "Network", "ServerAddress")
            .map(|address| address.trim().to_string())
            .filter(|address| !address.is_empty())
            .unwrap_or_else(|| OFFICIAL_LEAGUE_SERVER.to_string());
        let alternate_server_address =
            native_config_text(&config, "Network", "AlternateServerAddress")
                .map(|address| address.trim().to_string())
                .filter(|address| !address.is_empty())
                .unwrap_or_else(|| OFFICIAL_LEAGUE_SERVER.to_string());
        let redirect = reply.league_server_redirect.trim().to_string();
        if redirect == server_address
            || (use_alternate_server && server_address != alternate_server_address)
        {
            return Ok(());
        }

        let message = format_resource_string(
            startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_SERVERREDIRECTMSG",
                "The configured server is no longer active and offers the following server redirection:||%s||Do you want to switch to the new server?",
            ),
            &[&redirect],
        );
        let caption = startup_resource_string(
            self.app_paths.as_ref(),
            "IDS_NET_SERVERREDIRECT",
            "Server Redirection",
        );
        self.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::new(
                message,
                caption,
                lc_frontend::message_dialog::MessageDialogButtons::YES_NO,
                lc_frontend::message_dialog::MessageDialogIcon::Standard(44),
                lc_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::NetworkServerRedirect { address: redirect },
        )
    }

    fn sync_startup_network_game_rows(&mut self) {
        let use_alternate_server =
            load_network_search_settings(self.app_paths.as_ref()).use_alternate_server;
        let mut games = self
            .startup_game_references
            .iter()
            .map(|reference| {
                Self::startup_network_reference_row_with_config(
                    self.app_paths.as_ref(),
                    use_alternate_server,
                    reference,
                )
            })
            .collect::<Vec<_>>();
        games.extend(
            self.startup_discovery_reference_queries
                .iter()
                .map(|query| self.startup_discovery_reference_query_row(query)),
        );
        games.extend(
            self.startup_direct_reference_queries
                .iter()
                .map(|query| self.startup_direct_reference_query_row(query)),
        );
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.set_games(games);
        }
    }

    fn selected_startup_direct_reference_query_id(&self) -> Option<u64> {
        let selected = self.startup_network_dialog.as_ref()?.selected_game()?;
        let query_index = selected
            .checked_sub(self.startup_game_references.len())?
            .checked_sub(self.startup_discovery_reference_queries.len())?;
        self.startup_direct_reference_queries
            .get(query_index)
            .map(|query| query.id)
    }

    fn selected_startup_game_reference(&self) -> Option<lc_network::NetworkGameReference> {
        let selected = self.startup_network_dialog.as_ref()?.selected_game()?;
        self.startup_game_references.get(selected).cloned()
    }

    fn focus_startup_game_reference(
        &mut self,
        reference: &lc_network::NetworkGameReference,
    ) {
        let index = self
            .startup_game_references
            .iter()
            .position(|candidate| candidate == reference)
            .or_else(|| {
                self.startup_game_references.iter().position(|candidate| {
                    Self::startup_network_reference_identity_eq(candidate, reference)
                })
            });
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            if let Some(index) = index {
                let _ = dialog.focus_game(index);
            }
        }
    }

    fn selected_startup_discovery_reference_query_id(&self) -> Option<u64> {
        let selected = self.startup_network_dialog.as_ref()?.selected_game()?;
        let query_index = selected.checked_sub(self.startup_game_references.len())?;
        self.startup_discovery_reference_queries
            .get(query_index)
            .map(|query| query.id)
    }

    fn focus_startup_discovery_reference_query(&mut self, id: u64) -> bool {
        let Some(query_index) = self
            .startup_discovery_reference_queries
            .iter()
            .position(|query| query.id == id)
        else {
            return false;
        };
        let row = self.startup_game_references.len() + query_index;
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            let _ = dialog.focus_game(row);
        }
        true
    }

    fn focus_startup_direct_reference_query(&mut self, id: u64) -> bool {
        let Some(query_index) = self
            .startup_direct_reference_queries
            .iter()
            .position(|query| query.id == id)
        else {
            return false;
        };
        let row = self.startup_game_references.len()
            + self.startup_discovery_reference_queries.len()
            + query_index;
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            let _ = dialog.focus_game(row);
        }
        true
    }

    fn begin_startup_direct_reference_query(&mut self, address: String) {
        if let Some(existing) = self
            .startup_direct_reference_queries
            .iter()
            .find(|query| {
                !matches!(query.state, StartupDirectReferenceQueryState::Failed(_))
                    && query.address.eq_ignore_ascii_case(&address)
            })
            .map(|query| query.id)
        {
            self.focus_startup_direct_reference_query(existing);
            self.mark_menu_dirty();
            return;
        }

        self.next_startup_direct_reference_query_id =
            self.next_startup_direct_reference_query_id.wrapping_add(1);
        let id = self.next_startup_direct_reference_query_id;
        self.startup_direct_reference_queries
            .push(StartupDirectReferenceQuery {
                id,
                address: address.clone(),
                state: StartupDirectReferenceQueryState::Pending,
                expires_at: None,
            });
        let default_port = load_network_reference_port(self.app_paths.as_ref());
        let submitted = self.startup_game_search.as_ref().is_some_and(|search| {
            search.query_direct(id, address, default_port).is_ok()
        });
        if !submitted {
            if let Some(query) = self
                .startup_direct_reference_queries
                .iter_mut()
                .find(|query| query.id == id)
            {
                query.state = StartupDirectReferenceQueryState::Failed(
                    "Unable to start direct reference query".to_string(),
                );
                query.expires_at = Instant::now()
                    .checked_add(STARTUP_NETWORK_QUERY_ERROR_LIFETIME);
            }
        }
        self.sync_startup_network_game_rows();
        self.focus_startup_direct_reference_query(id);
        self.mark_menu_dirty();
    }

    fn startup_network_join_target(&self, index: usize) -> Option<StartupNetworkJoinTarget> {
        if let Some(reference) = self.startup_game_references.get(index) {
            return Some(StartupNetworkJoinTarget::Reference(reference.clone()));
        }
        let query_index = index.checked_sub(self.startup_game_references.len())?;
        if let Some(query) = self.startup_discovery_reference_queries.get(query_index) {
            return Some(match &query.state {
                StartupDirectReferenceQueryState::Failed(error) => {
                    StartupNetworkJoinTarget::QueryError(error.clone())
                }
                StartupDirectReferenceQueryState::Pending
                | StartupDirectReferenceQueryState::Empty => {
                    StartupNetworkJoinTarget::DirectAddress(query.address.to_string())
                }
            });
        }
        let query = self
            .startup_direct_reference_queries
            .get(query_index.checked_sub(self.startup_discovery_reference_queries.len())?)?;
        Some(match &query.state {
            StartupDirectReferenceQueryState::Failed(error) => {
                StartupNetworkJoinTarget::QueryError(error.clone())
            }
            StartupDirectReferenceQueryState::Pending
            | StartupDirectReferenceQueryState::Empty => {
                StartupNetworkJoinTarget::DirectAddress(query.address.clone())
            }
        })
    }

    fn begin_startup_discovery_reference_query(&mut self, address: SocketAddr) {
        if self
            .startup_discovery_reference_queries
            .iter()
            .any(|query| {
                query.address == address
                    && !matches!(query.state, StartupDirectReferenceQueryState::Failed(_))
            })
        {
            return;
        }
        let selected_direct_query = self.selected_startup_direct_reference_query_id();
        self.next_startup_direct_reference_query_id =
            self.next_startup_direct_reference_query_id.wrapping_add(1);
        let id = self.next_startup_direct_reference_query_id;
        self.startup_discovery_reference_queries
            .push(StartupDiscoveryReferenceQuery {
                id,
                address,
                state: StartupDirectReferenceQueryState::Pending,
                expires_at: None,
            });
        self.sync_startup_network_game_rows();
        if let Some(id) = selected_direct_query {
            self.focus_startup_direct_reference_query(id);
        }
    }

    fn finish_startup_discovery_reference_query(
        &mut self,
        address: SocketAddr,
        references: Vec<lc_network::NetworkGameReference>,
        resolved_reference: bool,
    ) {
        let selected_reference = self.selected_startup_game_reference();
        let selected_direct_query = self.selected_startup_direct_reference_query_id();
        let selected_discovery_query = self.selected_startup_discovery_reference_query_id();
        let Some(query_index) = self
            .startup_discovery_reference_queries
            .iter()
            .rposition(|query| {
                query.address == address
                    && !matches!(query.state, StartupDirectReferenceQueryState::Failed(_))
            })
        else {
            return;
        };
        let query_id = self.startup_discovery_reference_queries[query_index].id;
        self.startup_game_references = references;
        if resolved_reference {
            self.startup_discovery_reference_queries.remove(query_index);
        } else {
            self.startup_discovery_reference_queries[query_index].state =
                StartupDirectReferenceQueryState::Empty;
            self.startup_discovery_reference_queries[query_index].expires_at = Instant::now()
                .checked_add(STARTUP_NETWORK_QUERY_ERROR_LIFETIME);
        }
        // Unlike NRQT_DirectJoin, NRQT_GameDiscovery never explicitly selects
        // a returned reference; preserve the controller's existing selection.
        self.sync_startup_network_game_rows();
        if let Some(reference) = selected_reference.as_ref() {
            self.focus_startup_game_reference(reference);
        } else if let Some(id) = selected_direct_query {
            self.focus_startup_direct_reference_query(id);
        } else if let Some(selected_id) = selected_discovery_query {
            if selected_id != query_id {
                self.focus_startup_discovery_reference_query(selected_id);
            }
        }
    }

    fn fail_startup_discovery_reference_query(
        &mut self,
        address: SocketAddr,
        message: String,
    ) {
        let expires_at = Instant::now().checked_add(STARTUP_NETWORK_QUERY_ERROR_LIFETIME);
        if let Some(query) = self
            .startup_discovery_reference_queries
            .iter_mut()
            .rev()
            .find(|query| {
                query.address == address
                    && !matches!(query.state, StartupDirectReferenceQueryState::Failed(_))
            })
        {
            query.state = StartupDirectReferenceQueryState::Failed(message);
            query.expires_at = expires_at;
        } else {
            // Started is queued before every result. Missing means this is a
            // stale duplicate completion whose same-address row was already
            // resolved or cleared; native suppresses duplicate live queries.
            return;
        }
        self.sync_startup_network_game_rows();
    }

    fn finish_startup_direct_reference_query(
        &mut self,
        request_id: u64,
        references: Vec<lc_network::NetworkGameReference>,
        selected_index: Option<usize>,
    ) {
        let selected_reference = self.selected_startup_game_reference();
        let selected_query = self.selected_startup_direct_reference_query_id();
        let selected_discovery_query = self.selected_startup_discovery_reference_query_id();
        let Some(query_index) = self
            .startup_direct_reference_queries
            .iter()
            .position(|query| query.id == request_id)
        else {
            return;
        };
        self.startup_game_references = references;
        if let Some(selected_index) = selected_index {
            self.startup_direct_reference_queries.remove(query_index);
            self.sync_startup_network_game_rows();
            match selected_query {
                Some(id) if id == request_id => {
                    if let Some(dialog) = self.startup_network_dialog.as_mut() {
                        let _ = dialog.focus_game(selected_index);
                    }
                }
                Some(id) => {
                    self.focus_startup_direct_reference_query(id);
                }
                None => {}
            }
        } else {
            self.startup_direct_reference_queries[query_index].state =
                StartupDirectReferenceQueryState::Empty;
            self.startup_direct_reference_queries[query_index].expires_at = Instant::now()
                .checked_add(STARTUP_NETWORK_QUERY_ERROR_LIFETIME);
            self.sync_startup_network_game_rows();
            if let Some(id) = selected_query {
                self.focus_startup_direct_reference_query(id);
            }
        }
        if selected_query.is_none() {
            if let Some(reference) = selected_reference.as_ref() {
                self.focus_startup_game_reference(reference);
            } else if let Some(id) = selected_discovery_query {
                self.focus_startup_discovery_reference_query(id);
            }
        }
    }

    fn fail_startup_direct_reference_query(&mut self, request_id: u64, message: String) {
        let selected_query = self.selected_startup_direct_reference_query_id();
        let Some(query) = self
            .startup_direct_reference_queries
            .iter_mut()
            .find(|query| query.id == request_id)
        else {
            return;
        };
        query.state = StartupDirectReferenceQueryState::Failed(message);
        query.expires_at =
            Instant::now().checked_add(STARTUP_NETWORK_QUERY_ERROR_LIFETIME);
        self.sync_startup_network_game_rows();
        if let Some(id) = selected_query {
            self.focus_startup_direct_reference_query(id);
        }
    }

    fn tick_startup_network_query_rows_at(&mut self, now: Instant) {
        let selected_query = self.selected_startup_direct_reference_query_id();
        let selected_discovery_query = self.selected_startup_discovery_reference_query_id();
        let query_count = self.startup_discovery_reference_queries.len()
            + self.startup_direct_reference_queries.len();
        self.startup_discovery_reference_queries.retain(|query| {
            query
                .expires_at
                .map_or(true, |expires_at| now < expires_at)
        });
        self.startup_direct_reference_queries.retain(|query| {
            query
                .expires_at
                .map_or(true, |expires_at| now < expires_at)
        });
        if self.startup_discovery_reference_queries.len()
            + self.startup_direct_reference_queries.len()
            != query_count
        {
            self.sync_startup_network_game_rows();
            if let Some(id) = selected_query {
                self.focus_startup_direct_reference_query(id);
            } else if let Some(id) = selected_discovery_query {
                self.focus_startup_discovery_reference_query(id);
            }
            self.mark_menu_dirty();
        }

        let masterserver_enabled = self
            .startup_network_dialog
            .as_ref()
            .is_some_and(|dialog| dialog.config().masterserver_signup);
        if masterserver_enabled
            && self
                .startup_masterserver_next_query_at
                .is_some_and(|next_query_at| now >= next_query_at)
        {
            self.startup_masterserver_next_query_at = None;
            self.reset_startup_masterserver_entry();
            self.mark_menu_dirty();
        }
    }

    fn request_network_reference_join(
        &mut self,
        reference: lc_network::NetworkGameReference,
    ) -> Result<(), EngineError> {
        let version_matches = reference.version == lc_network::CURRENT_GAME_VERSION
            && reference.build == lc_network::CURRENT_GAME_BUILD;
        if !version_matches {
            let remote = network_game_version_string(
                &reference.game,
                reference.version,
                reference.build,
            );
            let local = network_game_version_string(
                "LegacyClonk",
                lc_network::CURRENT_GAME_VERSION,
                lc_network::CURRENT_GAME_BUILD,
            );
            let message = format_resource_string(
                startup_resource_string(
                    self.app_paths.as_ref(),
                    "IDS_NET_NOJOIN_BADVER",
                    "Engine version mismatch: the game runs with %s - you have %s.",
                ),
                &[&remote, &local],
            );
            let caption = startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_NOJOIN",
                "Cannot join game",
            );
            self.push_message_dialog(
                lc_frontend::message_dialog::MessageDialogState::regular_ok(
                    message,
                    caption,
                    lc_frontend::message_dialog::MessageDialogIcon::ERROR,
                ),
                MessageDialogContinuation::None,
            )?;
            return Ok(());
        }
        if !reference.join_allowed {
            let message = startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_NOJOIN_NORUNTIME",
                "The game has started already and runtime join is not allowed! Try joining anyway?",
            );
            let caption = startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_NOJOIN",
                "Cannot join game",
            );
            self.push_message_dialog(
                lc_frontend::message_dialog::MessageDialogState::new(
                    message,
                    caption,
                    lc_frontend::message_dialog::MessageDialogButtons::YES_NO,
                    lc_frontend::message_dialog::MessageDialogIcon::ERROR,
                    lc_frontend::message_dialog::MessageDialogSize::Regular,
                    false,
                ),
                MessageDialogContinuation::NetworkRuntimeJoin { reference },
            )?;
            return Ok(());
        }
        self.activate_network_reference_join(reference)
    }

    fn show_startup_discovery_error(&mut self, detail: &str) -> Result<(), EngineError> {
        let message = format_resource_string(
            startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_NODISCOVERY_DESC",
                "Search failed: %s",
            ),
            &[detail],
        );
        let caption = startup_resource_string(
            self.app_paths.as_ref(),
            "IDS_NET_NODISCOVERY",
            "Search Error",
        );
        self.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::new(
                message,
                caption,
                lc_frontend::message_dialog::MessageDialogButtons::CANCEL,
                lc_frontend::message_dialog::MessageDialogIcon::ERROR,
                lc_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::None,
        )
    }

    fn request_startup_network_refresh(&mut self) -> Result<(), EngineError> {
        self.request_startup_network_refresh_at(Instant::now())
    }

    fn request_startup_network_refresh_at(
        &mut self,
        now: Instant,
    ) -> Result<(), EngineError> {
        if self.startup_network_last_refresh.is_some_and(|last| {
            now.saturating_duration_since(last) < STARTUP_NETWORK_MIN_REFRESH_INTERVAL
        }) {
            self.play_ui_sound("Error");
            return Ok(());
        }

        self.startup_network_last_refresh = Some(now);
        let masterserver_enabled = self
            .startup_network_dialog
            .as_ref()
            .is_some_and(|dialog| dialog.config().masterserver_signup);
        self.startup_masterserver_next_query_at = if masterserver_enabled {
            now.checked_add(lc_network::GAME_SEARCH_INTERVAL)
        } else {
            None
        };
        self.startup_game_references.clear();
        self.startup_discovery_reference_queries.clear();
        self.startup_direct_reference_queries.clear();
        self.netdlg_last_click = None;
        self.netdlg_join_edit_last_click = None;
        self.netdlg_edit_consumed_keys.clear();
        self.sync_startup_network_game_rows();
        self.reset_startup_masterserver_entry();
        self.status_text.clear();
        self.mark_menu_dirty();

        self.startup_network_refresh_waiting_for_clear = true;
        let refresh_error = match self.startup_game_search.as_ref() {
            Some(search) => {
                // The old generation may already have results queued. C++
                // deletes those clients synchronously; discard their queued
                // projections before asking the worker for a fresh Cleared.
                search.events().try_iter().for_each(drop);
                search.refresh().err().map(|error| error.to_string())
            }
            None => Some("network game search is not running".to_string()),
        };
        if let Some(error) = refresh_error {
            self.startup_network_refresh_waiting_for_clear = false;
            self.show_startup_discovery_error(&error)?;
        }
        Ok(())
    }

    fn sync_startup_irc_projection(
        &mut self,
        snapshot: lc_frontend::startup_netdlg::NetDlgChatSnapshot,
    ) {
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.sync_chat_snapshot(snapshot.clone());
        }
        if let Some(dialog) = self.external_irc_dialog.as_mut() {
            dialog.sync_chat_snapshot(snapshot);
        }
        self.mark_menu_dirty();
    }

    fn startup_irc_client_active(&self) -> bool {
        self.startup_irc_client
            .as_ref()
            .is_some_and(lc_network::IrcClientHandle::is_active)
    }

    fn startup_irc_chat_visible(&self) -> bool {
        self.external_irc_dialog_visible
            || (self.mode == AppMode::Menu
                && self.startup_view == StartupView::NetworkGame
                && self.startup_network_dialog.as_ref().is_some_and(|dialog| {
                    dialog.mode() == lc_frontend::startup_netdlg::NetDlgMode::Chat
                }))
    }

    fn show_startup_irc_error(&mut self, message: String) -> Result<(), EngineError> {
        let caption = self.runtime_resource_text("IDS_DLG_ERROR", "Error");
        self.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::regular_ok(
                message,
                caption,
                lc_frontend::message_dialog::MessageDialogIcon::ERROR,
            ),
            MessageDialogContinuation::None,
        )
    }

    fn show_startup_irc_validation_error(
        &mut self,
        field: lc_frontend::startup_netdlg::NetDlgChatLoginField,
    ) -> Result<(), EngineError> {
        let (key, fallback) = match field {
            lc_frontend::startup_netdlg::NetDlgChatLoginField::Nick => {
                ("IDS_ERR_INVALIDNICKNAME", "Invalid nickname.")
            }
            lc_frontend::startup_netdlg::NetDlgChatLoginField::Password => (
                "IDS_ERR_INVALIDPASSWORDMAX31CHARA",
                "Invalid password. Maximum 31 characters. No spaces allowed.",
            ),
            lc_frontend::startup_netdlg::NetDlgChatLoginField::RealName => return Ok(()),
            lc_frontend::startup_netdlg::NetDlgChatLoginField::Channel => {
                ("IDS_ERR_INVALIDCHANNELNAME", "Invalid channel name.")
            }
        };
        self.show_startup_irc_error(self.runtime_resource_text(key, fallback))
    }

    fn show_startup_irc_connect_failure(&mut self, error: &str) -> Result<(), EngineError> {
        let template =
            self.runtime_resource_text("IDS_ERR_IRCCONNECTIONFAILED", "IRC connection failed: %s");
        self.show_startup_irc_error(format_resource_string(template, &[error]))
    }

    fn request_startup_irc_disconnect_confirmation(&mut self) -> Result<(), EngineError> {
        self.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::new(
                self.runtime_resource_text(
                    "IDS_MSG_DISCONNECTFROMSERVER",
                    "Disconnect from server?",
                ),
                self.runtime_resource_text("IDS_DLG_CHAT", "Chat"),
                lc_frontend::message_dialog::MessageDialogButtons::OK_CANCEL,
                lc_frontend::message_dialog::MessageDialogIcon::CONFIRM,
                lc_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            ),
            MessageDialogContinuation::StartupIrcDisconnectConfirm,
        )
    }

    fn external_irc_dialog_contains_point(&self, point: GuiPoint) -> bool {
        let Some(bounds) = self
            .external_irc_dialog
            .as_ref()
            .and_then(|dialog| dialog.chat_bounds_override())
        else {
            return false;
        };
        point.x >= bounds.x as f32
            && point.x < bounds.x.saturating_add(bounds.w) as f32
            && point.y >= bounds.y as f32
            && point.y < bounds.y.saturating_add(bounds.h) as f32
    }

    fn handle_runtime_external_irc_pointer_move(
        &mut self,
        point: GuiPoint,
    ) -> Result<bool, EngineError> {
        if !matches!(self.mode, AppMode::Running)
            || !self.external_irc_dialog_visible
            || (!self.external_irc_dialog_contains_point(point)
                && !self.external_irc_pointer_capture)
        {
            return Ok(false);
        }
        let actions = self
            .assets
            .clonk_fonts
            .clone()
            .and_then(|fonts| {
                self.external_irc_dialog
                    .as_mut()
                    .map(|dialog| dialog.handle_pointer_move(point, &fonts.text))
            })
            .unwrap_or_default();
        self.process_network_dialog_actions(actions)?;
        Ok(true)
    }

    fn handle_runtime_external_irc_pointer_button(
        &mut self,
        button_state: ElementState,
    ) -> Result<bool, EngineError> {
        if !matches!(self.mode, AppMode::Running) || !self.external_irc_dialog_visible {
            self.external_irc_pointer_capture = false;
            return Ok(false);
        }
        let release_captured = button_state == ElementState::Released
            && std::mem::take(&mut self.external_irc_pointer_capture);
        let Some(point) = self.running_pointer_position else {
            return Ok(release_captured);
        };
        if !release_captured && !self.external_irc_dialog_contains_point(point) {
            return Ok(false);
        }
        if button_state == ElementState::Pressed {
            self.external_irc_pointer_capture = true;
            self.show_or_raise_runtime_default_dialog(RuntimeDefaultDialog::ExternalIrc);
        }
        let Some(fonts) = self.assets.clonk_fonts.clone() else {
            return Ok(true);
        };
        let mut actions = self
            .external_irc_dialog
            .as_mut()
            .map(|dialog| match button_state {
                ElementState::Pressed => dialog.handle_pointer_down(point, &fonts.text),
                ElementState::Released => dialog.handle_pointer_up(point, &fonts.text),
            })
            .unwrap_or_default();
        if button_state == ElementState::Released {
            let now = Instant::now();
            let double = self.irc_dialog_last_click.is_some_and(|(last, at)| {
                now.saturating_duration_since(at) < CPP_DOUBLE_CLICK_INTERVAL
                    && (last.x - point.x).abs() <= 4.0
                    && (last.y - point.y).abs() <= 4.0
            });
            self.irc_dialog_last_click = (!double).then_some((point, now));
            if double {
                actions.extend(
                    self.external_irc_dialog
                        .as_mut()
                        .map(|dialog| dialog.handle_pointer_double_click(point, &fonts.text))
                        .unwrap_or_default(),
                );
            }
        }
        self.process_network_dialog_actions(actions)?;
        Ok(true)
    }

    fn show_external_irc_dialog(&mut self) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        let resource_check = self
            .assets
            .netdlg_assets()
            .context("exact C4ChatDlg graphics are unavailable")
            .and_then(|_| {
                self.assets
                    .clonk_fonts
                    .as_ref()
                    .context("C4ChatDlg fonts are unavailable")
                    .map(|_| ())
            });
        Self::guard_gui_overlay_result("C4ChatDlg", resource_check)?;
        if self.mode == AppMode::Running {
            self.cancel_ingame_mouse_gestures();
            self.menu_title_drag = None;
            self.ingame_menu_close_pointer_capture = None;
            self.script_menu_close_pointer_capture = None;
        }
        self.close_context_menu_silently();
        if self.running_chat_controller().is_some() {
            self.close_running_chat()?;
        }
        if self.external_irc_dialog_visible && self.external_irc_dialog.is_some() {
            self.sync_startup_irc_snapshot();
            self.mark_menu_dirty();
            return Ok(());
        }
        let (width, height) = {
            let surface = self.graphics.surface();
            (surface.width() as i32, surface.height() as i32)
        };
        let bounds =
            lc_frontend::startup_netdlg::NetDlgController::standalone_chat_bounds(width, height);
        let active = self.startup_irc_client_active();
        let history = self.message_input_history.iter().cloned().collect();
        let mut dialog = self.new_network_dialog_controller();
        dialog.resize(width, height);
        dialog.set_chat_bounds_override(Some(bounds));
        dialog.set_chat_history(history);
        if !active {
            dialog.show_chat_login();
        }
        self.external_irc_dialog = Some(dialog);
        self.external_irc_dialog_visible = true;
        self.show_or_raise_runtime_default_dialog(RuntimeDefaultDialog::ExternalIrc);
        self.irc_dialog_last_click = None;
        self.sync_startup_irc_snapshot();
        if let Some(dialog) = self.external_irc_dialog.as_mut() {
            // The standalone C4ChatControl picks its initial focus after the
            // process-global IRC projection has selected Login versus Chats.
            dialog.force_chat_mode_and_default_focus();
            dialog.pointer_left();
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn hide_external_irc_dialog(&mut self) {
        self.close_context_menu_silently();
        self.external_irc_dialog_visible = false;
        self.external_irc_dialog = None;
        self.hide_runtime_default_dialog(RuntimeDefaultDialog::ExternalIrc);
        self.irc_dialog_last_click = None;
        self.external_irc_pointer_capture = false;
        self.mark_menu_dirty();
    }

    fn toggle_external_irc_dialog(&mut self) -> Result<(), EngineError> {
        if self.external_irc_dialog_visible {
            self.hide_external_irc_dialog();
            Ok(())
        } else {
            self.show_external_irc_dialog()
        }
    }

    fn sync_startup_irc_snapshot(&mut self) {
        let Some(client) = self.startup_irc_client.as_ref() else {
            return;
        };
        let snapshot = if self.startup_irc_chat_visible() {
            client.snapshot_and_mark_message_log_read()
        } else {
            client.snapshot()
        };
        let snapshot = project_startup_irc_snapshot(&self.startup_irc_server, snapshot);
        self.sync_startup_irc_projection(snapshot);
    }

    fn show_irc_login_on_all_controllers(&mut self) {
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.show_chat_login();
        }
        if let Some(dialog) = self.external_irc_dialog.as_mut() {
            dialog.show_chat_login();
        }
    }

    fn request_startup_irc_connection(
        &mut self,
        login: lc_frontend::startup_netdlg::NetDlgChatLogin,
    ) -> Result<(), EngineError> {
        // C4ChatControl::OnConnectBtn stores these three editable values
        // before the disclaimer. Server2 stays config-owned and the password
        // remains transient even when the user cancels the warning.
        if let Some(paths) = self.app_paths.as_ref() {
            if let Err(error) = persist_irc_login_settings(paths, &login) {
                tracing::warn!(%error, "failed to persist IRC login settings");
                self.status_text = format!("Unable to save IRC login settings: {error}");
            }
        }

        if load_irc_settings(self.app_paths.as_ref()).hide_dangerous_warning {
            return self.connect_startup_irc(login);
        }

        let message = format_resource_string(
            self.runtime_resource_text(
                "IDS_MSG_YOUAREABOUTTOCONNECTTOAPU",
                "You are about to connect to a public chat server (%s). RedWolf Design cannot assume liability for the contents of any public chat. Additional rules can be found as part of the server messages in the server channel. Proceed?",
            ),
            &[&login.server],
        );
        let caption = self.runtime_resource_text(
            "IDS_MSG_CHATDISCLAIMER",
            "Chat - Disclaimer",
        );
        let checkbox = self.runtime_resource_text(
            "IDS_MSG_DONTSHOW",
            "&Don't display this message in the future.",
        );
        self.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::new(
                message,
                caption,
                lc_frontend::message_dialog::MessageDialogButtons::OK_CANCEL,
                lc_frontend::message_dialog::MessageDialogIcon::NOTIFY,
                lc_frontend::message_dialog::MessageDialogSize::Regular,
                false,
            )
            .with_checkbox(checkbox, false),
            MessageDialogContinuation::StartupIrcConnectWarning { login },
        )?;
        Ok(())
    }

    fn connect_startup_irc(
        &mut self,
        login: lc_frontend::startup_netdlg::NetDlgChatLogin,
    ) -> Result<(), EngineError> {
        if let Some(mut client) = self.startup_irc_client.take() {
            if let Err(error) = client.close() {
                tracing::warn!(%error, "failed to close the previous IRC connection");
            }
        }
        self.startup_irc_initial_connect_pending = false;

        self.startup_irc_server.clone_from(&login.server);
        self.sync_startup_irc_projection(lc_frontend::startup_netdlg::NetDlgChatSnapshot {
            server: login.server.clone(),
            nick: login.nick.clone(),
            ..Default::default()
        });
        let encode = |text: &str| {
            encode_startup_irc_text(text).ok_or_else(|| EngineError::ClassicMenuParityBoundary {
                detail: "validated IRC text is not representable in the native byte charset"
                    .to_string(),
            })
        };
        let mut config = lc_network::IrcConnectConfig::new(
            login.server.clone(),
            encode(&login.nick)?,
            encode(&login.real_name)?,
        );
        config.password = if login.password.is_empty() {
            None
        } else {
            Some(encode(&login.password)?)
        };
        config.auto_join = if login.channel.is_empty() {
            None
        } else {
            Some(encode(&login.channel)?)
        };
        match lc_network::IrcClientHandle::connect(config) {
            Ok(client) => {
                self.startup_irc_initial_connect_pending = true;
                self.startup_irc_client = Some(client);
                self.sync_startup_irc_snapshot();
            }
            Err(error) => {
                let error = error.to_string();
                let snapshot = lc_frontend::startup_netdlg::NetDlgChatSnapshot {
                    server: login.server,
                    nick: login.nick,
                    ..Default::default()
                };
                self.sync_startup_irc_projection(snapshot);
                self.show_irc_login_on_all_controllers();
                self.show_startup_irc_connect_failure(&error)?;
            }
        }
        Ok(())
    }

    fn disconnect_startup_irc(&mut self) {
        self.startup_irc_initial_connect_pending = false;
        let Some(mut client) = self.startup_irc_client.take() else {
            return;
        };
        let close_error = client.close().err().map(|error| error.to_string());
        let mut snapshot =
            project_startup_irc_snapshot(&self.startup_irc_server, client.snapshot());
        if close_error.is_some() {
            snapshot.last_error = close_error;
        }
        self.sync_startup_irc_projection(snapshot);
    }

    fn dispatch_startup_irc_command(
        &mut self,
        command: lc_frontend::startup_netdlg::NetDlgChatCommand,
    ) {
        let Some(command) = project_startup_irc_command(command) else {
            return;
        };
        let result = self
            .startup_irc_client
            .as_ref()
            .ok_or(lc_network::IrcClientError::NotConnected)
            .and_then(|client| client.queue_command(command));
        if let Err(error) = result {
            tracing::warn!(%error, "failed to queue IRC command");
            if let Some(client) = self.startup_irc_client.as_ref() {
                let snapshot = if self.startup_irc_chat_visible() {
                    client.snapshot_and_mark_message_log_read()
                } else {
                    client.snapshot()
                };
                let mut snapshot =
                    project_startup_irc_snapshot(&self.startup_irc_server, snapshot);
                snapshot.last_error = Some(error.to_string());
                self.sync_startup_irc_projection(snapshot);
            }
        }
    }

    fn poll_startup_irc(&mut self) -> Result<(), EngineError> {
        let events = self
            .startup_irc_client
            .as_ref()
            .map(|client| client.events().try_iter().collect::<Vec<_>>())
            .unwrap_or_default();
        let changed = !events.is_empty();
        let mut initial_failure = None;
        for event in events {
            match event {
                lc_network::IrcClientEvent::Connected => {
                    self.startup_irc_initial_connect_pending = false;
                }
                lc_network::IrcClientEvent::Disconnected { reason }
                    if self.startup_irc_initial_connect_pending =>
                {
                    self.startup_irc_initial_connect_pending = false;
                    initial_failure = Some(reason);
                }
                lc_network::IrcClientEvent::Closed => {
                    self.startup_irc_initial_connect_pending = false;
                }
                lc_network::IrcClientEvent::Notification
                | lc_network::IrcClientEvent::Disconnected { .. } => {}
            }
        }
        if changed {
            self.sync_startup_irc_snapshot();
        }
        if let Some(error) = initial_failure {
            self.startup_irc_client = None;
            self.show_irc_login_on_all_controllers();
            self.show_startup_irc_connect_failure(&error)?;
        }
        Ok(())
    }

    fn process_network_dialog_actions(
        &mut self,
        actions: Vec<lc_frontend::startup_netdlg::NetDlgAction>,
    ) -> Result<(), EngineError> {
        use lc_frontend::startup_netdlg::NetDlgAction;

        if self.startup_network_transition_active() {
            return Ok(());
        }

        for action in actions {
            match action {
                NetDlgAction::FocusChanged(_)
                | NetDlgAction::ModeChanged(lc_frontend::startup_netdlg::NetDlgMode::GameList)
                | NetDlgAction::JoinAddressChanged(_) => {}
                NetDlgAction::ModeChanged(lc_frontend::startup_netdlg::NetDlgMode::Chat) => {
                    self.sync_startup_irc_snapshot();
                }
                NetDlgAction::OpenJoinAddressContextMenu(request) => {
                    let entries = request
                        .items
                        .into_iter()
                        .map(|item| {
                            let (label_key, label, tooltip_key, tooltip) = match item.command {
                                lc_frontend::startup_netdlg::NetDlgEditContextCommand::Cut => (
                                    "IDS_DLG_CUT",
                                    item.label.as_str(),
                                    "IDS_DLGTIP_CUT",
                                    item.tooltip.as_str(),
                                ),
                                lc_frontend::startup_netdlg::NetDlgEditContextCommand::Copy => (
                                    "IDS_DLG_COPY",
                                    item.label.as_str(),
                                    "IDS_DLGTIP_COPY",
                                    item.tooltip.as_str(),
                                ),
                                lc_frontend::startup_netdlg::NetDlgEditContextCommand::Paste => (
                                    "IDS_DLG_PASTE",
                                    item.label.as_str(),
                                    "IDS_DLGTIP_PASTE",
                                    item.tooltip.as_str(),
                                ),
                                lc_frontend::startup_netdlg::NetDlgEditContextCommand::Clear => (
                                    "IDS_DLG_CLEAR",
                                    item.label.as_str(),
                                    "IDS_DLGTIP_CLEAR",
                                    item.tooltip.as_str(),
                                ),
                                lc_frontend::startup_netdlg::NetDlgEditContextCommand::SelectAll => (
                                    "IDS_DLG_SELALL",
                                    item.label.as_str(),
                                    "IDS_DLGTIP_SELALL",
                                    item.tooltip.as_str(),
                                ),
                            };
                            ContextMenuEntry::new(startup_resource_string(
                                self.app_paths.as_ref(),
                                label_key,
                                label,
                            ))
                            .with_tooltip(startup_resource_string(
                                self.app_paths.as_ref(),
                                tooltip_key,
                                tooltip,
                            ))
                            .with_icon(ContextMenuIcon::None)
                            .with_action(AppContextMenuCommand::NetworkJoinEdit(item.command))
                        })
                        .collect();
                    self.open_context_menu_at(entries, request.anchor)?;
                }
                NetDlgAction::ClipboardTransfer { text, cut } => {
                    match arboard::Clipboard::new()
                        .and_then(|mut clipboard| clipboard.set_text(text))
                    {
                        Ok(()) if cut => {
                            let fonts = self.assets.clonk_fonts.clone();
                            let follow_up = fonts
                                .as_deref()
                                .and_then(|fonts| {
                                    self.input_network_dialog_mut()
                                        .map(|dialog| dialog.confirm_clipboard_cut(&fonts.text))
                                })
                                .unwrap_or_default();
                            self.process_network_dialog_actions(follow_up)?;
                        }
                        Ok(()) => {}
                        Err(error) => {
                            tracing::warn!(%error, "failed to copy join-address edit text");
                        }
                    }
                }
                NetDlgAction::GuiSound(sound) => self.play_ui_sound(match sound {
                    lc_frontend::startup_netdlg::NetDlgSound::ArrowHit => "ArrowHit",
                    lc_frontend::startup_netdlg::NetDlgSound::Command => "Command",
                    lc_frontend::startup_netdlg::NetDlgSound::Error => "Error",
                }),
                NetDlgAction::ChatConnect(login) => {
                    self.request_startup_irc_connection(login)?;
                }
                NetDlgAction::ChatValidationFailed(error) => {
                    self.show_startup_irc_validation_error(error.field())?;
                }
                NetDlgAction::ChatCommand(command) => self.dispatch_startup_irc_command(command),
                NetDlgAction::ChatDisconnectConfirmationRequested => {
                    self.request_startup_irc_disconnect_confirmation()?;
                }
                NetDlgAction::ChatDisconnect => {
                    self.disconnect_startup_irc();
                    self.show_irc_login_on_all_controllers();
                }
                NetDlgAction::ChatHistoryStored(text) => {
                    self.store_message_input_history(&text);
                }
                NetDlgAction::ChatDialogCloseRequested => self.hide_external_irc_dialog(),
                NetDlgAction::ChatSelectSheet { .. } => {
                    self.sync_startup_irc_snapshot();
                }
                NetDlgAction::Back => {
                    self.begin_startup_dialog_fade(StartupDialog::MainMenu);
                    self.show_main_menu();
                }
                NetDlgAction::Refresh => {
                    self.request_startup_network_refresh()?;
                }
                NetDlgAction::QueryAddress { address } => {
                    self.begin_startup_direct_reference_query(address);
                }
                NetDlgAction::OpenUrl(url) => {
                    if let Err(error) = open_external_http_url(&url) {
                        tracing::warn!(%url, %error, "failed to open network-dialog hyperlink");
                        self.status_text = format!("Unable to open link: {error}");
                    }
                }
                NetDlgAction::JoinGame { .. } => {
                    let selected_index = self
                        .startup_network_dialog
                        .as_ref()
                        .and_then(|dialog| dialog.selected_game());
                    let target = selected_index
                        .and_then(|index| self.startup_network_join_target(index));
                    let Some(target) = target else {
                        self.status_text.clear();
                        let message = startup_resource_string(
                            self.app_paths.as_ref(),
                            "IDS_NET_NOJOIN_NOREF",
                            "No reference selected. Select a game from the list or enter a direct join address below!",
                        );
                        let caption = startup_resource_string(
                            self.app_paths.as_ref(),
                            "IDS_NET_NOJOIN",
                            "Cannot join game",
                        );
                        self.push_message_dialog(
                            lc_frontend::message_dialog::MessageDialogState::regular_ok(
                                message,
                                caption,
                                lc_frontend::message_dialog::MessageDialogIcon::ERROR,
                            ),
                            MessageDialogContinuation::None,
                        )?;
                        continue;
                    };
                    match target {
                        StartupNetworkJoinTarget::Reference(reference) => {
                            self.request_network_reference_join(reference)?;
                        }
                        StartupNetworkJoinTarget::DirectAddress(address) => {
                            self.activate_network_join(address)?;
                        }
                        StartupNetworkJoinTarget::QueryError(error) => {
                            let message = format_resource_string(
                                startup_resource_string(
                                    self.app_paths.as_ref(),
                                    "IDS_NET_NOJOIN_BADREF",
                                    "Cannot join selected game: %s",
                                ),
                                &[&error],
                            );
                            let caption = startup_resource_string(
                                self.app_paths.as_ref(),
                                "IDS_NET_NOJOIN",
                                "Cannot join game",
                            );
                            self.push_message_dialog(
                                lc_frontend::message_dialog::MessageDialogState::regular_ok(
                                    message,
                                    caption,
                                    lc_frontend::message_dialog::MessageDialogIcon::ERROR,
                                ),
                                MessageDialogContinuation::None,
                            )?;
                        }
                    }
                }
                NetDlgAction::CreateGame => {
                    // C4StartupNetDlg opens C4StartupScenSelDlg(true) before
                    // any host socket or NetworkManager exists.
                    self.begin_startup_dialog_fade(StartupDialog::ScenarioBrowser(
                        ScenarioSelectorMode::NetworkHost,
                    ));
                    self.open_network_host_scenario_browser();
                }
                NetDlgAction::MasterserverSignupChanged(enabled) => {
                    if let Some(search) = self.startup_game_search.as_ref() {
                        let _ = search.set_internet_enabled(enabled);
                    }
                    if enabled {
                        let now = Instant::now();
                        self.startup_network_last_refresh = Some(now);
                        self.startup_masterserver_next_query_at =
                            now.checked_add(lc_network::GAME_SEARCH_INTERVAL);
                        self.reset_startup_masterserver_entry();
                    } else {
                        self.startup_masterserver_next_query_at = None;
                    }
                    if let Some(paths) = self.app_paths.as_ref() {
                        if let Err(error) = persist_config_value(
                            paths,
                            "Network",
                            "MasterServerSignUp",
                            i32::from(enabled).to_string(),
                        ) {
                            self.status_text = format!("Unable to save network setting: {error}");
                        }
                    }
                }
                NetDlgAction::RecordingChanged(record) => {
                    self.startup_view_flags.record = record;
                    self.recording_enabled = record && self.recordings_dir.is_some();
                    if let Some(paths) = self.app_paths.as_ref() {
                        if let Err(error) = persist_config_value(
                            paths,
                            "General",
                            "Record",
                            i32::from(record).to_string(),
                        ) {
                            self.status_text = format!("Unable to save recording setting: {error}");
                        }
                    }
                }
            }
        }
        Ok(())
    }

    fn apply_network_join_edit_context_command(
        &mut self,
        command: lc_frontend::startup_netdlg::NetDlgEditContextCommand,
    ) -> Result<(), EngineError> {
        if !self.external_irc_dialog_visible
            && (self.mode != AppMode::Menu || self.startup_view != StartupView::NetworkGame)
        {
            tracing::error!(?command, "stale join-address context command");
            return Ok(());
        }
        let clipboard = matches!(
            command,
            lc_frontend::startup_netdlg::NetDlgEditContextCommand::Paste
        )
        .then(|| {
            arboard::Clipboard::new()
                .and_then(|mut clipboard| clipboard.get_text())
                .ok()
        })
        .flatten();
        let fonts = self.assets.clonk_fonts.clone();
        let actions = fonts
            .as_deref()
            .and_then(|fonts| {
                self.input_network_dialog_mut().map(|dialog| {
                    dialog.apply_context_command(command, clipboard.as_deref(), &fonts.text)
                })
            })
            .unwrap_or_default();
        self.process_network_dialog_actions(actions)?;
        self.mark_menu_dirty();
        Ok(())
    }

    fn apply_league_signup_edit_context_command(
        &mut self,
        field: lc_frontend::league_signup::LeagueSignupField,
        command: lc_frontend::league_signup::LeagueSignupEditContextCommand,
    ) -> Result<(), EngineError> {
        if self.league_signup_dialog.is_none() {
            tracing::error!(?field, ?command, "stale league-signup context command");
            return Ok(());
        }
        let clipboard = matches!(
            command,
            lc_frontend::league_signup::LeagueSignupEditContextCommand::Paste
        )
        .then(|| {
            arboard::Clipboard::new()
                .and_then(|mut clipboard| clipboard.get_text())
                .ok()
        })
        .flatten();
        let layout = self.league_signup_layout();
        let fonts = self.assets.clonk_fonts.clone();
        let actions = layout
            .as_ref()
            .zip(fonts.as_deref())
            .and_then(|(layout, fonts)| {
                self.league_signup_dialog.as_mut().map(|dialog| {
                    dialog.controller.apply_edit_context_command(
                        field,
                        command,
                        clipboard.as_deref(),
                        layout,
                        &fonts.text,
                    )
                })
            })
            .unwrap_or_default();
        self.process_league_signup_actions(actions)?;
        self.mark_menu_dirty();
        Ok(())
    }

    fn begin_startup_network_connection(
        &mut self,
        receiver: Receiver<StartupNetworkResult>,
        purpose: StartupNetworkPurpose,
        selected_scenario: Option<(String, String)>,
        connect_targets: Option<String>,
    ) -> Result<(), EngineError> {
        self.install_startup_network_connection(
            StartupNetworkConnection::new(receiver, selected_scenario, purpose),
            connect_targets,
        )
    }

    fn begin_cancellable_startup_network_connection(
        &mut self,
        receiver: Receiver<StartupNetworkResult>,
        attempt: StartupNetworkAttempt,
        purpose: StartupNetworkPurpose,
        selected_scenario: Option<(String, String)>,
        connect_targets: Option<String>,
    ) -> Result<(), EngineError> {
        self.install_startup_network_connection(
            StartupNetworkConnection::new(receiver, selected_scenario, purpose)
                .with_attempt(attempt),
            connect_targets,
        )
    }

    fn install_startup_network_connection(
        &mut self,
        connection: StartupNetworkConnection,
        connect_targets: Option<String>,
    ) -> Result<(), EngineError> {
        let purpose = connection.purpose;
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            // Transition guards suppress subsequent input, so release every
            // net-dialog press/capture before installing that guard.
            dialog.cancel_interaction();
        }
        if purpose == StartupNetworkPurpose::Join {
            let connect_targets = connect_targets
                .filter(|targets| !targets.trim().is_empty())
                .unwrap_or_else(|| "network game".to_string());
            let message = format_resource_string(
                startup_resource_string(
                    self.app_paths.as_ref(),
                    "IDS_NET_CONNECTHOST",
                    "Connecting to host on %s...",
                ),
                &[&connect_targets],
            );
            let caption = startup_resource_string(
                self.app_paths.as_ref(),
                "IDS_NET_JOINGAME",
                "Joining network game",
            );
            self.push_message_dialog(
                lc_frontend::message_dialog::MessageDialogState::new(
                    message,
                    caption,
                    lc_frontend::message_dialog::MessageDialogButtons::CANCEL,
                    lc_frontend::message_dialog::MessageDialogIcon::Standard(3),
                    lc_frontend::message_dialog::MessageDialogSize::Regular,
                    false,
                ),
                MessageDialogContinuation::StartupNetworkConnectProgress,
            )?;
        }
        self.startup_network_connection = Some(connection);
        if purpose == StartupNetworkPurpose::StagedHost {
            let initial_fonts = self
                .staged_network_host_scenario
                .as_ref()
                .and_then(|staged| staged.loader_screen.as_ref())
                .map(|loader| loader.resources().fonts().clone());
            let initial_tooltip = self
                .staged_network_host_scenario
                .as_ref()
                .map(|staged| staged.loader_initial_tooltip_font.clone());
            let initial_native_source = self
                .staged_network_host_scenario
                .as_ref()
                .and_then(|staged| staged.loader_initial_native_font_source.clone());
            if let (Some(fonts), Some(tooltip)) = (initial_fonts, initial_tooltip) {
                self.install_active_classic_fonts(fonts, Some(tooltip), initial_native_source);
            }
            // C4Game opens the scenario and installs its loader before
            // InitNetworkHost. Show that exact full loader while the socket
            // worker starts; the lobby later retains only its background.
            self.cancel_underlying_interaction();
            self.replace_startup_view(StartupView::NetworkGame);
            if let Some(loader) = self
                .staged_network_host_scenario
                .as_mut()
                .and_then(|staged| staged.loader_screen.take())
            {
                self.loader_screen = Some(loader);
                self.loader_error = None;
            }
            self.status_text.clear();
            self.mode = AppMode::Loading;
        } else {
            self.status_text.clear();
        }
        self.mark_menu_dirty();
        Ok(())
    }

    fn activate_prepared_network_host(
        &mut self,
        scenario: FrontendScenario,
        bind_addr: SocketAddr,
    ) {
        if self.startup_network_connection.is_some() {
            self.status_text = "A network connection is already in progress".to_string();
            return;
        }
        let staged = self.staged_network_host_scenario.as_ref().filter(|staged| {
            staged.frontend.identifier == scenario.identifier
                && staged.frontend.path == scenario.path
        });
        let Some(staged) = staged else {
            self.status_text =
                "Unable to prepare network game: staged scenario resources are unavailable"
                    .to_string();
            return;
        };
        let staged_identity = Some((staged.lobby.local_name.as_str(), staged.lobby.nick.as_str()));
        let preparation = match build_network_host_preparation(
            self,
            &scenario,
            &staged.definition_load,
            &staged.effective_definition_modules,
            &staged.definition_resources,
            Some((&staged.definition_executable_path, &staged.definition_path)),
            staged_identity,
        ) {
            Ok(preparation) => preparation,
            Err(error) => {
                self.status_text = format!("Unable to prepare network game: {error}");
                return;
            }
        };
        let selected_scenario = Some((scenario.identifier.clone(), scenario.title.clone()));
        self.startup_game_search = None;
        let (sender, receiver) = mpsc::channel();
        let local_owner = self.local_owner;
        let spawn = thread::Builder::new()
            .name("lc-prepare-network-host".to_string())
            .spawn(move || {
                let result = preparation
                    .prepare()
                    .map_err(|error| {
                        NetworkStartError::Other(format!("host preparation failed: {error}"))
                    })
                    .and_then(|prepared| {
                        let mode = NetworkMode::Host(HostSettings {
                            bind_addr,
                            player_name: native_bytes_as_legacy_text(
                                prepared.host_config().local_core.name.as_bytes(),
                            ),
                            prepared: Some(prepared),
                        });
                        NetworkManager::for_mode(mode.clone(), local_owner)
                            .map(|manager| (mode, manager))
                    });
                let _ = sender.send(result);
            });
        match spawn {
            Ok(_) => {
                match self.begin_startup_network_connection(
                    receiver,
                    StartupNetworkPurpose::StagedHost,
                    selected_scenario,
                    None,
                ) {
                    Ok(()) => {
                        self.status_text = "Preparing network game…".to_string();
                    }
                    Err(error) => {
                        self.status_text =
                            format!("Unable to start network preparation: {error}");
                    }
                }
            }
            Err(error) => {
                self.status_text = format!("Unable to start network preparation: {error}");
            }
        }
    }

    fn activate_network_join(&mut self, address: String) -> Result<(), EngineError> {
        if self.startup_network_connection.is_some() {
            self.status_text = "A network connection is already in progress".to_string();
            return Ok(());
        }
        if let Err(error) = self.freeze_configured_client_players_for_game() {
            self.status_text = format!("Unable to load configured players: {error}");
            return Ok(());
        }
        self.prepare_network_join_game_state();
        self.startup_game_search = None;
        let local_owner = self.local_owner;
        let player_name = self.player_name.clone();
        let app_paths = self.app_paths.clone();
        let group_maker = self
            .configured_client_player_selection
            .as_ref()
            .map(|selection| selection.group_maker().clone());
        let (_, default_port) = load_network_startup_settings(self.app_paths.as_ref());
        let connect_target = address.clone();
        let spawn = spawn_startup_network_attempt(
            "lc-startup-network",
            move |cancellation| {
                let server_addr = resolve_join_socket(&address, default_port).map_err(|error| {
                    NetworkStartError::Other(format!("invalid network address: {error:#}"))
                })?;
                if cancellation.is_cancelled() {
                    return Err(NetworkStartError::Cancelled);
                }
                let mut settings =
                    client_settings_for_paths(server_addr, player_name, app_paths.as_ref());
                if let Some(group_maker) = group_maker {
                    settings.group_maker = group_maker;
                }
                let mode = NetworkMode::Client(settings.clone());
                NetworkManager::for_client_cancellable(
                    settings,
                    local_owner,
                    cancellation,
                )
                .map(|manager| (mode, manager))
            },
        );
        match spawn {
            Ok((receiver, attempt)) => {
                self.begin_cancellable_startup_network_connection(
                    receiver,
                    attempt,
                    StartupNetworkPurpose::Join,
                    None,
                    Some(connect_target),
                )?;
            }
            Err(error) => {
                self.status_text = format!("Unable to start network worker: {error}");
            }
        }
        Ok(())
    }

    fn activate_network_reference_join(
        &mut self,
        reference: lc_network::NetworkGameReference,
    ) -> Result<(), EngineError> {
        if self.startup_network_connection.is_some() {
            self.status_text = "A network connection is already in progress".to_string();
            return Ok(());
        }
        if let Err(error) = self.freeze_configured_client_players_for_game() {
            self.status_text = format!("Unable to load configured players: {error}");
            return Ok(());
        }
        self.prepare_network_join_game_state();
        let attempts = reference.join_attempts_for_local_host();
        let netpuncher_address = reference.netpuncher_address.clone();
        let netpuncher_game_ids = lc_network::NetpuncherGameIds {
            ipv4: reference.netpuncher_ipv4,
            ipv6: reference.netpuncher_ipv6,
        };
        let mut settings = client_settings_for_paths(
            reference.source_address,
            self.player_name.clone(),
            self.app_paths.as_ref(),
        );
        if let Some(selection) = self.configured_client_player_selection.as_ref() {
            settings.group_maker = selection.group_maker().clone();
        }
        let settings = settings
            .with_join_attempts(attempts)
            .with_netpuncher(netpuncher_address, netpuncher_game_ids);
        self.startup_game_search = None;
        self.pending_network_join = Some(settings);
        if reference.password_needed {
            self.open_network_join_password_dialog()?;
        } else {
            self.launch_pending_network_join()?;
        }
        Ok(())
    }

    /// Mirrors the game-state reset immediately before C++ starts either a
    /// reference-backed or unresolved direct join. The synchronized client
    /// load replaces this seed with the host's exact fixed resources later.
    fn prepare_network_join_game_state(&mut self) {
        self.startup_restart_diagnostics.begin_game_init();
        self.clear_lobby_preload();
        self.active_scenario = None;
        let definition_load = self.take_scenario_seed_definition_load();
        self.active_definition_load = Some(definition_load);
        self.active_description_definition_modules.clear();
    }

    fn launch_pending_network_join(&mut self) -> Result<(), EngineError> {
        let Some(settings) = self.pending_network_join.clone() else {
            self.status_text = "Network join settings are unavailable".to_string();
            return Ok(());
        };
        let connect_targets = startup_network_connect_targets(&settings);
        let local_owner = self.local_owner;
        let spawn = spawn_startup_network_attempt(
            "lc-startup-network",
            move |cancellation| {
                let mode = NetworkMode::Client(settings.clone());
                NetworkManager::for_client_cancellable(
                    settings,
                    local_owner,
                    cancellation,
                )
                .map(|manager| (mode, manager))
            },
        );
        match spawn {
            Ok((receiver, attempt)) => {
                if let Err(error) = self.begin_cancellable_startup_network_connection(
                    receiver,
                    attempt,
                    StartupNetworkPurpose::Join,
                    None,
                    Some(connect_targets),
                ) {
                    self.pending_network_join = None;
                    return Err(error);
                }
            }
            Err(error) => {
                self.pending_network_join = None;
                self.status_text = format!("Unable to start network worker: {error}");
            }
        }
        Ok(())
    }

    fn open_network_join_password_dialog(&mut self) -> Result<(), EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        Self::guard_gui_overlay_result(
            "Network join password input dialog",
            self.assets.input_dialog_resources().map(|_| ()),
        )?;
        self.close_context_menu_silently();
        if let Some(dialog) = self.startup_network_dialog.as_mut() {
            dialog.cancel_interaction();
        }
        let controller = InputDialogController::new(
            "Enter password:",
            "Enter password:",
            InputDialogIcon::LOCKED,
        );
        self.startup_tooltip.pointer_left();
        self.game_option_input_dialog = Some(PendingGameOptionInputDialog {
            purpose: PendingInputDialogPurpose::NetworkJoinPassword,
            controller,
        });
        self.game_option_input_consumed_keys.clear();
        self.game_option_input_pointer_capture = None;
        self.game_option_input_pointer_position = None;
        self.game_option_input_last_click = None;
        self.status_text.clear();
        self.mark_menu_dirty();
        Ok(())
    }

