    fn close_stale_classic_lobby_team_combo(&mut self) {
        let roster_active = self
            .visible_classic_lobby_controller()
            .is_some_and(|controller| controller.active_sheet().is_roster());
        let stale_team_combo = self.context_menu_lobby_team_player.is_some_and(|player_id| {
            !roster_active
                || self
                    .visible_classic_lobby_controller()
                    .and_then(ClassicGameLobby::open_team_combo_player)
                    != Some(player_id)
        });
        let stale_kick = self.context_menu_lobby_kick_client.is_some_and(|client_id| {
            !roster_active
                || !self.control_clients.contains(client_id)
                || self.visible_lobby_client_is_local(client_id).is_none()
        });
        let stale_player = self
            .context_menu_lobby_player
            .is_some_and(|(client_id, player_id, opened_as_free_savegame)| {
                !roster_active
                    || !self
                        .visible_classic_lobby_player_context_target(player_id)
                        .is_some_and(|(visible_client_id, free_savegame_player)| {
                            visible_client_id == client_id
                                && free_savegame_player == opened_as_free_savegame
                        })
            });
        let stale_option = self.context_menu_lobby_option.is_some_and(|option| {
            let lobby_owns = self.classic_host_lobby.as_ref().is_some_and(|lobby| {
                lobby.controller.active_sheet() == LobbySheet::Options
                    && lobby.controller.open_option_combo() == Some(option)
            });
            let runtime_owns = self
                .runtime_client_list
                .as_ref()
                .is_some_and(|dialog| dialog.open_option() == Some(option));
            !lobby_owns && !runtime_owns
        });
        if stale_team_combo || stale_kick || stale_player || stale_option {
            // ComboBox::SetReadOnly aborts its menu without a DoorClose sound.
            self.close_context_menu_silently();
        }
    }

    fn open_context_menu_at_with_minimum_width(
        &mut self,
        entries: Vec<ContextMenuEntry<AppContextMenuCommand>>,
        anchor: GuiPoint,
        minimum_width: i32,
        lobby_team_player: Option<i32>,
    ) -> Result<bool, EngineError> {
        self.guard_classic_global_gui_bootstrap()?;
        let resources = self
            .assets
            .context_menu_resources()
            .map_err(|error| Self::gui_overlay_engine_error("C4GUI context menu", error))?;
        let surface = self.graphics.surface();
        let screen = lc_frontend::classic_gui::IntRect {
            x: 0,
            y: 0,
            w: surface.width() as i32,
            h: surface.height() as i32,
        };
        let (menu, outcome) = ClassicContextMenu::open_with_minimum_width(
            entries,
            anchor,
            screen,
            resources,
            minimum_width,
        );
        self.startup_tooltip.pointer_left();
        self.note_classic_lobby_non_pointer_input();
        self.context_menu = Some(menu);
        self.context_menu_lobby_kick_client = None;
        self.context_menu_lobby_player = None;
        self.set_context_menu_lobby_option(None);
        self.set_context_menu_lobby_team_player(lobby_team_player);
        self.process_context_menu_outcome(outcome)?;
        Ok(true)
    }

