    fn handle_classic_lobby_wheel(&mut self, delta: i32) -> Result<(), EngineError> {
        if delta == 0 {
            return Ok(());
        }
        let Some(point) = self
            .classic_host_lobby
            .as_ref()
            .and_then(|lobby| lobby.pointer)
        else {
            return Ok(());
        };
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let contains = |rect: lc_frontend::classic_gui::IntRect| {
            point.x >= rect.x as f32
                && point.y >= rect.y as f32
                && point.x < (rect.x + rect.w) as f32
                && point.y < (rect.y + rect.h) as f32
        };
        let scroll_window_captured =
            contains(layout.chat_log_client) || contains(layout.roster_client);
        if let Some(lobby) = self.classic_host_lobby.as_mut() {
            lobby.controller.note_pointer_wheel();
        }
        self.scenario_game_options.note_pointer_wheel();
        let outside_scroll_window = contains(layout.chat_log)
            && !contains(layout.chat_log_client)
            || contains(layout.roster) && !contains(layout.roster_client);
        let scrolled = self
            .classic_host_lobby
            .as_mut()
            .is_some_and(|lobby| {
                !outside_scroll_window && lobby.controller.wheel(point, delta, &layout, &roster)
            });
        if scroll_window_captured {
            // C4GUI::ScrollWindow consumes the wheel and clears the screen's
            // pMouseOver owner. Keep retained positions for integer motion
            // detection, but require a later pointer event before either
            // controller may expose another tooltip.
            self.note_classic_lobby_non_pointer_input();
        }
        if scrolled || scroll_window_captured {
            self.mark_menu_dirty();
        }
        Ok(())
    }

    fn handle_classic_lobby_touch(
        &mut self,
        phase: TouchPhase,
        point: GuiPoint,
        double_click: bool,
    ) -> Result<(), EngineError> {
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let actions = self
            .classic_host_lobby
            .as_mut()
            .map(|lobby| {
                lobby.pointer = (!matches!(phase, TouchPhase::Cancelled)).then_some(point);
                match phase {
                    TouchPhase::Started if double_click => lobby
                        .controller
                        .pointer_double_click(point, &layout, &roster),
                    TouchPhase::Started => lobby.controller.touch_start(point, &layout, &roster),
                    TouchPhase::Moved => lobby.controller.touch_move(point, &layout, &roster),
                    TouchPhase::Ended => {
                        lobby
                            .controller
                            .touch_end(point, &layout, &roster, Instant::now())
                    }
                    TouchPhase::Cancelled => lobby.controller.touch_cancel(),
                }
            })
            .unwrap_or_default();
        self.process_classic_lobby_actions(actions)
    }

    fn handle_classic_lobby_gamepad_direction(
        &mut self,
        button: ControlButton,
        state: ElementState,
    ) -> Result<(), EngineError> {
        if state == ElementState::Released {
            return Ok(());
        }
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let (horizontal, vertical) = match button {
            ControlButton::Left => (-1, 0),
            ControlButton::Right => (1, 0),
            ControlButton::Up => (0, -1),
            ControlButton::Down => (0, 1),
        };
        let actions = self
            .classic_host_lobby
            .as_mut()
            .map(|lobby| {
                lobby
                    .controller
                    .gamepad_direction(horizontal, vertical, &layout, &roster)
            })
            .unwrap_or_default();
        self.process_classic_lobby_actions(actions)
    }

    fn handle_classic_lobby_gamepad_action(
        &mut self,
        action: GamepadActionType,
        state: ElementState,
    ) -> Result<(), EngineError> {
        let (layout, roster) = self.classic_host_lobby_layouts()?;
        let actions = self
            .classic_host_lobby
            .as_mut()
            .map(|lobby| match action {
                GamepadActionType::Select => match state {
                    ElementState::Pressed => {
                        lobby
                            .controller
                            .gamepad_low_down(Instant::now(), &layout, &roster)
                    }
                    ElementState::Released => lobby.controller.gamepad_low_up(),
                },
                GamepadActionType::Cancel | GamepadActionType::MenuToggle => {
                    if state == ElementState::Pressed {
                        lobby.controller.gamepad_high_down()
                    } else {
                        Vec::new()
                    }
                }
            })
            .unwrap_or_default();
        self.process_classic_lobby_actions(actions)
    }

    fn handle_main_menu_activation(&mut self, item: MainMenuItem) -> Result<(), EngineError> {
        match item {
            MainMenuItem::LocalGame => {
                self.begin_startup_dialog_fade(StartupDialog::ScenarioBrowser(
                    ScenarioSelectorMode::Local,
                ));
                self.open_scenario_browser();
            }
            MainMenuItem::NetworkGame => {
                if self.network_mode.is_some() && self.network_lobby.is_some() {
                    self.open_network_lobby();
                } else {
                    self.begin_startup_dialog_fade(StartupDialog::NetworkGame);
                    self.open_network_game_dialog();
                }
            }
            MainMenuItem::PlayerSelection => {
                self.begin_startup_dialog_fade(StartupDialog::PlayerSelection);
                self.open_player_selection_dialog();
            }
            MainMenuItem::Options => {
                self.begin_startup_dialog_fade(StartupDialog::Options);
                self.open_options_menu();
            }
            MainMenuItem::About => {
                self.begin_startup_dialog_fade(StartupDialog::About);
                self.open_about_dialog();
            }
            MainMenuItem::Quit => {
                self.request_exit();
            }
        }
        Ok(())
    }

    /// C4StartupScenSelDlg::DoBack(true) (cpp:1705-1725): backtrace the
    /// folder stack first; from the root, return to the main screen.
    fn configure_current_folder_map(&mut self) {
        // SetFolderData/UpdateList replace Book/Map child elements without
        // replacing the outer dialog. Mirror native element destruction by
        // dropping hover ownership before resolving the rebuilt hierarchy.
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
        let width = self.graphics.surface().width() as i32;
        let height = self.graphics.surface().height() as i32;
        let languages = self
            .app_paths
            .as_ref()
            .and_then(|paths| classic_runtime_language_sequence(paths).ok())
            .filter(|languages| !languages.is_empty())
            .unwrap_or_else(|| vec!["US".to_string()]);
        self.menu_state.configure_current_folder_map(
            self.show_folder_maps,
            width,
            height,
            &self.mission_access,
            &languages,
        );
    }

    fn enter_scenario_folder(&mut self, identifier: &str) {
        self.menu_state.enter_folder(identifier);
        self.configure_current_folder_map();
        self.mark_menu_dirty();
    }

    fn scensel_do_back(&mut self) -> Result<(), EngineError> {
        if self.scenario_selector_discovery.is_some() {
            self.close_scenario_browser();
            return Ok(());
        }
        if self.menu_state.stack.len() <= 1 {
            self.close_scenario_browser();
        } else {
            self.play_ui_sound("DoorClose");
            self.menu_state.leave_folder();
            self.configure_current_folder_map();
            self.set_scensel_dialog_focus(ScenselDialogFocus::List);
            self.scenario_label = self.menu_state.label_path();
            self.handle_menu_input(|menu| menu.select_default_entry())?;
        }
        Ok(())
    }

    fn close_scenario_browser(&mut self) {
        self.menu_state.abort_renaming();
        self.scensel_rename_pointer_focus = None;
        match self.startup_scenario_back_dialog.take() {
            Some(StartupDialog::MainMenu) => {
                // `SDID_Back` reuses the retained Main dialog, so the
                // remembered ID remains the selector until a later explicit
                // switch replaces it.
                let remembered = self.last_startup_dialog;
                self.begin_startup_dialog_fade(StartupDialog::MainMenu);
                self.show_main_menu();
                self.last_startup_dialog = remembered;
            }
            Some(StartupDialog::NetworkGame) => {
                self.begin_startup_dialog_fade(StartupDialog::NetworkGame);
                self.close_context_menu_silently();
                self.game_option_input_dialog = None;
                self.game_option_input_consumed_keys.clear();
                self.game_option_input_pointer_capture = None;
                self.game_option_consumed_keys.clear();
                self.scenario_game_options.cancel_interaction();
                self.refresh_retained_network_dialog_internet();
                self.replace_startup_view(StartupView::NetworkGame);
                if let Some(dialog) = self.startup_network_dialog.as_mut() {
                    dialog.pointer_left();
                }
                self.status_text.clear();
                self.mark_menu_dirty();
            }
            _ => {
                // `DoStartup` recreated the selector without `pLastDlg`.
                // Native normalizes Back in that state to an explicit Main.
                self.begin_startup_dialog_fade(StartupDialog::MainMenu);
                self.show_main_menu();
            }
        }
    }

    /// Routes a click through the C++-faithful scenario book layout
    /// (Back / Open buttons + list rows, C4StartupScenSelDlg.cpp:1349-1382).
    fn handle_scensel_parity_click(
        &mut self,
        point: GuiPoint,
        suppress_click_focus: bool,
    ) -> Result<(), EngineError> {
        let Some(fonts) = self.assets.clonk_fonts.clone() else {
            return Ok(());
        };
        let layout = lc_frontend::startup_scensel::scen_sel_layout(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
            &fonts,
        );
        let (px, py) = (point.x as i32, point.y as i32);
        let inside =
            |x: i32, y: i32, w: i32, h: i32| px >= x && px < x + w && py >= y && py < y + h;
        if self.scenario_selector_discovery.is_some() {
            let back = layout.back_button;
            if inside(back.x, back.y, back.w, back.h) {
                if !suppress_click_focus {
                    self.set_scensel_dialog_focus(ScenselDialogFocus::Back);
                }
                self.scensel_do_back()?;
            }
            return Ok(());
        }
        if self.menu_state.current_map().is_some() {
            return self.handle_scensel_map_click(point, layout);
        }
        let (back, open, list, search, definitions) = (
            layout.back_button,
            layout.open_button,
            layout.list,
            layout.search_edit,
            layout.user_change_checkbox,
        );
        if inside(search.x, search.y, search.w, search.h) {
            if !suppress_click_focus {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Search);
            }
        } else if inside(definitions.x, definitions.y, definitions.h, definitions.h) {
            if !suppress_click_focus && self.menu_state.definition_checkbox_enabled {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Definitions);
            }
            if self.menu_state.toggle_definition_checkbox() {
                self.play_ui_sound("ArrowHit");
            }
        } else if inside(back.x, back.y, back.w, back.h) {
            if !suppress_click_focus {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Back);
            }
            self.scensel_do_back()?;
        } else if inside(open.x, open.y, open.w, open.h) {
            if !suppress_click_focus {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Open);
            }
            self.handle_menu_input(|menu| menu.menu().handle_key_down(KeyCode::Enter))?;
            self.handle_menu_input(|menu| menu.menu().handle_key_up(KeyCode::Enter))?;
        } else if inside(list.x + 3, list.y + 3, list.w - 6 - 16, list.h - 6) {
            if !suppress_click_focus {
                self.set_scensel_dialog_focus(ScenselDialogFocus::List);
            }
            if let Some(book) = self.assets.book_fonts.clone() {
                let pitch = lc_frontend::startup_scensel::scen_list_item_height(&book.text) + 1;
                let index = ((py - (list.y + 3) + self.menu_state.scenario_list_scroll()) / pitch)
                    .max(0) as usize;
                // Double-click on the selected row opens/starts it
                // (OnSelDblClick -> DoOK, C4StartupScenSelDlg.h:430).
                let now = Instant::now();
                let is_double = self.scensel_last_click.is_some_and(|(last_index, at)| {
                    last_index == index && now.duration_since(at) < Duration::from_millis(500)
                }) && self.menu_state.menu().selected_index() == Some(index);
                self.scensel_last_click = Some((index, now));
                if is_double {
                    self.handle_menu_input(|menu| menu.menu().handle_key_down(KeyCode::Enter))?;
                    self.handle_menu_input(|menu| menu.menu().handle_key_up(KeyCode::Enter))?;
                } else {
                    self.handle_menu_input(|menu| {
                        menu.menu().select_entry_by_index(index).unwrap_or_default()
                    })?;
                }
            }
        }
        Ok(())
    }

    fn handle_scensel_map_click(
        &mut self,
        point: GuiPoint,
        layout: lc_frontend::startup_scensel::ScenSelLayout,
    ) -> Result<(), EngineError> {
        let inside = |rect: lc_frontend::classic_gui::IntRect| {
            point.x >= rect.x as f32
                && point.x < (rect.x + rect.w) as f32
                && point.y >= rect.y as f32
                && point.y < (rect.y + rect.h) as f32
        };
        if inside(layout.user_change_checkbox) {
            if self.menu_state.definition_checkbox_enabled {
                self.set_scensel_dialog_focus(ScenselDialogFocus::Definitions);
            }
            if self.menu_state.toggle_definition_checkbox() {
                self.play_ui_sound("ArrowHit");
            }
            return Ok(());
        }
        if inside(layout.back_button) {
            self.set_scensel_dialog_focus(ScenselDialogFocus::Back);
            return self.scensel_do_back();
        }
        if inside(layout.open_button) {
            self.set_scensel_dialog_focus(ScenselDialogFocus::Open);
            let action = self.menu_state.start_selected_map_scenario();
            return self.handle_menu_input(move |_| action.into_iter().collect());
        }

        let surface = self.graphics.surface();
        let button = {
            let map = self
                .menu_state
                .current_map()
                .expect("map click requires active map data");
            let transform =
                MapFolderTransform::for_map(map, &layout, surface.width(), surface.height());
            if point_in_map_rect(point, &transform.rect(map.scenario_info_area)) {
                None
            } else {
                map_folder_button_at(map, transform, point)
            }
        };
        if let Some(index) = button {
            self.set_scensel_dialog_focus(ScenselDialogFocus::List);
            let action = self.menu_state.activate_map_button(index);
            if action.is_none() {
                self.menu_state.sync_definition_checkbox_to_selection();
                self.sync_scenario_game_option_constraint();
            }
            return self.handle_menu_input(move |_| action.into_iter().collect());
        }
        Ok(())
    }

    /// `MapPic::MouseInput` invokes `DeselectAll` on left-down. Scenario
    /// buttons sit above map pictures and consume the press instead, while a
    /// fullscreen dialog background is not a `MapPic` at all.
    fn handle_scensel_map_pointer_down(&mut self, point: GuiPoint) -> bool {
        if self.scenario_selector_discovery.is_some() {
            return true;
        }
        let Some(fonts) = self.assets.clonk_fonts.as_deref() else {
            return false;
        };
        let Some(map) = self.menu_state.current_map() else {
            return false;
        };
        let surface = self.graphics.surface();
        let layout = lc_frontend::startup_scensel::scen_sel_layout(
            surface.width() as i32,
            surface.height() as i32,
            fonts,
        );
        let transform = MapFolderTransform::for_map(
            map,
            &layout,
            surface.width(),
            surface.height(),
        );
        if point_in_map_rect(point, &transform.rect(map.scenario_info_area)) {
            return true;
        }
        if map_folder_button_at(map, transform, point).is_some() {
            return true;
        }
        let map_picture = (!map.fullscreen_background
            && point_in_map_rect(point, &transform.background))
            || map
                .access_overlays
                .iter()
                .any(|overlay| point_in_map_rect(point, &transform.rect(overlay.area)));
        if !map_picture {
            return false;
        }
        if self.menu_state.deselect_map() {
            self.play_ui_sound("ArrowHit");
        }
        self.sync_scenario_game_option_constraint();
        self.mark_menu_dirty();
        true
    }

    fn start_selected_map_scenario_from_ui(&mut self) -> Result<(), EngineError> {
        let action = self.menu_state.start_selected_map_scenario();
        self.handle_menu_input(move |_| action.into_iter().collect())
    }

    fn open_scenario_browser(&mut self) {
        self.open_scenario_browser_with_mode(ScenarioSelectorMode::Local);
    }

    fn visible_startup_dialog(&self) -> Option<StartupDialog> {
        match self.startup_view {
            StartupView::MainMenu => Some(StartupDialog::MainMenu),
            StartupView::ScenarioBrowser => Some(StartupDialog::ScenarioBrowser(
                self.scenario_selector_mode,
            )),
            StartupView::NetworkGame => Some(StartupDialog::NetworkGame),
            StartupView::Options => Some(StartupDialog::Options),
            StartupView::About => Some(StartupDialog::About),
            StartupView::PlayerSelection => Some(StartupDialog::PlayerSelection),
            // C4GameLobby is a game state, not a C4Startup dialog.
            StartupView::NetworkLobby => None,
        }
    }

    fn render_inactive_startup_dialog_layer(&mut self, frame: &mut [u8]) -> Result<()> {
        let scenario_loading_label = self.scenario_selector_loading_label();
        let gamma = self.startup_fragment_gamma();
        render_startup_frame(
            &mut self.graphics,
            self.assets.as_ref(),
            &mut self.main_menu_state,
            &mut self.menu_state,
            &self.scenario_entry_enabled,
            scenario_loading_label.as_deref(),
            self.startup_network_dialog.as_ref(),
            self.startup_player_dialog.as_ref(),
            &self.startup_player_models,
            &self.startup_crew_models,
            self.startup_crew_rename.as_mut(),
            None,
            true,
            true,
            true,
            true,
            &self.scenario_game_options,
            self.scenario_selector_mode,
            self.startup_options_dialog.as_ref(),
            None,
            false,
            self.startup_about_dialog.as_ref(),
            self.startup_view,
            None,
            self.startup_view_flags,
            &mut self.menu_backdrop_cache,
            false,
            &gamma,
            frame,
        )
    }

    fn capture_startup_dialog_fade_layers(&mut self) -> Result<StartupDialogFadeLayers> {
        let (width, height) = {
            let surface = self.graphics.surface();
            (surface.width(), surface.height())
        };
        let mut underlay = vec![0_u8; width as usize * height as usize * 4];
        let gamma = self.startup_fragment_gamma();
        render_startup_underlay(
            &mut self.graphics,
            self.assets.as_ref(),
            &gamma,
            &mut underlay,
        );
        let mut outgoing = vec![0_u8; underlay.len()];
        self.render_inactive_startup_dialog_layer(&mut outgoing)?;

        self.begin_native_text_capture(false);
        let mut outgoing_native = vec![0_u8; underlay.len()];
        let native_result = self.render_inactive_startup_dialog_layer(&mut outgoing_native);
        let outgoing_native_text = self.graphics.surface_mut().take_clonk_text_capture();
        native_result?;

        Ok(StartupDialogFadeLayers {
            width,
            height,
            underlay,
            outgoing_frame: outgoing,
            outgoing_native_frame: outgoing_native,
            outgoing_native_text,
        })
    }

    fn begin_startup_dialog_fade(&mut self, incoming: StartupDialog) {
        let Some(outgoing) = self.visible_startup_dialog() else {
            return;
        };
        if self.mode != AppMode::Menu {
            return;
        }
        self.pointer_left_unchecked();
        let layers = match self.capture_startup_dialog_fade_layers() {
            Ok(layers) => layers,
            Err(error) => {
                tracing::error!(%error, "failed to capture outgoing startup dialog fade layer");
                return;
            }
        };
        self.startup_dialog_fade = Some(StartupDialogFade {
            outgoing: Some(outgoing),
            incoming,
            step: 0,
            width: layers.width,
            height: layers.height,
            underlay: layers.underlay,
            outgoing_frame: Some(layers.outgoing_frame),
            outgoing_native_frame: Some(layers.outgoing_native_frame),
            outgoing_native_text: layers.outgoing_native_text,
            outgoing_native_fonts: self.native_startup_fonts.clone(),
        });
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
    }

    fn begin_startup_dialog_fade_in(&mut self) {
        let Some(incoming) = self.visible_startup_dialog() else {
            return;
        };
        if self.mode != AppMode::Menu {
            return;
        }
        self.pointer_left_unchecked();
        let (width, height) = {
            let surface = self.graphics.surface();
            (surface.width(), surface.height())
        };
        let mut underlay = vec![0_u8; width as usize * height as usize * 4];
        let gamma = self.startup_fragment_gamma();
        render_startup_underlay(
            &mut self.graphics,
            self.assets.as_ref(),
            &gamma,
            &mut underlay,
        );
        self.startup_dialog_fade = Some(StartupDialogFade {
            outgoing: None,
            incoming,
            step: 0,
            width,
            height,
            underlay,
            outgoing_frame: None,
            outgoing_native_frame: None,
            outgoing_native_text: Vec::new(),
            outgoing_native_fonts: None,
        });
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
    }

    fn replace_startup_view(&mut self, view: StartupView) {
        // Destroying/replacing a native dialog clears CMouse's owned
        // pMouseOverElement. Retaining only the screen coordinate would
        // otherwise invent a target in the new view without mouse input.
        self.startup_tooltip.pointer_left();
        self.menu_frame_cache = None;
        if view != StartupView::Options {
            self.startup_options_advanced_dialog = None;
            self.gamepads.set_options_open_slot(None);
        }
        if view != StartupView::ScenarioBrowser {
            self.cancel_scenario_selector_discovery();
        }
        self.startup_view = view;
        let keeps_pending_fade = self
            .visible_startup_dialog()
            .zip(self.startup_dialog_fade.as_ref())
            .is_some_and(|(dialog, fade)| dialog == fade.incoming);
        if !keeps_pending_fade {
            self.startup_dialog_fade = None;
        }
    }

    fn replace_startup_dialog(&mut self, view: StartupView, dialog: StartupDialog) {
        self.last_startup_dialog = dialog;
        self.replace_startup_view(view);
    }

    fn restore_startup_dialog(&mut self, dialog: StartupDialog) {
        if !matches!(dialog, StartupDialog::MainMenu) {
            // `show_main_menu` is also the teardown hub and may have opened
            // its first-player prompt. Native DoStartup constructs only the
            // remembered non-Main dialog, so that Main-only child must not
            // leak above the restored screen.
            self.startup_player_properties_dialog = None;
        }
        match dialog {
            StartupDialog::MainMenu => {}
            StartupDialog::ScenarioBrowser(mode) => {
                self.open_scenario_browser_with_mode(mode);
                self.startup_scenario_back_dialog = None;
            }
            StartupDialog::NetworkGame => self.open_network_game_dialog(),
            StartupDialog::Options => self.open_options_menu(),
            StartupDialog::About => self.open_about_dialog(),
            StartupDialog::PlayerSelection => self.open_player_selection_dialog(),
        }
    }

    fn open_network_host_scenario_browser(&mut self) {
        self.open_scenario_browser_with_mode(ScenarioSelectorMode::NetworkHost);
    }

    fn open_scenario_browser_with_mode(&mut self, selector_mode: ScenarioSelectorMode) {
        self.cancel_scenario_selector_discovery();
        self.menu_state.abort_renaming();
        self.close_context_menu_silently();
        self.startup_player_properties_dialog = None;
        self.game_option_input_dialog = None;
        self.league_signup_dialog = None;
        self.cancelled_league_signup_continuation = None;
        self.league_signup_consumed_keys.clear();
        self.league_signup_pointer_capture = false;
        self.league_signup_pointer_position = None;
        self.game_option_input_consumed_keys.clear();
        self.game_option_input_pointer_capture = None;
        self.game_option_pointer_capture = false;
        self.game_option_consumed_keys.clear();
        self.scenario_selector_mode = selector_mode;
        self.startup_scenario_back_dialog = Some(match selector_mode {
            ScenarioSelectorMode::Local => StartupDialog::MainMenu,
            ScenarioSelectorMode::NetworkHost => StartupDialog::NetworkGame,
        });
        let values = load_scenario_game_option_values(self.app_paths.as_ref());
        self.startup_view_flags.fair_crew = values.fair_crew;
        self.startup_view_flags.record = values.record;
        self.recording_enabled = values.record && self.recordings_dir.is_some();
        self.scenario_game_options =
            GameOptionButtons::new(selector_mode.game_option_context(), values);
        self.apply_classic_game_option_overrides();
        self.replace_startup_dialog(
            StartupView::ScenarioBrowser,
            StartupDialog::ScenarioBrowser(selector_mode),
        );
        self.menu_state.set_pointer_position(None);
        self.menu_state.scensel_title_present = true;
        self.menu_state.scensel_title_topmost = false;
        // The C++ dialog reloads from the root folder every time it is
        // shown (OnShown -> pScenLoader->Load(ExePath), cpp:1431-1443).
        self.menu_state.stack.truncate(1);
        self.menu_state.clear_search();
        self.menu_state.scenario_list_scroll = 0;
        self.menu_state.selection_info_scroll = 0;
        self.menu_state.scrollbar_interaction = None;
        self.menu_state.set_dialog_focus(ScenselDialogFocus::List);
        // The C++ book has no Back list entry — Back is a button/K_LEFT
        // (C4StartupScenSelDlg.cpp:1367-1369,1388-1389).
        self.menu_state.set_include_back(false);
        self.refresh_scenario_entry_enabled();
        self.menu_state.refresh_menu_entries();
        let width = self.graphics.surface().width() as f32;
        let height = self.graphics.surface().height() as f32;
        self.menu_state.menu().resize(width, height);
        if let Err(err) = self.handle_menu_input(|menu| menu.select_default_entry()) {
            tracing::error!(error = %err, "failed to select default scenario entry");
        }
        self.sync_scenario_game_option_bounds();
        self.sync_scenario_game_option_constraint();
        self.scenario_label = self.menu_state.label_path();
        self.status_text.clear();
    }

    fn open_network_lobby(&mut self) {
        self.close_context_menu_silently();
        self.replace_startup_view(StartupView::NetworkLobby);
        self.menu_state.set_pointer_position(None);
        self.menu_state.set_include_back(true);
        self.menu_state.refresh_menu_entries();
        let width = self.graphics.surface().width() as f32;
        let height = self.graphics.surface().height() as f32;
        self.menu_state.menu().resize(width, height);
        if let Err(err) = self.handle_menu_input(|menu| menu.select_default_entry()) {
            tracing::error!(error = %err, "failed to select default scenario entry");
        }
        let labels = self.classic_lobby_labels();
        if let Some(lobby) = self.network_lobby.as_mut() {
            lobby.labels = labels;
            lobby.update_layout(width, height);
            self.scenario_label = lobby.scenario_label();
        } else {
            self.scenario_label = "Network lobby unavailable".to_string();
        }
        self.sync_network_lobby_game_option_state();
        self.status_text.clear();
        self.acknowledge_initial_lobby_status_if_ready();
    }

    fn localized_irc_chat_strings(&self) -> lc_frontend::startup_netdlg::NetDlgChatStrings {
        let command_template = |key: &str, fallback: &str| {
            self.runtime_resource_text(key, fallback)
                .replace("%s", "{command}")
        };
        lc_frontend::startup_netdlg::NetDlgChatStrings {
            chat: self.runtime_resource_text("IDS_DLG_CHAT", "Chat"),
            not_connected: self.runtime_resource_text("IDS_CHAT_NOTCONNECTED", "not connected"),
            server: self.runtime_resource_text("IDS_CHAT_SERVER", "Server"),
            nick: self.runtime_resource_text("IDS_CTL_NICK", "Nickname:"),
            password_optional: self
                .runtime_resource_text("IDS_CTL_PASSWORDOPTIONAL", "Password (optional):"),
            real_name: self.runtime_resource_text("IDS_CTL_REALNAME", "Real name:"),
            channel: self.runtime_resource_text("IDS_CTL_CHANNEL", "Channel:"),
            connect: self.runtime_resource_text("IDS_BTN_CONNECT", "Connect"),
            no_message: "No message entered".to_string(),
            not_connected_error: self
                .runtime_resource_text("IDS_ERR_NOTCONNECTEDTOSERVER", "Not connected to server."),
            insufficient_parameters: command_template(
                "IDS_ERR_INSUFFICIENTPARAMETERS",
                "/%s: insufficient parameters",
            ),
            invalid_nick: command_template("IDS_ERR_INVALIDNICKNAME2", "/%s: invalid nick name"),
            unknown_command: command_template(
                "IDS_ERR_UNKNOWNCMD",
                "Unknown command: \"%s\" - type /help to get a list of valid commands",
            ),
            not_on_channel: self
                .runtime_resource_text("IDS_ERR_NOTONACHANNEL", "Not on a channel."),
        }
    }

    fn new_network_dialog_controller(&self) -> lc_frontend::startup_netdlg::NetDlgController {
        let (masterserver_signup, _) = load_network_startup_settings(self.app_paths.as_ref());
        let metrics = self
            .assets
            .clonk_fonts
            .as_deref()
            .map(lc_frontend::startup_netdlg::NetDlgFontMetrics::from_fonts)
            .unwrap_or(lc_frontend::startup_netdlg::NetDlgFontMetrics {
                caption_back_extent: 51,
                text_ip_extent: 18,
                text_line_height: 22,
                caption_line_height: 25,
                title_line_height: 34,
            });
        let mut dialog = lc_frontend::startup_netdlg::NetDlgController::new(
            lc_frontend::startup_netdlg::NetDlgConfig {
                masterserver_signup,
                record: self.startup_view_flags.record,
            },
            metrics,
        );
        dialog.set_chat_strings(self.localized_irc_chat_strings());
        dialog.set_chat_login(load_irc_settings(self.app_paths.as_ref()).login());
        dialog.set_chat_history(self.message_input_history.iter().cloned().collect());
        if let Some(fonts) = self.assets.clonk_fonts.as_deref() {
            dialog.set_text_font(&fonts.text);
        }
        dialog.resize(
            self.graphics.surface().width() as i32,
            self.graphics.surface().height() as i32,
        );
        dialog
    }

    fn open_network_game_dialog(&mut self) {
        self.external_irc_dialog_visible = false;
        self.external_irc_dialog = None;
        self.hide_runtime_default_dialog(RuntimeDefaultDialog::ExternalIrc);
        self.irc_dialog_last_click = None;
        self.external_irc_pointer_capture = false;
        self.close_context_menu_silently();
        self.status_text.clear();
        self.startup_network_refresh_waiting_for_clear = false;
        self.startup_network_ignore_redirect = false;
        self.startup_game_references.clear();
        self.startup_discovery_reference_queries.clear();
        self.startup_direct_reference_queries.clear();
        self.netdlg_last_click = None;
        self.netdlg_join_edit_last_click = None;
        self.netdlg_edit_consumed_keys.clear();
        self.pending_network_join = None;
        let mut dialog = self.new_network_dialog_controller();
        let search_config = load_network_search_settings(self.app_paths.as_ref());
        let masterserver_enabled = search_config.internet_enabled;
        dialog.set_masterserver_entry(Self::startup_masterserver_query_entry(
            self.app_paths.as_ref(),
            &search_config.master_server_url,
        ));
        let reference_config = load_reference_query_settings(self.app_paths.as_ref());
        self.startup_game_search = match lc_network::StartupGameSearch::start_with_reference_config(
            search_config,
            reference_config,
        ) {
            Ok(search) => {
                if search.initial_refresh().is_err() {
                    self.status_text = "Unable to start network game search".to_string();
                }
                Some(search)
            }
            Err(error) => {
                self.status_text = format!("Unable to start network game search: {error}");
                None
            }
        };
        self.startup_network_dialog = Some(dialog);
        self.replace_startup_dialog(StartupView::NetworkGame, StartupDialog::NetworkGame);
        self.sync_startup_irc_snapshot();
        let now = Instant::now();
        self.startup_network_last_refresh = Some(now);
        self.startup_masterserver_next_query_at = if masterserver_enabled {
            now.checked_add(lc_network::GAME_SEARCH_INTERVAL)
        } else {
            None
        };
    }

    /// C4StartupNetDlg::OnShown refreshes the Internet icon and query-row
    /// presence from Config; its Record icon intentionally retains the
    /// controller's older value.
    fn refresh_retained_network_dialog_internet(&mut self) {
        let (masterserver_signup, _) = load_network_startup_settings(self.app_paths.as_ref());
        let recreate_masterserver = self.startup_network_dialog.as_mut().is_some_and(|dialog| {
            let recreate = !dialog.config().masterserver_signup && masterserver_signup;
            dialog.sync_masterserver_signup_from_config(masterserver_signup);
            recreate
        });
        if let Some(search) = self.startup_game_search.as_ref() {
            let _ = search.set_internet_enabled(masterserver_signup);
        }
        if !masterserver_signup {
            self.startup_masterserver_next_query_at = None;
        }
        if recreate_masterserver {
            let now = Instant::now();
            self.startup_network_last_refresh = Some(now);
            self.startup_masterserver_next_query_at =
                now.checked_add(lc_network::GAME_SEARCH_INTERVAL);
            self.reset_startup_masterserver_entry();
        }
    }

    fn open_player_selection_dialog(&mut self) {
        self.abort_startup_crew_rename();
        self.close_context_menu_silently();
        self.startup_player_properties_dialog = None;
        self.startup_crew_files.clear();
        self.startup_crew_models.clear();
        self.startup_crew_player_index = None;
        let activation_refusals = self
            .app_paths
            .as_ref()
            .map(AppPaths::config_file)
            .map(|config_path| {
                persist_activations(&config_path, &mut self.startup_player_files)
            })
            .transpose();
        let activation_refusals = match activation_refusals {
            Ok(Some(refusals)) => refusals,
            Ok(None) => Vec::new(),
            Err(error) => {
                tracing::warn!(%error, "failed to validate participants while opening player selection");
                Vec::new()
            }
        };
        for refusal in &activation_refusals {
            if let Some(player) = self.startup_player_models.get_mut(refusal.index) {
                player.activated = false;
            }
        }
        if !activation_refusals.is_empty() {
            self.selected_player_file = self
                .startup_player_files
                .iter()
                .find(|player| player.render_model.activated)
                .map(|player| player.player_file.clone());
        }
        let mut dialog =
            lc_frontend::startup_plrsel::PlrSelController::new(self.startup_player_models.len());
        dialog.set_player_activations(
            self.startup_player_models
                .iter()
                .map(|player| player.activated)
                .collect(),
        );
        let width = self.graphics.surface().width() as i32;
        let height = self.graphics.surface().height() as i32;
        if let (Some(fonts), Some(book)) = (
            self.assets.clonk_fonts.as_deref(),
            self.assets.plrsel_book_fonts.as_deref(),
        ) {
            dialog.resize_with_fonts(width, height, fonts, book);
        } else {
            dialog.resize(width, height);
        }
        self.startup_player_dialog = Some(dialog);
        self.plrsel_last_click = None;
        self.replace_startup_dialog(
            StartupView::PlayerSelection,
            StartupDialog::PlayerSelection,
        );
        self.status_text.clear();
        if let Err(error) =
            self.show_startup_player_activation_refusals(&activation_refusals)
        {
            tracing::error!(%error, "failed to show participant overflow while opening player selection");
        }
    }

