    #[test]
    fn classic_command_line_preserves_file_and_definition_order() {
        let classic = parse_classic_command_line(&[
            OsString::from("First.c4s"),
            OsString::from("Players/Alice.C4P"),
            OsString::from("Defs/ExtraOne.c4d"),
            OsString::from("Players/Bob.c4p"),
            OsString::from("Defs/ExtraTwo.C4D"),
            OsString::from("Missions/Last/Scenario.TXT"),
            OsString::from("Patch.c4u"),
            OsString::from("Round.c4r"),
        ]);

        assert_eq!(classic.scenario, Some(PathBuf::from("Missions/Last")));
        assert_eq!(
            classic.player_files,
            vec![
                PathBuf::from("Players/Alice.C4P"),
                PathBuf::from("Players/Bob.c4p")
            ]
        );
        assert_eq!(
            classic.definition_files,
            vec![
                PathBuf::from("Defs/ExtraOne.c4d"),
                PathBuf::from("Defs/ExtraTwo.C4D")
            ]
        );
        assert_eq!(classic.incoming_update, Some(PathBuf::from("Patch.c4u")));
        assert_eq!(classic.record_stream, Some(PathBuf::from("Round.c4r")));
        assert_eq!(
            classic_command_line_definition_modules(
                b"[General]\nDefinitions=Base.c4d;Second.c4d\n",
                &classic.definition_files,
            ),
            vec![
                "Base.c4d",
                "Second.c4d",
                "Defs/ExtraOne.c4d",
                "Defs/ExtraTwo.C4D",
            ]
        );
        assert_eq!(
            classic_command_line_definition_modules(
                b"[General]\nDefinitions=;Base.c4d;;Second.c4d;\n",
                &[],
            ),
            vec!["", "Base.c4d", "", "Second.c4d"],
            "std::getline preserves leading/interior empty modules but not a trailing delimiter"
        );
    }

    #[test]
    fn classic_recdump_writes_cpp_text_and_binary_outputs() {
        let directory = tempdir().expect("record-dump tempdir");
        let text_path = directory.path().join("dump.TXT");
        let leading_dot_text_path = directory.path().join(".tXt");
        let binary_path = directory.path().join("dump.c4b");
        // One RCT_Ctrl with a noncanonical two-byte packed zero, followed by
        // End and an ignored suffix. C4Playback fully loads the record,
        // canonicalizes typed payloads, and stops at the first End.
        let input = [
            5,
            lc_engine::RCT_CTRL,
            0x86,
            1,
            1,
            0x80,
            0,
            0xff,
            42,
            lc_engine::RCT_END,
            9,
            lc_engine::RCT_FRAME,
        ];

        let chunks = lc_network::decode_control_record(&input).expect("decode replay fixture");
        write_classic_record_dump(&chunks, &text_path).expect("write text /recdump");
        write_classic_record_dump(&chunks, &leading_dot_text_path)
            .expect("write leading-dot text /recdump");
        write_classic_record_dump(&chunks, &binary_path).expect("write binary /recdump");

        let expected_text = concat!(
            "[Rec]\r\n",
            "Frame=5\r\n",
            "Type=0\r\n",
            "\r\n",
            "  [IDPacket]\r\n",
            "  ID=134\r\n",
            "\r\n",
            "    [Synchronize]\r\n",
            "    SavePlrs=true\r\n",
            "    SyncClear=true\r\n",
            "    ByClient=0\r\n",
            "\n\n",
            "[Rec]\r\n",
            "Frame=47\r\n",
            "Type=16\r\n",
            "\n\n",
        );
        assert_eq!(fs::read(&text_path).unwrap(), expected_text.as_bytes());
        assert_eq!(
            fs::read(&leading_dot_text_path).unwrap(),
            expected_text.as_bytes()
        );
        assert_eq!(
            fs::read(&binary_path).unwrap(),
            [
                5,
                lc_engine::RCT_CTRL,
                0x86,
                1,
                1,
                0,
                0xff,
                42,
                lc_engine::RCT_END,
            ]
        );

        let missing_parent = directory.path().join("missing/dump.c4b");
        let error = write_classic_record_dump(&chunks, &missing_parent)
            .expect_err("an unwritable destination must fail replay loading");
        assert!(
            error
                .to_string()
                .contains("failed to write classic record dump"),
            "unexpected write diagnostic: {error:#}"
        );
    }

