    #[test]
    fn l085_lobby_options_refresh_only_while_the_sheet_is_active() {
        let mut app = new_menu_app(640, 480);
        let (_events, _commands) = install_classic_host_network_stub(&mut app);
        app.engine.set_control_rate(4);
        app.network_control_clock = Some(NetworkControlClock::new(0, 4));

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::SheetRequested(
            LobbySheet::Options,
        )])
        .expect("activate the Options list");
        let option_value = |app: &GameApp, kind| {
            app.classic_host_lobby
                .as_ref()
                .unwrap()
                .controller
                .option_rows()
                .iter()
                .find(|row| row.kind == kind)
                .unwrap()
                .value
                .clone()
        };
        assert_eq!(option_value(&app, LobbyOptionKind::ControlRate), "4");

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::SheetRequested(
            LobbySheet::Players,
        )])
        .expect("deactivate the Options list");
        app.network_control_clock
            .as_mut()
            .unwrap()
            .set_control_rate(7);
        app.sec1_timer().expect("pulse the inactive second timer");
        assert_eq!(
            option_value(&app, LobbyOptionKind::ControlRate),
            "4",
            "inactive options retain their last snapshot"
        );

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::SheetRequested(
            LobbySheet::Options,
        )])
        .expect("reactivation forces an immediate update");
        assert_eq!(option_value(&app, LobbyOptionKind::ControlRate), "7");

        app.network_control_clock
            .as_mut()
            .unwrap()
            .set_control_rate(8);
        app.sec1_timer().expect("pulse the active second timer");
        assert_eq!(option_value(&app, LobbyOptionKind::ControlRate), "8");
    }

    #[test]
    fn l085_control_rate_submits_relative_set_and_waits_for_echo() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated control-rate user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let mut app = new_menu_app(640, 480);
        app.app_paths = Some(paths.clone());
        let (_events, mut commands) = install_classic_host_network_stub(&mut app);
        app.engine.set_control_rate(4);
        app.network_control_clock = Some(NetworkControlClock::new(0, 4));
        assert!(app.select_classic_lobby_sheet(LobbySheet::Options));

        app.submit_classic_lobby_control_rate(7);
        let sets = commands.take_submitted_control_sets();
        assert_eq!(
            sets,
            [lc_network::LegacyControlSet {
                value_type: 0,
                data: 3,
                by_client: 0,
            }]
        );
        assert_eq!(app.engine.control_rate(), 4);
        assert_eq!(
            app.network_control_clock.unwrap().control_rate(),
            4,
            "the menu selection is not an optimistic clock mutation"
        );
        assert!(app.classic_host_lobby.as_ref().unwrap().controller.option_rows().iter().any(
            |row| row.kind == LobbyOptionKind::ControlRate && row.value == "4"
        ));

        app.execute_control_set(sets[0]);
        assert_eq!(app.engine.control_rate(), 7);
        assert_eq!(app.network_control_clock.unwrap().control_rate(), 7);
        assert_eq!(
            Config::load(paths.config_file())
                .expect("reload echoed control rate")
                .get_in(Some("Network"), "ControlRate"),
            Some("7"),
            "only the authoritative host echo writes the next-session setting"
        );
        assert!(app.classic_host_lobby.as_ref().unwrap().controller.option_rows().iter().any(
            |row| row.kind == LobbyOptionKind::ControlRate && row.value == "7"
        ));

        app.submit_classic_lobby_control_rate(7);
        app.submit_classic_lobby_control_rate(10);
        assert!(commands.take_submitted_control_sets().is_empty());
    }

    #[test]
    fn l085_runtime_join_persists_inverse_policy_and_refreshes_the_host_row() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated lobby-option user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let mut app = new_menu_app_with_paths(640, 480, &paths);
        let (_events, mut commands) = install_classic_host_network_stub(&mut app);
        assert!(app.select_classic_lobby_sheet(LobbySheet::Options));

        app.set_classic_lobby_runtime_join(true);
        assert!(
            commands.take_lobby_start_commands().is_empty(),
            "changing the future policy must not close current lobby admission"
        );
        assert!(app
            .classic_host_lobby
            .as_ref()
            .is_some_and(|lobby| lobby.runtime_join_allowed));
        assert!(app.classic_host_lobby.as_ref().unwrap().controller.option_rows().iter().any(
            |row| row.kind == LobbyOptionKind::RuntimeJoin
                && row.value == "Runtime join allowed"
        ));
        assert_eq!(
            Config::load(paths.config_file())
                .expect("reload enabled runtime-join policy")
                .get_in(Some("Network"), "NoRuntimeJoin"),
            Some("0")
        );

        app.set_classic_lobby_runtime_join(false);
        assert!(
            commands.take_lobby_start_commands().is_empty(),
            "the prohibited policy is applied only when the lobby exits"
        );
        assert!(!app
            .classic_host_lobby
            .as_ref()
            .is_some_and(|lobby| lobby.runtime_join_allowed));
        assert_eq!(
            Config::load(paths.config_file())
                .expect("reload prohibited runtime-join policy")
                .get_in(Some("Network"), "NoRuntimeJoin"),
            Some("1")
        );
    }

    #[test]
    fn l134_team_options_submit_exact_sets_and_refresh_from_echoes() {
        let mut app = new_menu_app(640, 480);
        let (_events, mut commands) = install_classic_host_network_stub(&mut app);
        let metadata = set_control_test_metadata(
            false,
            vec![
                set_control_test_team(1, Vec::new(), 0),
                set_control_test_team(2, Vec::new(), 0),
            ],
        );
        app.network_team_assignment =
            Some(NetworkTeamAssignmentState::from_prepared_host(metadata));
        assert!(app.select_classic_lobby_sheet(LobbySheet::Options));

        app.submit_classic_lobby_team_setting(LobbyOptionKind::TeamDistribution, 4);
        app.submit_classic_lobby_team_setting(LobbyOptionKind::TeamColors, 1);
        let sets = commands.take_submitted_control_sets();
        assert_eq!(
            sets,
            [
                lc_network::LegacyControlSet {
                    value_type: 3,
                    data: 4,
                    by_client: 0,
                },
                lc_network::LegacyControlSet {
                    value_type: 4,
                    data: 1,
                    by_client: 0,
                },
            ]
        );
        let teams = app.network_team_assignment.as_ref().unwrap().teams();
        assert_eq!(
            teams.team_distribution,
            lc_engine::InitialNetworkTeamDistribution::Free
        );
        assert!(!teams.team_colors, "menu selections wait for host echoes");

        app.execute_control_set(sets[0]);
        app.execute_control_set(sets[1]);
        let options = app
            .classic_host_lobby
            .as_ref()
            .unwrap()
            .controller
            .option_rows();
        assert!(options.iter().any(|row| {
            row.kind == LobbyOptionKind::TeamDistribution && row.value == "surprise random!"
        }));
        assert!(options.iter().any(|row| {
            row.kind == LobbyOptionKind::TeamColors && row.value == "enabled"
        }));
        assert!(options
            .iter()
            .any(|row| row.kind == LobbyOptionKind::RandomTeamCount));

        app.submit_classic_lobby_team_setting(LobbyOptionKind::TeamDistribution, 2);
        assert!(
            commands.take_submitted_control_sets().is_empty(),
            "None is not offered for predefined teams"
        );
    }

    #[test]
    fn l134_random_team_count_mutates_host_directly_and_tracks_distribution() {
        let mut app = new_menu_app(640, 480);
        let (_events, mut commands) = install_classic_host_network_stub(&mut app);
        let mut metadata = set_control_test_metadata(
            true,
            vec![
                set_control_test_team(1, vec![1], 0),
                set_control_test_team(2, vec![2], 0),
            ],
        );
        metadata.team_distribution = lc_engine::InitialNetworkTeamDistribution::Random;
        let mut snapshot = lc_network::HostConfig::default()
            .initial_join_snapshot
            .expect("default host JoinData");
        snapshot.parameters.teams = lc_network::join_team_list_snapshot(metadata.clone());
        app.host_join_snapshot = Some(snapshot);
        app.network_team_assignment = Some(NetworkTeamAssignmentState::from_prepared_host(
            metadata,
        ));
        app.control_player_infos.replace_snapshot(
            3,
            [lc_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![
                    set_control_test_player(1, 1, 0),
                    set_control_test_player(2, 2, lc_engine::PLAYER_INFO_FLAG_INVISIBLE),
                    set_control_test_player(3, 1, lc_engine::PLAYER_INFO_FLAG_REMOVED),
                ],
                ..Default::default()
            }],
        );
        assert!(app.select_classic_lobby_sheet(LobbySheet::Options));
        let random = app
            .classic_host_lobby
            .as_ref()
            .unwrap()
            .controller
            .option_rows()
            .iter()
            .find(|row| row.kind == LobbyOptionKind::RandomTeamCount)
            .expect("random mode shows the count row");
        assert_eq!(
            random
                .choices
                .iter()
                .map(|choice| choice.id)
                .collect::<Vec<_>>(),
            [0, 2],
            "the maximum includes invisible players and excludes removed players"
        );

        app.set_classic_lobby_random_team_count(2);
        let (player_infos, snapshots) = commands.take_team_control_updates();
        assert_eq!(player_infos.len(), 1);
        assert_eq!(snapshots.len(), 1);
        let teams = app.network_team_assignment.as_ref().unwrap().teams();
        assert_eq!(teams.random_team_count, 2);
        assert_eq!(teams.teams.len(), 2);
        assert_eq!(
            app.host_join_snapshot
                .as_ref()
                .unwrap()
                .parameters
                .teams
                .random_team_count,
            2
        );
        assert!(app
            .classic_host_lobby
            .as_ref()
            .unwrap()
            .controller
            .option_rows()
            .iter()
            .any(|row| row.kind == LobbyOptionKind::RandomTeamCount && row.value == "2"));

        app.execute_control_set(lc_network::LegacyControlSet {
            value_type: 3,
            data: 0,
            by_client: 0,
        });
        assert!(!app
            .classic_host_lobby
            .as_ref()
            .unwrap()
            .controller
            .option_rows()
            .iter()
            .any(|row| row.kind == LobbyOptionKind::RandomTeamCount));
        app.execute_control_set(lc_network::LegacyControlSet {
            value_type: 3,
            data: 4,
            by_client: 0,
        });
        assert!(app
            .classic_host_lobby
            .as_ref()
            .unwrap()
            .controller
            .option_rows()
            .iter()
            .any(|row| row.kind == LobbyOptionKind::RandomTeamCount));
    }

    #[test]
    fn l082_classic_lobby_internet_signup_is_pollable_and_rolls_back_failure() {
        let mut app = new_menu_app(640, 480);
        let (_events, mut commands) = install_classic_host_network_stub(&mut app);
        let (_snapshot, reference) = default_exact_host_reference();
        app.advertised_game_reference = Some(reference);

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::GameOptions(
            LobbyGameOptionInput::Hotkey('I'),
        )])
        .expect("queue live lobby registration without blocking");
        assert!(!app.scenario_game_options.values().master_server_signup);
        let enable = commands.receive_masterserver_signup();
        assert!(enable.enabled);
        assert!(!enable.config.league_server_signup);
        assert_eq!(enable.reference.summary().state, "Lobby");
        enable.complete(Ok(Some(lc_network::LeagueStartResponse::default())));
        app.poll_live_masterserver_signup()
            .expect("apply live signup completion");
        assert!(app.scenario_game_options.values().master_server_signup);

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::GameOptions(
            LobbyGameOptionInput::Hotkey('I'),
        )])
        .expect("queue live lobby deregistration without blocking");
        assert!(app.scenario_game_options.values().master_server_signup);
        let disable = commands.receive_masterserver_signup();
        assert!(!disable.enabled);
        disable.complete(Ok(None));
        app.poll_live_masterserver_signup()
            .expect("apply live deregistration completion");
        assert!(!app.scenario_game_options.values().master_server_signup);
        assert!(!app.scenario_game_options.values().league_server_signup);

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::GameOptions(
            LobbyGameOptionInput::Hotkey('I'),
        )])
        .expect("queue rejected registration without blocking");
        let rejected = commands.receive_masterserver_signup();
        assert!(rejected.enabled);
        rejected.complete(Err("masterserver rejected the game".to_string()));
        app.poll_live_masterserver_signup()
            .expect("apply rejected live registration");
        assert!(!app.scenario_game_options.values().master_server_signup);
        assert!(app
            .status_text
            .contains("masterserver rejected the game"));
    }

    #[test]
    fn l082_aborting_live_internet_signup_keeps_the_prior_off_state() {
        let mut app = new_menu_app(640, 480);
        let (_events, mut commands) = install_classic_host_network_stub(&mut app);
        let (_snapshot, reference) = default_exact_host_reference();
        app.advertised_game_reference = Some(reference);

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::GameOptions(
            LobbyGameOptionInput::Hotkey('I'),
        )])
        .expect("queue live signup without waiting for its HTTP response");
        assert!(!app.scenario_game_options.values().master_server_signup);
        assert!(app.pending_lobby_internet_signup.is_some());
        let wait = app.message_dialogs.last().expect("cancellable wait dialog");
        assert!(matches!(
            wait.continuation,
            MessageDialogContinuation::LiveMasterserverSignup
        ));
        assert_eq!(
            wait.state.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::Standard(3)
        );
        assert_eq!(
            wait.state.button_label(
                lc_frontend::message_dialog::MessageDialogButton::Cancel
            ),
            "Abort"
        );

        let pending_command = commands.receive_masterserver_signup();
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Cancel)
            .expect("Abort closes the signup wait");
        pending_command.wait_for_cancellation();
        assert!(app.pending_lobby_internet_signup.is_none());
        assert!(!app.scenario_game_options.values().master_server_signup);
        assert_eq!(app.status_text, "Internet game signup cancelled.");
    }

    #[test]
    fn l082_live_signup_applies_every_start_response_field() {
        let mut app = new_menu_app(640, 480);
        let (_events, mut commands) = install_classic_host_network_stub(&mut app);
        let (snapshot, reference) = default_exact_host_reference();
        app.host_join_snapshot = Some(snapshot);
        app.advertised_game_reference = Some(reference);
        let league = LegacyCString::from_bytes(b"Cup".to_vec()).unwrap();
        let stream_to = LegacyCString::from_bytes(
            b"https://stream.example/upload?".to_vec(),
        )
        .unwrap();
        let response = lc_network::LeagueStartResponse {
            league: league.clone(),
            stream_to: stream_to.clone(),
            seed: Some(0x1234_5678),
            max_players: 4,
            ..lc_network::LeagueStartResponse::default()
        };

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::GameOptions(
            LobbyGameOptionInput::Hotkey('I'),
        )])
        .expect("queue live signup");
        commands
            .receive_masterserver_signup()
            .complete(Ok(Some(response)));
        app.poll_live_masterserver_signup()
            .expect("apply live Start response");

        let parameters = &app
            .host_join_snapshot
            .as_ref()
            .expect("live host JoinData")
            .parameters;
        assert_eq!(parameters.league, league);
        assert_eq!(parameters.random_seed, 0x1234_5678);
        assert_eq!(parameters.max_players, 4);
        assert_eq!(app.network_stream_address, stream_to);
        assert_eq!(app.network_league_name, b"Cup");
        assert_eq!(app.network_max_players, 4);
        assert_eq!(app.engine.max_players(), Some(4));
        let reference = app
            .advertised_game_reference
            .as_ref()
            .expect("updated exact host reference");
        assert_eq!(reference.parameters().league.as_bytes(), b"Cup");
        assert_eq!(reference.parameters().random_seed, 0x1234_5678);
        assert_eq!(reference.parameters().max_players, 4);
        let published = commands.take_published_join_snapshots();
        assert_eq!(published.len(), 1);
        assert_eq!(published[0].parameters.league.as_bytes(), b"Cup");
        assert_eq!(published[0].parameters.random_seed, 0x1234_5678);
        assert_eq!(published[0].parameters.max_players, 4);

        app.process_classic_lobby_actions(vec![ClassicLobbyAction::GameOptions(
            LobbyGameOptionInput::Hotkey('I'),
        )])
        .expect("queue live signup disable");
        let disable = commands.receive_masterserver_signup();
        assert!(!disable.enabled);
        disable.complete(Ok(None));
        app.poll_live_masterserver_signup()
            .expect("apply live signup disable");

        let parameters = &app
            .host_join_snapshot
            .as_ref()
            .expect("cleared live host JoinData")
            .parameters;
        assert!(parameters.league.is_empty());
        assert!(parameters.league_address.is_empty());
        assert_eq!(parameters.random_seed, 0x1234_5678);
        assert_eq!(parameters.max_players, 4);
        assert_eq!(app.network_stream_address, stream_to);
        assert!(app.network_league_name.is_empty());
        let reference = app
            .advertised_game_reference
            .as_ref()
            .expect("updated non-league host reference");
        assert!(reference.parameters().league.is_empty());
        assert!(reference.parameters().league_address.is_empty());
        assert_eq!(reference.parameters().random_seed, 0x1234_5678);
        assert_eq!(reference.parameters().max_players, 4);
        let published = commands.take_published_join_snapshots();
        assert_eq!(published.len(), 1);
        assert!(published[0].parameters.league.is_empty());
        assert!(published[0].parameters.league_address.is_empty());
        assert_eq!(published[0].parameters.random_seed, 0x1234_5678);
        assert_eq!(published[0].parameters.max_players, 4);
    }

