    #[test]
    fn scale_native_scensel_rows_retain_clipped_book_text() {
        let scenarios = [
            ("tutorial", "Tutorial"),
            ("missions", "Missions"),
            ("melees", "Melees"),
        ]
        .into_iter()
        .map(|(identifier, title)| {
            let mut scenario = FrontendScenario::fallback();
            scenario.identifier = identifier.to_string();
            scenario.title = title.to_string();
            scenario
        })
        .collect::<Vec<_>>();
        let mut app = new_menu_app_with_frontend_scenarios(640, 480, Some(scenarios));
        install_classic_test_assets(&mut app);
        app.open_scenario_browser();

        let assets = app.assets.scensel_assets().expect("scenario assets");
        let button_down = app
            .assets
            .dialog_image("GUIButtonDown.png")
            .expect("scenario button-down plank");
        let fonts = app.assets.clonk_fonts.clone().expect("classic fonts");
        let book = app.assets.book_fonts.clone().expect("book fonts");
        let expected_titles = app
            .menu_state
            .visible_entries()
            .iter()
            .map(|entry| entry.title.clone())
            .collect::<Vec<_>>();
        assert_eq!(expected_titles.len(), 3);

        // Retina/scale-native presentation captures role-tagged text instead
        // of rasterizing it into the logical surface. These commands must stay
        // on the destination frame and retain the ListBox viewport clip.
        let mut surface = Surface::new(640, 480, PixelFormat::Rgba8888);
        surface.begin_clonk_text_capture();
        draw_scensel_dynamic(
            &mut surface,
            &mut app.menu_state,
            &app.scenario_entry_enabled,
            &assets,
            &button_down,
            &fonts,
            &book,
            None,
            startup_gamma(),
            true,
        )
        .expect("render scale-native scenario rows");
        let commands = surface.take_clonk_text_capture();
        let layout = lc_frontend::startup_scensel::scen_sel_layout(640, 480, &fonts);
        let item_h = lc_frontend::startup_scensel::scen_list_item_height(&book.text);
        let list_x = layout.list.x + 3;
        let list_top = layout.list.y + 3;
        let list_clip = Rect::new(
            list_x,
            list_top,
            (layout.list.w - 6 - 16) as u32,
            (layout.list.h - 6) as u32,
        );

        for (index, title) in expected_titles.iter().enumerate() {
            let matches = commands
                .iter()
                .filter(|command| {
                    command.role == lc_graphics::clonk_font::ClonkFontRole::BookText
                        && command.text == *title
                        && command.clip == Some(list_clip)
                })
                .collect::<Vec<_>>();
            assert_eq!(matches.len(), 1, "one clipped row label for {title}");
            assert_eq!(matches[0].x, list_x + item_h + 2);
            assert_eq!(
                matches[0].y,
                list_top + index as i32 * (item_h + 1) + 2
            );
        }
    }

    #[test]
    fn scale_native_scensel_static_text_survives_backdrop_cache_hits() {
        let mut scenario = FrontendScenario::fallback();
        scenario.identifier = "tutorial".to_string();
        scenario.title = "Tutorial".to_string();
        let mut app =
            new_menu_app_with_frontend_scenarios(640, 480, Some(vec![scenario]));
        install_classic_test_assets(&mut app);
        app.open_scenario_browser();
        app.menu_state.set_search_text("needle");
        app.menu_state.set_search_focused(true);
        install_native_test_fonts(&mut app, 2.0);

        // The cold frame populates StartupBackdropCache. The second frame is
        // the failing path: cached pixels cannot carry semantic CStdFont
        // commands, so C++'s static title and WoodenLabel must be re-emitted.
        let (_, _, cold) = render_ordered_test_frame(&mut app, 2.0, 1280, 960);
        let cached_backdrop = app.menu_backdrop_cache.pixels.clone();
        let (cached_chrome, cached_rendered, cached) =
            render_ordered_test_frame(&mut app, 2.0, 1280, 960);
        assert!(app.menu_backdrop_cache.key.is_some());
        assert_eq!(
            app.menu_backdrop_cache.pixels, cached_backdrop,
            "the second frame must reuse the unchanged raster backdrop"
        );

        for (name, plan) in [("cold", &cold), ("cache hit", &cached)] {
            let commands = plan
                .batches
                .iter()
                .flat_map(|batch| batch.text.iter())
                .collect::<Vec<_>>();
            for (text, role) in [
                (
                    "Start Game",
                    lc_graphics::clonk_font::ClonkFontRole::GuiTitle,
                ),
                (
                    "Search:",
                    lc_graphics::clonk_font::ClonkFontRole::GuiText,
                ),
                (
                    "needle",
                    lc_graphics::clonk_font::ClonkFontRole::GuiText,
                ),
            ] {
                assert_eq!(
                    commands
                        .iter()
                        .filter(|command| command.text == text && command.role == role)
                        .count(),
                    1,
                    "{name} must contain exactly one {text:?} native command"
                );
            }
        }

        let cached_commands = cached
            .batches
            .iter()
            .flat_map(|batch| batch.text.iter())
            .collect::<Vec<_>>();
        let fonts = app.assets.clonk_fonts.as_deref().expect("classic fonts");
        let layout = lc_frontend::startup_scensel::scen_sel_layout(640, 480, fonts);
        let title = cached_commands
            .iter()
            .find(|command| command.text == "Start Game")
            .expect("cached frame title command");
        assert_eq!(
            (title.x, title.y, title.align, title.clip),
            (
                layout.title_anchor.0,
                layout.title_anchor.1,
                lc_graphics::clonk_font::TextAlign::Center,
                None
            )
        );

        let label = layout.search_label;
        let search = cached_commands
            .iter()
            .find(|command| command.text == "Search:")
            .expect("cached frame wooden-label command");
        let label_clip = Rect::new(
            label.x,
            label.y,
            (label.w + 1) as u32,
            (label.h + 1) as u32,
        );
        assert_eq!(
            (search.x, search.y, search.align, search.clip),
            (
                label.x + label.w / 2,
                label.y + (label.h - fonts.text.line_height) / 2 - 1,
                lc_graphics::clonk_font::TextAlign::Center,
                Some(label_clip)
            )
        );

        let edit = layout.search_edit;
        let (client_x, client_y, client_w, client_h) =
            (edit.x + 4, edit.y + 2, edit.w - 8, edit.h - 4);
        let query = cached_commands
            .iter()
            .find(|command| command.text == "needle")
            .expect("cached frame edit command");
        let query_y = if client_h <= fonts.text.line_height {
            client_y - 1
        } else {
            client_y + (client_h - fonts.text.line_height) / 2
        };
        assert_eq!(
            (query.x, query.y, query.align, query.clip),
            (
                client_x,
                query_y,
                lc_graphics::clonk_font::TextAlign::Left,
                Some(Rect::new(
                    client_x - 2,
                    client_y,
                    (client_w + 4) as u32,
                    (client_h + 1) as u32,
                ))
            )
        );

        let changed_in_search_label = (label.y * 2..(label.y + label.h) * 2).any(|y| {
            (label.x * 2..(label.x + label.w) * 2).any(|x| {
                let offset = (y as usize * 1280 + x as usize) * 4;
                cached_chrome[offset..offset + 4] != cached_rendered[offset..offset + 4]
            })
        });
        assert!(
            changed_in_search_label,
            "cache-hit Search: command must contribute visible physical pixels"
        );
    }

    // List icon defaults (C4StartupScenSelDlg.cpp:705-710,951-952,1036-1037):
    // scenario Icon= clamped to the 52-icon strip else 14; .c4f folder 0;
    // plain directory 44.
    #[test]
    fn scensel_entry_icons_follow_cpp_defaults() {
        let mut scenario = FrontendScenario::fallback();
        scenario.kind = ScenarioKind::Scenario;
        scenario.icon_index = Some(15);
        assert_eq!(scensel_entry_icon(&scenario), 15);
        scenario.icon_index = Some(99);
        assert_eq!(scensel_entry_icon(&scenario), 14);
        scenario.icon_index = None;
        assert_eq!(scensel_entry_icon(&scenario), 14);

        let mut folder = FrontendScenario::fallback();
        folder.kind = ScenarioKind::Folder;
        folder.path = Some(PathBuf::from("/tmp/Fantasy.c4f"));
        assert_eq!(scensel_entry_icon(&folder), 0);
        folder.path = Some(PathBuf::from("/tmp/Downloads"));
        assert_eq!(scensel_entry_icon(&folder), 44);
    }

    #[test]
    fn sandbox_music_is_decodable() {
        // Keep real installed-resource discovery and decoder coverage here;
        // the menu lifecycle regression uses an explicitly completed fixture
        // so thread scheduling cannot decide whether that state test passes.
        // Music discovery reads process env; hold the env lock so the
        // EnvGuard-based tests cannot redirect paths mid-load.
        let _lock = env_lock().lock();
        let audio = sandbox_music_bytes();
        let decoded = decode_audio(audio).expect("sandbox music decodes");
        assert_eq!(decoded.sample_rate, 44_100);
        assert!(decoded.frames.len() > 2_000);
    }

