    #[test]
    fn music_resolver_replaces_global_catalog_when_parent_has_music_group() {
        // A discovered local music directory clears the global song list
        // before local tracks are loaded (C4MusicSystem.cpp:152-166).
        let dir = tempdir().expect("tempdir");
        let global = dir.path().join("Music.c4g");
        fs::create_dir_all(&global).expect("create global music group");
        fs::write(global.join("Frontend.ogg"), b"frontend").expect("write frontend");

        let folder = dir.path().join("Fantasy.c4f");
        let scenario = folder.join("Scenario.c4s");
        let local = folder.join("Music.c4g");
        fs::create_dir_all(&scenario).expect("create scenario");
        fs::create_dir_all(&local).expect("create local music group");
        fs::write(local.join("Local Theme.ogg"), b"local").expect("write local theme");

        let global = Group::open(&global).expect("open global music");
        let mut resolver = MusicResolver::with_global_group(global).expect("build global resolver");
        resolver.set_playlist(Some("Frontend.*".to_string()));
        resolver
            .configure_scenario(Some(&scenario))
            .expect("configure local scenario");

        assert!(
            resolver.resolve("Frontend").is_none(),
            "a local catalog replaces rather than extends global music"
        );
        assert_eq!(
            resolver
                .resolve("Local Theme")
                .expect("local theme")
                .load_audio()
                .expect("read local theme"),
            b"local"
        );
        assert_eq!(
            resolver
                .first_default()
                .map(|asset| asset.file_name_bytes.as_slice()),
            Some(b"Local Theme.ogg".as_slice()),
            "loading a new scenario music catalog restores the default playlist"
        );
    }

    #[test]
    fn frontend_preinit_reloads_changed_music_and_more_music_catalog() {
        // QuitGame enters C4AS_PreInit, whose unconditional MusicSystem.emplace()
        // destroys the local catalog and reconstructs Music.c4g + MoreMusic.txt
        // before startup or the next full scenario (C4Application.cpp:232-293,
        // 373-400; C4MusicSystem.cpp:37-45,391-434).
        let dir = tempdir().expect("music lifecycle fixture");
        let global = dir.path().join("Music.c4g");
        let extras = dir.path().join("Extras");
        fs::create_dir_all(dir.path().join("planet/System.c4g"))
            .expect("create minimal install system group");
        fs::create_dir_all(&global).expect("create global music group");
        fs::create_dir_all(&extras).expect("create MoreMusic directory");
        fs::write(global.join("Old Base.ogg"), b"old base").expect("old global track");
        fs::write(global.join("Removed.mod"), b"removed").expect("removed global track");
        fs::write(extras.join("Old Match.mp3"), b"old wildcard").expect("old wildcard track");
        fs::write(dir.path().join("MoreMusic.txt"), b"Extras/*.mp3\n")
            .expect("initial MoreMusic manifest");

        let local_scenario = dir.path().join("Local.c4s");
        fs::create_dir_all(&local_scenario).expect("create local scenario");
        fs::write(local_scenario.join("Local Theme.ogg"), b"local")
            .expect("write local scenario track");

        let user_data = dir.path().join("user");
        let _env_lock = env_lock().lock();
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(dir.path())),
            ("LC_CONTENT_DIR", Some(dir.path())),
            ("LC_USER_DATA_DIR", Some(user_data.as_path())),
        ]);
        let paths = AppPaths::discover().expect("discover fixture paths");
        paths.ensure_user_dirs().expect("create fixture user paths");
        let mut audio = AudioContext::try_new_with_paths(
            AudioOptions {
                max_channels: 1,
                ..AudioOptions::default()
            },
            Some(&paths),
        )
        .expect("create audio context");

        let mut initial = audio.music_resolver.global.filenames();
        initial.sort();
        assert_eq!(initial, ["Old Base.ogg", "Old Match.mp3", "Removed.mod"]);
        audio.configure_scenario(Some(&local_scenario));
        let stale_recent = Arc::clone(
            &audio
                .music_resolver
                .resolve("Local Theme")
                .expect("local scenario catalog")
                .identity,
        );
        audio
            .music_resolver
            .set_playlist(Some("Local.*".to_string()));
        lock_unpoisoned(&audio.music_control).most_recently_played = Some(stale_recent);
        audio.set_scenario_music_level(Some(25));

        fs::remove_file(global.join("Old Base.ogg")).expect("remove old global track");
        fs::remove_file(global.join("Removed.mod")).expect("remove second old track");
        fs::remove_file(extras.join("Old Match.mp3")).expect("remove old wildcard track");
        fs::write(global.join("New Base.ogg"), b"new base").expect("new global track");
        fs::write(global.join("Frontend.ogg"), b"new frontend").expect("new frontend track");
        fs::write(extras.join("New Match.ogg"), b"new wildcard").expect("new wildcard track");
        fs::write(
            dir.path().join("MoreMusic.txt"),
            b"Extras/*.ogg\n#clear\nMusic.c4g\nExtras/*.ogg\n",
        )
        .expect("replacement MoreMusic manifest");

        assert!(
            audio.music_resolver.global.resolve("New Base").is_none(),
            "external edits remain invisible until the next PreInit"
        );
        audio.reset_music_system_generation(Some(&paths));

        let mut reloaded = audio.music_resolver.active_filenames();
        reloaded.sort();
        assert_eq!(reloaded, ["Frontend.ogg", "New Base.ogg", "New Match.ogg"]);
        assert_eq!(
            audio
                .music_resolver
                .resolve("New Base")
                .expect("reloaded Music.c4g addition")
                .load_audio()
                .expect("read reloaded global track"),
            b"new base"
        );
        assert_eq!(
            audio
                .music_resolver
                .resolve("New Match")
                .expect("changed wildcard match")
                .load_audio()
                .expect("read changed wildcard track"),
            b"new wildcard"
        );
        for removed in ["Old Base", "Removed", "Old Match", "Local Theme"] {
            assert!(
                audio.music_resolver.resolve(removed).is_none(),
                "{removed} must not leak into the reconstructed catalog"
            );
        }
        assert!(!audio.music_resolver.scenario_has_local_sources);
        assert!(audio.music_resolver.scenario_root.is_none());
        assert!(audio.music_resolver.playlist.is_none());
        let control = lock_unpoisoned(&audio.music_control);
        assert!(control.most_recently_played.is_none());
        assert!(control.scenario_level.is_none());
        drop(control);

        audio.prepare_frontend_music();
        assert_eq!(audio.music_resolver.playlist.as_deref(), Some("Frontend.*"));
        assert_eq!(
            audio
                .music_resolver
                .first_default()
                .map(|asset| asset.file_name_bytes.as_slice()),
            Some(b"Frontend.ogg".as_slice()),
            "the ensuing frontend selection must use the rediscovered catalog"
        );

        // A failed startup host/join also runs QuitGame -> PreInit ->
        // DoStartup. Prove that shortcut performs a third discovery before it
        // requests frontend music, rather than retaining this second catalog.
        let controlled_fixture = audio
            .system
            .load_music(&silent_pcm_wav(20))
            .expect("predecode controlled frontend fixture");
        audio.control_music_loads_with(controlled_fixture);
        fs::remove_file(global.join("New Base.ogg")).expect("remove second-generation base");
        fs::remove_file(extras.join("New Match.ogg"))
            .expect("remove second-generation wildcard match");
        fs::write(global.join("Final Base.ogg"), b"final base")
            .expect("third-generation global track");
        fs::write(extras.join("Final Match.ogg"), b"final wildcard")
            .expect("third-generation wildcard track");

        let mut app = new_real_classic_menu_app(640, 480);
        app.app_paths = Some(paths.clone());
        app.audio = Some(audio);
        app.resume_frontend_music_after_fade = true;
        app.startup_restart_diagnostics.mark_quit_with_error();
        app.startup_restart_diagnostics
            .add_fatal_error("fixture startup failure");
        app.finish_startup_network_restart(StartupNetworkPurpose::Join)
            .expect("failed startup returns through PreInit and DoStartup");

        let audio = app.audio.as_ref().expect("test audio survives PreInit");
        let mut final_catalog = audio.music_resolver.active_filenames();
        final_catalog.sort();
        assert_eq!(
            final_catalog,
            ["Final Base.ogg", "Final Match.ogg", "Frontend.ogg"]
        );
        assert_eq!(
            audio.music_resolver.playlist.as_deref(),
            Some("Frontend.*")
        );
        assert!(!app.resume_frontend_music_after_fade);
        assert!(app.frontend_music_attempted_for_entry);
        let expected_frontend = audio
            .music_resolver
            .first_default()
            .expect("fresh frontend selection")
            .identity
            .clone();
        let controlled = audio
            .controlled_music_loads
            .as_ref()
            .expect("controlled music loading");
        assert_eq!(controlled.requests.len(), 1);
        let request = controlled
            .requests
            .front()
            .expect("DoStartup frontend music request");
        assert!(!request.looped);
        assert!(request
            .identity
            .as_ref()
            .is_some_and(|identity| Arc::ptr_eq(identity, &expected_frontend)));

        let pre_console_generation = lock_unpoisoned(&audio.music_control).generation;
        fs::remove_file(global.join("Final Base.ogg")).expect("remove third-generation base");
        fs::remove_file(extras.join("Final Match.ogg"))
            .expect("remove third-generation wildcard match");
        fs::write(global.join("Console Only.ogg"), b"console").expect("console-only external edit");
        app.console_mode = true;
        app.resume_frontend_music_after_fade = true;
        app.startup_restart_diagnostics.mark_quit_with_error();
        app.startup_restart_diagnostics
            .add_fatal_error("fixture console failure");
        app.finish_startup_network_restart(StartupNetworkPurpose::Join)
            .expect("console open failure returns without application PreInit");

        let audio = app
            .audio
            .as_ref()
            .expect("console retains audio generation");
        assert_eq!(
            lock_unpoisoned(&audio.music_control).generation,
            pre_console_generation
        );
        let mut retained_catalog = audio.music_resolver.active_filenames();
        retained_catalog.sort();
        assert_eq!(
            retained_catalog,
            ["Final Base.ogg", "Final Match.ogg", "Frontend.ogg"]
        );
        assert!(audio.music_resolver.resolve("Console Only").is_none());
        assert_eq!(
            audio
                .controlled_music_loads
                .as_ref()
                .expect("controlled music loading")
                .requests
                .len(),
            1,
            "console failure must not run C4Startup::DoStartup again"
        );
        assert!(app.resume_frontend_music_after_fade);

        app.console_mode = false;
        app.classic_command_line.scenario = Some(dir.path().join("Explicit.c4s"));
        app.startup_restart_diagnostics.mark_quit_with_error();
        app.startup_restart_diagnostics
            .add_fatal_error("fixture command-line failure");
        app.finish_startup_network_restart(StartupNetworkPurpose::Join)
            .expect("explicit command-line failure does not enter PreInit");
        let audio = app
            .audio
            .as_ref()
            .expect("command-line failure retains audio generation");
        assert_eq!(
            lock_unpoisoned(&audio.music_control).generation,
            pre_console_generation
        );
        assert!(audio.music_resolver.resolve("Console Only").is_none());
        assert_eq!(
            audio
                .controlled_music_loads
                .as_ref()
                .expect("controlled music loading")
                .requests
                .len(),
            1
        );

        app.classic_command_line.scenario = None;
        app.classic_command_line.record_stream = Some(PathBuf::from("record.example:11114"));
        assert!(!app.failed_open_game_returns_to_startup());
        app.classic_command_line.record_stream = Some(PathBuf::new());
        app.classic_command_line.direct_join = Some(String::new());
        assert!(
            app.failed_open_game_returns_to_startup(),
            "native suppresses startup only for nonempty command-line buffers"
        );

        // User-aborting the pre-game lobby also makes OpenGame return false.
        // Its ordinary startup lineage must run the same QuitGame -> PreInit
        // reconstruction, while the earlier console edit is still pending.
        app.classic_command_line = ClassicCommandLine::default();
        let pre_lobby_generation = lock_unpoisoned(
            &app.audio
                .as_ref()
                .expect("lobby retains audio")
                .music_control,
        )
        .generation;
        install_test_classic_host_lobby(&mut app);
        app.process_classic_lobby_actions(vec![ClassicLobbyAction::ExitRequested])
            .expect("lobby abort returns through PreInit and DoStartup");
        let audio = app.audio.as_ref().expect("lobby abort retains audio");
        assert!(lock_unpoisoned(&audio.music_control).generation > pre_lobby_generation);
        assert!(audio.music_resolver.resolve("Console Only").is_some());
        assert_eq!(
            audio
                .controlled_music_loads
                .as_ref()
                .expect("controlled music loading")
                .requests
                .len(),
            2,
            "lobby abort requests frontend music exactly once after rediscovery"
        );
    }

    #[test]
    fn definition_pack_music_is_enumerated_in_groupset_order_and_replaces_global_music() {
        let dir = tempdir().expect("definition music fixture");
        let global = dir.path().join("Music.c4g");
        fs::create_dir_all(&global).expect("global music group");
        fs::write(global.join("Global.ogg"), b"global").expect("global track");

        let folder = dir.path().join("Fantasy.c4f");
        let scenario = folder.join("Scenario.c4s");
        let folder_music = folder.join("Music.c4g");
        fs::create_dir_all(&scenario).expect("scenario group");
        fs::create_dir_all(&folder_music).expect("folder music group");
        fs::write(folder_music.join("Shared.ogg"), b"folder").expect("folder track");

        let first_pack = dir.path().join("First.c4d");
        let second_pack = dir.path().join("Second.c4d");
        let first_music = first_pack.join("Music.c4g");
        let second_music = second_pack.join("Music.c4g");
        fs::create_dir_all(&first_music).expect("first definition music");
        fs::create_dir_all(&second_music).expect("second definition music");
        fs::write(first_music.join("FirstOnly.ogg"), b"first only")
            .expect("first-only track");
        fs::write(first_music.join("PackTie.ogg"), b"first")
            .expect("first tied track");
        fs::write(first_music.join("Shared.ogg"), b"first shared")
            .expect("first shared track");
        fs::write(second_music.join("SecondOnly.ogg"), b"second only")
            .expect("second-only track");
        fs::write(second_music.join("PackTie.ogg"), b"second")
            .expect("second tied track");

        let roots = [
            Group::open(&first_pack).expect("first definition root"),
            Group::open(&second_pack).expect("second definition root"),
        ];
        let mut resolver = MusicResolver::with_global_group(
            Group::open(&global).expect("global music root"),
        )
        .expect("global resolver");
        assert!(
            resolver
                .configure_scenario_with_definition_roots(Some(&scenario), &roots)
                .expect("configure definition music")
        );

        assert!(resolver.resolve("Global").is_none());
        assert_eq!(
            resolver
                .resolve("Shared")
                .expect("folder wins over definition roots")
                .load_audio()
                .expect("folder bytes"),
            b"folder"
        );
        assert_eq!(
            resolver
                .resolve("PackTie")
                .expect("tied definition track")
                .load_audio()
                .expect("definition bytes"),
            b"second",
            "FindGroup enumerates the later equal-priority definition root first"
        );
        assert!(resolver.resolve("FirstOnly").is_some());
        assert!(resolver.resolve("SecondOnly").is_some());
        assert!(
            !resolver
                .configure_scenario(Some(&scenario))
                .expect("same-path playback configure"),
            "the later path-only playback pass must retain definition-root music"
        );
        assert_eq!(
            resolver
                .resolve("PackTie")
                .expect("definition catalog retained")
                .load_audio()
                .expect("retained definition bytes"),
            b"second"
        );

        fs::write(second_music.join("Reloaded.ogg"), b"reloaded")
            .expect("same-path replacement track");
        resolver.set_playlist(Some("FirstOnly.*".to_string()));
        assert!(
            resolver
                .configure_scenario_with_definition_roots(Some(&scenario), &roots)
                .expect("resource-aware same-path reload"),
            "a real activation must rebuild even when path and roots are unchanged"
        );
        assert!(resolver.playlist.is_none());
        assert_eq!(
            resolver
                .resolve("Reloaded")
                .expect("replacement track discovered")
                .load_audio()
                .expect("replacement bytes"),
            b"reloaded"
        );
    }

    #[test]
    fn extra_music_uses_later_activated_children_then_root_and_skips_inactive_children() {
        let dir = tempdir().expect("Extra music fixture");
        let global = dir.path().join("Music.c4g");
        let scenario = dir.path().join("Scenario.c4s");
        let first_pack = dir.path().join("First.c4d");
        let second_pack = dir.path().join("Second.c4d");
        let extra = dir.path().join("Extra.c4g");
        let extra_root_music = extra.join("Music.c4g");
        let first_music = extra.join("First.c4d/Music.c4g");
        let second_music = extra.join("Second.c4d/Music.c4g");
        let unused_music = extra.join("Unused.c4d/Music.c4g");
        for path in [
            &global,
            &scenario,
            &first_pack,
            &second_pack,
            &extra_root_music,
            &first_music,
            &second_music,
            &unused_music,
        ] {
            fs::create_dir_all(path).expect("music fixture group");
        }
        fs::write(global.join("Global.ogg"), b"global").expect("global track");
        fs::write(extra_root_music.join("RootOnly.ogg"), b"root").expect("root track");
        fs::write(first_music.join("ChildTie.ogg"), b"first").expect("first child track");
        fs::write(second_music.join("ChildTie.ogg"), b"second")
            .expect("second child track");
        fs::write(unused_music.join("Unused.ogg"), b"unused").expect("unused child track");

        let roots = [
            Group::open(&first_pack).expect("first definition root"),
            Group::open(&second_pack).expect("second definition root"),
        ];
        let mut resolver = MusicResolver::with_global_group(
            Group::open(&global).expect("global music root"),
        )
        .expect("global resolver");
        resolver.extra = Some(Group::open(&extra).expect("Extra root"));
        resolver
            .configure_scenario_with_definition_roots(Some(&scenario), &roots)
            .expect("configure Extra music");

        assert!(resolver.resolve("Global").is_none());
        assert_eq!(
            resolver
                .resolve("ChildTie")
                .expect("activated child tie")
                .load_audio()
                .expect("second child bytes"),
            b"second",
            "direct GroupSet iteration keeps the later activated Extra child first"
        );
        assert_eq!(
            resolver
                .resolve("RootOnly")
                .expect("Extra root track")
                .load_audio()
                .expect("root bytes"),
            b"root"
        );
        assert!(resolver.resolve("Unused").is_none());
    }

    #[test]
    fn malformed_definition_pack_music_child_clears_global_without_aborting() {
        let dir = tempdir().expect("malformed definition music fixture");
        let global = dir.path().join("Music.c4g");
        let scenario = dir.path().join("Scenario.c4s");
        let definition = dir.path().join("Broken.c4d");
        fs::create_dir_all(&global).expect("global music group");
        fs::create_dir_all(&scenario).expect("scenario group");
        fs::create_dir_all(&definition).expect("definition group");
        fs::write(global.join("Global.ogg"), b"global").expect("global track");
        fs::write(definition.join("Music.c4g"), b"not a group")
            .expect("malformed music child");

        let mut resolver = MusicResolver::with_global_group(
            Group::open(&global).expect("global music root"),
        )
        .expect("global resolver");
        resolver
            .configure_scenario_with_definition_roots(
                Some(&scenario),
                &[Group::open(&definition).expect("definition root")],
            )
            .expect("malformed child is a logged LoadDir miss");

        assert!(resolver.resolve("Global").is_none());
        assert!(resolver.active_filenames().is_empty());
    }

    #[test]
    fn malformed_scenario_music_child_clears_global_and_keeps_valid_root_tracks() {
        let dir = tempdir().expect("malformed scenario music fixture");
        let global = dir.path().join("Music.c4g");
        fs::create_dir_all(&global).expect("global music group");
        fs::write(global.join("Global.ogg"), b"global").expect("global track");

        // LoadDir handles every path independently. A bad scenario child and
        // a bad inner .c4f child therefore cannot discard the scenario-root
        // track or the valid outer .c4f sibling that follows them.
        let outer = dir.path().join("Outer.c4f");
        let inner = outer.join("Inner.c4f");
        let scenario = inner.join("Scenario.c4s");
        let outer_music = outer.join("Music.c4g");
        fs::create_dir_all(&scenario).expect("scenario group");
        fs::create_dir_all(&outer_music).expect("outer music group");
        fs::write(scenario.join("Scenario Root.ogg"), b"scenario")
            .expect("scenario-root track");
        fs::write(scenario.join("Music.c4g"), b"not a group")
            .expect("malformed scenario child");
        fs::write(inner.join("Music.c4g"), b"also not a group")
            .expect("malformed parent child");
        fs::write(outer_music.join("Outer.ogg"), b"outer").expect("outer sibling track");

        let mut resolver = MusicResolver::with_global_group(
            Group::open(&global).expect("global music root"),
        )
        .expect("global resolver");
        resolver
            .configure_scenario(Some(&scenario))
            .expect("malformed local children are isolated");

        assert!(resolver.resolve("Global").is_none());
        assert_eq!(
            resolver.active_filenames(),
            ["Scenario Root.ogg", "Outer.ogg"],
            "valid sources retain native scenario-to-parent order"
        );
        assert_eq!(
            resolver
                .resolve("Scenario Root")
                .expect("scenario-root track retained")
                .load_audio()
                .expect("scenario-root bytes"),
            b"scenario"
        );
        assert_eq!(
            resolver
                .resolve("Outer")
                .expect("outer parent track retained")
                .load_audio()
                .expect("outer parent bytes"),
            b"outer"
        );

        // Presence, not successful opening, is the local-source signal for a
        // direct scenario child and for a registered .c4f parent child.
        let bad_scenario = dir.path().join("OnlyBroken.c4s");
        fs::create_dir_all(&bad_scenario).expect("standalone scenario group");
        fs::write(bad_scenario.join("Music.c4g"), b"broken")
            .expect("standalone malformed child");
        resolver
            .configure_scenario(Some(&bad_scenario))
            .expect("standalone malformed scenario child");
        assert!(resolver.resolve("Global").is_none());
        assert!(resolver.active_filenames().is_empty());

        let bad_parent = dir.path().join("OnlyBroken.c4f");
        let child_scenario = bad_parent.join("Child.c4s");
        fs::create_dir_all(&child_scenario).expect("parent-child scenario group");
        fs::write(bad_parent.join("Music.c4g"), b"broken parent")
            .expect("standalone malformed parent child");
        resolver
            .configure_scenario(Some(&child_scenario))
            .expect("standalone malformed parent child");
        assert!(resolver.resolve("Global").is_none());
        assert!(resolver.active_filenames().is_empty());
    }

