        fs::remove_file(global.join("B.ogg")).expect("remove deferred catalogued replacement");

        assert!(audio
            .complete_next_controlled_music_load()
            .expect("complete predecessor and pump replacement"));
        assert!(!audio.system.music_is_playing());
