    #[test]
    fn l061_player_selection_widget_sounds_reach_the_production_audio_route() {
        let mut app = new_classic_menu_app(640, 480);
        let mut dialog = lc_frontend::startup_plrsel::PlrSelController::new(2);
        dialog.resize(640, 480);
        app.startup_player_dialog = Some(dialog);
        app.ui_sound_log.clear();

        let actions = app
            .startup_player_dialog
            .as_mut()
            .unwrap()
            .handle_key_down(KeyCode::Down);
        app.process_player_dialog_actions(actions)
            .expect("route the selection sound");
        assert_eq!(app.ui_sound_log, ["Command"]);

        let back = lc_frontend::startup_plrsel::plrsel_layout(640, 480).buttons[0];
        let back = GuiPoint::new(
            (back.x + back.w / 2) as f32,
            (back.y + back.h / 2) as f32,
        );
        let actions = app
            .startup_player_dialog
            .as_mut()
            .unwrap()
            .handle_pointer_down(back);
        app.process_player_dialog_actions(actions)
            .expect("route the button-down sound");
        assert_eq!(app.ui_sound_log, ["Command", "ArrowHit"]);

        let actions = app
            .startup_player_dialog
            .as_mut()
            .unwrap()
            .handle_pointer_up(back);
        app.process_player_dialog_actions(actions)
            .expect("route the button-release sound before Back");
        assert_eq!(app.ui_sound_log, ["Command", "ArrowHit", "Click"]);
    }

    #[test]
    fn l063_activation_overflow_reverts_row_and_shows_native_error() {
        reset_cached_app_paths();
        let user_data = tempdir().expect("isolated player-selection config");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let player_model = |name: &str, activated: bool| {
            lc_frontend::startup_plrsel::PlrSelPlayer {
                name: name.to_string(),
                activated,
                big_icon: None,
                portrait: None,
                color_dw: 0xff,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                comment: String::new(),
            }
        };
        let alpha = player_model("Alpha", true);
        let overflow = player_model("Overflow", true);
        let mut app = new_classic_menu_app(640, 480);
        app.app_paths = Some(paths.clone());
        app.startup_player_files.push(StartupPlayerFile {
            path: PathBuf::from("A"),
            file_name: "A".to_string(),
            player_file: PlayerFile {
                name: "Alpha".to_string(),
                ..PlayerFile::default()
            },
            render_model: alpha.clone(),
        });
        app.startup_player_models.push(alpha);
        for index in 1..19 {
            let model = player_model(&format!("Inactive {index}"), false);
            app.startup_player_files.push(StartupPlayerFile {
                path: PathBuf::from(format!("Inactive{index}.c4p")),
                file_name: format!("Inactive{index}.c4p"),
                player_file: PlayerFile::default(),
                render_model: model.clone(),
            });
            app.startup_player_models.push(model);
        }
        let overflow_index = app.startup_player_files.len();
        app.startup_player_files.push(StartupPlayerFile {
            path: PathBuf::from("Overflow.c4p"),
            file_name: "b".repeat(1023),
            player_file: PlayerFile {
                name: "Overflow".to_string(),
                ..PlayerFile::default()
            },
            render_model: overflow.clone(),
        });
        app.startup_player_models.push(overflow);
        app.selected_player_file = Some(PlayerFile {
            name: "Overflow".to_string(),
            ..PlayerFile::default()
        });
        app.open_player_selection_dialog();
        assert!(!app.startup_player_files[overflow_index]
            .render_model
            .activated);
        assert!(!app.startup_player_models[overflow_index].activated);
        assert_eq!(
            app.selected_player_file
                .as_ref()
                .map(|player| player.name.as_str()),
            Some("Alpha")
        );
        assert_eq!(app.message_dialogs.len(), 1);
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("dismiss open-time overflow error");
        let (actions, scroll_before) = {
            let dialog = app
                .startup_player_dialog
                .as_mut()
                .expect("player-selection controller");
            dialog.set_selected_index(Some(overflow_index));
            let scroll_before = dialog.list_scroll_offset();
            assert!(scroll_before > 0, "fixture must exercise a scrolled list");
            let actions = dialog.handle_key_down(KeyCode::Space);
            assert_eq!(dialog.is_player_activated(overflow_index), Some(true));
            (actions, scroll_before)
        };

        app.process_player_dialog_actions(actions)
            .expect("refuse oversized activation");

        assert!(!app.startup_player_files[overflow_index]
            .render_model
            .activated);
        assert!(!app.startup_player_models[overflow_index].activated);
        let dialog = app
            .startup_player_dialog
            .as_ref()
            .expect("player-selection controller remains open");
        assert_eq!(
            dialog.is_player_activated(overflow_index),
            Some(false)
        );
        assert_eq!(dialog.selected_index(), Some(overflow_index));
        assert_eq!(dialog.list_scroll_offset(), scroll_before);
        assert_eq!(
            Config::load(paths.config_file())
                .expect("reload bounded participants")
                .get_in(Some("General"), "Participants"),
            Some("A")
        );
        assert!(app.status_text.is_empty());
        assert_eq!(app.message_dialogs.len(), 1);
        let error = &app.message_dialogs[0].state;
        assert_eq!(error.caption(), "Error");
        assert_eq!(
            error.message(),
            "Player \"Overflow\" has been deactivated: Too many activated players or path too long!"
        );
        assert_eq!(
            error.buttons(),
            lc_frontend::message_dialog::MessageDialogButtons::OK
        );
        assert_eq!(
            error.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::ERROR
        );
    }

    #[test]
    fn startup_crew_mode_replaces_typed_boundary_and_crewless_stays_in_player_mode() {
        let directory = tempdir().expect("crew fixture root");
        let player_path = directory.path().join("Ada.c4p");
        fs::create_dir(&player_path).expect("create player group");
        fs::write(
            player_path.join("Player.txt"),
            "[Player]\nName=Ada\n\n[Preferences]\nColorDw=255\n",
        )
        .expect("write player core");
        for (file_name, name, id, experience) in [
            ("Low.c4i", "Low", "CLNK", 20),
            ("High.c4i", "High", "WIPF", 200),
        ] {
            let crew = player_path.join(file_name);
            fs::create_dir(&crew).expect("create crew child");
            fs::write(
                crew.join("ObjectInfo.txt"),
                format!(
                    "[ObjectInfo]\nid={id}\nName={name}\nRankName=Clonk\nExperience={experience}\nParticipation=1\n"
                ),
            )
            .expect("write crew core");
        }
        let player_file = PlayerFile::load_from_path(&player_path).expect("load player fixture");
        let player_model = lc_frontend::startup_plrsel::PlrSelPlayer {
            name: "Ada".to_string(),
            activated: false,
            big_icon: None,
            portrait: None,
            color_dw: 255,
            score: 0,
            rounds: 0,
            rounds_won: 0,
            rounds_lost: 0,
            total_playing_time: 0,
            comment: String::new(),
        };
        let mut app = new_classic_menu_app(640, 480);
        app.startup_player_files.push(StartupPlayerFile {
            path: player_path.clone(),
            file_name: "Ada.c4p".to_string(),
            player_file,
            render_model: player_model.clone(),
        });
        app.startup_player_models.push(player_model);
        app.open_player_selection_dialog();

        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::ShowCrew(0),
        ])
        .expect("Crew enters without a PlayerCrew parity boundary");
        let controller = app.startup_player_dialog.as_ref().expect("player dialog");
        assert!(controller.is_crew_mode());
        assert_eq!(controller.dialog_title(), "Crew: Ada");
        assert_eq!(controller.selected_index(), Some(0));
        assert_eq!(
            app.startup_crew_models
                .iter()
                .map(|crew| crew.name.as_str())
                .collect::<Vec<_>>(),
            ["High", "Low"]
        );
        assert!(app.message_dialogs.is_empty());

        let selected_crew_file = app.startup_crew_files[0].file_name.clone();
        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::CrewParticipationChanged {
                index: 0,
                participating: false,
            },
        ])
        .expect("persist crew participation");
        let persisted = Group::open(player_path.join(&selected_crew_file))
            .and_then(|group| {
                lc_engine::player_file::CrewInfo::load(&group)
                    .map_err(|error| GroupError::InvalidGroup(error.to_string()))
            })
            .expect("reload persisted crew participation");
        assert_eq!(persisted.participation, 0);

        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::SetCrewDeathMessage(0),
        ])
        .expect("open crew death-message input");
        assert_eq!(
            app.game_option_input_dialog
                .as_ref()
                .expect("crew death-message input")
                .controller
                .max_text(),
            75
        );
        app.process_game_option_input_dialog_actions(vec![InputDialogAction::Accepted(
            "Farewell".to_string(),
        )])
        .expect("persist crew death message");
        let persisted = Group::open(player_path.join(&selected_crew_file))
            .and_then(|group| {
                lc_engine::player_file::CrewInfo::load(&group)
                    .map_err(|error| GroupError::InvalidGroup(error.to_string()))
            })
            .expect("reload persisted crew death message");
        assert_eq!(persisted.death_message, "Farewell");

        let layout = lc_frontend::startup_plrsel::plrsel_layout(640, 480);
        app.startup_player_dialog
            .as_mut()
            .expect("player dialog")
            .set_pointer_position(Some(GuiPoint::new(
                (layout.list_client.x + layout.item_height * 2) as f32,
                (layout.list_client.y + layout.item_height / 2) as f32,
            )));
        assert!(app
            .open_startup_player_context_menu(false)
            .expect("open crew context menu"));
        assert_eq!(
            app.context_menu
                .as_ref()
                .expect("crew context menu")
                .layout()
                .panels[0]
                .rows
                .len(),
            3
        );
        app.close_context_menu_silently();

        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::LeaveCrew,
        ])
        .expect("return to player mode");
        let controller = app.startup_player_dialog.as_ref().expect("player dialog");
        assert!(!controller.is_crew_mode());
        assert_eq!(controller.selected_index(), Some(0));

        fs::remove_dir_all(player_path.join("Low.c4i")).expect("remove low crew");
        fs::remove_dir_all(player_path.join("High.c4i")).expect("remove high crew");
        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::ShowCrew(0),
        ])
        .expect("crewless player opens a message, not a typed boundary");
        let controller = app.startup_player_dialog.as_ref().expect("player dialog");
        assert!(!controller.is_crew_mode());
        assert_eq!(controller.selected_index(), Some(0));
        assert_eq!(app.message_dialogs.len(), 1);
        assert_eq!(app.message_dialogs[0].state.caption(), "Crew: Ada");
        assert_eq!(
            app.message_dialogs[0].state.message(),
            "Ada does not have a crew yet!"
        );
        assert_eq!(
            app.message_dialogs[0].state.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::PLAYER
        );
    }

    #[test]
    fn player_properties_context_closes_and_opens_the_editor() {
        let mut app = new_classic_menu_app(640, 480);
        let model = lc_frontend::startup_plrsel::PlrSelPlayer {
            name: "Context Player".to_string(),
            activated: false,
            big_icon: None,
            portrait: None,
            color_dw: 0xff,
            score: 0,
            rounds: 0,
            rounds_won: 0,
            rounds_lost: 0,
            total_playing_time: 0,
            comment: String::new(),
        };
        app.startup_player_files.push(StartupPlayerFile {
            path: PathBuf::from("Context Player.c4p"),
            file_name: "Context Player.c4p".to_string(),
            player_file: PlayerFile::default(),
            render_model: model.clone(),
        });
        app.startup_player_models.push(model);
        app.open_player_selection_dialog();
        let layout = lc_frontend::startup_plrsel::plrsel_layout(640, 480);
        app.startup_player_dialog
            .as_mut()
            .unwrap()
            .set_pointer_position(Some(GuiPoint::new(
                (layout.list_client.x + layout.item_height * 2) as f32,
                (layout.list_client.y + layout.item_height / 2) as f32,
            )));
        assert!(app
            .open_startup_player_context_menu(false)
            .expect("open exact player context"));
        assert!(app.context_menu.is_some());
        let before_models = app.startup_player_models.len();
        let before_files = app.startup_player_files.len();

        app.process_context_menu_outcome(ContextMenuOutcome {
                captured: true,
                pass_through: false,
                focus_suppressed: true,
                events: vec![
                    ContextMenuEvent::Closed,
                    ContextMenuEvent::Sound(ContextMenuSound::Click),
                    ContextMenuEvent::Activated(AppContextMenuCommand::StartupPlayer(
                        PlrSelPlayerContextCommand::PlayerProperties(0),
                    )),
                ],
            })
            .expect("Properties callback opens the editor");
        assert!(app.context_menu.is_none());
        assert!(matches!(
            app.startup_player_properties_dialog
                .as_ref()
                .map(|pending| pending.controller.mode()),
            Some(lc_frontend::startup_plrproperties::PlayerPropertiesMode::Edit { index: 0 })
        ));
        assert!(app.status_text.is_empty());
        assert!(app.message_dialogs.is_empty());
        assert_eq!(app.startup_player_models.len(), before_models);
        assert_eq!(app.startup_player_files.len(), before_files);
    }

    #[test]
    fn startup_player_resize_matches_cpp_copyfrom_sfc_max_size() {
        let source = ImageData::new(
            4,
            2,
            [
                [0, 0, 0, 255],
                [64, 0, 0, 255],
                [128, 0, 0, 255],
                [255, 0, 0, 255],
                [0, 64, 0, 255],
                [0, 128, 0, 255],
                [0, 192, 0, 255],
                [0, 255, 0, 255],
            ]
            .into_iter()
            .flatten()
            .collect(),
        );
        // This offscreen helper intentionally has no display configuration:
        // application scale and PointFiltering cannot affect Blit8 sampling.
        let resized = resize_startup_player_image(&source, 2);
        assert_eq!((resized.width(), resized.height()), (2, 1));
        assert_eq!(
            resized.pixels(),
            &[0, 0, 0, 255, 128, 0, 0, 255],
            "offscreen Blit8 samples source-pixel left edges"
        );

        let aspect = ImageData::new(5, 3, vec![255; 5 * 3 * 4]);
        assert_eq!(
            {
                let resized = resize_startup_player_image(&aspect, 4);
                (resized.width(), resized.height())
            },
            (4, 2),
            "the minor axis uses truncating integer aspect math"
        );
        let no_scale = ImageData::new(2, 1, vec![1, 2, 3, 4, 5, 6, 7, 8]);
        assert_eq!(resize_startup_player_image(&no_scale, 2), no_scale);

        let loaded = startup_player_image_from_rgba(2, 1, vec![90, 80, 70, 0, 10, 20, 30, 255]);
        assert_eq!(
            loaded.pixels(),
            &[0, 0, 0, 0, 10, 20, 30, 255],
            "C4Surface load blackens hidden RGB"
        );
        let owner_source = ImageData::new(2, 1, vec![0, 0, 255, 255, 200, 30, 30, 255]);
        let icon = startup_player_big_icon(&owner_source, 0x00ff_ffff)
            .expect("ordinary icon dimensions survive materialization");
        assert_eq!(
            icon.pixels(),
            &[254, 254, 254, 255, 200, 30, 30, 255],
            "software ModulateClr divides owner RGB by 256"
        );

        let extreme = ImageData::new(1, 151, vec![255; 151 * 4]);
        let collapsed = resize_startup_player_image(&extreme, 150);
        assert_eq!((collapsed.width(), collapsed.height()), (0, 0));
        assert!(collapsed.pixels().is_empty());
        assert_eq!(materialize_startup_player_image(&extreme, 150), None);
    }

