    #[test]
    fn l020_global_gamepad_disable_drops_events_before_dispatch() {
        let mut app = new_real_classic_menu_app(640, 480);
        let mut frame = vec![0_u8; 640 * 480 * 4];
        app.render(&mut frame).expect("cache supported main menu");
        let initial_version = app.menu_render_version;
        let down = || GamepadEvent::Direction {
            slot: GamepadSlot::new(0),
            button: ControlButton::Down,
            state: ElementState::Pressed,
        };

        app.gamepads_enabled = false;
        app.gamepad_input_enabled = false;
        app.process_gamepad_event_batch([down()])
            .expect("globally disabled input is discarded");
        assert_eq!(
            app.menu_render_version, initial_version,
            "disabled events must not reach startup input dispatch"
        );

        app.gamepads_enabled = true;
        app.gamepad_input_enabled = true;
        app.process_gamepad_event_batch([down()])
            .expect("globally enabled input reaches dispatch");
        assert_eq!(app.menu_render_version, initial_version.wrapping_add(1));
    }

    #[test]
    fn options_program_focus_traverses_every_control_without_a_boundary() {
        use lc_frontend::startup_options_dlg::OptionsProgramFocusTarget;

        let mut app = new_classic_menu_app(640, 480);
        app.open_options_menu();
        let expected = [
            OptionsProgramFocusTarget::LanguageCombo,
            OptionsProgramFocusTarget::FontFaceCombo,
            OptionsProgramFocusTarget::FontSizeCombo,
            OptionsProgramFocusTarget::WhiteChatIngame,
            OptionsProgramFocusTarget::WhiteChatLobby,
            OptionsProgramFocusTarget::ShowLogTimestamps,
            OptionsProgramFocusTarget::Preloading,
            OptionsProgramFocusTarget::ResetButton,
            OptionsProgramFocusTarget::AdvancedButton,
        ];
        for target in expected {
            app.handle_gamepad_direction(
                GamepadSlot::new(0),
                ControlButton::Right,
                ElementState::Pressed,
            )
            .unwrap_or_else(|error| panic!("focus {target:?}: {error}"));
            assert_eq!(
                app.startup_options_dialog
                    .as_ref()
                    .expect("options state")
                    .focused_program_control(),
                Some(target)
            );
        }

        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Right,
            ElementState::Pressed,
        )
        .expect("wrap forward to Back");
        assert_eq!(
            app.startup_options_dialog
                .as_ref()
                .unwrap()
                .focused_program_control(),
            None
        );
        app.handle_gamepad_direction(
            GamepadSlot::new(0),
            ControlButton::Left,
            ElementState::Pressed,
        )
        .expect("wrap backward to Advanced");
        assert_eq!(
            app.startup_options_dialog
                .as_ref()
                .unwrap()
                .focused_program_control(),
            Some(OptionsProgramFocusTarget::AdvancedButton)
        );
    }

