    #[test]
    fn running_global_gui_guard_precedes_every_recursive_menu_screen() {
        let check = |mut app: GameApp, label: &str| {
            app.scoreboard_initial_reconcile_pending = true;
            let before = runtime_global_ui_snapshot(&app);
            remove_global_gui_sheet(&mut app, "GUIBigArrows.png");
            let mut frame = vec![0x84; 320 * 200 * 4];
            let error = app
                .render(&mut frame)
                .expect_err("running menu bypassed global GUI preflight");
            assert_global_gui_boundary(
                &error,
                vec![ClassicGuiBootstrapIssue::missing("GUIBigArrows")],
            );
            assert_eq!(runtime_global_ui_snapshot(&app), before, "{label}");
            assert!(frame.iter().all(|byte| *byte == 0x84), "{label}");
        };

        let pages = vec![
            (
                "C4MainMenu::Main",
                IngameMenuState::main_menu(&MainMenuConditions::default())
                    .expect("nonempty main menu"),
            ),
            (
                "C4MainMenu::Goals",
                IngameMenuState::goals_menu(&[GoalRuleEntry {
                    definition_id: "GOAL".to_string(),
                    name: "Goal".to_string(),
                    description: None,
                    fulfilled: false,
                }]),
            ),
            (
                "C4MainMenu::Rules",
                IngameMenuState::rules_menu(&[GoalRuleEntry {
                    definition_id: "RULE".to_string(),
                    name: "Rule".to_string(),
                    description: None,
                    fulfilled: false,
                }]),
            ),
            (
                "C4MainMenu::NewPlayer",
                IngameMenuState::new_player_menu(&[ingame_menu::NewPlayerEntry {
                    file: "Player.c4p".to_string(),
                    name: "Player".to_string(),
                }]),
            ),
            (
                "C4MainMenu::Savegame",
                IngameMenuState::savegame_menu(&[SaveSlotState { free: true }; 10]),
            ),
            (
                "C4MainMenu::Options",
                IngameMenuState::options_menu(
                    &OptionFlags {
                        sound: true,
                        music: true,
                        mouse_shown: true,
                        mouse: true,
                    },
                    0,
                ),
            ),
            (
                "C4MainMenu::Display",
                IngameMenuState::display_menu(&DisplayFlags::default(), 0),
            ),
            ("C4MainMenu::Surrender", IngameMenuState::surrender_menu()),
            (
                "C4MainMenu::ClientDisconnect",
                IngameMenuState::client_disconnect_menu(),
            ),
            (
                "C4MainMenu::HostDisconnect",
                IngameMenuState::host_disconnect_menu(&[HostDisconnectClientEntry {
                    client_id: 0,
                    caption: "Host (Host)".to_string(),
                    activated: true,
                }]),
            ),
        ];
        assert_eq!(pages.len(), 10, "MenuPage exhaustiveness changed");
        for (label, page) in pages {
            let mut app = new_running_sandbox_app();
            app.ingame_menu.replace(app.local_owner, Some(page));
            check(app, label);
        }

        let mut object = new_running_sandbox_app();
        assert!(object
            .open_object_menu()
            .expect("open app-owned object menu"));
        check(object, "app-owned object menu");

        for mode in [
            SaveBrowserMode::Save {
                suggested_label: "Slot".to_string(),
            },
            SaveBrowserMode::Load,
        ] {
            let mut app = new_running_sandbox_app();
            app.save_browser = Some(SaveBrowserState::new(mode.clone(), Vec::new()));
            check(
                app,
                match mode {
                    SaveBrowserMode::Save { .. } => "save browser",
                    SaveBrowserMode::Load => "load browser",
                },
            );
        }

        let mut scoreboard = new_running_sandbox_app();
        scoreboard.scoreboard_dialog = Some(scoreboard.scoreboard_request());
        check(scoreboard, "visible scoreboard");

        for style in 0..=3 {
            let mut app = new_running_sandbox_app();
            let cursor = app
                .engine
                .crew_cursor(app.local_owner)
                .expect("sandbox cursor");
            let mut menu = two_item_script_menu(cursor);
            menu.style = style;
            app.engine
                .apply_object_update(
                    cursor,
                    ObjectUpdate {
                        menu: Some(Some(menu)),
                        ..ObjectUpdate::default()
                    },
                )
                .expect("install engine script menu");
            check(app, &format!("engine script menu style {style}"));
        }
    }

    #[test]
    fn global_gui_guard_is_first_at_every_external_ui_ingress() {
        let mut app = new_classic_menu_app(320, 200);
        remove_global_gui_sheet(&mut app, "GUISpinBoxArrow.png");
        let version = app.menu_render_version;
        let modifiers = app.keyboard_modifiers;
        let dimensions = {
            let surface = app.graphics.surface();
            (surface.width(), surface.height())
        };
        let engine_game_time = app.engine.game_time();
        let snapshot_game_time = app.snapshot.game_time;
        let mut second_accumulator = Duration::from_millis(125);
        let expect_engine = |result: Result<(), EngineError>| {
            assert!(matches!(
                result,
                Err(EngineError::ClassicMenuParityBoundary { ref detail })
                    if detail.contains("GUISpinBoxArrow")
            ));
        };
        expect_engine(app.handle_modifiers_changed(ModifiersState::SHIFT));
        expect_engine(app.handle_text_input('x'));
        expect_engine(app.handle_key(VirtualKeyCode::A, ElementState::Pressed));
        expect_engine(app.handle_key(VirtualKeyCode::F11, ElementState::Pressed));
        expect_engine(app.handle_focus_lost());
        expect_engine(app.process_gamepad_event_batch([GamepadEvent::Clear {
            slot: GamepadSlot::new(0),
        }]));
        expect_engine(app.handle_cursor_moved(PhysicalPosition::new(10.0, 10.0)));
        expect_engine(app.handle_mouse_button(ElementState::Pressed));
        expect_engine(app.handle_right_mouse_button(ElementState::Pressed));
        expect_engine(app.handle_other_mouse_button(ElementState::Pressed));
        expect_engine(app.handle_mouse_wheel(MouseScrollDelta::LineDelta(0.0, 1.0), 1.0));
        expect_engine(app.handle_touch(TouchPhase::Started, GuiPoint::new(10.0, 10.0)));
        expect_engine(app.pointer_left());
        expect_engine(app.sec1_timer().map(|_| ()));
        expect_engine(
            advance_game_clock_from_elapsed(
                &mut app,
                &mut second_accumulator,
                Duration::from_secs(1),
            )
            .map(|_| ()),
        );
        expect_engine(app.update());
        let resize = app
            .resize(640, 480)
            .expect_err("resize must fail at global guard");
        assert!(matches!(
            resize.downcast_ref::<ClassicParityBoundary>(),
            Some(ClassicParityBoundary::GlobalGuiBootstrapResources { .. })
        ));
        assert_eq!(app.menu_render_version, version);
        assert_eq!(app.keyboard_modifiers, modifiers);
        let surface = app.graphics.surface();
        assert_eq!((surface.width(), surface.height()), dimensions);
        assert_eq!(app.engine.game_time(), engine_game_time);
        assert_eq!(app.snapshot.game_time, snapshot_game_time);
        assert_eq!(second_accumulator, Duration::from_millis(125));
        assert!(app.context_menu.is_none());
        assert!(app.message_dialogs.is_empty());
    }

    #[test]
    fn startup_bootstrap_issues_are_typed_and_aggregated_in_cpp_init_order() {
        let mut app = new_real_classic_menu_app(320, 200);
        let assets = Arc::get_mut(&mut app.assets).expect("frontend assets are app-owned");

        // Remove in deliberately non-oracle order. The boundary must still
        // report C4StartupGraphics::Init order, followed by its font order.
        assets.startup_dialog_images.remove("StartupNetGetRef.png");
        assets.startup_dialog_images.remove("StartupPlrPropBG.png");
        assets.startup_dialog_images.remove("StartupScenSelBG.png");
        assets.startup_dialog_images.insert(
            "StartupBookScroll.png".to_string(),
            ImageData::new(0, 48, Vec::new()),
        );
        assets
            .startup_dialog_images
            .remove("StartupPlrCtrlType.png");
        assets.startup_bootstrap_image_failures.insert(
            "StartupPlrCtrlType.png".to_string(),
            "failed to decode image".to_string(),
        );
        let (caption, text) = {
            let fonts = assets.book_fonts.as_deref().expect("book fonts");
            (fonts.caption.clone(), fonts.text.clone())
        };
        assets.book_fonts = Some(Arc::new(lc_frontend::startup_scensel::BookFontSet {
            title: lc_graphics::clonk_font::ClonkFont::new(0),
            caption,
            text,
        }));

        let error = assets
            .require_classic_startup_bootstrap_resources()
            .expect_err("incomplete bootstrap must fail as one aggregate");
        assert_eq!(
            error,
            ClassicParityBoundary::StartupBootstrapResources {
                issues: vec![
                    ClassicStartupBootstrapIssue::missing("StartupScenSelBG.png"),
                    ClassicStartupBootstrapIssue::missing("StartupPlrPropBG.png"),
                    ClassicStartupBootstrapIssue::malformed(
                        "StartupBookScroll.png",
                        "a non-empty decoded RGBA surface",
                        "0x48 with 0 bytes",
                    ),
                    ClassicStartupBootstrapIssue::malformed(
                        "StartupPlrCtrlType.png",
                        "a non-empty decoded RGBA surface",
                        "failed to decode image",
                    ),
                    ClassicStartupBootstrapIssue::missing("StartupNetGetRef.png"),
                    ClassicStartupBootstrapIssue::malformed(
                        "BookFontTitle",
                        "an initialized shadowless RX font",
                        "line_height=0, cell_height=1, h_space=-1",
                    ),
                ],
            }
        );
    }

    #[test]
    fn startup_bootstrap_precedes_all_seven_roots_status_models_cache_and_native_pixels() {
        let mut app = new_real_classic_menu_app(320, 200);
        let mut initial = vec![0_u8; 320 * 200 * 4];
        app.render(&mut initial)
            .expect("populate supported startup cache");
        Arc::get_mut(&mut app.assets)
            .expect("frontend assets are app-owned")
            .startup_dialog_images
            .remove("StartupPlrPropBG.png")
            .expect("player-properties background is eagerly loaded");
        let expected = vec![ClassicStartupBootstrapIssue::missing(
            "StartupPlrPropBG.png",
        )];

        for (index, view) in StartupView::ALL.into_iter().enumerate() {
            // Exhaustive arms make a future StartupView addition update this
            // all-root regression rather than silently escaping the audit.
            match view {
                StartupView::MainMenu => app.startup_view = StartupView::MainMenu,
                StartupView::ScenarioBrowser => {
                    app.startup_view = StartupView::ScenarioBrowser;
                }
                StartupView::NetworkLobby => {
                    app.startup_view = StartupView::NetworkLobby;
                    app.classic_host_lobby = None;
                }
                StartupView::NetworkGame => {
                    app.startup_view = StartupView::NetworkGame;
                    app.startup_network_dialog = None;
                }
                StartupView::Options => {
                    app.startup_view = StartupView::Options;
                    app.startup_options_dialog = None;
                }
                StartupView::About => {
                    app.startup_view = StartupView::About;
                    app.startup_about_dialog = None;
                }
                StartupView::PlayerSelection => {
                    app.startup_view = StartupView::PlayerSelection;
                    app.startup_player_dialog = None;
                }
            }
            app.status_text = format!("lower-priority status for {view:?}");
            let cached = vec![0x20 + index as u8; 320 * 200 * 4];
            app.menu_frame_cache = Some(MenuFrameCache {
                view,
                version: app.menu_render_version,
                width: 320,
                height: 200,
                native_text_deferred: false,
                frame: cached.clone(),
            });

            let mut frame = vec![0xa5; 320 * 200 * 4];
            let error = app
                .render(&mut frame)
                .expect_err("bootstrap must precede every root and cache lookup");
            assert_startup_bootstrap_boundary(&error, expected.clone());
            assert!(frame.iter().all(|byte| *byte == 0xa5));
            assert_eq!(
                app.menu_frame_cache.as_ref().expect("cache retained").frame,
                cached,
                "{view:?} must not clear or replace its stale cache first"
            );

            let mut native = vec![0x6d; 640 * 400 * 4];
            let error = app
                .render_native_main_menu_text(&mut native, 640, 400)
                .expect_err("native pass must use the same all-root preflight");
            assert_startup_bootstrap_boundary(&error, expected.clone());
            assert!(native.iter().all(|byte| *byte == 0x6d));
        }
    }

    #[test]
    fn startup_bootstrap_precedes_recursive_startup_children() {
        let mut app = new_real_classic_menu_app(640, 480);
        for child in [
            RetainedStartupChild::Unported(ClassicStartupSubscreen::Options(
                lc_frontend::startup_options_dlg::OptionsSheet::Graphics,
            )),
            RetainedStartupChild::OptionsSound,
            RetainedStartupChild::AboutLicenses,
        ] {
            enter_retained_startup_child(&mut app, child);
            let removed = Arc::get_mut(&mut app.assets)
                .expect("frontend assets are app-owned")
                .startup_dialog_images
                .remove("StartupPlrCtrlType.png")
                .expect("player-control atlas is eagerly loaded");
            let mut frame = vec![0xc7; 640 * 480 * 4];
            let error = app
                .render(&mut frame)
                .expect_err("bootstrap must precede the recursive child boundary");
            assert_startup_bootstrap_boundary(
                &error,
                vec![ClassicStartupBootstrapIssue::missing(
                    "StartupPlrCtrlType.png",
                )],
            );
            assert!(frame.iter().all(|byte| *byte == 0xc7));
            Arc::get_mut(&mut app.assets)
                .expect("frontend assets are app-owned")
                .startup_dialog_images
                .insert("StartupPlrCtrlType.png".to_string(), removed);
            app.status_text.clear();
            app.show_main_menu();
        }
    }

    #[test]
    fn integer_scale_main_requires_matching_native_fonts_before_cache_selection() {
        let mut app = new_real_classic_menu_app(320, 200);
        Arc::make_mut(&mut app.assets).startup_native_font_source = None;
        let cached = vec![0x42; 320 * 200 * 4];
        app.menu_frame_cache = Some(MenuFrameCache {
            view: StartupView::MainMenu,
            version: app.menu_render_version,
            width: 320,
            height: 200,
            native_text_deferred: false,
            frame: cached.clone(),
        });
        app.configure_native_startup_fonts(3.0, false);
        assert!(app.native_startup_fonts.is_none());

        let mut frame = vec![0xb4; 320 * 200 * 4];
        let error = app
            .render(&mut frame)
            .expect_err("scale-three logical-font approximation must fail closed");
        assert_startup_bootstrap_boundary(
            &error,
            vec![ClassicStartupBootstrapIssue::missing(
                "ScaleNativeStartupFonts",
            )],
        );
        assert!(frame.iter().all(|byte| *byte == 0xb4));
        assert_eq!(
            app.menu_frame_cache.as_ref().expect("cache retained").frame,
            cached
        );

        app.configure_native_startup_fonts(1.0, false);
        app.render(&mut frame)
            .expect("scale one intentionally uses logical startup fonts");
    }

    #[test]
    fn startup_status_boundary_precedes_supported_view_cached_pixels() {
        let mut app = new_real_classic_menu_app(320, 200);
        let mut initial = vec![0_u8; 320 * 200 * 4];
        app.render(&mut initial).expect("populate main-menu cache");
        let cached = app
            .menu_frame_cache
            .as_ref()
            .expect("main-menu frame is cached")
            .frame
            .clone();

        for view in [
            StartupView::MainMenu,
            StartupView::ScenarioBrowser,
            StartupView::NetworkGame,
            StartupView::PlayerSelection,
            StartupView::Options,
            StartupView::About,
        ] {
            match view {
                StartupView::MainMenu => app.show_main_menu(),
                StartupView::ScenarioBrowser => app.open_scenario_browser(),
                StartupView::NetworkGame => app.open_network_game_dialog(),
                StartupView::PlayerSelection => app.open_player_selection_dialog(),
                StartupView::Options => app.open_options_menu(),
                StartupView::About => app.open_about_dialog(),
                StartupView::NetworkLobby => unreachable!(),
            }
            app.menu_frame_cache = Some(MenuFrameCache {
                view,
                version: app.menu_render_version,
                width: 320,
                height: 200,
                native_text_deferred: false,
                frame: cached.clone(),
            });
            let status = format!("diagnostic status for {view:?}");
            app.status_text = status.clone();
            let mut frame = vec![0x5a; 320 * 200 * 4];

            let error = app
                .render(&mut frame)
                .expect_err("generic startup status must never reach a frame");
            match error.downcast_ref::<ClassicParityBoundary>() {
                Some(ClassicParityBoundary::StartupStatusOverlay {
                    view: boundary_view,
                    status: boundary_status,
                }) => {
                    assert_eq!(*boundary_view, view);
                    assert_eq!(boundary_status, &status);
                }
                other => panic!("unexpected startup status boundary: {other:?}"),
            }
            assert_eq!(app.status_text, status, "diagnostic state is retained");
            assert!(
                frame.iter().all(|byte| *byte == 0x5a),
                "{view:?} must fail before copying cached or newly rendered pixels"
            );
            assert_eq!(
                app.menu_frame_cache
                    .as_ref()
                    .expect("existing cache remains available for diagnostics")
                    .frame,
                cached,
                "{view:?} must fail before replacing the frame cache"
            );
        }
    }

    #[test]
    fn startup_status_boundary_precedes_native_main_text_pixels() {
        let mut app = new_real_classic_menu_app(320, 200);
        app.status_text = "native-pass diagnostic".to_string();
        let mut frame = vec![0x6b; 960 * 600 * 4];

        let error = app
            .render_native_main_menu_text(&mut frame, 960, 600)
            .expect_err("native text pass must reject arbitrary startup status");
        assert!(matches!(
            error.downcast_ref::<ClassicParityBoundary>(),
            Some(ClassicParityBoundary::StartupStatusOverlay {
                view: StartupView::MainMenu,
                status,
            }) if status == "native-pass diagnostic"
        ));
        assert_eq!(app.status_text, "native-pass diagnostic");
        assert!(
            frame.iter().all(|byte| *byte == 0x6b),
            "native pass must fail before touching the physical frame"
        );
    }

    #[test]
    fn network_lobby_live_render_bypasses_matching_exact_cache() {
        let mut app = new_real_classic_menu_app(320, 200);
        app.startup_view = StartupView::NetworkLobby;
        app.network_lobby = Some(NetworkLobbyState::new(7, "Host".to_string(), true));
        app.sync_network_lobby_game_option_state();
        assert!(app.status_text.is_empty());

        let cached = vec![0x31; 320 * 200 * 4];
        app.menu_frame_cache = Some(MenuFrameCache {
            view: StartupView::NetworkLobby,
            version: app.menu_render_version,
            width: 320,
            height: 200,
            native_text_deferred: false,
            frame: cached.clone(),
        });
        let mut frame = vec![0x73; 320 * 200 * 4];

        // A retained lobby advances tooltip clocks, held scrollbars and
        // transient status icons without input, so a matching cache must
        // neither replay nor be replaced by the live frame.
        assert!(app.render(&mut frame).expect("live lobby renders"));
        assert_ne!(frame, cached, "stale lobby pixels must not replay");
        assert_eq!(
            app.menu_frame_cache
                .as_ref()
                .expect("bypassed cache remains available for diagnostics")
                .frame,
            cached
        );

        let mut native_frame = vec![0x47; 960 * 600 * 4];
        app.render_native_main_menu_text(&mut native_frame, 960, 600)
            .expect("network lobby has no deferred main-menu text pass");
        assert!(native_frame.iter().all(|byte| *byte == 0x47));
    }

    fn write_map_png(path: &Path, width: u32, height: u32, pixel: [u8; 4]) {
        image::RgbaImage::from_pixel(width, height, image::Rgba(pixel))
            .save(path)
            .expect("write FolderMap image");
    }

    fn map_test_scenario(folder: &Path, filename: &str, title: &str) -> FrontendScenario {
        let mut scenario = FrontendScenario::fallback();
        scenario.identifier = format!("Map.c4f/{filename}");
        scenario.title = title.to_string();
        scenario.description = Some(format!("Description for {title}"));
        scenario.path = Some(folder.join(filename));
        scenario
    }

    fn map_test_folder(path: &Path, children: Vec<FrontendScenario>) -> FrontendScenario {
        let mut folder = FrontendScenario::fallback();
        folder.identifier = "Map.c4f".to_string();
        folder.title = "Map Folder".to_string();
        folder.kind = ScenarioKind::Folder;
        folder.is_playable = false;
        folder.path = Some(path.to_path_buf());
        folder.children = children;
        folder
    }

    fn open_map_test_folder(app: &mut GameApp, folder: FrontendScenario) {
        let scenarios = vec![folder.clone()];
        let menu = StartupMenu::new(build_menu_entries(&scenarios, false), test_font(), None)
            .expect("FolderMap menu");
        app.menu_state = MenuState::new(menu, scenarios.clone());
        app.scenario_catalog = build_scenario_catalog(&scenarios);
        app.open_scenario_browser();
        app.handle_menu_input(|_| {
            vec![StartupMenuAction::OpenEntry(lc_frontend::ScenarioSummary {
                identifier: folder.identifier.clone(),
                title: folder.title.clone(),
                kind: ScenarioKind::Folder,
            })]
        })
        .expect("FolderMap folder activation");
    }

    #[test]
    fn folder_map_f5_refresh_preserves_map_and_book_only_shortcuts() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("FolderMap refresh user data");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        let map_path = paths.scenario_dir().join("Map.c4f");
        let alpha_path = map_path.join("Alpha.c4s");
        fs::create_dir_all(&alpha_path).expect("initial map scenario");
        fs::write(map_path.join("Folder.txt"), "[Head]\nIndex=1\n")
            .expect("map folder core");
        fs::write(
            alpha_path.join("Scenario.txt"),
            "[Head]\nTitle=Alpha Mission\n",
        )
        .expect("initial map scenario core");
        write_map_png(
            &map_path.join("FolderMap.png"),
            16,
            8,
            [20, 30, 40, 255],
        );
        fs::write(
            map_path.join("FolderMap.txt"),
            "[FolderMap]\n    [Scenario]\n    File=Alpha.c4s\n    Area=0,0,8,8\n    [Scenario]\n    File=Beta.c4s\n    Area=8,0,8,8\n",
        )
        .expect("map data");

        let mut app = new_menu_app_with_paths(800, 600, &paths);
        app.open_scenario_browser();
        app.enter_scenario_folder("Map.c4f");
        assert!(app.menu_state.current_map().is_some());

        let select_alpha = app
            .menu_state
            .activate_map_button(0)
            .expect("select Alpha map button");
        app.handle_menu_input(move |_| vec![select_alpha])
            .expect("apply Alpha selection");
        assert_eq!(
            app.menu_state
                .selected_scenario()
                .map(|entry| entry.identifier.as_str()),
            Some("Map.c4f/Alpha.c4s")
        );

        app.handle_key(VirtualKeyCode::F2, ElementState::Pressed)
            .expect("map view has no inline rename shortcut");
        assert!(app.menu_state.rename_edit.is_none());
        app.handle_key(VirtualKeyCode::Delete, ElementState::Pressed)
            .expect("map view has no list delete shortcut");
        assert!(app.message_dialogs.is_empty());
        app.handle_modifiers_changed(ModifiersState::ALT)
            .expect("set map shortcut modifier");
        app.handle_key(VirtualKeyCode::M, ElementState::Pressed)
            .expect("map view has no Mission Access shortcut");
        assert!(app.game_option_input_dialog.is_none());
        app.handle_modifiers_changed(ModifiersState::empty())
            .expect("clear map shortcut modifier");

        let beta_path = map_path.join("Beta.c4s");
        fs::create_dir_all(&beta_path).expect("refreshed map scenario");
        fs::write(
            beta_path.join("Scenario.txt"),
            "[Head]\nTitle=Beta Mission\n",
        )
        .expect("refreshed map scenario core");
        app.handle_key(VirtualKeyCode::F5, ElementState::Pressed)
            .expect("refresh active map folder");
        wait_for_scenario_selector_discovery(&mut app);

        assert_eq!(
            app.menu_state
                .current_folder()
                .map(|folder| folder.identifier.as_str()),
            Some("Map.c4f")
        );
        let map = app
            .menu_state
            .current_map()
            .expect("F5 preserves FolderMap style");
        assert!(
            map.selected_entry().is_none(),
            "F5 rebuild clears the visible map selection"
        );
        assert!(map.scenarios.iter().any(|button| {
            button
                .entry
                .as_ref()
                .is_some_and(|entry| entry.identifier == "Map.c4f/Beta.c4s")
        }));
        assert!(app.scenario_catalog.contains_key("Map.c4f/Beta.c4s"));
        reset_cached_app_paths();
    }

    #[test]
    fn folder_map_disabled_opens_a_normal_book_without_inspecting_the_marker() {
        let root = tempdir().expect("FolderMap fixture");
        let map_path = root.path().join("Map.c4f");
        fs::create_dir(&map_path).expect("map folder");
        fs::write(
            map_path.join("FolderMap.txt"),
            "this is deliberately malformed and has no background",
        )
        .expect("malformed FolderMap marker");
        let alpha = map_test_scenario(&map_path, "Alpha.c4s", "Alpha");
        let folder = map_test_folder(&map_path, vec![alpha.clone()]);
        let mut app = new_menu_app(640, 480);
        app.show_folder_maps = false;

        open_map_test_folder(&mut app, folder.clone());

        assert_eq!(app.menu_state.stack.len(), 2);
        assert!(app.menu_state.current_map().is_none());
        assert_eq!(app.menu_state.visible_entries().len(), 1);
        assert_eq!(
            app.menu_state
                .selected_scenario()
                .map(|entry| entry.identifier.as_str()),
            Some(alpha.identifier.as_str())
        );
        assert_eq!(app.mode, AppMode::Menu);
        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);

        let mut invalid_map_app = new_menu_app(640, 480);
        open_map_test_folder(&mut invalid_map_app, folder);
        assert!(invalid_map_app.menu_state.current_map().is_none());
        assert_eq!(invalid_map_app.menu_state.visible_entries().len(), 1);
        assert_eq!(invalid_map_app.mode, AppMode::Menu);
    }

