    #[test]
    fn crew_name_label_respects_display_flags() {
        let mut app = new_state_only_running_sandbox_app();
        let viewer = app.local_owner;
        let focus = app
            .engine
            .crew_cursor(viewer)
            .expect("sandbox viewer has a crew cursor");
        let focus_state = app
            .engine
            .object_snapshot(focus)
            .expect("sandbox cursor remains live");
        let remote = viewer + 1;
        app.engine
            .register_player(PlayerConfig::new(remote, "Remote Player"))
            .expect("register allied remote player");
        app.engine
            .spawn_object(
                SpawnConfig::new(focus_state.definition_id)
                    .with_position(focus_state.position)
                    .with_owner(remote)
                    .with_crew_member(true)
                    .with_custom_name("Remote Clonk"),
            )
            .expect("spawn remote crew member");
        app.snapshot = app.engine.snapshot();

        let labels = |app: &GameApp| {
            let focus = app.snapshot.object(focus).expect("viewer focus in snapshot");
            app.crew_name_overlays(&[ViewportInput::new(
                viewer,
                focus.position,
                1.0,
                focus,
            )])
        };

        assert_eq!(
            labels(&app)
                .iter()
                .map(|label| label.text.as_str())
                .collect::<Vec<_>>(),
            ["Remote Clonk (Remote Player)"]
        );
        app.display_flags.player_names = false;
        assert_eq!(labels(&app)[0].text, "Remote Clonk");
        app.display_flags.player_names = true;
        app.display_flags.clonk_names = false;
        assert_eq!(labels(&app)[0].text, "Remote Player");
        app.display_flags.player_names = false;
        assert!(labels(&app).is_empty());
    }

    #[test]
    fn network_team_switch_rechecks_gate_then_queues_authenticated_control() {
        let mut app = new_state_only_running_sandbox_app();
        let primary = app.local_owner;
        let primary_team = app.engine.player(primary).and_then(lc_engine::Player::team);
        let owner = 17;
        app.engine.set_teams(vec![
            lc_engine::TeamInfo::new(1, "Red", 0x00f4_0000),
            lc_engine::TeamInfo::new(2, "Blue", 0x0000_00f4),
        ]);
        app.engine
            .register_player(PlayerConfig::new(owner, "Secondary"))
            .expect("register secondary local player");
        app.engine
            .player_mut(owner)
            .expect("secondary local player")
            .set_at_client(lc_engine::PlayerAtClient::new(7));
        app.engine
            .set_player_team(owner, Some(1))
            .expect("put secondary player on Red");
        app.snapshot = app.engine.snapshot();
        let mut teams = app.engine.team_configuration();
        teams.allow_team_switch = true;
        app.engine.set_team_configuration(teams);
        let (manager, _events, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);

        app.apply_ingame_menu_action_for_player(owner, MenuAction::ActivateTeamSelection)
            .expect("open first team-switch page");
        let outcome = {
            let menu = app.ingame_menu.get_mut(owner).expect("team-switch page");
            menu.set_selection(1);
            menu.handle_command(ControlCommand::MenuEnter, CommandKind::Press)
                .expect("select Blue")
        };
        teams.allow_team_switch = false;
        app.engine.set_team_configuration(teams);
        app.execute_ingame_menu_outcome_for_player(owner, outcome)
            .expect("disabled switch is a no-op");
        assert!(commands
            .take_submitted_internal_player_scripts()
            .is_empty());
        assert_eq!(app.engine.player(owner).and_then(lc_engine::Player::team), Some(1));
        assert!(app.ingame_menu.get(owner).is_none());

        teams.allow_team_switch = true;
        app.engine.set_team_configuration(teams);
        app.apply_ingame_menu_action_for_player(owner, MenuAction::ActivateTeamSelection)
            .expect("reopen team-switch page");
        let outcome = {
            let menu = app.ingame_menu.get_mut(owner).expect("team-switch page");
            menu.set_selection(1);
            menu.handle_command(ControlCommand::MenuEnter, CommandKind::Press)
                .expect("select Blue")
        };
        let tick = app.local_control_submission_tick();
        app.execute_ingame_menu_outcome_for_player(owner, outcome)
            .expect("queue enabled team switch");
        let control = lc_engine::SetPlayerTeamControlData {
            team: 2,
            player: owner,
            by_client: 7,
        };
        assert_eq!(
            commands.take_submitted_internal_player_scripts(),
            vec![(tick, lc_engine::ControlPacket::SetPlayerTeam(control))]
        );
        assert_eq!(
            app.engine.player(owner).and_then(lc_engine::Player::team),
            Some(1),
            "submission waits for synchronized execution"
        );

        app.apply_ready_controls(tick, vec![NetworkControl::SetPlayerTeam(control)])
            .expect("execute synchronized team switch");
        assert_eq!(app.engine.player(owner).and_then(lc_engine::Player::team), Some(2));
        assert_eq!(
            app.engine.player(primary).and_then(lc_engine::Player::team),
            primary_team,
            "the primary local player is not substituted for the menu owner"
        );
    }

    #[test]
    fn hostility_menu_lists_other_players_and_toggles_hostility() {
        let mut app = new_state_only_running_sandbox_app();
        let owner = app.local_owner;
        let ada = 17;
        let bot = 18;
        let hidden = 19;
        let ada_info = 117;
        let bot_info = 118;
        let hidden_info = 119;

        app.engine
            .register_player(PlayerConfig::new(ada, "Ada").with_player_info_id(ada_info))
            .expect("register visible user");
        app.engine
            .register_player(PlayerConfig::new(bot, "Bot").with_player_info_id(bot_info))
            .expect("register visible script player");
        app.engine
            .register_player(
                PlayerConfig::new(hidden, "Hidden").with_player_info_id(hidden_info),
            )
            .expect("register invisible user");
        app.engine
            .player_mut(owner)
            .expect("menu owner")
            .set_at_client(lc_engine::PlayerAtClient::new(3));
        app.engine
            .player_mut(ada)
            .expect("Ada")
            .set_hostile_towards(owner, true);
        app.engine
            .player_mut(owner)
            .expect("menu owner")
            .set_hostile_towards(bot, true);
        let mut teams = app.engine.team_configuration();
        teams.allow_hostility_change = true;
        app.engine.set_team_configuration(teams);
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![
                    lc_engine::ControlPlayerInfoEntry {
                        id: ada_info,
                        player_type: lc_engine::PLAYER_INFO_TYPE_USER,
                        ..Default::default()
                    },
                    lc_engine::ControlPlayerInfoEntry {
                        id: bot_info,
                        player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                        ..Default::default()
                    },
                    lc_engine::ControlPlayerInfoEntry {
                        id: hidden_info,
                        player_type: lc_engine::PLAYER_INFO_TYPE_USER,
                        flags: lc_engine::PLAYER_INFO_FLAG_INVISIBLE,
                        ..Default::default()
                    },
                ],
                ..Default::default()
            });
        app.snapshot = app.engine.snapshot();
        let (manager, _events, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(3);
        app.network = Some(manager);

        app.apply_ingame_menu_action(MenuAction::ActivateHostility)
            .expect("open hostility page");
        let menu = app
            .ingame_menu
            .get(owner)
            .expect("hostility page remains open");
        assert_eq!(menu.page(), ingame_menu::MenuPage::Hostility);
        assert_eq!(menu.caption(), "Don't attack Ada");
        assert!(menu.is_permanent());
        assert_eq!(menu.close_action(), Some(&MenuAction::ActivateMain));
        assert_eq!(
            menu.items()
                .iter()
                .map(|item| item.caption.as_str())
                .collect::<Vec<_>>(),
            vec!["Don't attack Ada", "Attack Bot"]
        );
        assert_eq!(
            menu.items()[0].info_caption.as_deref(),
            Some("Ada is currently hostile and will not be attacked.")
        );
        assert_eq!(
            menu.items()[1].info_caption.as_deref(),
            Some("Bot is currently friendly and will be attacked.")
        );
        assert!(matches!(
            menu.items()[1].symbol,
            ingame_menu::MenuSymbol::Hostility {
                opponent,
                hostile: true
            } if opponent == bot
        ));

        let tick = app.local_control_submission_tick();
        let outcome = {
            let menu = app.ingame_menu.get_mut(owner).expect("hostility page");
            menu.set_selection(0);
            menu.handle_command(ControlCommand::MenuEnter, CommandKind::Press)
                .expect("select Ada row")
        };
        assert!(matches!(
            outcome,
            MenuOutcome::Action {
                action: MenuAction::ToggleHostility(opponent),
                close_menu: false
            } if opponent == ada
        ));
        app.execute_ingame_menu_outcome_for_player(owner, outcome)
            .expect("queue hostility toggle");
        let control = lc_engine::ToggleHostilityControlData {
            opponent: ada,
            player: owner,
            by_client: 3,
        };
        assert_eq!(
            commands.take_submitted_internal_player_scripts(),
            vec![(
                tick,
                lc_engine::ControlPacket::ToggleHostility(control)
            )]
        );
        assert!(!app
            .engine
            .player(owner)
            .expect("menu owner")
            .is_hostile_towards(ada));
        assert_eq!(
            app.ingame_menu.get(owner).expect("permanent page").items()[0].caption,
            "Don't attack Ada"
        );

        app.apply_ready_controls(tick, vec![NetworkControl::ToggleHostility(control)])
            .expect("execute synchronized hostility toggle");
        assert!(app
            .engine
            .player(owner)
            .expect("menu owner")
            .is_hostile_towards(ada));
        assert_eq!(
            app.ingame_menu.get(owner).expect("permanent page").items()[0].caption,
            "Don't attack Ada",
            "native waits for C4Menu::Execute's Tick35 refill"
        );
        app.refresh_hostility_menus();
        assert_eq!(
            app.ingame_menu.get(owner).expect("Tick35-refreshed page").items()[0].caption,
            "Attack Ada"
        );

        app.apply_ingame_menu_action_for_player(owner, MenuAction::ToggleHostility(bot))
            .expect("script-player row is rejected");
        assert!(commands
            .take_submitted_internal_player_scripts()
            .is_empty());

        teams.allow_hostility_change = false;
        app.engine.set_team_configuration(teams);
        app.apply_ingame_menu_action_for_player(owner, MenuAction::ToggleHostility(ada))
            .expect("disabled hostility change is ignored");
        assert!(commands
            .take_submitted_internal_player_scripts()
            .is_empty());
        assert!(app
            .engine
            .player(owner)
            .expect("menu owner")
            .is_hostile_towards(ada));

        teams.allow_hostility_change = true;
        app.engine.set_team_configuration(teams);
        app.network = None;
        app.apply_ingame_menu_action_for_player(owner, MenuAction::ToggleHostility(ada))
            .expect("execute local hostility toggle");
        assert!(!app
            .engine
            .player(owner)
            .expect("menu owner")
            .is_hostile_towards(ada));
        assert_eq!(
            app.ingame_menu.get(owner).expect("permanent page").items()[0].caption,
            "Attack Ada",
            "local execution also waits for the periodic refill"
        );
        app.refresh_hostility_menus();
        assert_eq!(
            app.ingame_menu.get(owner).expect("locally refreshed page").items()[0].caption,
            "Don't attack Ada"
        );
    }

    #[test]
    fn unported_object_menu_requests_fail_before_generic_object_menu_state_exists() {
        let mut app = new_state_only_menu_app(320, 200);
        app.start_sandbox_scenario(FrontendScenario::fallback())
            .expect("start explicit test sandbox");
        let crew_id = app
            .snapshot
            .objects
            .iter()
            .find(|object| object.crew_member)
            .expect("sandbox crew")
            .id;

        for (kind, label) in [
            (MenuRequestKind::Activate, "Activate"),
            (
                MenuRequestKind::ActivateTarget { container: crew_id },
                "Activate",
            ),
            (MenuRequestKind::Get { container: crew_id }, "Get"),
        ] {
            app.object_menu = None;
            app.snapshot.menu_requests = vec![lc_engine::MenuRequest {
                crew_id,
                owner: app.local_owner,
                kind,
            }];
            let error = app
                .handle_menu_requests()
                .expect_err("generic app-owned object menu must fail at creation");
            assert!(error.to_string().contains(label), "unexpected {error}");
            assert!(app.object_menu.is_none());
        }

        app.snapshot.menu_requests = vec![lc_engine::MenuRequest {
            crew_id,
            owner: app.local_owner,
            kind: MenuRequestKind::Construction,
        }];
        app.handle_menu_requests()
            .expect("stale engine-owned construction request is ignored");
        assert!(app.object_menu.is_none());
    }

