    #[test]
    fn l149_fractional_client_wait_and_upper_dialog_keep_native_layer_order() {
        let _lock = env_lock().lock();
        let repository = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(repository)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("installed paths");
        let mut app = GameApp::new(
            640,
            480,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("app");
        app.configure_native_startup_fonts(1.5, false);
        app.loader_screen
            .as_mut()
            .expect("loader")
            .update(LoaderUpdate::SetTitle("L149 client loader".into()));
        let resources = app
            .loader_screen
            .as_ref()
            .expect("loader")
            .resources()
            .clone();
        let (_sender, receiver) = mpsc::channel();
        app.loading_state = Some(ScenarioLoadingState::new(
            FrontendScenario::fallback(),
            resources,
            HashMap::new(),
            receiver,
        ));
        app.mode = AppMode::Loading;
        app.network_mode = Some(NetworkMode::Client(client_network_settings()));
        app.show_reached_network_start_wait()
            .expect("show reached client wait");
        app.push_message_dialog(
            lc_frontend::message_dialog::MessageDialogState::regular_ok(
                "L149 upper message",
                "L149 upper caption",
                lc_frontend::message_dialog::MessageDialogIcon::NOTIFY,
            ),
            MessageDialogContinuation::None,
        )
        .expect("stack a second loading dialog");
        let (upper_layout, title_point) = {
            let resources = app
                .assets
                .message_dialog_resources()
                .expect("message-dialog resources");
            let layout = app
                .message_dialogs
                .last()
                .expect("upper dialog")
                .state
                .layout(640, 480, &resources.fonts.text);
            let caption = layout.caption.expect("upper dialog caption");
            let point = GuiPoint::new((caption.x + 10) as f32, (caption.y + 10) as f32);
            (layout, point)
        };
        let tooltip_started = Instant::now()
            .checked_sub(
                lc_frontend::context_menu::CLASSIC_TOOLTIP_DELAY + Duration::from_millis(1),
            )
            .expect("monotonic clock supports tooltip lookback");
        app.startup_tooltip = ClassicTooltipTracker::new_at(tooltip_started);
        app.startup_tooltip
            .note_pointer_move_at(title_point, tooltip_started);
        app.message_dialogs
            .last_mut()
            .expect("upper dialog")
            .state
            .handle_pointer_move(title_point, &upper_layout);

        let (_chrome, _rendered, plan) =
            render_ordered_test_frame(&mut app, 1.5, 960, 720);
        let command_batch = |needle: &str| {
            plan.batches
                .iter()
                .enumerate()
                .find_map(|(index, batch)| {
                    batch
                        .text
                        .iter()
                        .any(|command| command.text == needle)
                        .then_some(index)
                })
                .unwrap_or_else(|| panic!("captured loading text `{needle}`"))
        };
        let loader_batch = plan
            .batches
            .iter()
            .position(|batch| batch.native_loader_text)
            .expect("loader keeps its dedicated native renderer");
        let client_wait_batch = command_batch("Waiting for start...");
        let upper_batch = command_batch("L149 upper message");
        assert_eq!(loader_batch, 0);
        assert!(client_wait_batch > loader_batch);
        assert!(upper_batch > client_wait_batch);
        assert!(plan.batches[client_wait_batch].logical_layer.is_some());
        assert!(plan.batches[upper_batch].logical_layer.is_some());
        let upper_caption_batches = plan
            .batches
            .iter()
            .enumerate()
            .filter_map(|(index, batch)| {
                batch
                    .text
                    .iter()
                    .any(|command| command.text == "L149 upper caption")
                    .then_some(index)
            })
            .collect::<Vec<_>>();
        assert_eq!(upper_caption_batches.len(), 2);
        let tooltip_batch = *upper_caption_batches.last().unwrap();
        assert!(tooltip_batch > upper_batch);
        assert!(plan.batches[tooltip_batch].logical_layer.is_some());

        app.loader_screen = None;
        let mut failed_frame = vec![0_u8; 640 * 480 * 4];
        let error = app
            .render_ordered_native_base(&mut failed_frame)
            .expect_err("missing loader must still fail closed");
        assert!(error.to_string().contains("no selected classic loader"));
        assert!(app.pending_native_presentation.is_none());
        assert!(!app.graphics.surface().is_clonk_text_capture_active());
    }

    #[test]
    fn loader_selector_repeats_explicit_extension_passes_and_cpp_wildcards() {
        let directory = tempdir().expect("loader group");
        fs::write(directory.path().join("LoaderOne.png"), b"not decoded here")
            .expect("loader entry");
        let group = Group::open(directory.path()).expect("loader group");
        let graphics = group.clone();
        let mut ranges = Vec::new();
        let selected = select_loader_source(&[group], &graphics, "LoaderOne.png", |range| {
            ranges.push(range);
            if range == 1 {
                0
            } else {
                range - 1
            }
        })
        .expect("select explicit loader");
        assert_eq!(selected.entry.relative_path, PathBuf::from("LoaderOne.png"));
        assert_eq!(ranges, [1, 2, 3, 7]);
        assert!(classic_wildcard_match(b"*.*", b"extensionless"));
        assert_eq!(
            loader_patterns("LoaderTrailing.").expect("patterns").png,
            "LoaderTrailing..png"
        );
        assert!(loader_patterns("Loader\0Hidden").is_err());
    }

    #[test]
    fn raw_graphics_and_loader_lookup_ignores_unrelated_opaque_names() {
        let directory = tempdir().expect("raw graphics fixture");
        let image_path = directory.path().join("pixel.png");
        write_preview_png(&image_path, [11, 22, 33, 255]);
        let image_bytes = fs::read(image_path).expect("fixture PNG bytes");

        #[cfg(unix)]
        {
            use std::ffi::OsStr;
            use std::os::unix::ffi::OsStrExt;

            let opaque_path = PathBuf::from(OsStr::from_bytes(b"Opaque\xfe.bin"));
            assert!(opaque_path.to_str().is_none());
            let entry = |relative_path: PathBuf, name_bytes: &[u8]| GroupEntry {
                relative_path,
                name_bytes: name_bytes.to_vec(),
                is_directory: false,
                size: 1,
                time: 0,
                executable: false,
                crc_state: 0,
                stored_crc: 0,
            };
            let raw_entries = vec![
                entry(opaque_path, b"Opaque\xfe.bin"),
                entry(PathBuf::from("LoaderGood.png"), b"LoaderGood.png"),
                entry(PathBuf::from("Player.png"), b"Player.png"),
            ];
            assert!(loader_entries_have_content(&raw_entries));
            let graphic = find_classic_named_entry_from_entries(raw_entries, b"player.PNG")
                .expect("opaque sibling does not abort named graphics lookup");
            assert_eq!(graphic.name_bytes, b"Player.png");

            #[cfg(not(target_os = "macos"))]
            {
                let raw_directory = directory.path().join("Directory.c4g");
                fs::create_dir(&raw_directory).expect("directory graphics group");
                fs::write(
                    raw_directory.join(OsStr::from_bytes(b"Opaque\xfe.bin")),
                    b"unrelated",
                )
                .expect("opaque directory sibling");
                fs::write(raw_directory.join("LoaderGood.png"), &image_bytes)
                    .expect("directory loader");
                fs::write(raw_directory.join("Player.png"), &image_bytes)
                    .expect("directory named graphic");
                let directory_group = Group::open(&raw_directory).expect("open directory group");

                assert!(loader_group_has_content(&directory_group)
                    .expect("opaque sibling does not abort loader classification"));
                let selected = select_loader_source(
                    &[directory_group.clone()],
                    &directory_group,
                    "LoaderGood",
                    |_| 0,
                )
                .expect("opaque sibling does not abort loader selection");
                assert_eq!(selected.filename_bytes(), b"LoaderGood.png");
                let graphic = find_classic_named_entry(&directory_group, "player.PNG")
                    .expect("opaque sibling does not abort named graphics lookup")
                    .expect("case-insensitive directory graphic");
                assert_eq!(graphic.name_bytes, b"Player.png");
            }
        }

        let mut fixture = MutableGroup::new_bytes(b"Fixture.bin".to_vec());
        fixture
            .add_file_bytes_with_metadata(
                b"Opaque\xfe.bin".to_vec(),
                b"unrelated".to_vec(),
                1,
                false,
            )
            .expect("opaque sibling");
        fixture
            .add_file("LoaderGood.png", image_bytes.clone())
            .expect("ASCII loader");
        fixture
            .add_file_bytes_with_metadata(b"Loader\xff.png".to_vec(), image_bytes.clone(), 1, false)
            .expect("opaque loader");
        fixture
            .add_file("Player.png", image_bytes.clone())
            .expect("named graphic");
        let group = Group::from_raw_memory(
            PathBuf::from("Fixture.bin"),
            fixture.pack_raw().expect("pack raw lookup fixture"),
        )
        .expect("open raw lookup fixture");

        assert!(loader_group_has_content(&group).expect("classify loader group"));
        let selected = select_loader_source(&[group.clone()], &group, "LoaderGood", |_| 0)
            .expect("unrelated opaque sibling does not abort loader selection");
        assert_eq!(selected.filename_bytes(), b"LoaderGood.png");
        assert_eq!(
            decode_selected_loader(&selected)
                .expect("decode selected ASCII loader")
                .pixels(),
            [11, 22, 33, 255]
        );

        let graphic = find_classic_named_entry(&group, "player.PNG")
            .expect("enumerate named graphics")
            .expect("case-insensitive named graphic");
        assert_eq!(graphic.name_bytes, b"Player.png");

        let opaque_specification = lc_script::c4_string_from_bytes(b"Loader\xff.png");
        let selected = select_loader_source(&[group.clone()], &group, &opaque_specification, |_| 0)
            .expect("raw wildcard selects an opaque loader filename");
        assert_eq!(selected.filename_bytes(), b"Loader\xff.png");
        assert_eq!(
            decode_selected_loader(&selected)
                .expect("selected opaque loader is read by exact entry identity")
                .pixels(),
            [11, 22, 33, 255]
        );
    }

    #[test]
    fn loader_tier_keeps_later_equal_priority_registration_first() {
        let directory = tempdir().expect("loader tiers");
        let lower = directory.path().join("lower.c4f");
        let actual = directory.path().join("actual.c4f");
        let origin = directory.path().join("origin.c4f");
        for path in [&lower, &actual, &origin] {
            fs::create_dir(path).expect("loader group");
            fs::write(path.join("LoaderTier.png"), b"candidate").expect("loader entry");
        }
        let registrations = vec![
            LoaderGroupRegistration {
                priority: 100,
                registration_order: 0,
                group: Group::open(&lower).expect("lower group"),
            },
            LoaderGroupRegistration {
                priority: 101,
                registration_order: 1,
                group: Group::open(&actual).expect("actual group"),
            },
            LoaderGroupRegistration {
                priority: 101,
                registration_order: 2,
                group: Group::open(&origin).expect("origin group"),
            },
        ];
        let tier = highest_loader_tier(&registrations).expect("highest tier");
        assert_eq!(tier.len(), 2);
        assert_eq!(tier[0].root(), origin.as_path());
        assert_eq!(tier[1].root(), actual.as_path());
    }

    #[test]
    fn graphics_group_double_reversal_makes_actual_parent_beat_later_origin() {
        let directory = tempdir().expect("graphics tiers");
        let actual = directory.path().join("actual.c4f");
        let origin = directory.path().join("origin.c4f");
        let fallback = directory.path().join("Graphics.c4g");
        for (path, pixel) in [(&actual, [255, 0, 0, 255]), (&origin, [0, 0, 255, 255])] {
            let graphics = path.join("Graphics.c4g");
            fs::create_dir_all(&graphics).expect("local graphics");
            write_preview_png(&graphics.join("GUIProgress.png"), pixel);
        }
        fs::create_dir(&fallback).expect("fallback graphics");
        let registrations = vec![
            LoaderGroupRegistration {
                priority: 101,
                registration_order: 1,
                group: Group::open(&actual).expect("actual group"),
            },
            LoaderGroupRegistration {
                priority: 101,
                registration_order: 2,
                group: Group::open(&origin).expect("origin group"),
            },
        ];
        let graphics = loader_graphics_registrations(&registrations).expect("graphics children");
        let image = load_named_graphics_image(
            "GUIProgress",
            &graphics,
            &Group::open(&fallback).expect("fallback group"),
        )
        .expect("progress image");
        assert_eq!(image.pixels(), [255, 0, 0, 255]);
    }

    #[test]
    fn graphics_stem_resolver_matches_find_suitable_file_extension_bug() {
        let directory = tempdir().expect("global GUI resolver");
        let base = directory.path().join("base.c4g");
        let override_group = directory.path().join("override.c4g");
        fs::create_dir(&base).expect("base graphics group");
        fs::create_dir(&override_group).expect("override graphics group");
        write_preview_png(&base.join("GUIBigArrows.png"), [255, 0, 0, 255]);
        write_preview_image(
            &override_group.join("GUIBigArrows.bmp"),
            [0, 0, 255, 255],
            image::ImageFormat::Bmp,
        );
        let registrations = vec![LoaderGroupRegistration {
            priority: 200,
            registration_order: 0,
            group: Group::open(&override_group).expect("override group"),
        }];
        let base_group = Group::open(&base).expect("base group");
        let selected =
            select_named_graphics_image_source("GUIBigArrows", &registrations, &base_group)
                .expect("select globally later png");
        assert!(!selected.from_registration);
        assert_eq!(
            selected.source.entry.relative_path,
            PathBuf::from("GUIBigArrows.png")
        );
        assert_eq!(
            decode_selected_loader(&selected.source)
                .expect("decode selected base png")
                .pixels(),
            [255, 0, 0, 255],
            "FindSuitableFile never updates iPrio, so a base png replaces a scenario-priority bmp"
        );

        write_preview_png(&override_group.join("GUIBigArrows.png"), [0, 255, 0, 255]);
        let registrations = vec![LoaderGroupRegistration {
            priority: 200,
            registration_order: 0,
            group: Group::open(&override_group).expect("reopen override group"),
        }];
        let selected =
            select_named_graphics_image_source("GUIBigArrows", &registrations, &base_group)
                .expect("select equal-priority last extension");
        assert_eq!(
            selected.source.entry.relative_path,
            PathBuf::from("GUIBigArrows.png")
        );
        assert_eq!(
            decode_selected_loader(&selected.source)
                .expect("decode selected png")
                .pixels(),
            [0, 255, 0, 255]
        );
    }

    #[test]
    fn game_graphics_refreshes_hud_cursor_and_palette_then_reverts_at_preinit() {
        let directory = tempdir().expect("game graphics refresh fixture");
        let base_path = directory.path().join("base.c4g");
        let scenario_path = directory.path().join("scenario.c4g");
        let sized_path = directory.path().join("sized.c4g");
        for path in [&base_path, &scenario_path, &sized_path] {
            fs::create_dir(path).expect("graphics group");
        }
        let write_solid = |path: &Path, width: u32, height: u32, pixel: [u8; 4]| {
            image::RgbaImage::from_pixel(width, height, image::Rgba(pixel))
                .save(path)
                .expect("write solid graphics image");
        };
        for stem in [
            "Player",
            "Flag",
            "Crew",
            "Score",
            "Wealth",
            "Captain",
            "Fire",
            "Menu",
            "UpperBoard",
            "Logo",
            "Construction",
            "Energy",
            "Magic",
            "Arrow",
            "Exit",
            "Hand",
            "Build",
            "EnergyBars",
            "SelectMark",
            "Control",
            "Gamepad",
            "Background",
            "Options",
            "Liquid",
        ] {
            write_preview_png(&base_path.join(format!("{stem}.png")), [9, 8, 7, 255]);
        }
        write_preview_image(
            &base_path.join("Rank.bmp"),
            [20, 30, 40, 255],
            image::ImageFormat::Bmp,
        );
        for stem in [
            "CursorXXXXXLarge",
            "CursorXXXXLarge",
            "CursorXXXLarge",
            "CursorXXLarge",
            "CursorXLarge",
            "CursorLarge",
            "CursorMedium",
            "CursorSmall",
        ] {
            let pixel = if stem == "CursorLarge" {
                [10, 20, 30, 255]
            } else {
                [1, 1, 1, 255]
            };
            write_solid(&base_path.join(format!("{stem}.png")), 78, 2, pixel);
        }
        let mut base_palette = vec![0_u8; GamePalette::BYTE_LEN];
        base_palette[6 * 3..6 * 3 + 3].copy_from_slice(&[63, 63, 63]);
        base_palette[10 * 3..10 * 3 + 3].copy_from_slice(&[10, 0, 0]);
        fs::write(base_path.join("C4.pal"), base_palette).expect("base C4.pal");
        let base = Group::open(&base_path).expect("base graphics");
        let startup = resolve_game_graphics_resources(&[], &base, None, true)
            .expect("startup graphics bundle");

        let mut scenario_palette = vec![0_u8; GamePalette::BYTE_LEN];
        scenario_palette[6 * 3..6 * 3 + 3].copy_from_slice(&[3, 4, 5]);
        scenario_palette[10 * 3..10 * 3 + 3].copy_from_slice(&[1, 2, 3]);
        fs::write(scenario_path.join("C4.pal"), scenario_palette)
            .expect("scenario C4.pal");
        write_preview_png(&scenario_path.join("Control.png"), [80, 90, 100, 255]);
        write_preview_png(&scenario_path.join("Gamepad.png"), [140, 150, 160, 255]);
        write_preview_png(&scenario_path.join("Options.png"), [110, 120, 130, 255]);
        write_preview_png(&scenario_path.join("Liquid.png"), [170, 180, 190, 255]);
        let mut embedded_palette = [[0_u8; 3]; 256];
        embedded_palette[10] = [0, 255, 0];
        let indexed_rank = lc_resources::bitmap::IndexedBitmap {
            width: 1,
            height: 1,
            indices: vec![10],
        }
        .encode_with_palette(&embedded_palette)
        .expect("indexed scenario Rank.bmp");
        fs::write(scenario_path.join("Rank.bmp"), indexed_rank).expect("scenario Rank.bmp");
        write_solid(
            &scenario_path.join("Cursor.png"),
            39 * 13,
            13,
            [200, 0, 0, 255],
        );
        write_solid(
            &scenario_path.join("CursorLarge.png"),
            39 * 13,
            13,
            [0, 200, 0, 255],
        );
        let scenario_registrations = [LoaderGroupRegistration {
            priority: 200,
            registration_order: 0,
            group: Group::open(&scenario_path).expect("scenario graphics"),
        }];
        let active = resolve_game_graphics_resources(
            &scenario_registrations,
            &base,
            Some(Arc::clone(&startup.cursor_atlas)),
            true,
        )
        .expect("active scenario graphics bundle");
        assert_eq!(
            active
                .hud_graphics
                .rank
                .as_ref()
                .expect("scenario rank")
                .pixels(),
            [4, 8, 12, 255],
            "indexed BMP pixels use the selected game palette, not the embedded BMP palette"
        );
        assert_eq!(
            active
                .hud_graphics
                .control
                .as_ref()
                .expect("scenario control")
                .pixels(),
            [80, 90, 100, 255]
        );
        assert_eq!(
            active
                .hud_graphics
                .gamepad
                .as_ref()
                .expect("scenario gamepad")
                .pixels(),
            [140, 150, 160, 255],
            "the active group set reloads the startup gamepad facet"
        );
        assert_eq!(active.palette.color(6), Color::opaque(12, 16, 20));
        assert_eq!(
            active.options.as_deref().expect("scenario options").pixels(),
            [110, 120, 130, 255]
        );
        assert_eq!(
            active
                .liquid_animation
                .as_deref()
                .expect("scenario liquid animation")
                .pixels(),
            [170, 180, 190, 255]
        );
        assert_eq!(
            active
                .cursor_atlas
                .image_for_resolution(1280)
                .expect("cached large cursor")
                .pixels()[..4],
            [10, 20, 30, 255],
            "a valid legacy Cursor suppresses sized overrides, then the cached pre-game size wins"
        );

        write_solid(
            &sized_path.join("CursorLarge.png"),
            39 * 13,
            13,
            [0, 200, 0, 255],
        );
        let sized = resolve_game_graphics_resources(
            &[LoaderGroupRegistration {
                priority: 200,
                registration_order: 0,
                group: Group::open(&sized_path).expect("sized cursor graphics"),
            }],
            &base,
            Some(Arc::clone(&startup.cursor_atlas)),
            true,
        )
        .expect("sized cursor override bundle");
        let sized_large = sized
            .cursor_atlas
            .image_for_resolution(1280)
            .expect("overridden large cursor");
        assert_eq!(sized_large.height(), 13);
        assert_eq!(&sized_large.pixels()[..4], &[0, 200, 0, 255]);
        assert_eq!(
            (
                35 * sized_large.height(),
                36 * sized_large.height(),
                38 * sized_large.height()
            ),
            (455, 468, 494)
        );

        let mut app = new_menu_app(64, 64);
        let startup_hud = app.assets.hud_graphics();
        let startup_palette = app.assets.game_palette();
        app.active_game_graphics = Some(active.clone());
        app.configure_running_state("Overridden".to_string(), 64);
        assert_eq!(
            app.graphics
                .hud_graphics()
                .rank
                .as_ref()
                .expect("active rank")
                .pixels(),
            [4, 8, 12, 255]
        );
        assert_eq!(app.graphics.game_palette().color(6), Color::opaque(12, 16, 20));
        assert_eq!(
            app.ensure_ingame_menu_gfx()
                .options
                .as_ref()
                .expect("active options sheet")
                .pixels(),
            [110, 120, 130, 255]
        );
        app.resize(80, 80).expect("active graphics survive resize");
        assert_eq!(
            app.graphics
                .hud_graphics()
                .control
                .as_ref()
                .expect("active control after resize")
                .pixels(),
            [80, 90, 100, 255]
        );
        app.return_to_menu();
        assert!(app.active_game_graphics.is_none());
        assert_eq!(app.graphics.hud_graphics().as_ref(), startup_hud.as_ref());
        assert_eq!(app.graphics.game_palette().as_ref(), startup_palette.as_ref());
    }

    #[test]
    fn initial_extra_override_rebinds_canonical_and_malformed_winner_never_falls_back() {
        let _lock = env_lock().lock();

        let valid = tempdir().expect("valid initial Extra fixture");
        install_global_gui_test_root(valid.path(), None);
        let extra_graphics = valid.path().join("planet/Extra.c4g/Graphics.c4g");
        fs::create_dir_all(&extra_graphics).expect("valid Extra Graphics.c4g");
        write_preview_png(
            &extra_graphics.join("GUIBigArrows.png"),
            [0x12, 0x34, 0x56, 0xff],
        );
        {
            let user = valid.path().join("user");
            let _guard = EnvGuard::set(&[
                ("LC_INSTALL_ROOT", Some(valid.path())),
                ("LC_CONTENT_DIR", None),
                ("LC_USER_DATA_DIR", Some(user.as_path())),
            ]);
            let paths = AppPaths::discover().expect("valid initial Extra paths");
            let assets = FrontendAssets::load(Some(&paths));
            assets
                .require_classic_global_gui_bootstrap_resources(&HashMap::new())
                .expect("valid initial Extra override is accepted");
            assert_eq!(
                assets
                    .startup_dialog_images
                    .get("GUIBigArrows.png")
                    .expect("canonical renderer key rebound")
                    .pixels(),
                [0x12, 0x34, 0x56, 0xff]
            );
        }

        let malformed = tempdir().expect("malformed initial Extra fixture");
        install_global_gui_test_root(malformed.path(), None);
        let extra_graphics = malformed.path().join("planet/Extra.c4g/Graphics.c4g");
        fs::create_dir_all(&extra_graphics).expect("malformed Extra Graphics.c4g");
        write_preview_image(
            &extra_graphics.join("GUIBigArrows.png"),
            [0xaa, 0xbb, 0xcc, 0xff],
            image::ImageFormat::Bmp,
        );
        {
            let user = malformed.path().join("user");
            let _guard = EnvGuard::set(&[
                ("LC_INSTALL_ROOT", Some(malformed.path())),
                ("LC_CONTENT_DIR", None),
                ("LC_USER_DATA_DIR", Some(user.as_path())),
            ]);
            let paths = AppPaths::discover().expect("malformed initial Extra paths");
            let assets = FrontendAssets::load(Some(&paths));
            let error = assets
                .require_classic_global_gui_bootstrap_resources(&HashMap::new())
                .expect_err("malformed winning png must not fall back to base PNG");
            assert!(matches!(
                error,
                ClassicParityBoundary::GlobalGuiBootstrapResources { ref issues }
                    if issues.len() == 1
                        && issues[0].resource == "GUIBigArrows"
                        && matches!(&issues[0].defect,
                            ClassicGuiBootstrapDefect::Malformed { .. })
            ));
            assert!(
                !assets
                    .startup_dialog_images
                    .contains_key("GUIBigArrows.png"),
                "a malformed winning source must remove the lower base image"
            );
        }
    }

