    #[test]
    fn options_network_back_validates_both_port_pairs_and_alternate_notice_gate() {
        use lc_frontend::message_dialog::{MessageDialogIcon, MessageDialogResult};
        use lc_frontend::startup_options_dlg::OptionsDlgAction;
        use lc_frontend::startup_options_network::{NetworkCheckboxId, NetworkPortId};

        let mut app = new_classic_menu_app(640, 480);
        app.open_options_menu();
        {
            let network = app.startup_options_dialog.as_mut().unwrap().network_mut();
            let tcp = network.port(NetworkPortId::Tcp).port;
            network.port_mut(NetworkPortId::Reference).port = tcp;
        }
        app.process_options_dialog_actions(vec![OptionsDlgAction::Back])
            .expect("show TCP/reference validation");
        assert_eq!(app.startup_view, StartupView::Options);
        let tcp_error = app
            .message_dialogs
            .last()
            .expect("TCP/reference validation dialog");
        assert_eq!(tcp_error.state.caption(), "Configuration error");
        assert_eq!(
            tcp_error.state.message(),
            "TCP port and reference port must be set to different values between 1 and 65535!"
        );
        assert_eq!(tcp_error.state.icon(), MessageDialogIcon::ERROR);
        app.finish_message_dialog(MessageDialogResult::Ok)
            .expect("dismiss TCP error");

        {
            let network = app.startup_options_dialog.as_mut().unwrap().network_mut();
            network.port_mut(NetworkPortId::Reference).port = 11_111;
            let udp = network.port(NetworkPortId::Udp).port;
            network.port_mut(NetworkPortId::Discovery).port = udp;
        }
        app.process_options_dialog_actions(vec![OptionsDlgAction::Back])
            .expect("show UDP/discovery validation");
        assert_eq!(app.startup_view, StartupView::Options);
        let udp_error = app
            .message_dialogs
            .last()
            .expect("UDP/discovery validation dialog");
        assert_eq!(udp_error.state.caption(), "Configuration error");
        assert_eq!(
            udp_error.state.message(),
            "UDP port and discovery port must be set to different values between 1 and 65535!"
        );
        assert_eq!(udp_error.state.icon(), MessageDialogIcon::ERROR);
        app.finish_message_dialog(MessageDialogResult::Ok)
            .expect("dismiss UDP error");

        app.process_options_dialog_actions(vec![OptionsDlgAction::NetworkCheckboxChanged {
            id: NetworkCheckboxId::UseAlternateServer,
            checked: true,
        }])
        .expect("show alternate-server notice");
        assert!(app.message_dialogs.last().is_some_and(|dialog| matches!(
            dialog.continuation,
            MessageDialogContinuation::OptionsAlternateServerNotice
        )));
        app.message_dialogs
            .last_mut()
            .unwrap()
            .state
            .handle_hotkey('D');
        app.finish_message_dialog(MessageDialogResult::Ok)
            .expect("accept don't-show gate");
        assert!(
            app.startup_options_dialog
                .as_ref()
                .unwrap()
                .network()
                .hide_no_official_league_notice
        );
        app.process_options_dialog_actions(vec![OptionsDlgAction::NetworkCheckboxChanged {
            id: NetworkCheckboxId::UseAlternateServer,
            checked: true,
        }])
        .expect("hidden alternate-server notice");
        assert!(app.message_dialogs.is_empty());
    }

    #[test]
    fn options_close_reports_disk_write_failure() {
        use lc_frontend::message_dialog::MessageDialogIcon;

        let mut app = new_classic_menu_app(640, 480);
        app.open_options_menu();
        app.close_options_menu_with_persist_result(Some(Err(io::Error::new(
            io::ErrorKind::Other,
            "simulated config write failure",
        ))))
        .expect("show config save failure and close Options");

        assert_eq!(app.startup_view, StartupView::MainMenu);
        let error = app
            .message_dialogs
            .last()
            .expect("config save failure dialog remains above the main menu");
        assert_eq!(error.state.caption(), "Configuration error");
        assert_eq!(
            error.state.message(),
            "Could not save configuration: simulated config write failure"
        );
        assert_eq!(error.state.icon(), MessageDialogIcon::ERROR);
        assert!(matches!(error.continuation, MessageDialogContinuation::None));
    }

    #[test]
    fn options_language_loads_real_de_and_selection_reloads_and_persists() {
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        paths.ensure_user_dirs().expect("create user directories");
        fs::write(
            paths.config_file(),
            "[General]\nLanguage=DE - Deutsch\nLanguageEx=DE\n",
        )
        .expect("seed DE config");

        let mut app = GameApp::new(
            1280,
            720,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        wait_for_menu(&mut app);
        app.open_options_menu();

        let program = app
            .startup_options_dialog
            .as_ref()
            .expect("options dialog")
            .program();
        assert_eq!(program.language_text, "DE - Deutsch");
        assert_eq!(
            program.language_info,
            "Original-Sprachpaket von RedWolf Design."
        );
        assert_eq!(
            program.no_language_info,
            "Sprachpaket nicht verf\u{00fc}gbar."
        );
        let mut codes = program
            .language_infos
            .iter()
            .map(|info| info.code.as_str())
            .collect::<Vec<_>>();
        codes.sort_unstable();
        assert_eq!(codes, vec!["DE", "US"]);
        assert_eq!(app.needed_material_need, "%s|braucht noch");
        assert_eq!(app.object_no_dig, "%s kann|nicht graben.");
        assert_eq!(
            app.default_rank_names
                .as_deref()
                .and_then(|names| names.get(1))
                .map(String::as_str),
            Some("Fähnrich")
        );
        assert_eq!(app.loaded_default_rank_names, app.default_rank_names);
        assert_eq!(app_default_rank_promotion_name(&app), "Fähnrich");

        app.process_options_dialog_actions(vec![
            lc_frontend::startup_options_dlg::OptionsDlgAction::OpenLanguageCombo,
        ])
        .expect("open language combo");
        assert!(app.context_menu.is_some());
        app.process_context_menu_outcome(ContextMenuOutcome {
            captured: true,
            pass_through: false,
            focus_suppressed: true,
            events: vec![
                ContextMenuEvent::Closed,
                ContextMenuEvent::Activated(AppContextMenuCommand::OptionsLanguage(
                    "US".to_string(),
                )),
            ],
        })
        .expect("select US language");

        let program = app
            .startup_options_dialog
            .as_ref()
            .expect("recreated options dialog")
            .program();
        assert_eq!(program.language, "US");
        assert_eq!(program.language_text, "US - English");
        assert_eq!(program.language_ex, "US,DE");
        assert_eq!(app.needed_material_need, "%s|needs");
        assert_eq!(app.object_no_dig, "%s cannot dig.");
        assert_eq!(
            app.default_rank_names
                .as_deref()
                .and_then(|names| names.get(1))
                .map(String::as_str),
            Some("Fähnrich")
        );
        assert_eq!(
            app.loaded_default_rank_names
                .as_deref()
                .and_then(|names| names.get(1))
                .map(String::as_str),
            Some("Ensign")
        );
        assert_eq!(app_default_rank_promotion_name(&app), "Fähnrich");

        app.return_to_menu();
        assert_eq!(app.default_rank_names, app.loaded_default_rank_names);
        assert_eq!(app_default_rank_promotion_name(&app), "Ensign");

        let config = Config::load(paths.config_file()).expect("reload selected config");
        assert_eq!(config.get_in(Some("General"), "Language"), Some("US"));
        assert_eq!(config.get_in(Some("General"), "LanguageEx"), Some("US,DE"));
        assert_eq!(config.get_in(Some("General"), "LanguageCharset"), Some(""));
    }

    #[test]
    fn options_sound_sheet_seeds_from_live_audio_and_applies_typed_actions() {
        use lc_frontend::startup_options_dlg::{
            OptionsDlgAction, SoundCheckboxId, SoundSheetAction, SoundSheetState, SoundVolumeId,
        };

        let mut app = new_running_sandbox_app();
        app.return_to_menu();
        {
            let audio = app.audio.as_mut().expect("test audio");
            audio.options.menu_music_enabled = true;
            audio.options.menu_sound_enabled = false;
            audio.options.music_enabled = true;
            audio.options.sound_enabled = false;
            audio.set_music_volume_percent(83);
            audio.set_sound_volume_percent(27);
        }
        app.open_options_menu();
        assert_eq!(
            app.startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .sound(),
            &SoundSheetState::new(true, false, true, false, 83, 27)
        );

        app.process_options_dialog_actions(vec![OptionsDlgAction::Sound(
            SoundSheetAction::CheckboxChanged {
                id: SoundCheckboxId::FrontendMusic,
                checked: false,
            },
        )])
        .expect("disable frontend music");
        app.process_options_dialog_actions(vec![
            OptionsDlgAction::Sound(SoundSheetAction::CheckboxChanged {
                id: SoundCheckboxId::FrontendSoundEffects,
                checked: true,
            }),
            OptionsDlgAction::Sound(SoundSheetAction::CheckboxChanged {
                id: SoundCheckboxId::GameMusic,
                checked: false,
            }),
            OptionsDlgAction::Sound(SoundSheetAction::CheckboxChanged {
                id: SoundCheckboxId::GameSoundEffects,
                checked: true,
            }),
            OptionsDlgAction::Sound(SoundSheetAction::VolumeChanged {
                id: SoundVolumeId::Music,
                value: 25,
            }),
            OptionsDlgAction::Sound(SoundSheetAction::VolumeChanged {
                id: SoundVolumeId::SoundEffects,
                value: 75,
            }),
        ])
        .expect("apply Sound-sheet actions");

        let audio = app.audio.as_ref().expect("test audio");
        assert!(!audio.options.menu_music_enabled);
        assert!(audio.options.menu_sound_enabled);
        assert!(!audio.options.music_enabled);
        assert!(audio.options.sound_enabled);
        assert_eq!(audio.options.music_volume_percent(), 25);
        assert_eq!(audio.options.sound_volume_percent(), 75);
        assert_eq!(
            lock_unpoisoned(&audio.music_control).effective_volume(),
            0.25,
            "the live/pending music controller must update with the slider"
        );
    }

    #[test]
    fn options_sound_sheet_fails_typed_before_pixels_without_audio_context() {
        let mut app = new_real_classic_menu_app(320, 200);
        app.audio = None;
        app.open_options_menu();

        let mut program_frame = vec![0_u8; 320 * 200 * 4];
        app.render(&mut program_frame)
            .expect("Program remains available without audio");

        app.handle_key(VirtualKeyCode::Down, ElementState::Pressed)
            .expect("Graphics remains available without audio");
        app.handle_key(VirtualKeyCode::Down, ElementState::Released)
            .expect("release Graphics navigation");

        let sound_error = app
            .handle_key(VirtualKeyCode::Down, ElementState::Pressed)
            .expect_err("Sound requires the live audio context");
        assert_engine_parity_boundary(
            sound_error,
            ClassicParityBoundary::RuntimeAudioSystem {
                action: "the startup Options Sound sheet",
            },
        );
        assert_eq!(
            app.startup_options_dialog
                .as_ref()
                .expect("retained options model")
                .active_sheet(),
            lc_frontend::startup_options_dlg::OptionsSheet::Sound
        );

        let mut frame = vec![0xa5; 320 * 200 * 4];
        let error = app
            .render(&mut frame)
            .expect_err("render preflight must reject guessed Sound state");
        let expected = ClassicParityBoundary::RuntimeAudioSystem {
            action: "the startup Options Sound sheet",
        };
        assert_eq!(
            error.downcast_ref::<ClassicParityBoundary>(),
            Some(&expected)
        );
        assert!(frame.iter().all(|byte| *byte == 0xa5));
    }

    #[test]
    fn options_sound_modifier_tabs_and_raw_gamepad_buttons_keep_classic_ownership() {
        use lc_frontend::startup_options_dlg::SoundCheckboxId;

        let mut keyboard = new_running_sandbox_app();
        keyboard.return_to_menu();
        enter_unported_startup_subscreen(
            &mut keyboard,
            ClassicStartupSubscreen::Options(lc_frontend::startup_options_dlg::OptionsSheet::Sound),
        );
        keyboard
            .handle_modifiers_changed(ModifiersState::empty())
            .expect("clear modifiers");
        keyboard
            .handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("Tab enters the first Sound checkbox");
        assert_eq!(
            keyboard
                .startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .focused_sound_checkbox(),
            Some(SoundCheckboxId::FrontendMusic)
        );
        keyboard
            .handle_key(VirtualKeyCode::Tab, ElementState::Released)
            .expect("release Tab");
        keyboard
            .handle_modifiers_changed(ModifiersState::SHIFT)
            .expect("hold Shift");
        keyboard
            .handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("Shift+Tab reverses to the tabular");
        assert_eq!(
            keyboard
                .startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .focused_sound_checkbox(),
            None
        );

        keyboard
            .handle_modifiers_changed(ModifiersState::empty())
            .expect("clear Shift");
        keyboard
            .handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("focus the first Sound checkbox again");
        keyboard
            .handle_modifiers_changed(ModifiersState::ALT)
            .expect("hold Alt");
        keyboard
            .handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("Alt+Tab has no classic Options binding");
        assert_eq!(
            keyboard
                .startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .focused_sound_checkbox(),
            Some(SoundCheckboxId::FrontendMusic),
            "modifier-blind fallback must not invent a plain Tab"
        );
        keyboard
            .handle_modifiers_changed(ModifiersState::CTRL | ModifiersState::SHIFT)
            .expect("hold Ctrl+Shift");
        keyboard
            .handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("Ctrl+Shift+Tab cycles the sheet despite child focus");
        assert_eq!(
            keyboard
                .startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .active_sheet(),
            lc_frontend::startup_options_dlg::OptionsSheet::Graphics
        );

        let mut gamepad = new_running_sandbox_app();
        gamepad.return_to_menu();
        enter_unported_startup_subscreen(
            &mut gamepad,
            ClassicStartupSubscreen::Options(lc_frontend::startup_options_dlg::OptionsSheet::Sound),
        );
        gamepad
            .process_gamepad_event_batch([
                GamepadEvent::Direction {
                    slot: GamepadSlot::new(0),
                    button: ControlButton::Right,
                    state: ElementState::Pressed,
                },
                GamepadEvent::Direction {
                    slot: GamepadSlot::new(0),
                    button: ControlButton::Right,
                    state: ElementState::Pressed,
                },
            ])
            .expect("focus FE sound effects");
        assert_eq!(
            gamepad
                .startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .focused_sound_checkbox(),
            Some(SoundCheckboxId::FrontendSoundEffects)
        );
        assert!(!gamepad.audio.as_ref().unwrap().options.menu_sound_enabled);
        gamepad
            .process_gamepad_event_batch([
                GamepadEvent::GuiButton {
                    slot: GamepadSlot::new(0),
                    class: GuiButtonClass::Low,
                    state: ElementState::Pressed,
                },
                GamepadEvent::Action {
                    slot: GamepadSlot::new(0),
                    action: GamepadActionType::Select,
                    state: ElementState::Pressed,
                },
            ])
            .expect("raw AnyLowButton owns checkbox activation");
        assert!(gamepad.audio.as_ref().unwrap().options.menu_sound_enabled);

        let mut back = new_running_sandbox_app();
        back.return_to_menu();
        enter_unported_startup_subscreen(
            &mut back,
            ClassicStartupSubscreen::Options(lc_frontend::startup_options_dlg::OptionsSheet::Sound),
        );
        back.process_gamepad_event_batch([GamepadEvent::Direction {
            slot: GamepadSlot::new(0),
            button: ControlButton::Left,
            state: ElementState::Pressed,
        }])
        .expect("focus Back");
        back.process_gamepad_event_batch([
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::Low,
                state: ElementState::Pressed,
            },
            GamepadEvent::Action {
                slot: GamepadSlot::new(0),
                action: GamepadActionType::Select,
                state: ElementState::Pressed,
            },
            GamepadEvent::GuiButton {
                slot: GamepadSlot::new(0),
                class: GuiButtonClass::Low,
                state: ElementState::Released,
            },
            GamepadEvent::Action {
                slot: GamepadSlot::new(0),
                action: GamepadActionType::Select,
                state: ElementState::Released,
            },
        ])
        .expect("raw low release closes exactly once");
        assert_eq!(back.startup_view, StartupView::MainMenu);
    }

    #[test]
    fn options_non_tab_gui_bindings_require_the_exact_bare_modifier_mask() {
        use lc_frontend::startup_options_dlg::{OptionsSheet, SoundCheckboxId};

        let modifier_masks = [
            ModifiersState::ALT,
            ModifiersState::CTRL,
            ModifiersState::SHIFT,
            ModifiersState::ALT | ModifiersState::CTRL,
            ModifiersState::ALT | ModifiersState::SHIFT,
            ModifiersState::CTRL | ModifiersState::SHIFT,
            ModifiersState::ALT | ModifiersState::CTRL | ModifiersState::SHIFT,
        ];

        let mut checkbox = new_running_sandbox_app();
        checkbox.return_to_menu();
        enter_unported_startup_subscreen(
            &mut checkbox,
            ClassicStartupSubscreen::Options(OptionsSheet::Sound),
        );
        for modifiers in modifier_masks {
            checkbox
                .handle_modifiers_changed(modifiers)
                .expect("set exact C++ modifier mask");
            for key in [
                VirtualKeyCode::Up,
                VirtualKeyCode::Down,
                VirtualKeyCode::Left,
                VirtualKeyCode::Back,
                VirtualKeyCode::Escape,
                VirtualKeyCode::Right,
            ] {
                checkbox
                    .handle_key(key, ElementState::Pressed)
                    .unwrap_or_else(|error| panic!("modified {key:?} down: {error}"));
                checkbox
                    .handle_key(key, ElementState::Released)
                    .unwrap_or_else(|error| panic!("modified {key:?} up: {error}"));
            }
            assert_eq!(checkbox.startup_view, StartupView::Options);
            assert_eq!(
                checkbox
                    .startup_options_dialog
                    .as_ref()
                    .expect("Options model")
                    .active_sheet(),
                OptionsSheet::Sound,
                "modified Up/Down must not switch sheets"
            );
        }

        checkbox
            .handle_modifiers_changed(ModifiersState::empty())
            .expect("clear modifiers");
        checkbox
            .handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("bare Tab focuses FE Music");
        checkbox
            .handle_key(VirtualKeyCode::Tab, ElementState::Released)
            .expect("release bare Tab");
        checkbox
            .handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("bare Tab focuses FE Sound Effects");
        checkbox
            .handle_key(VirtualKeyCode::Tab, ElementState::Released)
            .expect("release second bare Tab");
        assert_eq!(
            checkbox
                .startup_options_dialog
                .as_ref()
                .expect("Options model")
                .focused_sound_checkbox(),
            Some(SoundCheckboxId::FrontendSoundEffects)
        );
        let before_checkbox = checkbox
            .startup_options_dialog
            .as_ref()
            .expect("Options model")
            .sound()
            .clone();
        for modifiers in modifier_masks {
            checkbox
                .handle_modifiers_changed(modifiers)
                .expect("set exact C++ modifier mask");
            for key in [
                VirtualKeyCode::Space,
                VirtualKeyCode::Left,
                VirtualKeyCode::Back,
                VirtualKeyCode::Escape,
            ] {
                checkbox
                    .handle_key(key, ElementState::Pressed)
                    .unwrap_or_else(|error| panic!("modified {key:?} down: {error}"));
                checkbox
                    .handle_key(key, ElementState::Released)
                    .unwrap_or_else(|error| panic!("modified {key:?} up: {error}"));
            }
            assert_eq!(checkbox.startup_view, StartupView::Options);
            assert_eq!(
                checkbox
                    .startup_options_dialog
                    .as_ref()
                    .expect("Options model")
                    .sound(),
                &before_checkbox,
                "modified Space must not toggle the focused checkbox"
            );
        }

        checkbox
            .handle_modifiers_changed(ModifiersState::LOGO)
            .expect("Logo is outside the C++ modifier mask");
        checkbox
            .handle_key(VirtualKeyCode::Space, ElementState::Pressed)
            .expect("Logo+Space remains the bare checkbox binding");
        assert_ne!(
            checkbox
                .startup_options_dialog
                .as_ref()
                .expect("Options model")
                .sound(),
            &before_checkbox
        );

        let mut back = new_running_sandbox_app();
        back.return_to_menu();
        enter_unported_startup_subscreen(
            &mut back,
            ClassicStartupSubscreen::Options(OptionsSheet::Sound),
        );
        back.handle_modifiers_changed(ModifiersState::SHIFT)
            .expect("hold Shift for reverse traversal");
        back.handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("Shift+Tab focuses Back");
        back.handle_key(VirtualKeyCode::Tab, ElementState::Released)
            .expect("release Shift+Tab");
        for modifiers in modifier_masks {
            back.handle_modifiers_changed(modifiers)
                .expect("set exact C++ modifier mask");
            for key in [
                VirtualKeyCode::Return,
                VirtualKeyCode::NumpadEnter,
                VirtualKeyCode::Space,
            ] {
                back.handle_key(key, ElementState::Pressed)
                    .unwrap_or_else(|error| panic!("modified Back {key:?} down: {error}"));
                back.handle_key(key, ElementState::Released)
                    .unwrap_or_else(|error| panic!("modified Back {key:?} up: {error}"));
            }
            assert_eq!(
                back.startup_view,
                StartupView::Options,
                "modified Enter/Space must not activate Back"
            );
        }
    }

    #[test]
    fn options_sound_held_arrow_advances_before_each_rendered_frame() {
        let mut app = new_classic_running_sandbox_app();
        app.return_to_menu();
        app.resize(800, 600).expect("resize menu");
        app.audio
            .as_mut()
            .expect("test audio")
            .set_music_volume_percent(50);
        enter_unported_startup_subscreen(
            &mut app,
            ClassicStartupSubscreen::Options(lc_frontend::startup_options_dlg::OptionsSheet::Sound),
        );
        let slider = {
            let gui = app.assets.clonk_fonts.as_deref().expect("GUI fonts");
            let book = app
                .assets
                .options_book_fonts
                .as_deref()
                .expect("options book fonts");
            lc_frontend::startup_options_dlg::options_dlg_layout(800, 600, gui, book)
                .sound
                .slider(lc_frontend::startup_options_dlg::SoundVolumeId::Music)
        };
        let decrement =
            PhysicalPosition::new(f64::from(slider.x + 2), f64::from(slider.y + slider.h / 2));
        app.handle_cursor_moved(decrement)
            .expect("hover decrement arrow");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("hold decrement arrow");
        assert_eq!(
            app.audio
                .as_ref()
                .expect("test audio")
                .options
                .music_volume_percent(),
            50,
            "the arrow changes during DrawElement, not on pointer-down"
        );

        let mut frame = vec![0_u8; 800 * 600 * 4];
        app.render(&mut frame).expect("render held-arrow frame");
        assert!(
            app.audio
                .as_ref()
                .expect("test audio")
                .options
                .music_volume_percent()
                < 50,
            "advance_frame must apply the slider callback before pixels"
        );
        app.handle_mouse_button(ElementState::Released)
            .expect("release decrement arrow");
    }

    // BoolConfig mutates Config.General.ShowLogTimestamps immediately, while
    // DoBack saves the configuration before returning to the main dialog
    // (C4StartupOptionsDlg.cpp:564-568, 1150-1184, 1189-1194).
    #[test]
    fn options_dialog_saves_log_timestamps_when_closed() {
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        persist_config_value(&paths, "General", "ShowLogTimestamps", "1")
            .expect("seed timestamp config");
        persist_config_value(&paths, "Sound", "MaxChannels", "37")
            .expect("seed preserved sound config");
        persist_config_value(&paths, "Sound", "VendorExtension", "keep-me")
            .expect("seed preserved sound extension");
        let mut app = GameApp::new(
            1280,
            720,
            AudioOptions {
                max_channels: 37,
                prefer_linear_resampling: false,
                sound_enabled: false,
                music_enabled: true,
                menu_music_enabled: false,
                menu_sound_enabled: true,
                mute_sound_command: false,
                sound_volume: 0.27,
                music_volume: 0.83,
            },
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        wait_for_menu(&mut app);
        app.open_options_menu();
        let gui = app.assets.clonk_fonts.as_deref().expect("GUI fonts");
        let book = app
            .assets
            .options_book_fonts
            .as_deref()
            .expect("options book fonts");
        let checkbox = lc_frontend::startup_options_dlg::options_dlg_layout(1280, 720, gui, book)
            .timestamps_check;
        let point = PhysicalPosition::new(
            f64::from(checkbox.x + checkbox.h / 2),
            f64::from(checkbox.y + checkbox.h / 2),
        );

        app.handle_cursor_moved(point).expect("hover Timestamps");
        app.handle_mouse_button(ElementState::Pressed)
            .expect("press Timestamps");
        app.handle_mouse_button(ElementState::Released)
            .expect("release Timestamps");
        assert!(
            !app.startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .program()
                .show_log_timestamps,
            "checkbox toggles before the dialog closes"
        );
        assert_eq!(
            Config::load(paths.config_file())
                .expect("config before close")
                .get_in(Some("General"), "ShowLogTimestamps"),
            Some("1"),
            "C++ defers Config.Save until DoBack"
        );

        app.handle_modifiers_changed(ModifiersState::CTRL)
            .expect("hold Ctrl");
        app.handle_key(VirtualKeyCode::F3, ElementState::Pressed)
            .expect("global frontend-sound toggle");
        assert!(
            app.startup_options_dialog
                .as_ref()
                .expect("options dialog")
                .sound()
                .frontend_sound_effects,
            "Ctrl+F3 leaves the classic checkbox visually stale"
        );
        assert!(
            !app.audio
                .as_ref()
                .expect("test audio")
                .options
                .menu_sound_enabled,
            "live audio configuration remains authoritative"
        );
        app.handle_modifiers_changed(ModifiersState::empty())
            .expect("release Ctrl");

        {
            use lc_frontend::startup_options_graphics::GraphicsDisplayMode;
            use lc_frontend::startup_options_network::NetworkPortId;
            let dialog = app.startup_options_dialog.as_mut().unwrap();
            dialog
                .graphics_mut()
                .set_display_mode(GraphicsDisplayMode::Window);
            dialog.graphics_mut().smoke_level = 73;
            dialog.graphics_mut().fire_particles = false;
            dialog.network_mut().port_mut(NetworkPortId::Tcp).enabled = false;
            dialog.network_mut().use_alternate_server = true;
            dialog.network_mut().local_name = "Same Name".to_string();
            dialog.network_mut().nick = "Same Name".to_string();
            dialog.network_mut().hide_no_official_league_notice = true;
        }
        app.bindings
            .rebind_for_set(2, ControlBindingId::Dig, VirtualKeyCode::Z);
        app.gamepad_bindings
            .rebind_button(1, ControlBindingId::Up, 1, 4);
        app.gamepad_gui_control = true;

        app.handle_key(VirtualKeyCode::Escape, ElementState::Pressed)
            .expect("close options");

        assert_eq!(app.startup_view, StartupView::MainMenu);
        let config = Config::load(paths.config_file()).expect("config after close");
        assert_eq!(
            config.get_in(Some("General"), "ShowLogTimestamps"),
            Some("0")
        );
        assert_eq!(config.get_in(Some("Sound"), "Sound"), Some("false"));
        assert_eq!(config.get_in(Some("Sound"), "Music"), Some("true"));
        assert_eq!(config.get_in(Some("Sound"), "MenuMusic"), Some("false"));
        assert_eq!(config.get_in(Some("Sound"), "MenuSound"), Some("false"));
        assert_eq!(config.get_in(Some("Sound"), "MusicVolume"), Some("83"));
        assert_eq!(config.get_in(Some("Sound"), "SoundVolume"), Some("27"));
        assert_eq!(config.get_in(Some("Sound"), "MaxChannels"), Some("37"));
        assert_eq!(
            config.get_in(Some("Sound"), "VendorExtension"),
            Some("keep-me")
        );
        assert_eq!(config.get_in(Some("Graphics"), "DisplayMode"), Some("Window"));
        assert_eq!(config.get_in(Some("Graphics"), "SmokeLevel"), Some("73"));
        assert_eq!(config.get_in(Some("Graphics"), "FireParticles"), Some("0"));
        assert_eq!(config.get_in(Some("Network"), "PortTCP"), Some("0"));
        assert_eq!(config.get_in(Some("Network"), "UseAlternateServer"), Some("1"));
        assert_eq!(config.get_in(Some("Network"), "LocalName"), Some("Same Name"));
        assert_eq!(config.get_in(Some("Network"), "Nick"), Some(""));
        assert_eq!(
            config.get_in(Some("Startup"), "HideMsgNoOfficialLeague"),
            Some("1")
        );
        assert!(config.get_in(Some("Controls"), "Kbd3Key6").is_some());
        assert_eq!(config.get_in(Some("Controls"), "GamepadGuiControl"), Some("1"));
        assert_eq!(
            config.get_in(Some("Gamepad1"), "Button5"),
            input::legacy_gamepad_button_key(1, 4)
                .map(|key| key.to_string())
                .as_deref()
        );
    }

    #[test]
    fn network_create_selects_a_scenario_before_binding_a_host() {
        // C4StartupNetDlg::CreateGame only switches to the network scenario
        // selector. The selected scenario is stored before OpenGame opens it
        // and calls InitNetworkHost, so no network socket/reference exists in
        // the selector (src/C4StartupNetDlg.cpp:1111-1114;
        // src/C4StartupScenSelDlg.cpp:1635-1666;
        // src/C4Game.cpp:421-438).
        let mut app = new_menu_app(1280, 720);
        app.open_network_game_dialog();

        app.process_network_dialog_actions(vec![
            lc_frontend::startup_netdlg::NetDlgAction::CreateGame,
        ])
        .expect("open network scenario selector");

        assert_eq!(app.startup_view, StartupView::ScenarioBrowser);
        assert_eq!(
            app.scenario_selector_mode,
            ScenarioSelectorMode::NetworkHost
        );
        assert!(app.startup_network_connection.is_none());
        assert!(app.network.is_none());
        assert!(app.network_game_advertiser.is_none());

        app.scensel_do_back()
            .expect("return from network scenario selector");
        assert_eq!(app.startup_view, StartupView::NetworkGame);
    }

    #[test]
    fn network_host_preparation_keeps_cpp_configured_participant_order() {
        // C4Game freezes Config.General.Participants into PlayerFilenames and
        // C4ClientPlayerInfos walks those modules in order. The separately
        // sorted startup player-selection rows never reorder the host's
        // initial packet or NRT_Player IDs (pristine 9ffa0a5d
        // src/C4Game.cpp:361-364; src/C4PlayerInfo.cpp:70-104,357-395).
        let install = tempdir().expect("install root");
        install_global_gui_and_loader_test_root(install.path());
        let content = install.path().join("content");
        let scenario_path = content.join("Order.c4s");
        fs::create_dir_all(&scenario_path).expect("create scenario group");
        let players = install.path().join("Players");
        fs::create_dir_all(&players).expect("create player directory");
        let write_player = |filename: &str, name: &[u8]| {
            let path = players.join(filename);
            let mut group = lc_resources::MutableGroup::new(filename);
            let mut player_core = b"[Player]\nName=".to_vec();
            player_core.extend_from_slice(name);
            player_core.extend_from_slice(b"\n[Preferences]\nColorDw=255\n");
            group
                .add_file_with_metadata("Player.txt", player_core, 1, false)
                .expect("add player core");
            fs::write(&path, group.pack().expect("pack player")).expect("write player");
            path
        };
        let bravo = write_player("Bravo.c4p", b"Br\xc3\xa4vo");
        let alpha = write_player("Alpha.c4p", b"Alpha");
        let user_data = tempdir().expect("user data");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install.path())),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        paths.ensure_user_dirs().expect("create user directories");
        let mut config = b"[General]\nName=\"M\xc3\xa4ker\"\nPlayerPath=Players\nParticipants=Players/Bravo.c4p;Players/Alpha.c4p\n\n[Network]\nLocalName=\"H\xc3\xa4st\"\nNick=\"N\xc3\xa4ck\"\nComment=\"".to_vec();
        for _ in 0..129 {
            config.extend_from_slice(b"\xc3\xa4");
        }
        config.extend_from_slice(
            b"\"\nControlRate=7\nControlMode=1\nPortTCP=12345\nPortUDP=12346\nMaxLoadFileSize=123456\nNoRuntimeJoin=0\nEnableUPnP=0\n",
        );
        fs::write(paths.config_file(), config).expect("write native configured participants");
        let app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialize app");
        assert_eq!(
            app.startup_player_files
                .iter()
                .map(|player| player.path.as_path())
                .collect::<Vec<_>>(),
            vec![alpha.as_path(), bravo.as_path()],
            "the UI model supplies the deliberately opposite sorted order"
        );
        let mut scenario = FrontendScenario::fallback();
        scenario.title = "Order".to_string();
        scenario.path = Some(scenario_path);

        let preparation = build_network_host_preparation(
            &app,
            &scenario,
            &ScenarioDefinitionLoad::Seed {
                modules: Vec::new(),
                definition_root: None,
            },
            &[],
            &[],
            None,
            None,
        )
        .expect("prepare host inputs");

        assert_eq!(
            lc_resources::encode_legacy_script_text(&preparation.group_maker),
            Some(b"M\xc3\xa4ker".to_vec())
        );
        assert_eq!(
            lc_resources::encode_legacy_script_text(&preparation.host_name),
            Some(b"H\xc3\xa4st".to_vec())
        );
        assert_eq!(
            lc_resources::encode_legacy_script_text(&preparation.host_nick),
            Some(b"N\xc3\xa4ck".to_vec())
        );
        assert_eq!(
            lc_resources::encode_legacy_script_text(&preparation.network_comment),
            Some(b"\xc3\xa4".repeat(128)),
            "VAL_Comment counts and truncates native bytes, not Unicode scalars"
        );
        assert_eq!(
            preparation.player_sources[0]
                .identity
                .as_ref()
                .expect("configured player identity")
                .player_name
                .as_bytes(),
            b"Br\xc3\xa4vo",
            "valid UTF-8-shaped player-name bytes remain native bytes"
        );
        assert_eq!(preparation.config.control_rate, 7);
        assert_eq!(preparation.config.control_mode, 1);
        assert_eq!(preparation.config.network_tcp_port, 12_345);
        assert_eq!(preparation.config.network_udp_port, 12_346);
        assert_eq!(preparation.config.max_load_file_size, 123_456);
        assert!(!preparation.config.no_runtime_join);
        assert!(!preparation.config.enable_upnp);

        let publication = preparation
            .league
            .as_ref()
            .expect("master-server signup creates a lifecycle client");
        assert!(!publication.league_server_signup);
        assert_eq!(
            preparation
                .player_sources
                .iter()
                .map(|source| {
                    (
                        source.resource.path.as_path(),
                        source.resource.wire_name.as_bytes(),
                    )
                })
                .collect::<Vec<_>>(),
            vec![
                (bravo.as_path(), b"Players/Bravo.c4p".as_slice()),
                (alpha.as_path(), b"Players/Alpha.c4p".as_slice()),
            ]
        );
    }

    #[test]
    fn command_line_definition_selection_is_published_to_network_clients() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("command-line host user data");
        let content = tempdir().expect("command-line host content");
        let content_root = content.path();
        fs::create_dir_all(content_root.join("Material.c4g")).expect("global material group");
        let base = install_network_definition_pack(content_root, "Base.c4d", "BAS1");
        let extra_one = install_network_definition_pack(content_root, "ExtraOne.c4d", "EXT1");
        let extra_two = install_network_definition_pack(content_root, "ExtraTwo.c4d", "EXT2");
        let objects = install_network_definition_pack(content_root, "Objects.c4d", "OBJS");
        let scenario_path = content_root.join("CommandLine.c4s");
        fs::create_dir_all(&scenario_path).expect("command-line scenario group");
        fs::write(
            scenario_path.join("Scenario.txt"),
            "[Head]\nTitle=Command Line Definitions\nMaxPlayer=1\nNoInitialize=1\n\n[Definitions]\nLocalOnly=1\n",
        )
        .expect("command-line scenario core");

        let (_guard, paths) = exact_loader_test_paths(user_data.path(), Some(content_root));
        persist_config_value(&paths, "General", "Definitions", "Base.c4d")
            .expect("configure default definition seed");
        let mut app = new_menu_app_with_paths(640, 480, &paths);
        let classic = parse_classic_command_line(&[
            OsString::from("./ExtraOne.c4d"),
            OsString::from("ExtraTwo.c4d"),
        ]);
        app.apply_classic_command_line(&classic)
            .expect("apply classic definition arguments");
        persist_config_value(&paths, "General", "Definitions", "ChangedAfterParse.c4d")
            .expect("mutate config after ParseCommandLine snapshot");
        let definition_load = app.take_scenario_seed_definition_load();
        assert!(matches!(
            &definition_load,
            ScenarioDefinitionLoad::Seed { modules, .. }
                if modules == &["Base.c4d", "./ExtraOne.c4d", "ExtraTwo.c4d", "Objects.c4d"]
        ));
        let frontend = FrontendScenario {
            identifier: "CommandLine.c4s".to_string(),
            title: "Command Line Definitions".to_string(),
            path: Some(scenario_path),
            ..FrontendScenario::fallback()
        };
        let staged = app
            .prepare_network_host_scenario(frontend, definition_load)
            .expect("stage the consumed command-line definition host");
        assert!(matches!(
            app.scenario_seed_definition_load(),
            ScenarioDefinitionLoad::Seed { modules, .. }
                if modules == ["Objects.c4d"]
        ));
        assert_eq!(
            staged.scenario.definition_resource_paths(),
            &[
                base.clone(),
                extra_one.clone(),
                extra_two.clone(),
                objects.clone(),
            ]
        );
        let prepared = prepare_staged_network_host(&app, &staged);
        assert_eq!(
            published_definition_wire_names(&prepared),
            vec![
                b"Base.c4d".to_vec(),
                b"./ExtraOne.c4d".to_vec(),
                b"ExtraTwo.c4d".to_vec(),
                b"Objects.c4d".to_vec(),
            ]
        );

        let host = prepared.host_config();
        let snapshot = host
            .initial_join_snapshot
            .as_ref()
            .expect("prepared JoinData")
            .clone();
        assert_eq!(
            snapshot
                .parameters
                .game_resources
                .iter()
                .filter(|core| {
                    core.resource_type == lc_network::HostResourceType::Definitions as u8
                })
                .map(|core| core.filename.as_bytes().to_vec())
                .collect::<Vec<_>>(),
            published_definition_wire_names(&prepared)
        );
        let dynamic_path = host
            .resource_files
            .iter()
            .find(|resource| {
                resource.core.resource_type == lc_network::HostResourceType::Dynamic as u8
            })
            .expect("published dynamic")
            .path
            .clone();
        let dynamic_scenario = Group::open(&dynamic_path)
            .expect("open published dynamic")
            .read_file("Scenario.txt")
            .expect("dynamic Scenario.txt");
        let expected_definitions =
            b"Definitions=\"Base.c4d\",\"./ExtraOne.c4d\",\"ExtraTwo.c4d\",\"Objects.c4d\"";
        assert!(dynamic_scenario
            .windows(expected_definitions.len())
            .any(|window| window == expected_definitions));

        let host_files = host.resource_files.clone();
        let join_data = lc_network::JoinDataEnvelope {
            client_id: 2,
            start_control_tick: snapshot.dynamic_tick,
            status: host.initial_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        let complete_path = |core: &lc_engine::NetworkResourceCore| {
            host_files
                .iter()
                .find(|resource| resource.core.id == core.id)
                .map(|resource| resource.path.clone())
        };
        let scenario_resources =
            resolve_client_scenario_resources(&join_data, complete_path).expect("client scenario");
        let game_resources = resolve_client_game_resources(&join_data, |core| {
            host_files
                .iter()
                .find(|resource| resource.core.id == core.id)
                .map(|resource| resource.path.clone())
        })
        .expect("client game resources");
        let client_directory = tempdir().expect("client preload directory");
        let combined_path = client_directory.path().join("Combined2.c4s");
        let mut artifact = GameApp::run_lobby_preload_job(LobbyPreloadJob {
            graphics: LobbyPreloadGraphicsContext {
                app_paths: app.app_paths.clone(),
                fallback: app.startup_game_graphics_resources(),
                liquid_animation_enabled: app.assets.liquid_animation_enabled(),
            },
            source: LobbyPreloadJobSource::Client {
                join_data,
                scenario_resources: Some(scenario_resources),
                game_resources,
                resource_directory: client_directory.path().to_path_buf(),
                maker: "Exact Host".to_string(),
                scenario_path: combined_path,
                staging_path: None,
            },
        })
        .expect("client loads published definition vector");
        let mut client_definition_ids = Vec::new();
        artifact
            .client
            .as_mut()
            .and_then(|client| client.scenario.take())
            .expect("preloaded client Scenario")
            .visit_definition_groups(|id, _| client_definition_ids.push(id.to_string()));
        assert_eq!(
            client_definition_ids,
            vec![
                "BAS1".to_string(),
                "EXT1".to_string(),
                "EXT2".to_string(),
                "OBJS".to_string(),
            ]
        );
        let mut host_definition_ids = Vec::new();
        prepared
            .claim_scenario()
            .expect("prepared host Scenario")
            .visit_definition_groups(|id, _| host_definition_ids.push(id.to_string()));
        assert_eq!(host_definition_ids, client_definition_ids);
    }

    #[test]
    fn packed_scenario_alias_is_skipped_as_an_external_definition() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("scenario-alias user data");
        let content = tempdir().expect("scenario-alias content");
        let content_root = content.path();
        fs::create_dir_all(content_root.join("Material.c4g"))
            .expect("scenario-alias global material group");
        let scenario_path = content_root.join("AliasScenario.c4s");
        let mut scenario_group = lc_resources::MutableGroup::new("AliasScenario.c4s");
        scenario_group
            .add_file(
                "Scenario.txt",
                b"[Head]\nTitle=Scenario Alias\nMaxPlayer=1\nNoInitialize=1\n\n[Definitions]\nLocalOnly=1\n"
                    .to_vec(),
            )
            .expect("add packed scenario core");
        scenario_group
            .add_child(
                "ScenarioDef.c4d",
                packed_network_definition("ScenarioDef.c4d", "SCEN"),
            )
            .expect("add packed scenario definition");
        fs::write(
            &scenario_path,
            scenario_group.pack().expect("pack aliased scenario"),
        )
        .expect("write aliased scenario");

        let (_guard, paths) = exact_loader_test_paths(user_data.path(), Some(content_root));
        let app = new_menu_app_with_paths(640, 480, &paths);
        let staged = app
            .prepare_network_host_scenario(
                FrontendScenario {
                    identifier: "AliasScenario.c4s".to_string(),
                    title: "Scenario Alias".to_string(),
                    path: Some(scenario_path.clone()),
                    ..FrontendScenario::fallback()
                },
                ScenarioDefinitionLoad::Fixed {
                    modules: vec![path_as_legacy_text(&scenario_path)],
                    definition_root: None,
                },
            )
            .expect("stage packed scenario alias");
        assert_eq!(
            staged.scenario.definition_resource_paths(),
            [scenario_path.clone()]
        );

        let prepared = prepare_staged_network_host(&app, &staged);
        let snapshot = prepared
            .host_config()
            .initial_join_snapshot
            .as_ref()
            .expect("scenario-alias JoinData");
        assert_eq!(snapshot.parameters.game_resources[0].id, snapshot.parameters.scenario.id);
        assert_eq!(
            snapshot.parameters.game_resources[0].resource_type,
            lc_network::HostResourceType::Scenario as u8
        );
        assert!(published_definition_wire_names(&prepared).is_empty());
        assert_eq!(
            prepared.definition_modules(),
            [path_as_legacy_text(&scenario_path)]
        );

        let scenario = prepared
            .claim_scenario()
            .expect("claim post-publication scenario alias");
        assert!(scenario.definition_resource_paths().is_empty());
        let mut definition_ids = Vec::new();
        scenario.visit_definition_groups(|id, _| definition_ids.push(id.to_string()));
        assert_eq!(definition_ids, ["SCEN"]);
    }

