    #[test]
    fn client_join_flow_password_prompt_retains_the_complete_prepared_reference() {
        let mut app = new_classic_menu_app(800, 600);
        let global_tcp = lc_network::NetworkAddress::new(
            lc_network::NetworkProtocol::Tcp,
            "8.8.8.8:11112".parse().unwrap(),
        );
        let private_udp = lc_network::NetworkAddress::new(
            lc_network::NetworkProtocol::Udp,
            "10.0.0.7:11113".parse().unwrap(),
        );
        let reference = lc_network::NetworkGameReference {
            title: "Passworded game".to_string(),
            password_needed: true,
            addresses: vec![private_udp, global_tcp],
            source_address: "127.0.0.1:11111".parse().unwrap(),
            netpuncher_ipv4: 0x1122_3344,
            netpuncher_ipv6: 0x5566_7788,
            netpuncher_address: "puncher.invalid:11115".to_string(),
            version: lc_network::CURRENT_GAME_VERSION,
            build: lc_network::CURRENT_GAME_BUILD,
            ..Default::default()
        };
        let metrics = lc_frontend::startup_netdlg::NetDlgFontMetrics {
            caption_back_extent: 51,
            text_ip_extent: 18,
            text_line_height: 22,
            caption_line_height: 25,
            title_line_height: 34,
        };
        let mut network_dialog = lc_frontend::startup_netdlg::NetDlgController::new(
            lc_frontend::startup_netdlg::NetDlgConfig {
                masterserver_signup: false,
                record: false,
            },
            metrics,
        );
        network_dialog.resize(800, 600);
        network_dialog.set_games(vec![lc_frontend::startup_netdlg::NetDlgGameEntry {
            title: reference.title.clone(),
            details: String::new(),
            extra_lines: Vec::new(),
            status_icons: Vec::new(),
            row_icon: lc_frontend::startup_netdlg::NetDlgRowIcon::None,
            address: None,
            joinable: true,
        }]);
        assert!(network_dialog
            .handle_key_down(KeyCode::Down)
            .is_empty());
        let actions = network_dialog.handle_key_down(KeyCode::Enter);
        assert_eq!(
            actions,
            [lc_frontend::startup_netdlg::NetDlgAction::JoinGame {
                address: None,
            }]
        );
        app.startup_network_dialog = Some(network_dialog);
        app.startup_game_references = vec![reference];
        app.active_scenario = Some(FrontendScenario::fallback());
        app.active_definition_load = Some(ScenarioDefinitionLoad::Fixed {
            modules: vec!["Stale.c4d".to_string()],
            definition_root: None,
        });

        app.process_network_dialog_actions(actions)
            .expect("selected complete reference opens the exact password prompt");

        assert!(app.active_scenario.is_none());
        match app.active_definition_load.as_ref() {
            Some(ScenarioDefinitionLoad::Seed { modules, .. }) => {
                assert_eq!(modules, &["Objects.c4d".to_string()]);
            }
            other => panic!("reference join must install the Objects seed, got {other:?}"),
        }
        let settings = app
            .pending_network_join
            .as_ref()
            .expect("prepared join is retained while prompting");
        assert_eq!(settings.server_addresses, [global_tcp, private_udp]);
        assert_eq!(
            settings.netpuncher_address.as_deref(),
            Some("puncher.invalid:11115")
        );
        assert_eq!(settings.netpuncher_game_ids.ipv4, 0x1122_3344);
        assert_eq!(settings.netpuncher_game_ids.ipv6, 0x5566_7788);
        assert!(settings.password.is_empty());
        let dialog = app
            .game_option_input_dialog
            .as_ref()
            .expect("password prompt is modal");
        assert_eq!(
            dialog.purpose,
            PendingInputDialogPurpose::NetworkJoinPassword
        );
        assert_eq!(dialog.controller.message(), "Enter password:");
        assert_eq!(dialog.controller.caption(), "Enter password:");
        assert_eq!(dialog.controller.icon(), InputDialogIcon::LOCKED);
        assert!(dialog.controller.text().is_empty());

        app.process_game_option_input_dialog_actions(vec![InputDialogAction::Cancelled])
            .expect("cancel password prompt");
        assert!(app.pending_network_join.is_none());
        assert!(app.game_option_input_dialog.is_none());
    }

    #[test]
    fn client_join_flow_wrong_password_reprompts_without_rebuilding_attempts() {
        let mut app = new_classic_menu_app(800, 600);
        let attempts = vec![
            lc_network::NetworkAddress::new(
                lc_network::NetworkProtocol::Tcp,
                "127.0.0.1:30111".parse().unwrap(),
            ),
            lc_network::NetworkAddress::new(
                lc_network::NetworkProtocol::Udp,
                "127.0.0.1:30112".parse().unwrap(),
            ),
        ];
        app.pending_network_join = Some(
            ClientSettings::new(attempts[0].endpoint, "Player")
                .with_join_attempts(attempts.clone())
                .with_password(
                    lc_engine::LegacyCString::from_bytes(b"rejected".to_vec()).unwrap(),
                ),
        );
        let (sender, receiver) = mpsc::channel();
        sender
            .send(Err(NetworkStartError::WrongPassword {
                message: lc_engine::LegacyCString::from_bytes(b"wrong password".to_vec())
                    .unwrap(),
            }))
            .expect("queue typed wrong-password result");
        app.startup_network_connection = Some(StartupNetworkConnection::new(
            receiver,
            None,
            StartupNetworkPurpose::Join,
        ));

        app.poll_startup_network_connection()
            .expect("poll wrong-password result");

        assert!(app.startup_network_connection.is_none());
        assert_eq!(
            app.pending_network_join
                .as_ref()
                .expect("same join remains pending")
                .server_addresses,
            attempts
        );
        let prompt = app
            .game_option_input_dialog
            .as_ref()
            .expect("wrong password reopens prompt");
        assert_eq!(
            prompt.purpose,
            PendingInputDialogPurpose::NetworkJoinPassword
        );
        assert!(prompt.controller.text().is_empty());

        app.process_game_option_input_dialog_actions(vec![InputDialogAction::Accepted(
            String::new(),
        )])
        .expect("empty replacement aborts like C++");
        assert!(app.pending_network_join.is_none());
        assert!(app.startup_network_connection.is_none());

        app.pending_network_join = Some(
            ClientSettings::new(attempts[0].endpoint, "Player")
                .with_join_attempts(attempts),
        );
        let (sender, receiver) = mpsc::channel();
        sender
            .send(Err(NetworkStartError::Other("join denied".to_string())))
            .expect("queue terminal rejection");
        app.startup_network_connection = Some(StartupNetworkConnection::new(
            receiver,
            None,
            StartupNetworkPurpose::Join,
        ));
        app.poll_startup_network_connection()
            .expect("poll terminal join rejection");
        assert!(app.pending_network_join.is_none());
        assert!(app.game_option_input_dialog.is_none());
        assert_eq!(app.startup_view, StartupView::NetworkGame);
        assert_startup_error_log(
            &app,
            "Unable to start network session: join denied",
        );
    }

    #[test]
    fn client_join_flow_submitted_password_is_frozen_for_the_worker() {
        let mut app = new_classic_menu_app(800, 600);
        let closed = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let address = closed.local_addr().unwrap();
        drop(closed);
        app.pending_network_join = Some(
            ClientSettings::new(address, "Player").with_join_attempts([
                lc_network::NetworkAddress::new(lc_network::NetworkProtocol::Tcp, address),
            ]),
        );
        app.open_network_join_password_dialog()
            .expect("open network password prompt");

        app.process_game_option_input_dialog_actions(vec![InputDialogAction::Accepted(
            "typed secret".to_string(),
        )])
        .expect("submit network password");

        assert_eq!(
            app.pending_network_join
                .as_ref()
                .expect("settings stay frozen while the worker starts")
                .password
                .as_bytes(),
            b"typed secret"
        );
        assert!(app.startup_network_connection.is_some());
        for _ in 0..100 {
            app.poll_startup_network_connection()
                .expect("poll submitted-password join");
            if app.startup_network_connection.is_none() {
                break;
            }
            thread::sleep(Duration::from_millis(10));
        }
        assert!(app.startup_network_connection.is_none());
        assert!(app.pending_network_join.is_none());
    }

    #[test]
    fn player_delete_confirmation_removes_refreshes_and_reports_failure() {
        let _lock = env_lock().lock();
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let player_root = user_data.path().join("Players");
        let ada = player_root.join("Ada.c4p");
        fs::create_dir_all(&ada).expect("create directory player group");
        fs::write(
            ada.join("Player.txt"),
            "[Player]\nName=Ada\nTotalPlayingTime=36001\n\n[Preferences]\nColorDw=255\n",
        )
        .expect("write player core");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        let mut config = Config::new();
        config.set_in(Some("General"), "PlayerPath", player_root.to_string_lossy());
        config.set_in(Some("General"), "Participants", ada.to_string_lossy());
        fs::create_dir_all(paths.config_file().parent().expect("config parent"))
            .expect("create config directory");
        config
            .save(paths.config_file())
            .expect("save player config");

        let mut app = GameApp::new(
            1280,
            720,
            AudioOptions {
                sound_enabled: false,
                music_enabled: false,
                menu_music_enabled: false,
                menu_sound_enabled: false,
                ..AudioOptions::default()
            },
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialise app");
        wait_for_menu(&mut app);
        app.open_player_selection_dialog();
        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::DeletePlayer(0),
        ])
        .expect("open delete confirmation");

        let confirm = &app.message_dialogs[0].state;
        assert_eq!(confirm.caption(), "Delete");
        assert_eq!(
            confirm.message(),
            "Do you really want to delete player Ada? - this player has a total playing time of 10:00:01!"
        );
        assert_eq!(
            confirm.buttons(),
            lc_frontend::message_dialog::MessageDialogButtons::YES_NO
        );
        assert_eq!(
            confirm.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::CONFIRM
        );
        assert_eq!(
            confirm.focused_button(),
            Some(lc_frontend::message_dialog::MessageDialogButton::Yes)
        );

        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::No)
            .expect("decline deletion");
        assert!(ada.exists());
        assert_eq!(app.startup_player_files.len(), 1);

        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::DeletePlayer(0),
        ])
        .expect("reopen delete confirmation");
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Yes)
            .expect("confirm deletion");
        assert!(!ada.exists());
        assert!(app.message_dialogs.is_empty());
        assert!(app.startup_player_files.is_empty());
        assert!(app.startup_player_models.is_empty());
        assert_eq!(
            app.startup_player_dialog
                .as_ref()
                .expect("player controller")
                .selected_index(),
            None
        );
        assert_eq!(
            Config::load(paths.config_file())
                .expect("reload player config")
                .get_in(Some("General"), "Participants"),
            Some("")
        );

        let broken = player_root.join("Broken.c4p");
        fs::create_dir_all(&broken).expect("create failure player group");
        fs::write(
            broken.join("Player.txt"),
            "[Player]\nName=Broken\n\n[Preferences]\nColorDw=255\n",
        )
        .expect("write failure player core");
        app.refresh_startup_player_list();
        app.process_player_dialog_actions(vec![
            lc_frontend::startup_plrsel::PlrSelAction::DeletePlayer(0),
        ])
        .expect("open failure confirmation");
        fs::remove_dir_all(&broken).expect("remove player before confirmation");
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Yes)
            .expect("handle failed deletion");
        assert_eq!(app.message_dialogs.len(), 1);
        let failure = &app.message_dialogs[0].state;
        assert_eq!(failure.caption(), "Clear");
        assert_eq!(failure.message(), "Delete failure.");
        assert_eq!(
            failure.buttons(),
            lc_frontend::message_dialog::MessageDialogButtons::OK
        );
        assert_eq!(
            failure.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::ERROR
        );
        assert!(app.startup_player_files.is_empty());
        reset_cached_app_paths();
    }

    #[test]
    fn participant_context_helpers_preserve_raw_indices_and_lazy_scan_rules() {
        let _lock = env_lock().lock();
        let install = tempdir().expect("install root");
        let install_root = install.path();
        fs::create_dir_all(install_root.join("planet")).expect("create planet directory");
        fs::write(install_root.join("planet/System.c4g"), b"").expect("create system group marker");
        let user_data = tempdir().expect("user data");
        let player_root = user_data.path().join("Players");
        let ada = player_root.join("Ada.c4p");
        let bob = player_root.join("Bob.c4p");
        let broken = player_root.join("Broken.c4p");
        fs::create_dir_all(&ada).expect("create Ada group");
        fs::create_dir_all(&bob).expect("create Bob group");
        fs::write(&broken, b"not a group").expect("create invalid C4P file");
        fs::write(player_root.join(".Hidden.c4p"), b"hidden").expect("create hidden C4P");
        fs::write(player_root.join("Notes.txt"), b"text").expect("create non-player file");
        let nested = player_root.join("Nested");
        fs::create_dir_all(&nested).expect("create nested directory");
        fs::write(nested.join("Deep.c4p"), b"nested").expect("create nested C4P");

        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        let save_participants = |participants: String| {
            let mut config = Config::new();
            config.set_in(Some("General"), "PlayerPath", player_root.to_string_lossy());
            config.set_in(Some("General"), "Participants", participants);
            fs::create_dir_all(paths.config_file().parent().expect("config parent"))
                .expect("create config directory");
            config.save(paths.config_file()).expect("save config");
        };

        save_participants(format!(
            "{};{};{};{};{}",
            bob.display(),
            ada.display(),
            bob.display(),
            player_root.join("Missing.c4p").display(),
            player_root.join("Notes.txt").display(),
        ));
        update_startup_participant_config(&paths, |_| {}).expect("validate participants");
        assert_eq!(
            startup_participant_references(&paths).expect("read validated participants"),
            vec![
                bob.to_string_lossy().into_owned(),
                ada.to_string_lossy().into_owned(),
            ],
            "validation keeps first spelling and config order while deduplicating"
        );

        save_participants(format!("{};;{}", ada.display(), bob.display()));
        let remove = startup_participant_remove_entries(&paths);
        assert_eq!(remove.len(), 2);
        assert_eq!(remove[0].text, "Ada");
        assert_eq!(remove[0].icon, ContextMenuIcon::Phase(9));
        assert_eq!(
            remove[0].tooltip.as_deref(),
            Some("Remove this player from participation list")
        );
        assert_eq!(
            remove[0].action,
            Some(AppContextMenuCommand::RemoveStartupParticipant(0))
        );
        assert_eq!(
            remove[1].action,
            Some(AppContextMenuCommand::RemoveStartupParticipant(2)),
            "empty raw segments must not renumber callback indices"
        );

        save_participants(format!("{};;{}", bob.display(), ada.display()));
        let removed = remove_startup_participant_config(&paths, 2)
            .expect("remove using fresh raw index")
            .expect("raw index still resolves");
        assert_eq!(removed, ada.to_string_lossy());
        assert_eq!(
            startup_participant_references(&paths).expect("read after removal"),
            vec![bob.to_string_lossy().into_owned()],
            "activation re-reads the captured raw index instead of a stale filename"
        );

        save_participants(ada.to_string_lossy().into_owned());
        let add = startup_participant_add_entries(&paths);
        let mut names = add
            .iter()
            .map(|entry| entry.text.as_str())
            .collect::<Vec<_>>();
        names.sort_unstable();
        assert_eq!(names, vec!["Bob", "Broken"]);
        for entry in &add {
            assert_eq!(entry.icon, ContextMenuIcon::Phase(9));
            assert_eq!(
                entry.tooltip.as_deref(),
                Some("Let this player join in next game")
            );
            assert!(matches!(
                entry.action,
                Some(AppContextMenuCommand::AddStartupParticipant(_))
            ));
        }
        assert!(
            add.iter().any(|entry| entry.text == "Broken"),
            "Add scans filenames without opening or parsing C4P groups"
        );
        assert!(!add.iter().any(|entry| entry.text == "Deep"));

        let developer_players = install_root.join("build/DevPlayers");
        fs::create_dir_all(&developer_players).expect("create developer PlayerPath");
        fs::write(developer_players.join("Late.C4P"), b"not parsed").expect("create developer C4P");
        let mut config = Config::new();
        config.set_in(Some("General"), "PlayerPath", "DevPlayers");
        config.set_in(Some("General"), "Participants", "");
        config
            .save(paths.config_file())
            .expect("save relative config");
        let developer_add = startup_participant_add_entries(&paths);
        assert_eq!(developer_add.len(), 1);
        assert_eq!(developer_add[0].text, "Late");
        assert_eq!(
            developer_add[0].action,
            Some(AppContextMenuCommand::AddStartupParticipant(
                Path::new("DevPlayers")
                    .join("Late.C4P")
                    .to_string_lossy()
                    .into_owned(),
            )),
            "developer ExePath variants use the same relative reference as player discovery"
        );
        reset_cached_app_paths();
    }

