    #[test]
    fn synchronize_record_request_starts_with_the_executing_control_list() {
        let directory = tempdir().expect("record directory");
        let output_path = directory.path().join("001-Runtime.c4s");
        let mut app = new_state_only_running_sandbox_app();
        app.recording_enabled = false;
        install_test_recording_template(&mut app, output_path.clone());
        app.runtime_record_requested = true;
        let synchronize = lc_engine::SynchronizeControlData {
            save_player_files: false,
            sync_clearance: true,
            by_client: 0,
        };

        app.apply_ready_controls(
            0,
            vec![NetworkControl::Synchronize(synchronize.clone())],
        )
        .expect("execute runtime record synchronize");
        assert!(app.recording.is_some(), "the sync request arms recording");
        assert!(app.finish_recording().is_none());

        let group = Group::open(output_path).expect("runtime record group");
        let stream = group.read_file("CtrlRec.c4b").expect("runtime CtrlRec");
        let mut playback = ControlRecordPlayback::from_bytes(&stream).expect("runtime playback");
        assert_eq!(
            playback.take_controls(0),
            vec![lc_engine::ControlPacket::Synchronize(synchronize)]
        );
    }

    #[test]
    fn any_synchronize_starts_only_an_explicitly_requested_runtime_record() {
        let directory = tempdir().expect("record directory");
        let mut app = new_state_only_running_sandbox_app();
        install_test_recording_template(&mut app, directory.path().join("001-RuntimeJoin.c4s"));
        app.apply_synchronized_controls(
            0,
            vec![NetworkControl::Synchronize(
                lc_engine::SynchronizeControlData {
                    save_player_files: false,
                    sync_clearance: false,
                    by_client: 0,
                },
            )],
        )
        .expect("execute unrequested CDT_Sync");

        assert!(app.recording.is_none());
        assert!(app.recording_template.is_some());

        app.runtime_record_requested = true;
        app.apply_synchronized_controls(
            1,
            vec![NetworkControl::Synchronize(
                lc_engine::SynchronizeControlData {
                    save_player_files: false,
                    sync_clearance: false,
                    by_client: 0,
                },
            )],
        )
        .expect("the next game synchronization starts the request");

        assert!(!app.runtime_record_requested);
        assert!(app.recording.is_some());
    }

    #[test]
    fn synchronized_player_file_policy_matches_native_suppression_matrix() {
        use lc_engine::PlayerStatus;

        let policy = |status, script_player, at_client, league, max_players| {
            synchronized_player_file_policy(
                status,
                script_player,
                at_client,
                7,
                league,
                max_players,
            )
        };
        for status in [
            PlayerStatus::Inactive,
            PlayerStatus::Active,
            PlayerStatus::TeamSelection,
            PlayerStatus::TeamSelectionPending,
        ] {
            assert_eq!(
                policy(status, false, 7, true, Some(0)),
                SynchronizedPlayerFilePolicy::Persist {
                    local_control: true
                },
                "local users persist regardless of remote-only gates"
            );
        }
        for status in [PlayerStatus::Eliminated, PlayerStatus::Surrendered] {
            assert_eq!(
                policy(status, false, 7, false, Some(4)),
                SynchronizedPlayerFilePolicy::Skip
            );
        }
        assert_eq!(
            policy(PlayerStatus::Active, true, 7, false, Some(4)),
            SynchronizedPlayerFilePolicy::Skip
        );
        for (league, max_players) in [
            (true, Some(4)),
            (false, Some(0)),
            (false, Some(-1)),
        ] {
            assert_eq!(
                policy(PlayerStatus::Active, false, 8, league, max_players),
                SynchronizedPlayerFilePolicy::BlockedRemote
            );
        }
        for max_players in [None, Some(1)] {
            assert_eq!(
                policy(PlayerStatus::Active, false, 8, false, max_players),
                SynchronizedPlayerFilePolicy::Persist {
                    local_control: false
                }
            );
        }
    }

    #[test]
    fn synchronized_player_file_remote_gates_leave_profile_untouched() {
        let directory = tempdir().expect("player profile directory");
        let profile_path = directory.path().join("Remote.c4p");
        let sentinel = b"profile must not be opened";
        fs::write(&profile_path, sentinel).expect("write remote sentinel");

        let mut app = new_state_only_synthetic_crew_running_sandbox_app();
        let player_number = app.local_owner;
        let info_id = 602;
        let mut state = app.engine.capture_state();
        let player = state
            .players
            .iter_mut()
            .find(|player| player.id == player_number)
            .expect("sandbox player state");
        player.player_info_id = info_id;
        player.at_client = lc_engine::PlayerAtClient::new(8);
        player.status = lc_engine::PlayerStatus::Active;
        player.script_player = false;
        app.engine
            .restore_state(&state)
            .expect("install remote player state");
        app.control_player_infos.replace_snapshot(
            info_id,
            [lc_engine::PlayerInfoControlData {
                client_id: 8,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: info_id,
                    filename: LegacyCString::from_bytes(b"Remote.c4p".to_vec())
                        .expect("player filename"),
                    game_number: player_number,
                    ..lc_engine::ControlPlayerInfoEntry::default()
                }],
                by_client: 0,
                ..lc_engine::PlayerInfoControlData::default()
            }],
        );
        app.local_player_profile_paths
            .insert(info_id, profile_path.clone());
        assert_eq!(
            app.offline_local_client_id(),
            0,
            "the fixture must classify client 8 as remote"
        );

        app.engine.set_max_players(4);
        app.network_is_league = true;
        assert!(!app.persist_synchronized_local_player_files());
        assert_eq!(fs::read(&profile_path).unwrap(), sentinel);

        app.network_is_league = false;
        app.engine.set_max_players(0);
        assert!(!app.persist_synchronized_local_player_files());
        assert_eq!(fs::read(&profile_path).unwrap(), sentinel);
    }

    #[test]
    fn save_player_files_synchronize_persists_local_player_core_and_crew() {
        let directory = tempdir().expect("player profile directory");
        let profile_path = directory.path().join("Local.c4p");
        fs::create_dir(&profile_path).expect("create unpacked local profile");
        fs::write(
            profile_path.join("Player.txt"),
            b"[Player]\nName=Stale\nScore=1\n",
        )
        .expect("stale player core");
        fs::write(profile_path.join("C4Player.c4b"), b"obsolete core")
            .expect("obsolete binary core");
        fs::write(profile_path.join("KeepRoot.dat"), b"root sentinel")
            .expect("profile sentinel");
        fs::write(profile_path.join(".local-metadata"), b"ignored sentinel")
            .expect("ignored profile metadata");
        for (filename, name) in [("Hero.c4i", "Hero"), ("Idle.c4i", "Idle")] {
            let child = profile_path.join(filename);
            fs::create_dir(&child).expect("create stale crew child");
            fs::write(
                child.join("ObjectInfo.txt"),
                format!("[ObjectInfo]\nid=CLNK\nName={name}\n"),
            )
            .expect("stale crew core");
            fs::write(child.join("KeepCrew.dat"), format!("{name} sentinel"))
                .expect("crew sentinel");
            fs::write(child.join(".crew-metadata"), format!("{name} metadata"))
                .expect("ignored crew metadata");
        }

        let mut app = new_state_only_synthetic_crew_running_sandbox_app();
        let player_number = app.local_owner;
        let info_id = 601;
        let crew = |name: &str,
                    filename: &str,
                    total_playing_time: i32,
                    in_action: bool| {
            let mut core = lc_engine::CrewInfoCoreFields::default();
            core.original_filename = filename.to_string();
            core.portrait_file = "none".to_string();
            lc_engine::player_file::CrewInfo {
                id: "CLNK".to_string(),
                name: name.to_string(),
                death_message: format!("{name} fell"),
                core,
                rank: 0,
                rank_name: "Clonk".to_string(),
                experience: if in_action { 321 } else { 123 },
                rounds: 4,
                physical: lc_engine::PhysicalInfo::default(),
                death_count: if in_action { 2 } else { 1 },
                total_playing_time,
                birthday: 1_234,
                age: 3,
                participation: 1,
                in_action,
                was_in_action: in_action,
                in_action_time: 10,
                has_died: false,
                extra_data: vec![(
                    "CrewToken".to_string(),
                    Value::Int(if in_action { 77 } else { 33 }),
                )],
                portraits: lc_engine::CrewPortraitState {
                    permanent: lc_engine::CrewPermanentPortrait::ExplicitNone,
                    ..lc_engine::CrewPortraitState::default()
                },
            }
        };
        let mut state = app.engine.capture_state();
        state.game_time = 25;
        state.player_crew_rosters_authoritative = true;
        let player = state
            .players
            .iter_mut()
            .find(|player| player.id == player_number)
            .expect("sandbox player state");
        player.player_info_id = info_id;
        player.at_client = lc_engine::PlayerAtClient::HOST;
        player.status = lc_engine::PlayerStatus::Active;
        player.script_player = false;
        player.score = 900;
        player.rounds = 8;
        player.rounds_won = 5;
        player.rounds_lost = 3;
        player.total_playing_time = 40;
        player.extra_data = vec![("PlayerToken".to_string(), Value::Int(99))];
        let mut info_core = player.player_info_core.take().unwrap_or_default();
        info_core.pref_name = "Persistent Player".to_string();
        player.player_info_core = Some(info_core);
        state.crew_info_rosters.insert(
            player_number,
            vec![
                crew("Hero", "Hero.c4i", 7, true),
                crew("Idle", "Idle.c4i", 11, false),
            ],
        );
        state.crew_info_order.insert(player_number, vec![0, 1]);
        app.engine
            .restore_state(&state)
            .expect("install synchronized player state");
        app.engine
            .player_mut(player_number)
            .expect("sandbox player")
            .set_game_join_time(10);
        app.engine.set_local_players([player_number]);
        app.control_player_infos.replace_snapshot(
            info_id,
            [lc_engine::PlayerInfoControlData {
                client_id: 0,
                flags: 0,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: info_id,
                    name: LegacyCString::from_bytes(b"Persistent Player".to_vec())
                        .expect("player name"),
                    filename: LegacyCString::from_bytes(b"Local.c4p".to_vec())
                        .expect("player filename"),
                    flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                    game_number: player_number,
                    ..lc_engine::ControlPlayerInfoEntry::default()
                }],
                by_client: 0,
            }],
        );
        app.local_player_profile_paths
            .insert(info_id, profile_path.clone());

        let synchronize = || {
            NetworkControl::Synchronize(lc_engine::SynchronizeControlData {
                save_player_files: true,
                sync_clearance: false,
                by_client: 0,
            })
        };
        app.apply_synchronized_controls(0, vec![synchronize()])
            .expect("save local player profile");

        let saved = PlayerFile::load_from_path(&profile_path).expect("reload saved profile");
        assert_eq!(saved.name, "Persistent Player");
        assert_eq!(
            (
                saved.score,
                saved.rounds,
                saved.rounds_won,
                saved.rounds_lost
            ),
            (900, 8, 5, 3)
        );
        assert_eq!(saved.total_playing_time, 55);
        assert_eq!(
            saved.info_core.extra_data,
            vec![("PlayerToken".to_string(), Value::Int(99))]
        );
        let hero = saved
            .crew
            .iter()
            .find(|crew| crew.name == "Hero")
            .expect("active crew persisted");
        assert_eq!(
            (hero.experience, hero.death_count, hero.total_playing_time),
            (321, 2, 22)
        );
        assert_eq!(
            hero.extra_data,
            vec![("CrewToken".to_string(), Value::Int(77))]
        );
        let idle = saved
            .crew
            .iter()
            .find(|crew| crew.name == "Idle")
            .expect("idle crew persisted");
        assert_eq!(
            idle.total_playing_time, 11,
            "idle crew has no active-time delta"
        );
        let saved_group = Group::open(&profile_path).expect("saved profile remains a C4Group");
        assert_eq!(
            saved_group.read_file("KeepRoot.dat").unwrap(),
            b"root sentinel"
        );
        assert_eq!(
            saved_group
                .open_child("Hero.c4i")
                .unwrap()
                .read_file("KeepCrew.dat")
                .unwrap(),
            b"Hero sentinel"
        );
        assert_eq!(
            fs::read(profile_path.join("Hero.c4i/.crew-metadata")).unwrap(),
            b"Hero metadata"
        );
        assert!(!saved_group.exists("C4Player.c4b"));
        assert_eq!(
            fs::read(profile_path.join(".local-metadata")).unwrap(),
            b"ignored sentinel"
        );

        // A removed local source is not an eligibility failure in C++: its
        // unchecked copy leaves a fresh temp group that Save fills. Recreate
        // it at the same game time and also prove the ledgers are not counted
        // twice at consecutive SavePlrs boundaries.
        fs::remove_dir_all(&profile_path).expect("remove admitted local profile");
        app.apply_synchronized_controls(1, vec![synchronize()])
            .expect("recreate missing local player profile");
        let recreated =
            PlayerFile::load_from_path(&profile_path).expect("reload recreated profile");
        assert_eq!(recreated.total_playing_time, 55);
        assert_eq!(
            recreated
                .crew
                .iter()
                .find(|crew| crew.name == "Hero")
                .expect("recreated active crew")
                .total_playing_time,
            22
        );
        let recreated_group = Group::open(&profile_path).expect("recreated profile C4Group");
        assert!(!recreated_group.exists("KeepRoot.dat"));
        assert!(!recreated_group.exists("C4Player.c4b"));
        assert!(fs::read_dir(directory.path())
            .expect("enumerate rewrite directory")
            .all(|entry| !entry
                .expect("rewrite directory entry")
                .file_name()
                .to_string_lossy()
                .starts_with(".Local.c4p.lc-rewrite-")));

        // SavePlrs inside control replay is a complete no-op for both the
        // mutable time checkpoint and the app-owned profile write.
        let profile_before_replay = fs::read(&profile_path).expect("snapshot recreated profile");
        let mut replay_state = app.engine.capture_state();
        replay_state.game_time = 30;
        replay_state
            .players
            .iter_mut()
            .find(|player| player.id == player_number)
            .expect("replay player state")
            .score = 901;
        app.engine
            .restore_state(&replay_state)
            .expect("advance live replay state");
        app.engine
            .player_mut(player_number)
            .expect("replay player")
            .set_game_join_time(25);
        app.control_playback = Some(
            ControlRecordPlayback::from_bytes(&[0, lc_engine::RCT_END])
                .expect("open replay marker"),
        );
        app.engine.set_replay_control(true);
        app.apply_synchronized_controls(2, vec![synchronize()])
            .expect("replay SavePlrs is suppressed");
        assert_eq!(fs::read(&profile_path).unwrap(), profile_before_replay);
        assert_eq!(
            (
                app.engine
                    .player(player_number)
                    .expect("replay player remains")
                    .total_playing_time(),
                app.engine
                    .player(player_number)
                    .expect("replay player remains")
                    .game_join_time(),
            ),
            (55, 25)
        );
        let replay_state = app.engine.capture_state();
        let replay_roster = &replay_state.crew_info_rosters[&player_number];
        let replay_hero = replay_roster
            .iter()
            .find(|crew| crew.name == "Hero")
            .expect("replay hero remains");
        assert_eq!(
            (replay_hero.total_playing_time, replay_hero.in_action_time),
            (22, 25)
        );
    }

    #[test]
    fn developer_console_runtime_record_waits_for_its_queued_synchronize() {
        let directory = tempdir().expect("record directory");
        let output_path = directory.path().join("001-ConsoleRuntime.c4s");
        let mut app = new_state_only_running_sandbox_app();
        install_test_recording_template(&mut app, output_path);
        let (_events, mut commands) = install_running_network_stub(&mut app, 0, 0, 2);
        let tick = app.local_control_submission_tick();

        assert!(app.developer_console_runtime_record_possible());
        assert!(app
            .developer_console_request_runtime_record()
            .expect("queue console runtime record"));
        assert!(app.runtime_record_requested);
        assert!(!app.developer_console_runtime_record_possible());
        assert!(app.recording.is_none());

        let decided = commands.take_submitted_decided_controls();
        assert_eq!(
            decided,
            vec![(
                tick,
                lc_engine::ControlPacket::Synchronize(lc_engine::SynchronizeControlData {
                    save_player_files: false,
                    sync_clearance: true,
                    by_client: 0,
                },),
                false,
            )]
        );

        app.apply_ready_controls(
            tick,
            vec![NetworkControl::Synchronize(
                lc_engine::SynchronizeControlData {
                    save_player_files: false,
                    sync_clearance: true,
                    by_client: 0,
                },
            )],
        )
        .expect("execute queued runtime-record synchronization");
        assert!(!app.runtime_record_requested);
        assert!(app.recording.is_some());
    }

    #[test]
    fn developer_console_latches_no_input_and_reflects_pending_network_pause() {
        let mut app = new_state_only_running_sandbox_app();
        app.console_mode = true;
        app.control_playback = Some(
            ControlRecordPlayback::from_bytes(&[0, lc_engine::RCT_END])
                .expect("open replay marker"),
        );
        app.sync_developer_console_view();
        app.control_playback = None;
        app.sync_developer_console_view();
        assert!(!app.developer_console.view_model().editing);

        let (_events, _commands) = install_running_network_stub(&mut app, 0, 0, 1);
        app.network_control_running = true;
        app.runtime_network_status_barrier = Some(RuntimeNetworkStatusBarrier {
            status: lc_network::NetworkStatus {
                state: lc_network::NETWORK_STATE_PAUSE,
                control_mode: 0,
                target_tick: 0,
            },
            local_reached: false,
            actual_control_tick: None,
        });
        assert!(
            app.developer_console_view_model().halted,
            "IsPaused becomes true as soon as a network status barrier is pending"
        );
        app.runtime_network_status_barrier = None;
        assert!(!app.developer_console_view_model().halted);
    }

    #[test]
    fn developer_console_player_and_net_menus_use_native_controls() {
        let mut app = new_state_only_running_sandbox_app();
        let player = app.local_owner;
        app.engine
            .player_mut(player)
            .expect("console player exists")
            .set_at_client_name("Host");
        let (_events, mut commands) = install_running_network_stub(&mut app, 0, 0, 2);
        let mut remote = message_client(7, b"Remote");
        remote.activated = false;
        app.control_clients
            .replace_snapshot([message_client(0, b"Host"), remote]);

        assert_eq!(
            app.developer_console_player_menu_entries(true),
            vec![ConsolePlayerRow {
                number: player,
                quit_label: format!(
                    "Remove {} (Host) ",
                    c4_presentation_text(app.engine.player(player).expect("player remains").name())
                ),
                quit_enabled: true,
                viewport_label: format!(
                    "New for {}",
                    c4_presentation_text(app.engine.player(player).expect("player remains").name())
                ),
            }]
        );
        assert_eq!(
            app.developer_console_net_menu_entries(),
            vec![
                ConsoleClientRow {
                    id: 0,
                    menu_label: "Host Host (0)".to_string(),
                    menu_enabled: true,
                },
                ConsoleClientRow {
                    id: 7,
                    menu_label: "Client Remote (7) deactivated".to_string(),
                    menu_enabled: true,
                },
            ]
        );

        app.engine.set_control_host(false);
        assert!(
            app.developer_console_net_menu_entries()
                .iter()
                .all(|entry| entry.menu_enabled),
            "native keeps the rows enabled and rejects their callback"
        );
        assert!(!app
            .developer_console_kick_client(7)
            .expect("non-control host ignores kick"));
        assert!(commands.take_submitted_client_removes().is_empty());
        app.engine.set_control_host(true);
        assert!(app
            .developer_console_kick_client(7)
            .expect("control host queues kick"));
        assert_eq!(
            commands.take_submitted_client_removes(),
            vec![lc_engine::ClientRemoveControlData {
                client_id: 7,
                reason: lc_engine::LegacyCString::from_bytes(b"kicked from host menu".to_vec())
                    .expect("fixture reason"),
                by_client: 0,
            }]
        );

        let tick = app.local_control_submission_tick();
        assert!(app
            .developer_console_quit_player(player, true)
            .expect("queue console player quit"));
        assert_eq!(
            commands.take_submitted_internal_player_scripts(),
            vec![(
                tick,
                lc_engine::ControlPacket::EliminatePlayer(lc_engine::EliminatePlayerControlData {
                    player,
                    by_client: 0,
                },),
            )]
        );
        assert!(app.engine.player(player).is_some());
    }

    #[test]
    fn developer_console_offline_join_and_quit_use_control_cadence() {
        let player_path = Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../lc-engine/tests/fixtures/embedded_player.c4p"
        ));
        let mut app = new_synthetic_running_sandbox_app();
        let before = app.engine.snapshot().players.len();

        assert_eq!(
            app.developer_console_join_players(&[player_path.to_path_buf()], true)
                .expect("join selected offline player"),
            1
        );
        assert_eq!(app.engine.snapshot().players.len(), before + 1);

        let player = app.local_owner;
        app.engine.set_control_rate(3);
        app.snapshot = app.engine.tick().expect("advance past cadence frame zero");
        assert!(app
            .developer_console_quit_player(player, true)
            .expect("queue local CID_EliminatePlayer"));
        assert_ne!(
            app.engine.player(player).map(lc_engine::Player::status),
            Some(lc_engine::PlayerStatus::Eliminated),
            "Game.Control.Input.Add must not execute the callback immediately"
        );
        app.update().expect("frame one is before the control cadence");
        app.update().expect("frame two is before the control cadence");
        assert_ne!(
            app.engine.player(player).map(lc_engine::Player::status),
            Some(lc_engine::PlayerStatus::Eliminated)
        );
        app.update().expect("frame three executes the control input");
        assert_eq!(
            app.engine.player(player).map(lc_engine::Player::status),
            Some(lc_engine::PlayerStatus::Eliminated)
        );
    }

    #[test]
    fn developer_console_network_join_uses_join_local_player_route() {
        let player_path = Path::new(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../lc-engine/tests/fixtures/embedded_player.c4p"
        ));
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _events, commands) = NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        let mut settings =
            ClientSettings::new(SocketAddr::from(([127, 0, 0, 1], 11_112)), "Client");
        settings.group_maker =
            LegacyCString::from_bytes(b"Console maker".to_vec()).expect("valid maker");
        app.network_mode = Some(NetworkMode::Client(settings));
        app.control_clients.register(7, true, false);
        let wire_name = LegacyCString::from_bytes(path_to_legacy_bytes(player_path))
            .expect("fixture path has no NUL");
        let resource = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: 7 << 16,
            loadable: true,
            filename: wire_name.clone(),
            ..Default::default()
        };
        let observer = thread::spawn(move || commands.complete_initial_client_join(vec![resource]));

        assert_eq!(
            app.developer_console_join_players(&[player_path.to_path_buf()], true)
                .expect("console network player joins"),
            1
        );
        drop(app.network.take());
        let (order, publications, updates, acknowledgements) =
            observer.join().expect("network command observer");
        assert_eq!(order, vec!["publish", "player-info"]);
        assert_eq!(publications.len(), 1);
        assert_eq!(publications[0].source_path.as_path(), player_path);
        assert_eq!(publications[0].wire_name, wire_name);
        assert_eq!(publications[0].group_maker.as_bytes(), b"Console maker");
        assert_eq!(updates.len(), 1);
        assert_eq!(updates[0].client_id, 7);
        assert_eq!(
            updates[0].flags,
            lc_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS
        );
        assert!(acknowledgements.is_empty());
    }

