    #[test]
    fn team_selection_execute_keeps_an_ambiguous_local_choice_open() {
        // With two joinable teams GetForcedTeamSelection returns zero;
        // C4Player::Execute leaves C4MN_TeamSelection active instead of
        // submitting either choice (C4Player.cpp:159-173;
        // C4Teams.cpp:887-894).
        let mut app = new_running_sandbox_app();
        app.engine.set_teams(vec![
            lc_engine::TeamInfo::new(1, "Left", 0x00f4_0000),
            lc_engine::TeamInfo::new(2, "Right", 0x0000_c800),
        ]);
        let chooser = app
            .engine
            .join_player_for_team_selection(JoinPlayerConfig {
                name: "Chooser".to_string(),
                player_info_id: 0,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0x0000_c800,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                control_style: false,
                auto_context_menu: false,
                startup_player_count: 2,
            })
            .expect("chooser waits for team selection");
        app.local_controls.initialize(LocalControlInit {
            owner: chooser,
            preferred_set: 1,
            prefers_mouse: false,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
        app.open_initial_team_selection(chooser);
        app.ingame_menu
            .as_mut()
            .expect("team menu opens")
            .set_selection(1);
        let (manager, events, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        let tick = app.local_control_submission_tick();
        events
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: Vec::new(),
            })
            .expect("complete control tick is ready");

        app.update().expect("ambiguous selection executes");

        assert_eq!(
            app.engine.player(chooser).map(lc_engine::Player::status),
            Some(PlayerStatus::TeamSelection)
        );
        let menu = app.ingame_menu.as_ref().expect("selection remains open");
        assert_eq!(menu.selection(), 1, "the local choice is not reset");
        assert!(commands.take_submitted_init_scenario_players().is_empty());

        app.engine
            .set_teams(vec![lc_engine::TeamInfo::new(1, "Existing", 0x00f4_0000)]);
        app.engine.set_auto_generate_teams(true);
        let local_owner = app.local_owner;
        app.engine
            .set_player_team(local_owner, Some(1))
            .expect("sandbox player joins the existing team");
        let tick = app.local_control_submission_tick();
        events
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: Vec::new(),
            })
            .expect("next complete control tick is ready");

        app.update().expect("generated alternative executes");

        assert_eq!(
            app.ingame_menu
                .as_ref()
                .expect("generated alternative keeps menu open")
                .items()
                .iter()
                .map(|item| item.action.clone())
                .collect::<Vec<_>>(),
            [MenuAction::SelectTeam(1), MenuAction::SelectTeam(-1)]
        );
        assert!(commands.take_submitted_init_scenario_players().is_empty());
    }

    #[test]
    fn real_regicide_opens_initial_team_menu_and_hides_disabled_switch() {
        // Regicide's custom active Teams.txt leaves the initial user
        // teamless. C4Player::Execute opens C4MN_TeamSelection with both
        // ordered teams before the player's ScenarioInit can run
        // (C4Player.cpp:159-173,1762-1772; C4MainMenu.cpp:175-236).
        let mut app =
            real_installed_scenario_app("Knights.c4f/Regicide.c4s", "Regicide team chooser");
        wait_for_running(&mut app);

        assert!(
            !app.engine.team_configuration().allow_team_switch,
            "Regicide's parsed Teams.txt keeps mid-round switching disabled"
        );
        assert_eq!(
            app.engine
                .player(app.local_owner)
                .map(lc_engine::Player::status),
            Some(PlayerStatus::TeamSelection)
        );
        let menu = app
            .ingame_menu
            .as_ref()
            .expect("team selection opens automatically");
        assert_eq!(menu.page(), ingame_menu::MenuPage::TeamSelection);
        assert_eq!(
            menu.items()
                .iter()
                .map(|item| item.action.clone())
                .collect::<Vec<_>>(),
            [MenuAction::SelectTeam(1), MenuAction::SelectTeam(2)]
        );

        let outcome = app
            .ingame_menu
            .as_mut()
            .expect("team menu remains open")
            .handle_command(ControlCommand::MenuEnter, CommandKind::Press)
            .expect("first team activates");
        app.execute_ingame_menu_outcome(outcome)
            .expect("team selection executes");

        let player = app
            .engine
            .player(app.local_owner)
            .expect("selected player remains registered");
        assert_eq!(player.status(), PlayerStatus::Active);
        assert_eq!(player.team(), Some(1));
        assert!(
            app.engine.crew_cursor(app.local_owner).is_some(),
            "Regicide selection must leave the player with usable crew"
        );
        assert!(app.ingame_menu.is_none());

        let owner = app.local_owner;
        app.activate_ingame_main_menu_for_player(owner)
            .expect("open post-selection main menu");
        assert!(!app
            .ingame_menu
            .as_ref()
            .expect("main menu")
            .items()
            .iter()
            .any(|item| item.action == MenuAction::ActivateTeamSelection));
    }

    #[test]
    fn secondary_local_player_controls_own_initial_team_menu() {
        // C4Player stores one C4MainMenu per player. LocalPlayerControl looks
        // up the keyboard-set owner, converts through that player's menu, and
        // TeamSel dispatches DoTeamSelection on the menu's Player
        // (pristine 9ffa0a5d src/C4Player.h:85;
        // src/C4Game.cpp:3572-3624; src/C4MainMenu.cpp:899-908).
        let mut app = new_synthetic_running_sandbox_app();
        let primary = app.local_owner;
        let primary_before = app
            .engine
            .player(primary)
            .map(|player| (player.status(), player.team()))
            .expect("primary local player");
        app.engine.set_teams(vec![
            lc_engine::TeamInfo::new(1, "West", 0xff0000),
            lc_engine::TeamInfo::new(2, "East", 0x0000ff),
        ]);
        let secondary = app
            .engine
            .join_player_for_team_selection(JoinPlayerConfig {
                name: "Secondary".to_string(),
                player_info_id: 0,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0x0000ff,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                control_style: false,
                auto_context_menu: false,
                startup_player_count: 2,
            })
            .expect("secondary waits for a team");
        app.engine.set_local_players([primary, secondary]);
        app.local_controls = LocalControlRegistry::default();
        app.local_controls.initialize(LocalControlInit {
            owner: primary,
            preferred_set: 0,
            prefers_mouse: false,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
        app.local_controls.initialize(LocalControlInit {
            owner: secondary,
            preferred_set: 1,
            prefers_mouse: false,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
        app.handle_key(VirtualKeyCode::Z, ElementState::Pressed)
            .expect("primary holds left");

        app.open_initial_team_selection(secondary);
        assert_eq!(
            app.ingame_menu.as_ref().and_then(IngameMenuState::player),
            Some(secondary)
        );

        // Keyboard set 2 Key4 is Throw; an active C4MainMenu converts it to
        // MenuEnter and selects the first team.
        app.handle_key(VirtualKeyCode::Numpad4, ElementState::Pressed)
            .expect("secondary enters selected team");

        let secondary_player = app.engine.player(secondary).expect("secondary remains");
        assert_eq!(secondary_player.status(), PlayerStatus::Active);
        assert_eq!(secondary_player.team(), Some(1));
        assert!(
            app.engine.crew_cursor(secondary).is_some(),
            "team activation spawns the default native crew"
        );
        assert_eq!(
            app.engine
                .player(primary)
                .map(|player| (player.status(), player.team())),
            Some(primary_before),
            "secondary menu control must not mutate the primary player"
        );
        assert_ne!(
            app.engine
                .snapshot()
                .players
                .into_iter()
                .find(|player| player.id == primary)
                .expect("primary snapshot")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_LEFT),
            0,
            "closing the secondary menu must clear only secondary controls"
        );
        assert!(app.ingame_menu.is_none());
    }

    #[test]
    fn simultaneous_local_team_selection_menus_route_independently() {
        // Every C4Player owns its C4MainMenu, and LocalPlayerControl converts
        // input through the addressed player's menu. Each viewport likewise
        // draws only its associated player's menu (pristine 9ffa0a5d
        // src/C4Player.h:85; src/C4Game.cpp:3572-3624;
        // src/C4Viewport.cpp:965-1017).
        let mut app = new_state_only_synthetic_crew_running_sandbox_app();
        app.engine.set_teams(vec![
            lc_engine::TeamInfo::new(1, "West", 0xff0000),
            lc_engine::TeamInfo::new(2, "East", 0x0000ff),
        ]);
        let first = app
            .engine
            .join_player_for_team_selection(JoinPlayerConfig {
                name: "First chooser".to_string(),
                player_info_id: 31,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0xff0000,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                control_style: false,
                auto_context_menu: false,
                startup_player_count: 2,
            })
            .expect("first player waits for a team");
        let second = app
            .engine
            .join_player_for_team_selection(JoinPlayerConfig {
                name: "Second chooser".to_string(),
                player_info_id: 32,
                score: 0,
                rounds: 0,
                rounds_won: 0,
                rounds_lost: 0,
                total_playing_time: 0,
                team: None,
                color_dw: 0x0000ff,
                pref_color: 0,
                pref_position: 0,
                crew: Vec::new(),
                control_style: false,
                auto_context_menu: false,
                startup_player_count: 2,
            })
            .expect("second player waits for a team");
        app.engine.set_local_players([first, second]);
        app.local_controls = LocalControlRegistry::default();
        for (owner, preferred_set) in [(first, 0), (second, 1)] {
            app.local_controls.initialize(LocalControlInit {
                owner,
                preferred_set,
                prefers_mouse: false,
                gamepads_enabled: true,
                replay: false,
                disable_mouse: false,
            });
            app.open_initial_team_selection(owner);
        }

        assert!(
            [first, second]
                .into_iter()
                .all(|owner| app.ingame_menu_belongs_to(owner)),
            "both local players retain their own initial team menu"
        );
        assert!(app
            .handle_menu_command(first, ControlCommand::MenuDown, CommandKind::Press,)
            .expect("first player navigates own menu"));
        assert!(app
            .handle_menu_command(first, ControlCommand::MenuEnter, CommandKind::Press,)
            .expect("first player selects own team"));
        assert_eq!(
            app.engine
                .player(first)
                .map(|player| (player.status(), player.team())),
            Some((PlayerStatus::Active, Some(2)))
        );
        assert!(
            app.engine.crew_cursor(first).is_some(),
            "first team activation spawns its native crew"
        );
        assert_eq!(
            app.engine
                .player(second)
                .map(|player| (player.status(), player.team())),
            Some((PlayerStatus::TeamSelection, None)),
            "first player's selection must not mutate the second player"
        );
        assert!(
            app.ingame_menu_belongs_to(second),
            "second player's menu survives the first player's selection"
        );

        assert!(app
            .handle_menu_command(second, ControlCommand::MenuEnter, CommandKind::Press,)
            .expect("second player selects own team"));
        assert_eq!(
            app.engine
                .player(second)
                .map(|player| (player.status(), player.team())),
            Some((PlayerStatus::Active, Some(1)))
        );
        assert!(
            app.engine.crew_cursor(second).is_some(),
            "second team activation spawns its native crew"
        );
        assert!(!app.ingame_menu_belongs_to(first));
        assert!(!app.ingame_menu_belongs_to(second));
    }

    #[test]
    fn change_to_local_preserves_synchronized_league_state() {
        // ActivateMain suppresses New Player while Game.Parameters.isLeague()
        // sees a nonempty synchronized LeagueAddress. JoinData replaces those
        // parameters for clients. C4GameControl::ChangeToLocal clears network
        // control without clearing Game.Parameters, so the league gate remains
        // part of the running round (pristine 9ffa0a5d
        // src/C4MainMenu.cpp:643-686; src/C4GameParameters.h:126-173;
        // src/C4GameControl.cpp:93-127; src/C4Network2.cpp:1595-1602).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx, _commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        let host_config = lc_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot.parameters.league =
            lc_engine::LegacyCString::from_bytes(b"League".to_vec()).unwrap();
        snapshot.parameters.league_address =
            lc_engine::LegacyCString::from_bytes(b"https://league.invalid/".to_vec()).unwrap();
        snapshot.parameters.player_infos = lc_network::PlayerInfoListSnapshot {
            last_player_id: 41,
            clients: vec![lc_network::ClientPlayerInfosSnapshot {
                client_id: 0,
                flags: 0,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 41,
                    flags: lc_engine::PLAYER_INFO_FLAG_REMOVED,
                    league_progress_data: lc_engine::LegacyCString::from_bytes(
                        b"retained-progress".to_vec(),
                    )
                    .unwrap(),
                    ..Default::default()
                }],
            }],
        };
        snapshot
            .parameters
            .clients
            .clients
            .push(lc_engine::ClientCoreControlData {
                client_id: 7,
                activated: false,
                observer: true,
                ..Default::default()
            });
        snapshot.parameters.clients.local_client_id = Some(7);
        let synchronized_max_players = snapshot.parameters.max_players as usize;
        event_tx
            .send(NetworkEvent::JoinData(lc_network::JoinDataEnvelope {
                client_id: 7,
                start_control_tick: snapshot.dynamic_tick,
                status: host_config.initial_status,
                dynamic: snapshot.dynamic,
                parameters: snapshot.parameters,
            }))
            .expect("queue league JoinData");

        app.process_network_events().expect("apply league JoinData");
        app.pending_network_join_data = None;

        assert_eq!(app.network_league_name, b"League");
        assert_eq!(app.engine.snapshot().league_name, b"League");
        assert_eq!(
            app.engine
                .snapshot()
                .player_info_league_progress_data
                .get(&41),
            Some(&Some(b"retained-progress".to_vec()))
        );

        let conditions = app.main_menu_conditions();
        assert!(conditions.is_league);
        let menu = IngameMenuState::main_menu(&conditions).expect("main menu has entries");
        assert!(
            !menu
                .items()
                .iter()
                .any(|item| item.action == MenuAction::ActivateNewPlayer)
        );

        app.change_network_control_to_local(7);
        assert!(app.main_menu_conditions().is_league);
        assert_eq!(app.network_max_players, synchronized_max_players);
        assert_eq!(app.engine.snapshot().league_name, b"League");
        assert_eq!(
            app.engine
                .snapshot()
                .player_info_league_progress_data
                .get(&41),
            Some(&Some(b"retained-progress".to_vec()))
        );
    }

    #[test]
    fn league_update_applies_projected_gains_and_directly_rebroadcasts_owners() {
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx, mut commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(0);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.host_join_snapshot = lc_network::HostConfig::default().initial_join_snapshot;
        app.control_player_infos.replace_snapshot(
            20,
            [
                lc_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 10,
                        league_projected_gain: 1,
                        ..Default::default()
                    }],
                    ..Default::default()
                },
                lc_engine::PlayerInfoControlData {
                    client_id: 4,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 20,
                        league_projected_gain: 2,
                        ..Default::default()
                    }],
                    ..Default::default()
                },
            ],
        );
        let response = lc_network::LeagueUpdateResponse {
            player_infos: lc_network::ClientPlayerInfosSnapshot {
                client_id: -1,
                flags: 0,
                players: vec![
                    lc_engine::ControlPlayerInfoEntry {
                        id: 20,
                        league_projected_gain: 7,
                        ..Default::default()
                    },
                    lc_engine::ControlPlayerInfoEntry {
                        id: 10,
                        league_projected_gain: 1,
                        ..Default::default()
                    },
                ],
            },
            ..lc_network::LeagueUpdateResponse::default()
        };
        event_tx
            .send(NetworkEvent::LeagueUpdate(response.clone()))
            .expect("queue league Update reply");

        app.process_network_events().expect("apply league Update");

        assert_eq!(
            app.control_player_infos
                .get(20)
                .unwrap()
                .league_projected_gain,
            7
        );
        let (broadcasts, invalidations) = commands.take_league_update_effects();
        assert_eq!(
            broadcasts
                .iter()
                .map(|packet| packet.client_id)
                .collect::<Vec<_>>(),
            vec![4]
        );
        assert_eq!(invalidations, 1);

        event_tx
            .send(NetworkEvent::LeagueUpdate(response))
            .expect("queue unchanged league Update reply");
        app.process_network_events()
            .expect("ignore unchanged league Update");
        assert_eq!(commands.take_league_update_effects(), (Vec::new(), 0));
    }

    #[test]
    fn client_league_round_result_packet_applies_persistent_evaluation_fields() {
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.control_player_infos.replace_snapshot(
            10,
            [lc_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 10,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        let packet = lc_network::LeagueRoundResultsPacket {
            success: true,
            result_string: lc_engine::LegacyCString::from_bytes(b"evaluated".to_vec()).unwrap(),
            players: vec![lc_network::LeagueRoundResultsPlayer {
                player_info_id: 10,
                total_playing_time: 90,
                settlement_score_old: 11,
                settlement_score_new: 12,
                league_score_new: 80,
                league_score_gain: 5,
                league_rank_new: 3,
                league_rank_symbol_new: 4,
                league_progress_data: lc_engine::LegacyCString::from_bytes(
                    b"progress".to_vec(),
                )
                .unwrap(),
                status: lc_network::LeagueRoundPlayerStatus::Won,
            }],
        };
        event_tx
            .send(NetworkEvent::LeagueRoundResults(packet))
            .expect("queue league result packet");

        app.process_network_events().expect("apply league result packet");

        let info = app.control_player_infos.get(10).unwrap();
        assert_eq!(
            (info.league_score, info.league_rank, info.league_rank_symbol),
            (0, 0, 0),
            "EvaluateLeague does not overwrite live PlayerInfo"
        );
        let engine_snapshot = app.engine.snapshot();
        assert_eq!(app.snapshot.round_results, engine_snapshot.round_results);
        assert_eq!(
            engine_snapshot.round_results.network_result,
            Some(lc_engine::RoundResultsNetworkResult::LeagueOk)
        );
        assert_eq!(
            engine_snapshot
                .round_results
                .network_result_message
                .as_slice(),
            &b"evaluated"[..]
        );
        let result = engine_snapshot
            .round_results
            .players
            .iter()
            .find(|result| result.player_info_id == 10)
            .unwrap();
        assert_eq!((result.score_old, result.score_new), (-1, None));
        assert_eq!(
            (
                result.league_score_new,
                result.league_score_gain,
                result.league_rank_new,
                result.league_rank_symbol_new,
            ),
            (80, 5, 3, 4)
        );
        assert_eq!(result.league_progress_data.as_deref(), Some(&b"progress"[..]));
    }

    #[test]
    fn league_host_and_client_report_the_correct_connection_failure_players() {
        let joined = |id| lc_engine::ControlPlayerInfoEntry {
            id,
            flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
            ..Default::default()
        };

        let mut host = new_state_only_running_sandbox_app();
        let (manager, event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(0);
        host.network = Some(manager);
        host.network_mode = Some(NetworkMode::Host(host_network_settings()));
        host.network_is_league = true;
        host.control_player_infos.replace_snapshot(
            41,
            [lc_engine::PlayerInfoControlData {
                client_id: 8,
                players: vec![joined(41)],
                ..Default::default()
            }],
        );
        let host_report = std::thread::spawn(move || commands.complete_league_disconnect_report());
        event_tx
            .send(NetworkEvent::PeerConnectionFailed { client_id: 8 })
            .expect("queue host route loss");
        host.process_network_events().expect("report host route loss");
        let (reason, players) = host_report
            .join()
            .expect("join host report worker")
            .expect("host sent report");
        assert_eq!(reason, lc_network::LeagueDisconnectReason::ConnectionFailed);
        assert_eq!(players.client_id, 8);
        assert_eq!(players.players[0].id, 41);

        let mut client = new_state_only_running_sandbox_app();
        let (manager, event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        client.network = Some(manager);
        client.network_mode = Some(NetworkMode::Client(client_network_settings()));
        client.network_is_league = true;
        client.control_player_infos.replace_snapshot(
            55,
            [lc_engine::PlayerInfoControlData {
                client_id: 7,
                players: vec![joined(55)],
                ..Default::default()
            }],
        );
        let client_report =
            std::thread::spawn(move || commands.complete_league_disconnect_report());
        event_tx
            .send(NetworkEvent::PeerDisconnected {
                client_id: 0,
                reason: Some("lost".to_string()),
            })
            .expect("queue client host loss");
        client
            .process_network_events()
            .expect("report client host loss");
        let (reason, players) = client_report
            .join()
            .expect("join client report worker")
            .expect("client sent report");
        assert_eq!(reason, lc_network::LeagueDisconnectReason::ConnectionFailed);
        assert_eq!(players.client_id, 7);
        assert_eq!(players.players[0].id, 55);
    }

    #[test]
    fn active_network_client_runtime_join_publishes_before_add_request() {
        // JoinPlayer:<file> calls JoinLocalPlayer(file, true). LoadFromLocalFile
        // publishes the NRT_Player resource before the client sends the
        // CIF_AddPlayers PID_PlayerInfoUpdReq to the host
        // (pristine 9ffa0a5d src/C4MainMenu.cpp:760-771;
        // src/C4PlayerInfo.cpp:70-104,357-395;
        // src/C4Network2Players.cpp:78-137).
        let directory = tempdir().expect("create runtime player directory");
        let player_path = directory.path().join("Runtime.c4p");
        let mut player_group = lc_resources::MutableGroup::new("Runtime.c4p");
        player_group
            .add_file_with_metadata(
                "Player.txt",
                b"[Player]\nName=Runtime\n[Preferences]\nColorDw=6636321\n".to_vec(),
                1,
                false,
            )
            .expect("add runtime player core");
        fs::write(
            &player_path,
            player_group.pack().expect("pack runtime player"),
        )
        .expect("write runtime player");

        let mut app = new_running_sandbox_app();
        app.player_name = "Exact maker".to_string();
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        let mut client_settings = ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        );
        client_settings.group_maker =
            LegacyCString::from_bytes(b"Exact maker".to_vec()).unwrap();
        app.network_mode = Some(NetworkMode::Client(client_settings));
        app.control_clients.register(7, true, false);

        let wire_name = lc_engine::LegacyCString::from_bytes(
            player_path.as_os_str().as_encoded_bytes().to_vec(),
        )
        .expect("fixture player path is NUL-free");
        let resource = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: 7 << 16,
            loadable: true,
            filename: wire_name.clone(),
            ..Default::default()
        };
        let expected_resource = resource.clone();
        let command_observer =
            thread::spawn(move || commands.complete_initial_client_join(vec![resource]));

        app.apply_ingame_menu_action(MenuAction::JoinPlayer(
            player_path.to_string_lossy().into_owned(),
        ))
        .expect("runtime player menu action");
        assert_eq!(
            app.admission_resources.complete_path(expected_resource.id),
            Some(player_path.as_path()),
            "the publishing client keeps its own player resource complete"
        );
        drop(app.network.take());

        let (order, publications, player_infos, acknowledgements) =
            command_observer.join().expect("command observer");
        assert_eq!(order, vec!["publish", "player-info"]);
        assert_eq!(publications.len(), 1);
        assert_eq!(publications[0].source_path, player_path);
        assert_eq!(publications[0].wire_name, wire_name.clone());
        assert_eq!(publications[0].group_maker.as_bytes(), b"Exact maker");
        assert_eq!(player_infos.len(), 1);
        assert_eq!(player_infos[0].client_id, 7);
        assert_eq!(
            player_infos[0].flags,
            lc_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS
        );
        let player = &player_infos[0].players[0];
        assert_eq!(player.id, 0);
        assert_eq!(player.name.as_bytes(), b"Runtime");
        assert_eq!(player.filename, wire_name);
        assert_eq!(player.color, 0x65_43_21);
        assert_eq!(player.original_color, 0x65_43_21);
        assert_eq!(player.resource, Some(expected_resource));
        assert!(acknowledgements.is_empty());
    }

    #[test]
    fn active_network_host_runtime_join_publishes_admits_and_queues_join() {
        // JoinLocalPlayer(file, true) first lets LoadFromLocalFile publish an
        // NRT_Player. A host handles CIF_AddPlayers directly, assigns the next
        // player ID, broadcasts authoritative PlayerInfo with CDT_Direct, and
        // the running-host handler then queues JoinPlayer with the resource
        // file (pristine 9ffa0a5d src/C4PlayerInfo.cpp:70-104;
        // src/C4Network2Players.cpp:78-137,160-239,245-270,353-388).
        let directory = tempdir().expect("create runtime player directory");
        let player_path = directory.path().join("HostRuntime.c4p");
        let mut player_group = lc_resources::MutableGroup::new("HostRuntime.c4p");
        player_group
            .add_file_with_metadata(
                "Player.txt",
                b"[Player]\nName=Host Runtime\n[Preferences]\nColorDw=1193046\n".to_vec(),
                1,
                false,
            )
            .expect("add runtime player core");
        fs::write(
            &player_path,
            player_group.pack().expect("pack runtime player"),
        )
        .expect("write runtime player");

        let mut app = new_running_sandbox_app();
        app.player_name = "Exact host maker".to_string();
        app.control_clients.register(0, true, false);
        app.control_player_infos.replace_snapshot(40, []);
        let tick = app.local_control_submission_tick();
        let (manager, event_tx, commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));

        let wire_name = lc_engine::LegacyCString::from_bytes(
            player_path.as_os_str().as_encoded_bytes().to_vec(),
        )
        .expect("fixture player path is NUL-free");
        let resource = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: 17,
            loadable: true,
            filename: wire_name.clone(),
            ..Default::default()
        };
        let expected_resource = resource.clone();
        let (direct_ready, direct_wait) = std::sync::mpsc::channel();
        let command_observer = thread::spawn(move || {
            commands.complete_runtime_host_join(resource, event_tx, direct_ready)
        });

        app.apply_ingame_menu_action(MenuAction::JoinPlayer(
            player_path.to_string_lossy().into_owned(),
        ))
        .expect("runtime host player menu action");
        direct_wait
            .recv_timeout(Duration::from_secs(1))
            .expect("authoritative PlayerInfo broadcast");
        app.process_network_events()
            .expect("execute authoritative PlayerInfo");
        drop(app.network.take());

        let (order, publications, player_infos, joins) =
            command_observer.join().expect("command observer");
        assert_eq!(order, vec!["publish", "player-info", "join-player"]);
        assert_eq!(publications.len(), 1);
        assert_eq!(publications[0].source_path, player_path);
        assert_eq!(publications[0].wire_name, wire_name.clone());
        assert_eq!(publications[0].group_maker.as_bytes(), b"Exact host maker");
        let [info] = player_infos.as_slice() else {
            panic!("expected one authoritative PlayerInfo");
        };
        assert_eq!((info.client_id, info.by_client), (0, 0));
        assert_eq!(info.flags, lc_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS);
        let [player] = info.players.as_slice() else {
            panic!("expected one admitted player");
        };
        assert_eq!(player.id, 41);
        assert_eq!(player.name.as_bytes(), b"Host Runtime");
        assert_eq!(player.resource.as_ref(), Some(&expected_resource));
        assert_eq!(joins.len(), 1);
        assert_eq!(joins[0].0, tick);
        assert_eq!(joins[0].1.at_client, 0);
        assert_eq!(joins[0].1.info_id, 41);
        assert_eq!(
            joins[0].1.filename.as_bytes(),
            player_path.as_os_str().as_encoded_bytes()
        );
        assert_eq!(
            joins[0].1.source,
            lc_engine::JoinPlayerSource::Resource(expected_resource)
        );
    }

    #[test]
    fn active_network_host_runtime_join_assigns_team_before_broadcast() {
        // The host handles its local CIF_AddPlayers packet directly, assigning
        // its ID and team before broadcasting authoritative PlayerInfo
        // (src/C4Network2Players.cpp:78-137,160-205;
        // src/C4Teams.cpp:53-81,474-542).
        let directory = tempdir().expect("create runtime player directory");
        let player_path = directory.path().join("HostTeamRuntime.c4p");
        let mut player_group = lc_resources::MutableGroup::new("HostTeamRuntime.c4p");
        player_group
            .add_file_with_metadata(
                "Player.txt",
                b"[Player]\nName=Host Team Runtime\n[Preferences]\nColorDw=1193046\nAlternateColorDw=6636321\n".to_vec(),
                1,
                false,
            )
            .expect("add runtime player core");
        fs::write(
            &player_path,
            player_group.pack().expect("pack runtime player"),
        )
        .expect("write runtime player");

        let team = |id, player_ids, color| lc_engine::InitialNetworkTeam {
            id,
            name: lc_engine::LegacyCString::from_bytes(format!("Team {id}").into_bytes()).unwrap(),
            player_start_index: 0,
            player_ids,
            color,
            icon_spec: lc_engine::LegacyCString::default(),
            max_players: 0,
        };
        let mut app = new_state_only_running_sandbox_app();
        app.player_name = "Exact host maker".to_string();
        app.control_clients.register(0, true, false);
        app.control_player_infos.replace_snapshot(
            1,
            [lc_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 1,
                    team: 1,
                    color: 0x0012_3456,
                    original_color: 0x0012_3456,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        app.network_team_assignment = Some(NetworkTeamAssignmentState::from_prepared_host(
            lc_engine::InitialNetworkTeamMetadata {
                active: true,
                custom: true,
                allow_hostility_change: false,
                allow_team_switch: false,
                auto_generate_teams: false,
                last_team_id: 2,
                team_distribution: lc_engine::InitialNetworkTeamDistribution::Random,
                team_colors: false,
                max_script_players: 0,
                script_player_names: lc_engine::LegacyCString::default(),
                random_team_count: 0,
                teams: vec![
                    team(1, vec![1], 0x00f4_0000),
                    team(2, Vec::new(), 0x0000_c800),
                ],
            },
        ));
        let (manager, event_tx, commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        let wire_name = lc_engine::LegacyCString::from_bytes(
            player_path.as_os_str().as_encoded_bytes().to_vec(),
        )
        .expect("fixture player path is NUL-free");
        let resource = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: 17,
            loadable: true,
            filename: wire_name,
            ..Default::default()
        };
        let (direct_ready, direct_wait) = std::sync::mpsc::channel();
        let command_observer = thread::spawn(move || {
            commands.complete_runtime_host_join(resource, event_tx, direct_ready)
        });

        app.submit_runtime_network_player(&player_path.to_string_lossy())
            .expect("submit local host runtime player");
        direct_wait
            .recv_timeout(Duration::from_secs(1))
            .expect("authoritative PlayerInfo broadcast");
        app.process_network_events()
            .expect("execute authoritative PlayerInfo");
        drop(app.network.take());

        let (_, _, player_infos, _) = command_observer.join().expect("command observer");
        let [info] = player_infos.as_slice() else {
            panic!("expected one authoritative PlayerInfo");
        };
        let [player] = info.players.as_slice() else {
            panic!("expected one admitted player");
        };
        assert_eq!((player.id, player.team), (2, 2));
        assert_eq!(
            (player.color, player.original_color),
            (0x0093_99c5, 0x0012_3456),
            "native skips the alternate while current still equals original and enters its seeded random fallback"
        );
        assert_eq!(
            app.host_local_alternate_colors_by_resource.get(&17),
            Some(&0x0065_4321),
            "a successful local runtime join extends the persistent sidecar"
        );
        assert!(app.host_local_player_info_ids.contains(&2));
        let teams = app
            .network_team_assignment
            .as_mut()
            .expect("prepared host team state remains installed")
            .teams_mut();
        assert_eq!(teams.teams[0].player_ids, vec![1]);
        assert_eq!(teams.teams[1].player_ids, vec![2]);
    }

    #[test]
    fn client_join_data_submits_an_empty_initial_player_info_for_an_observer() {
        // JoinLocalPlayer sends even an empty CIF_Initial request so the host
        // marks the client as an observer and answers with all player infos;
        // it happens before DoLobby reaches and acknowledges GS_Lobby
        // (src/C4Network2Players.cpp:38-49,78-137;
        // src/C4Game.cpp:3840-3844).
        let mut app = new_state_only_menu_app(320, 200);
        let (manager, event_tx, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Observer",
        )));
        app.network_lobby = Some(NetworkLobbyState::new(7, "Observer".to_string(), false));
        app.selected_player_file = None;

        let host_config = lc_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot
            .parameters
            .clients
            .clients
            .push(lc_engine::ClientCoreControlData {
                client_id: 7,
                name: lc_engine::LegacyCString::from_bytes(b"Observer".to_vec())
                    .expect("valid client name"),
                ..Default::default()
            });
        snapshot.parameters.clients.local_client_id = Some(7);
        let join_data = lc_network::JoinDataEnvelope {
            client_id: 7,
            start_control_tick: snapshot.dynamic_tick,
            status: host_config.initial_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data))
            .expect("queue JoinData");

        app.process_network_events().expect("apply JoinData");

        assert_eq!(
            commands.take_player_info_updates(),
            vec![lc_network::PlayerInfoUpdateRequest {
                client_id: 7,
                flags: lc_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
                players: Vec::new(),
            }]
        );
    }

    #[test]
    fn client_join_publishes_selected_players_before_info_and_lobby_ack() {
        // InitNetworkFromReference initializes Network.Players before DoLobby;
        // C4Game copies the raw configured module list and loads it directly;
        // each resource is published first, all successful player infos travel
        // in one CIF_Initial request, and only then may GS_Lobby be
        // acknowledged (pristine 9ffa0a5d src/C4Game.cpp:361-364,3823-3844;
        // src/C4PlayerInfo.cpp:70-104,357-395;
        // src/C4Network2Players.cpp:38-49,78-136).
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let players = tempdir().expect("configured players");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        paths.ensure_user_dirs().expect("create user directories");
        let write_player = |filename: &str, name: &str, color: u32| {
            let path = players.path().join(filename);
            let mut group = lc_resources::MutableGroup::new(filename);
            group
                .add_file_with_metadata(
                    "Player.txt",
                    format!("[Player]\nName={name}\n[Preferences]\nColorDw={color}\n")
                        .into_bytes(),
                    1,
                    false,
                )
                .expect("add player core");
            fs::write(&path, group.pack().expect("pack player")).expect("write player group");
            path
        };
        let bravo = write_player("Bravo.c4p", "Bravo", 0x11_22_33);
        let alpha = write_player("Alpha.c4p", "Alpha", 0x44_55_66);
        let mut config = b"[General]\nName=\"Maker\"\nParticipants=\"".to_vec();
        config.extend_from_slice(bravo.as_os_str().as_encoded_bytes());
        config.push(b';');
        config.extend_from_slice(alpha.as_os_str().as_encoded_bytes());
        config.extend_from_slice(b"\"\n");
        fs::write(paths.config_file(), config).expect("write raw configured participants");

        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialize app with configured participants");
        wait_for_menu(&mut app);
        app.freeze_configured_client_players_for_game()
            .expect("C4Game::Init freezes configured participants");
        fs::write(
            paths.config_file(),
            b"[General]\nName=Changed\nParticipants=\"\"\n",
        )
        .expect("mutate persisted config after C4Game::Init snapshot");
        let (manager, event_tx, commands) =
            NetworkManager::test_stub_with_commands_for_client_id(7);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.network_lobby = Some(NetworkLobbyState::new(7, "Client".to_string(), false));
        app.startup_view = StartupView::NetworkLobby;
        // The visible startup list is deliberately stale: production joining
        // must use Config.General.Participants directly, not this UI model.
        app.startup_player_files.clear();
        app.startup_player_models.clear();
        app.selected_player_file = None;

        let configured_paths = [bravo, alpha];
        let cores = configured_paths
            .iter()
            .enumerate()
            .map(|(index, path)| lc_engine::NetworkResourceCore {
                resource_type: lc_network::HostResourceType::Player as u8,
                id: (7 << 16) + index as i32,
                loadable: true,
                filename: lc_engine::LegacyCString::from_bytes(
                    path.as_os_str().as_encoded_bytes().to_vec(),
                )
                .expect("fixture path is NUL-free"),
                ..Default::default()
            })
            .collect::<Vec<_>>();
        let expected_cores = cores.clone();
        let command_observer = thread::spawn(move || commands.complete_initial_client_join(cores));

        let host_config = lc_network::HostConfig::default();
        let mut snapshot = host_config
            .initial_join_snapshot
            .expect("default host publishes JoinData");
        snapshot
            .parameters
            .clients
            .clients
            .push(lc_engine::ClientCoreControlData {
                client_id: 7,
                name: lc_engine::LegacyCString::from_bytes(b"Client".to_vec())
                    .expect("valid client name"),
                ..Default::default()
            });
        snapshot.parameters.clients.local_client_id = Some(7);
        let join_data = lc_network::JoinDataEnvelope {
            client_id: 7,
            start_control_tick: 23,
            status: host_config.initial_status,
            dynamic: snapshot.dynamic,
            parameters: snapshot.parameters,
        };
        event_tx
            .send(NetworkEvent::JoinData(join_data))
            .expect("queue JoinData");

        app.process_network_events()
            .expect("initialize client lobby");
        for (core, path) in expected_cores.iter().zip(&configured_paths) {
            assert_eq!(
                app.admission_resources.complete_path(core.id),
                Some(path.as_path()),
                "the publishing client keeps each initial player resource complete"
            );
        }

        let (order, publications, player_infos, acknowledgements) =
            command_observer.join().expect("command observer");
        assert_eq!(
            order,
            vec!["publish", "publish", "player-info", "status-ack"]
        );
        assert_eq!(
            publications
                .iter()
                .map(|request| request.wire_name.as_bytes())
                .collect::<Vec<_>>(),
            configured_paths
                .iter()
                .map(|path| path.as_os_str().as_encoded_bytes())
                .collect::<Vec<_>>()
        );
        assert!(publications
            .iter()
            .all(|request| request.group_maker.as_bytes() == b"Maker"));
        assert_eq!(player_infos.len(), 1);
        assert_eq!(
            player_infos[0]
                .players
                .iter()
                .map(|player| {
                    (
                        player.name.as_bytes(),
                        player.color,
                        player.resource.clone(),
                    )
                })
                .collect::<Vec<_>>(),
            vec![
                (
                    b"Bravo".as_slice(),
                    0x11_22_33,
                    Some(expected_cores[0].clone())
                ),
                (
                    b"Alpha".as_slice(),
                    0x44_55_66,
                    Some(expected_cores[1].clone())
                ),
            ]
        );
        assert_eq!(acknowledgements.len(), 1);
        assert_eq!(acknowledgements[0].target_tick, 23);
    }

    #[test]
    fn league_player_rejection_uses_cpp_swap_with_last_iteration_order() {
        let mut players = [1, 2, 3, 4]
            .into_iter()
            .map(|id| lc_engine::ControlPlayerInfoEntry {
                id,
                ..Default::default()
            })
            .collect::<Vec<_>>();
        let mut visited = Vec::new();

        retain_player_infos_with_cpp_swap_remove(&mut players, |player| {
            visited.push(player.id);
            player.id != 1 && player.id != 3
        });

        assert_eq!(visited, vec![1, 4, 2, 3]);
        assert_eq!(
            players.iter().map(|player| player.id).collect::<Vec<_>>(),
            vec![4, 2]
        );
    }

    fn poll_league_auth_until(
        app: &mut GameApp,
        context: &str,
        mut complete: impl FnMut(&GameApp) -> bool,
    ) {
        let deadline = Instant::now() + Duration::from_secs(2);
        while !complete(app) {
            assert!(Instant::now() < deadline, "timed out waiting for {context}");
            app.poll_league_player_auth().expect("poll Auth exchange");
            thread::sleep(Duration::from_millis(1));
        }
    }

    fn abort_open_league_signup(app: &mut GameApp) {
        let abort = app
            .league_signup_dialog
            .as_mut()
            .expect("league signup dialog")
            .controller
            .abort();
        app.process_league_signup_actions(vec![abort])
            .expect("abort league signup");
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("dismiss league signup cancellation notice");
    }

    #[test]
    fn league_client_authenticates_each_published_player_and_submits_only_auid_survivors() {
        // JoinLocalPlayer publishes player resources first, authenticates each
        // loaded row in packet order, removes failures in place, and sends the
        // successful AUIDs in one CIF_Initial packet
        // (src/C4Network2Players.cpp:78-137;
        // src/C4Network2.cpp:2596-2738).
        let install_root = Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent()
            .and_then(Path::parent)
            .and_then(Path::parent)
            .expect("repository root");
        let user_data = tempdir().expect("user data");
        let players = tempdir().expect("configured players");
        let _guard = EnvGuard::set(&[
            ("LC_INSTALL_ROOT", Some(install_root)),
            ("LC_USER_DATA_DIR", Some(user_data.path())),
        ]);
        let paths = AppPaths::discover().expect("discover app paths");
        paths.ensure_user_dirs().expect("create user directories");
        let write_player = |filename: &str, name: &str, color: u32| {
            let path = players.path().join(filename);
            let mut group = lc_resources::MutableGroup::new(filename);
            group
                .add_file_with_metadata(
                    "Player.txt",
                    format!("[Player]\nName={name}\n[Preferences]\nColorDw={color}\n").into_bytes(),
                    1,
                    false,
                )
                .expect("add player core");
            fs::write(&path, group.pack().expect("pack player")).expect("write player group");
            path
        };
        let accepted_path = write_player("Accepted.c4p", "Accepted", 0x11_22_33);
        let rejected_path = write_player("Rejected.c4p", "Rejected", 0x44_55_66);
        let mut config = b"[General]\nName=Maker\nParticipants=\"".to_vec();
        config.extend_from_slice(accepted_path.as_os_str().as_encoded_bytes());
        config.push(b';');
        config.extend_from_slice(rejected_path.as_os_str().as_encoded_bytes());
        config.extend_from_slice(b"\"\n");
        fs::write(paths.config_file(), config).expect("write configured participants");

        let mut app = GameApp::new(
            320,
            200,
            AudioOptions::default(),
            Some(&paths),
            RuntimeConfig {
                player_owner: 1,
                player_name: "Player".to_string(),
                network: None,
                record_enabled: false,
            },
        )
        .expect("initialize app");
        wait_for_menu(&mut app);
        app.freeze_configured_client_players_for_game()
            .expect("freeze configured players");
        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        let auth = lc_network::LeagueAuthRequestHead {
            account: lc_engine::LegacyCString::from_bytes(b"account".to_vec()).unwrap(),
            password: lc_engine::LegacyCString::from_bytes(b"password".to_vec()).unwrap(),
            ..Default::default()
        };
        app.network_mode = Some(NetworkMode::Client(
            ClientSettings::new(
                SocketAddr::from(([127, 0, 0, 1], 11_112)),
                "Client",
            )
            .with_league_auth(auth.clone()),
        ));
        app.network_is_league = true;
        let configured_paths = [accepted_path, rejected_path];
        let cores = configured_paths
            .iter()
            .enumerate()
            .map(|(index, path)| lc_engine::NetworkResourceCore {
                resource_type: lc_network::HostResourceType::Player as u8,
                id: (7 << 16) + index as i32,
                loadable: true,
                filename: lc_engine::LegacyCString::from_bytes(
                    path.as_os_str().as_encoded_bytes().to_vec(),
                )
                .unwrap(),
                ..Default::default()
            })
            .collect::<Vec<_>>();
        let all_rejected_cores = cores.clone();
        let responses = vec![
            lc_network::decode_league_auth_response(
                b"[Response]\r\nStatus=Success\r\nAUID=accepted-token\r\n",
            ),
        ];
        let observer = thread::spawn(move || {
            commands.complete_initial_league_client_join(cores, responses)
        });

        assert_eq!(
            app.submit_initial_client_player_info(7, "league.example".to_string()),
            LeaguePlayerAuthStatus::Pending
        );
        poll_league_auth_until(&mut app, "Auth error", |app| {
            matches!(
                app.message_dialogs.last().map(|dialog| &dialog.continuation),
                Some(MessageDialogContinuation::LeaguePlayerAuthError)
            )
        });
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("acknowledge rejected Auth");
        let retry = {
            let retry = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("rejected Auth reopens login")
                .controller;
            retry.set_password("replacement");
            retry.submit()
        };
        app.process_league_signup_actions(vec![retry])
            .expect("submit rejected Auth retry");
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Cancel)
            .expect("Abort drops the rejected player");
        let (order, auth_heads, auth_players, requests) =
            observer.join().expect("league command observer");

        assert_eq!(
            order,
            vec!["publish", "publish", "auth", "auth", "auth", "player-info"]
        );
        assert_eq!(&auth_heads[..2], &[auth.clone(), auth.clone()]);
        assert_eq!(
            auth_players
                .iter()
                .map(|player| player.name.as_bytes())
                .collect::<Vec<_>>(),
            vec![
                b"Accepted".as_slice(),
                b"Rejected".as_slice(),
                b"Rejected".as_slice(),
            ]
        );
        let [request] = requests.as_slice() else {
            panic!("expected one initial PlayerInfo request");
        };
        assert_eq!(request.flags, lc_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL);
        let [player] = request.players.as_slice() else {
            panic!("only the authenticated player should survive");
        };
        assert_eq!(player.name.as_bytes(), b"Accepted");
        assert_eq!(player.auth_id.as_bytes(), b"accepted-token");

        let (manager, _event_tx, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        if let Some(NetworkMode::Client(settings)) = app.network_mode.as_mut() {
            settings.league_auth = auth;
        }
        let observer = thread::spawn(move || {
            commands.complete_initial_league_client_join(
                all_rejected_cores,
                Vec::new(),
            )
        });
        assert_eq!(
            app.submit_initial_client_player_info(7, "league.example".to_string()),
            LeaguePlayerAuthStatus::Pending
        );
        poll_league_auth_until(&mut app, "Auth error", |app| {
            matches!(
                app.message_dialogs.last().map(|dialog| &dialog.continuation),
                Some(MessageDialogContinuation::LeaguePlayerAuthError)
            )
        });
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("acknowledge first rejected Auth");
        abort_open_league_signup(&mut app);
        abort_open_league_signup(&mut app);
        let (_, _, _, requests) = observer.join().expect("all-rejected observer");
        assert_eq!(requests.len(), 1);
        assert!(
            requests[0].players.is_empty(),
            "an initial all-failed auth still sends the empty observer packet"
        );
    }

    #[test]
    fn league_auth_wait_is_abortable_and_success_uses_exact_welcome_confirmation() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated league Auth configuration");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        persist_config_value(&paths, "Network", "LeagueAutoLogin", "0")
            .expect("disable league auto-login");
        let mut app = new_menu_app_with_paths(640, 480, &paths);
        let (manager, _events, mut commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        let auth = lc_network::LeagueAuthRequestHead {
            account: LegacyCString::from_bytes(b"account".to_vec()).unwrap(),
            password: LegacyCString::from_bytes(b"password".to_vec()).unwrap(),
            ..Default::default()
        };
        app.network_mode = Some(NetworkMode::Client(
            ClientSettings::new(
                SocketAddr::from(([127, 0, 0, 1], 11_112)),
                "Client",
            )
            .with_league_auth(auth.clone()),
        ));
        let player = lc_engine::ControlPlayerInfoEntry {
            name: LegacyCString::from_bytes(b"Exact Player".to_vec()).unwrap(),
            ..Default::default()
        };
        let request = || lc_network::PlayerInfoUpdateRequest {
            client_id: 7,
            flags: lc_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
            players: vec![player.clone()],
        };

        assert_eq!(
            app.begin_league_player_auth_exchange(
                LeaguePlayerAuthContinuation::InitialClient {
                    request: request(),
                    index: 0,
                    server_name: "league.example".to_string(),
                },
                auth.clone(),
                lc_frontend::league_signup::LeagueSignupMode::Login,
            )
            .expect("begin league Auth"),
            LeaguePlayerAuthStatus::Pending
        );
        let replacement = lc_network::PlayerInfoUpdateRequest {
            client_id: 7,
            flags: lc_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
            players: vec![lc_engine::ControlPlayerInfoEntry {
                name: LegacyCString::from_bytes(b"Replacement".to_vec()).unwrap(),
                ..Default::default()
            }],
        };
        assert_eq!(
            app.continue_league_player_auth(LeaguePlayerAuthContinuation::InitialClient {
                request: replacement,
                index: 0,
                server_name: "other.example".to_string(),
            })
            .expect("reject overlapping Auth without replacing it"),
            LeaguePlayerAuthStatus::Completed(false)
        );
        assert_eq!(
            app.pending_league_player_auth
                .as_ref()
                .map(|pending| GameApp::league_auth_continuation_player_name(
                    &pending.continuation
                )),
            Some("Exact Player".to_string())
        );
        let wait = app.message_dialogs.last().expect("Auth wait dialog");
        assert_eq!(
            wait.state.message(),
            "League login for player Exact Player on league.example..."
        );
        assert_eq!(wait.state.caption(), "League Login");
        assert_eq!(
            wait.state.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::Standard(3)
        );
        assert_eq!(
            wait.state.buttons(),
            lc_frontend::message_dialog::MessageDialogButtons::CANCEL
        );
        assert_eq!(
            wait.state.button_label(
                lc_frontend::message_dialog::MessageDialogButton::Cancel
            ),
            "Abort"
        );
        let command = commands.receive_league_player_auth();
        assert!(command.complete(Ok(lc_network::decode_league_auth_response(
            b"[Response]\r\nStatus=Success\r\nAUID=one-use-token\r\nMessage=Server welcome\r\n",
        ))));
        app.poll_league_player_auth()
            .expect("resolve successful Auth");

        let welcome = app.message_dialogs.last().expect("welcome confirmation");
        assert_eq!(welcome.state.message(), "Server welcome");
        assert_eq!(welcome.state.caption(), "Confirm League Login");
        assert_eq!(
            welcome.state.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::Extended(8)
        );
        assert_eq!(
            welcome.state.buttons(),
            lc_frontend::message_dialog::MessageDialogButtons::OK_CANCEL
        );
        assert_eq!(
            welcome.state.button_label(
                lc_frontend::message_dialog::MessageDialogButton::Cancel
            ),
            "Abort"
        );
        assert!(commands.take_player_info_updates().is_empty());
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("approve welcome");
        let updates = commands.take_player_info_updates();
        let [submitted] = updates.as_slice() else {
            panic!("welcome approval submits one initial PlayerInfo");
        };
        assert_eq!(submitted.players[0].auth_id.as_bytes(), b"one-use-token");

        assert_eq!(
            app.begin_league_player_auth_exchange(
                LeaguePlayerAuthContinuation::InitialClient {
                    request: request(),
                    index: 0,
                    server_name: "league.example".to_string(),
                },
                auth,
                lc_frontend::league_signup::LeagueSignupMode::Login,
            )
            .expect("begin abandoned league Auth"),
            LeaguePlayerAuthStatus::Pending
        );
        let abandoned = commands.receive_league_player_auth();
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Cancel)
            .expect("Abort wait drops current player without hanging");
        assert!(!abandoned.complete(Ok(
            lc_network::LeagueAuthResponse::default()
        )));
        let updates = commands.take_player_info_updates();
        let [submitted] = updates.as_slice() else {
            panic!("aborted Auth submits the empty observer packet");
        };
        assert!(submitted.players.is_empty());
    }

    #[test]
    fn league_auth_error_dialog_retries_with_cleared_password() {
        let _lock = env_lock().lock();
        let user_data = tempdir().expect("isolated league Auth configuration");
        let (_guard, paths) = exact_loader_test_paths(user_data.path(), None);
        persist_config_value(&paths, "Network", "LeagueAutoLogin", "0")
            .expect("disable league auto-login");
        persist_config_value(&paths, "Network", "LeaguePassword", "password")
            .expect("seed remembered password");
        let mut app = new_menu_app_with_paths(640, 480, &paths);
        let (manager, _events, mut commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(7);
        app.network = Some(manager);
        let auth = lc_network::LeagueAuthRequestHead {
            account: LegacyCString::from_bytes(b"account".to_vec()).unwrap(),
            password: LegacyCString::from_bytes(b"password".to_vec()).unwrap(),
            ..Default::default()
        };
        app.network_mode = Some(NetworkMode::Client(
            ClientSettings::new(
                SocketAddr::from(([127, 0, 0, 1], 11_112)),
                "Client",
            )
            .with_league_auth(auth.clone()),
        ));
        let player = lc_engine::ControlPlayerInfoEntry {
            name: LegacyCString::from_bytes(b"Exact Player".to_vec()).unwrap(),
            ..Default::default()
        };
        assert_eq!(
            app.begin_league_player_auth_exchange(
                LeaguePlayerAuthContinuation::InitialClient {
                    request: lc_network::PlayerInfoUpdateRequest {
                        client_id: 7,
                        flags: lc_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
                        players: vec![player.clone()],
                    },
                    index: 0,
                    server_name: "league.example".to_string(),
                },
                auth,
                lc_frontend::league_signup::LeagueSignupMode::Login,
            )
            .expect("begin league Auth"),
            LeaguePlayerAuthStatus::Pending
        );
        let rejected = commands.receive_league_player_auth();
        assert_eq!(rejected.auth.password.as_bytes(), b"password");
        assert!(rejected.complete(Ok(lc_network::decode_league_auth_response(
            b"[Response]\r\nStatus=Failure\r\nMessage=Wrong password\r\n",
        ))));
        app.poll_league_player_auth()
            .expect("resolve rejected Auth");
        let error = app.message_dialogs.last().expect("Auth error dialog");
        assert_eq!(error.state.message(), "League server reply: Wrong password");
        assert_eq!(error.state.caption(), "League Login Failed");
        assert_eq!(
            error.state.icon(),
            lc_frontend::message_dialog::MessageDialogIcon::ERROR
        );

        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("acknowledge server error and retry");
        let retry_submission = {
            let retry = &mut app
                .league_signup_dialog
                .as_mut()
                .expect("login retry")
                .controller;
            assert!(retry.password().is_empty());
            retry.set_password("replacement");
            retry.submit()
        };
        app.process_league_signup_actions(vec![retry_submission])
            .expect("submit login retry");
        let retry = commands.receive_league_player_auth();
        assert_eq!(retry.player, player);
        assert_eq!(retry.auth.password.as_bytes(), b"replacement");
        assert!(retry.complete(Ok(lc_network::decode_league_auth_response(
            b"[Response]\r\nStatus=Success\r\nAUID=retry-token\r\nAccount=Master\r\n",
        ))));
        app.poll_league_player_auth()
            .expect("resolve retried Auth");
        let welcome = app.message_dialogs.last().expect("derived welcome dialog");
        assert_eq!(
            welcome.state.message(),
            "Player: Exact Player|League user name: Master|Server: league.example"
        );
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("approve retried Auth");
        let updates = commands.take_player_info_updates();
        let [submitted] = updates.as_slice() else {
            panic!("retry success submits initial PlayerInfo");
        };
        assert_eq!(submitted.players[0].auth_id.as_bytes(), b"retry-token");
        assert!(load_league_auth_settings(Some(&paths)).password.is_empty());

        // A declined registration welcome loops in registration mode. Native
        // retains the local old Password fallback and the server's canonical
        // AccountMaster while clearing only the process-global password.
        let registration_auth = lc_network::LeagueAuthRequestHead {
            account: LegacyCString::from_bytes(b"old-master".to_vec()).unwrap(),
            password: LegacyCString::from_bytes(b"old-password".to_vec()).unwrap(),
            new_account: LegacyCString::from_bytes(b"requested".to_vec()).unwrap(),
            new_password: LegacyCString::from_bytes(b"old-password".to_vec()).unwrap(),
        };
        assert_eq!(
            app.begin_league_player_auth_exchange(
                LeaguePlayerAuthContinuation::InitialClient {
                    request: lc_network::PlayerInfoUpdateRequest {
                        client_id: 7,
                        flags: lc_engine::CLIENT_PLAYER_INFO_FLAG_INITIAL,
                        players: vec![player],
                    },
                    index: 0,
                    server_name: "league.example".to_string(),
                },
                registration_auth,
                lc_frontend::league_signup::LeagueSignupMode::Registration,
            )
            .expect("begin registration Auth"),
            LeaguePlayerAuthStatus::Pending
        );
        let registration = commands.receive_league_player_auth();
        assert!(registration.complete(Ok(lc_network::decode_league_auth_response(
            b"[Response]\r\nStatus=Success\r\nAUID=registration-token\r\nAccount=canonical-master\r\n",
        ))));
        app.poll_league_player_auth()
            .expect("resolve registration Auth");
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Cancel)
            .expect("decline registration welcome");
        assert!(matches!(
            app.message_dialogs.last().map(|dialog| &dialog.continuation),
            Some(MessageDialogContinuation::LeaguePlayerAuthCancelled)
        ));
        app.finish_message_dialog(lc_frontend::message_dialog::MessageDialogResult::Ok)
            .expect("dismiss registration cancellation notice");
        let registration_retry = app
            .league_signup_dialog
            .as_ref()
            .expect("registration welcome cancellation reopens registration");
        assert_eq!(
            registration_retry.controller.mode(),
            lc_frontend::league_signup::LeagueSignupMode::Registration
        );
        assert_eq!(registration_retry.auth.account.as_bytes(), b"canonical-master");
        assert_eq!(registration_retry.auth.password.as_bytes(), b"old-password");
        assert!(registration_retry.auth.new_account.is_empty());
        assert!(registration_retry.auth.new_password.is_empty());
    }

