    #[test]
    fn running_host_direct_script_info_queues_one_synchronized_join() {
        // On a running host, direct PlayerInfo executes first and then
        // JoinUnjoinedPlayersInControlQueue appends one script JoinPlayer to
        // the next control input (src/C4Network2Players.cpp:245-269,353-388).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        let tick = app.local_control_submission_tick();
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                lc_engine::PlayerInfoControlData {
                    client_id: 0,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 41,
                        player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                        ..Default::default()
                    }],
                    by_client: 0,
                    ..Default::default()
                },
            )))
            .expect("queue direct script PlayerInfo");

        app.process_network_events()
            .expect("process direct script PlayerInfo");

        assert_eq!(
            commands.take_submitted_join_players(),
            vec![(
                tick,
                lc_engine::JoinPlayerControlData {
                    at_client: 0,
                    info_id: 41,
                    source: lc_engine::JoinPlayerSource::Embedded(Vec::new()),
                    by_client: 0,
                    ..Default::default()
                },
            )]
        );
    }

    #[test]
    fn running_host_queues_remote_join_before_player_resource_completes() {
        // HandlePlayerInfo starts loading the advertised resource and queues
        // JoinPlayer immediately. Resource completeness is checked later by
        // the synchronized control's PreExecute
        // (src/C4Network2Players.cpp:245-269,353-388;
        // src/C4Control.cpp:811-825).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        app.control_clients.register(3, true, false);
        let tick = app.local_control_submission_tick();
        let resource = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: 61,
            loadable: true,
            filename: lc_engine::LegacyCString::from_bytes(b"Remote.c4p".to_vec())
                .expect("valid resource filename"),
            ..Default::default()
        };

        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::PlayerInfo(
                lc_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 41,
                        flags: lc_engine::PLAYER_INFO_FLAG_HAS_RESOURCE,
                        resource: Some(resource.clone()),
                        ..Default::default()
                    }],
                    by_client: 0,
                    ..Default::default()
                },
            )))
            .expect("queue direct resource-backed PlayerInfo");

        app.process_network_events()
            .expect("process direct resource-backed PlayerInfo");

        assert_eq!(
            app.admission_resources.status(resource.id),
            Some(&AdmissionResourceState::Loading { removed: false })
        );
        assert_eq!(
            commands.take_submitted_join_players(),
            vec![(
                tick,
                lc_engine::JoinPlayerControlData {
                    filename: resource.filename.clone(),
                    at_client: 3,
                    info_id: 41,
                    source: lc_engine::JoinPlayerSource::Resource(resource),
                    by_client: 0,
                },
            )]
        );
    }

    #[test]
    fn offline_create_script_player_joins_through_player_info_control_path() {
        let mut app = new_state_only_running_sandbox_app();
        let existing_player_info_id = app
            .engine
            .player(app.local_owner)
            .expect("sandbox has a low-level local player")
            .player_info_id();
        assert!(existing_player_info_id > 0);
        app.engine
            .install_scenario_script_with_convention(
                "CreateScriptPlayer fixture",
                r#"
                global func SpawnBot()
                {
                    return CreateScriptPlayer("Bot", 0x445566, 2, 15, __AI);
                }
                "#,
                true,
            )
            .expect("fixture script installs");
        let before = app.engine.snapshot().players.len();
        app.engine
            .call_scenario_script_function("SpawnBot", Vec::new())
            .expect("script call succeeds");
        assert_eq!(
            app.engine.snapshot().players.len(),
            before,
            "CreateScriptPlayer must not join synchronously inside the VM call"
        );

        app.handle_script_player_info_updates()
            .expect("offline control path joins script player");
        app.handle_script_player_info_updates()
            .expect("drained request is not replayed");

        let infos = app
            .control_player_infos
            .client_info_ids(0)
            .into_iter()
            .filter_map(|id| app.control_player_infos.get(id))
            .filter(|info| info.name.as_bytes() == b"Bot")
            .collect::<Vec<_>>();
        assert_eq!(infos.len(), 1, "script PlayerInfo is admitted exactly once");
        let info = infos[0];
        assert_eq!(
            info.id,
            existing_player_info_id + 1,
            "PlayerInfo admission reserves IDs already owned by live low-level players"
        );
        assert_eq!(info.player_type, lc_engine::PLAYER_INFO_TYPE_SCRIPT);
        assert_eq!((info.color, info.original_color, info.team), (0x445566, 0x445566, 2));
        assert_eq!(info.extra_data, *b"__AI");
        assert_eq!(
            info.flags
                & (lc_engine::PLAYER_INFO_FLAG_ATTRIBUTES_FIXED
                    | lc_engine::PLAYER_INFO_FLAG_NO_SCENARIO_INIT
                    | lc_engine::PLAYER_INFO_FLAG_NO_ELIMINATION_CHECK
                    | lc_engine::PLAYER_INFO_FLAG_INVISIBLE),
            lc_engine::PLAYER_INFO_FLAG_ATTRIBUTES_FIXED
                | lc_engine::PLAYER_INFO_FLAG_NO_SCENARIO_INIT
                | lc_engine::PLAYER_INFO_FLAG_NO_ELIMINATION_CHECK
                | lc_engine::PLAYER_INFO_FLAG_INVISIBLE
        );
        let runtime = app
            .engine
            .snapshot()
            .players
            .into_iter()
            .find(|player| player.player_info_id == info.id)
            .expect("script player joined from its PlayerInfo");
        assert_eq!(runtime.name, "Bot");
        assert_eq!(runtime.team, Some(2));
        assert_eq!(runtime.color, Some(lc_engine::RgbColor::new(0x44, 0x55, 0x66)));
        assert!(
            app.snapshot
                .players
                .iter()
                .any(|player| player.player_info_id == info.id),
            "post-control app snapshot includes the joined player"
        );
    }

    #[test]
    fn script_league_progress_writes_mirror_null_and_empty_into_player_infos() {
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.host_join_snapshot = lc_network::HostConfig::default().initial_join_snapshot;
        app.network_league_name = b"League".to_vec();
        app.control_player_infos.replace_snapshot(
            41,
            [lc_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 41,
                    league_score: 321,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        seed_engine_player_info_parameters(
            &mut app.engine,
            &app.network_league_name,
            &app.control_player_infos,
        );
        app.engine
            .install_scenario_script_with_convention(
                "League progress fixture",
                r#"#strict 3
                global func WriteProgress() { return SetLeagueProgressData("data", 41); }
                global func EmptyProgress() { return SetLeagueProgressData("", 41); }
                global func ClearProgress() { return SetLeagueProgressData(nil, 41); }
                global func ReadLeagueScore() { return SetMaxPlayer(GetLeagueScore(41)); }
                global func SetLimit() { return SetMaxPlayer(5); }
                "#,
                true,
            )
            .expect("fixture script installs");
        app.engine
            .call_scenario_script_function("ReadLeagueScore", Vec::new())
            .expect("retained PlayerInfo league score is visible");
        assert_eq!(app.engine.max_players(), Some(321));

        app.engine
            .call_scenario_script_function("WriteProgress", Vec::new())
            .expect("nonempty progress writes");
        app.handle_script_player_info_updates()
            .expect("nonempty progress mirrors");
        let info = app
            .control_player_infos
            .get(41)
            .expect("info remains retained");
        assert!(!info.league_progress_data_is_null);
        assert_eq!(info.league_progress_data.as_bytes(), b"data");
        let published = commands.take_published_join_snapshots();
        let info = &published
            .last()
            .expect("nonempty progress publishes JoinData")
            .parameters
            .player_infos
            .clients[0]
            .players[0];
        assert!(!info.league_progress_data_is_null);
        assert_eq!(info.league_progress_data.as_bytes(), b"data");

        app.engine
            .call_scenario_script_function("EmptyProgress", Vec::new())
            .expect("empty progress writes");
        app.handle_script_player_info_updates()
            .expect("empty progress mirrors");
        let info = app
            .control_player_infos
            .get(41)
            .expect("info remains retained");
        assert!(!info.league_progress_data_is_null);
        assert!(info.league_progress_data.is_empty());
        let published = commands.take_published_join_snapshots();
        let info = &published
            .last()
            .expect("empty progress publishes JoinData")
            .parameters
            .player_infos
            .clients[0]
            .players[0];
        assert!(!info.league_progress_data_is_null);
        assert!(info.league_progress_data.is_empty());

        app.engine
            .call_scenario_script_function("ClearProgress", Vec::new())
            .expect("nil progress clears");
        app.handle_script_player_info_updates()
            .expect("null progress mirrors");
        let info = app
            .control_player_infos
            .get(41)
            .expect("info remains retained");
        assert!(info.league_progress_data_is_null);
        assert!(info.league_progress_data.is_empty());
        let published = commands.take_published_join_snapshots();
        let info = &published
            .last()
            .expect("cleared progress publishes JoinData")
            .parameters
            .player_infos
            .clients[0]
            .players[0];
        assert!(info.league_progress_data_is_null);
        assert!(info.league_progress_data.is_empty());

        app.engine
            .call_scenario_script_function("SetLimit", Vec::new())
            .expect("SetMaxPlayer executes without a player-info update");
        app.handle_script_player_info_updates()
            .expect("SetMaxPlayer mirrors into host parameters");
        let published = commands.take_published_join_snapshots();
        assert_eq!(
            published
                .last()
                .expect("SetMaxPlayer publishes JoinData")
                .parameters
                .max_players,
            5
        );
        assert_eq!(
            app.host_join_snapshot
                .as_ref()
                .expect("host parameters remain retained")
                .parameters
                .max_players,
            5
        );
    }

    #[test]
    fn offline_negative_set_max_player_preserves_cap_and_rejects_queued_script_player() {
        // Hazard's CreateScriptPlayer runs after SetMaxPlayer in the same
        // Script1 callback. Exercise the app admission boundary as well as
        // the VM result: a rejected negative change must leave the one-slot
        // Game.Parameters cap in force when the deferred PlayerInfo arrives
        // (src/C4Script.cpp:3693-3705; src/C4PlayerInfo.cpp:781-807).
        let mut app = new_state_only_running_sandbox_app();
        app.network_max_players = 1;
        app.engine.set_max_players(1);
        app.control_player_infos.replace_snapshot(
            1,
            [lc_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 1,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        app.engine
            .install_scenario_script_with_convention(
                "SetMaxPlayer negative admission fixture",
                r#"
                static set_result;

                global func RejectLimitAndSpawn()
                {
                    set_result = SetMaxPlayer(-1);
                    CreateScriptPlayer("Rejected Bot", 0x112233, 2, 15, __AI);
                }
                "#,
                true,
            )
            .expect("fixture script installs");

        app.engine
            .call_scenario_script_function("RejectLimitAndSpawn", Vec::new())
            .expect("negative SetMaxPlayer does not abort its caller");

        let globals = app.engine.snapshot().script_globals.named;
        assert_eq!(
            globals.get("set_result"),
            Some(&Value::Int(0)),
            "FnSetMaxPlayer has the C4ValueInt false result"
        );
        assert_eq!(app.engine.max_players(), Some(1));

        app.handle_script_player_info_updates()
            .expect("offline admission handles the queued script player");

        assert_eq!(app.network_max_players, 1);
        assert!(
            app.control_player_infos
                .client_info_ids(0)
                .into_iter()
                .filter_map(|id| app.control_player_infos.get(id))
                .all(|info| info.name.as_bytes() != b"Rejected Bot"),
            "the unchanged full cap rejects the PlayerInfo"
        );
        assert!(
            app.engine
                .snapshot()
                .players
                .iter()
                .all(|player| player.name != "Rejected Bot"),
            "a rejected PlayerInfo cannot reach JoinPlayer"
        );
    }

    #[test]
    fn offline_set_max_player_raise_reaches_admission_before_queued_script_player() {
        // SetMaxPlayer mutates Game.Parameters directly; CreateScriptPlayer
        // queues its PlayerInfo later in the same callback. The app must copy
        // the new limit out of Engine before applying that deferred request
        // (src/C4Script.cpp:2882-2902,3693-3705).
        let mut app = new_state_only_running_sandbox_app();
        app.network_max_players = 1;
        app.engine.set_max_players(1);
        app.engine
            .install_scenario_script_with_convention(
                "SetMaxPlayer raised admission fixture",
                r#"
                static set_result;

                global func RaiseLimitAndSpawn()
                {
                    set_result = SetMaxPlayer(2);
                    CreateScriptPlayer("Admitted Bot", 0x445566, 2, 15, __AI);
                }
                "#,
                true,
            )
            .expect("fixture script installs");

        let before = app.engine.snapshot().players.len();
        app.engine
            .call_scenario_script_function("RaiseLimitAndSpawn", Vec::new())
            .expect("SetMaxPlayer and CreateScriptPlayer execute in order");

        let globals = app.engine.snapshot().script_globals.named;
        assert_eq!(
            globals.get("set_result"),
            Some(&Value::Int(1)),
            "FnSetMaxPlayer has the C4ValueInt success result"
        );
        assert_eq!(app.engine.max_players(), Some(2));
        assert_eq!(
            app.engine.snapshot().players.len(),
            before,
            "CreateScriptPlayer remains deferred until app admission"
        );

        app.handle_script_player_info_updates()
            .expect("raised cap admits the queued script player");

        assert_eq!(
            app.network_max_players, 2,
            "the app admission cap follows Game.Parameters.MaxPlayers"
        );
        let admitted = app
            .control_player_infos
            .client_info_ids(0)
            .into_iter()
            .filter_map(|id| app.control_player_infos.get(id))
            .find(|info| info.name.as_bytes() == b"Admitted Bot")
            .expect("script PlayerInfo is admitted under the raised cap");
        assert!(
            app.engine
                .snapshot()
                .players
                .iter()
                .any(|player| player.player_info_id == admitted.id),
            "the admitted PlayerInfo reaches JoinPlayer"
        );
    }

    #[test]
    fn client_direct_cpp_sync_check_desync_continues_running_round_locally() {
        // An inactive C++ host sends CID_SyncCheck through
        // PID_ControlPkt/CDT_Direct, which HandleControlPkt executes at once
        // (src/C4GameControl.cpp:439-450;
        // src/C4GameControlNetwork.cpp:558-565). A mismatch clears C4Network2,
        // which invokes ChangeToLocal without aborting the round
        // (src/C4Control.cpp:469-519; src/C4Network2.cpp:746-789;
        // src/C4GameControl.cpp:93-127). Live frame-100 fixture:
        // ff 1a 00 00 00 42 02 85 64 00 32 00 6d 03 00 00 74 80 01 00
        // 00 00 00 00 98 01 99 01 56 02 00.
        let mut app = new_state_only_running_sandbox_app();
        let sound_dir = tempdir().expect("desync sound fixture directory");
        let sound_scenario = sound_dir.path().join("DesyncAudio.c4s");
        fs::create_dir_all(&sound_scenario).expect("create desync sound fixture");
        fs::write(
            sound_scenario.join("SyncError.wav"),
            silent_pcm_wav(100),
        )
        .expect("write SyncError fixture");
        let audio = app.audio.as_mut().expect("sandbox audio context");
        audio.options.sound_enabled = true;
        audio.configure_scenario(Some(&sound_scenario));
        assert!(app.snapshot.audio.is_empty());
        app.ui_sound_log.clear();
        let local_player = app.local_owner;
        let local_client = 1;
        let remote_player = 17;
        app.engine
            .player_mut(local_player)
            .expect("local runtime player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        app.engine
            .register_player(PlayerConfig::new(remote_player, "Host player"))
            .expect("register host runtime player");
        app.engine
            .player_mut(remote_player)
            .expect("host runtime player")
            .set_at_client(lc_engine::PlayerAtClient::HOST);
        app.engine.initialize_network_control_timing(
            lc_engine::NetworkControlTiming::new(37, 4).expect("valid network timing"),
        );
        app.snapshot = app.engine.snapshot();
        let (manager, event_tx, _commands) =
            NetworkManager::test_stub_with_commands_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.network_control_clock = Some(NetworkControlClock::new(37, 4));
        app.control_clients = ControlClientRegistry::default();
        app.control_clients.register(0, true, false);
        app.control_clients.register(local_client, true, false);
        let remote = SyncCheckPacket {
            frame: 100,
            control_tick: 50,
            random3: 0,
            random_count: 877,
            crew_positions_sum: 16_500,
            pxs_count: 0,
            mass_mover_index: 0,
            object_count: 152,
            object_enumeration_index: 153,
            sector_shape_sum: 342,
            by_client: 0,
        };
        let mut local = remote.clone();
        local.random_count -= 1;
        app.sync_checks.record_local(local);
        let frame_before = app.engine.frame();
        let control_tick_before = app.engine.sync_check(local_client).control_tick;
        event_tx
            .send(NetworkEvent::DirectControl(NetworkControl::SyncCheck(
                remote,
            )))
            .expect("queue direct C++ SyncCheck");

        app.process_network_events()
            .expect("execute direct C++ SyncCheck");

        assert!(matches!(app.mode, AppMode::Running));
        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert_eq!(app.engine.frame(), frame_before);
        assert_eq!(
            app.engine.sync_check(local_client).control_tick,
            control_tick_before
        );
        assert_eq!(app.engine.control_rate, 1);
        assert!(app.engine.player(local_player).is_some());
        assert!(app.engine.player(remote_player).is_none());
        assert_eq!(
            app.status_text,
            "Network desync detected; disconnected from host"
        );
        assert_eq!(
            app.engine.snapshot().round_results.network_result,
            Some(lc_engine::RoundResultsNetworkResult::NetworkError)
        );
        assert_eq!(
            app.engine
                .snapshot()
                .round_results
                .network_result_message
                .as_slice(),
            &b"Network: Synchronization loss!"[..]
        );
        assert_eq!(
            app.snapshot.round_results,
            app.engine.snapshot().round_results,
            "the presentation snapshot exposes the verdict immediately"
        );
        assert!(
            app.audio
                .as_ref()
                .expect("sandbox audio context remains")
                .loaded_sounds
                .keys()
                .any(|key| key.to_ascii_lowercase().contains("syncerror.wav")),
            "SyncError is eagerly decoded and played immediately"
        );
        assert_eq!(
            app.ui_sound_log
                .iter()
                .filter(|sound| sound.as_str() == "CloseViewport")
                .count(),
            0,
            "the normally removed remote host has no local physical viewport to close"
        );
        assert!(
            app.snapshot.audio.is_empty(),
            "the immediate UI cue is not replayed through engine audio"
        );
    }

    #[test]
    fn league_client_desync_reports_joined_local_players_before_change_to_local() {
        let mut app = new_state_only_running_sandbox_app();
        let local_client = 7;
        let local_info = 55;
        app.engine
            .player_mut(app.local_owner)
            .expect("local runtime player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        app.control_clients = ControlClientRegistry::default();
        app.control_clients.register(0, true, false);
        app.control_clients.register(local_client, true, false);
        app.control_player_infos.replace_snapshot(
            local_info,
            [lc_engine::PlayerInfoControlData {
                client_id: local_client,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: local_info,
                    flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                    ..Default::default()
                }],
                ..Default::default()
            }],
        );
        let (manager, events, commands) =
            NetworkManager::test_stub_with_league_commands_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.network_is_league = true;

        let local = app.engine.sync_check(local_client);
        let mut remote = local.clone();
        remote.random_count = remote.random_count.wrapping_add(1);
        remote.by_client = 0;
        app.sync_checks.record_local(local);
        events
            .send(NetworkEvent::DirectControl(NetworkControl::SyncCheck(
                remote,
            )))
            .expect("queue mismatching host sync check");
        let report = std::thread::spawn(move || commands.complete_league_disconnect_report());

        app.process_network_events()
            .expect("process league desync");

        let (reason, players) = report
            .join()
            .expect("join league report worker")
            .expect("desync report was sent before network clear");
        assert_eq!(reason, lc_network::LeagueDisconnectReason::Desync);
        assert_eq!(players.client_id, local_client);
        assert_eq!(players.players.len(), 1);
        assert_eq!(players.players[0].id, local_info);
        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert_eq!(
            app.snapshot.round_results.network_result,
            Some(lc_engine::RoundResultsNetworkResult::NetworkError)
        );
        assert_eq!(
            app.snapshot.round_results.network_result_message.as_slice(),
            &b"Network: Synchronization loss!"[..]
        );
    }

    #[test]
    fn host_ignores_remote_sync_check_without_desync_side_effects() {
        let mut app = new_state_only_running_sandbox_app();
        let (manager, events) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        let status_before = app.status_text.clone();
        let local = app.engine.sync_check(0);
        let mut remote = local.clone();
        remote.random_count = remote.random_count.wrapping_add(1);
        remote.by_client = 7;
        app.sync_checks.record_local(local);
        events
            .send(NetworkEvent::DirectControl(NetworkControl::SyncCheck(
                remote,
            )))
            .expect("queue client sync check");

        app.process_network_events()
            .expect("host ignores client sync check");

        assert!(app.network.is_some());
        assert!(matches!(app.network_mode, Some(NetworkMode::Host(_))));
        assert_eq!(app.status_text, status_before);
        assert!(app.engine.snapshot().round_results.network_result.is_none());
        assert!(app.snapshot.round_results.network_result.is_none());
        assert!(app.sync_checks.remote.is_empty());
    }

