    #[test]
    fn synchronized_custom_command_executes_only_while_game_is_running() {
        let mut app = new_state_only_running_sandbox_app();
        let command = NetworkControl::CustomCommand(lc_engine::CustomCommandControlData {
            command: lc_engine::LegacyCString::from_bytes(b"speed".to_vec())
                .expect("command is NUL-free"),
            argument: lc_engine::LegacyCString::from_bytes(b"100".to_vec())
                .expect("argument is NUL-free"),
            player: -1,
            by_client: 91,
        });
        let initial_delay = app.engine.game_tick_delay_ms();

        app.mode = AppMode::Loading;
        app.apply_ready_controls(11, vec![command.clone()])
            .expect("non-running custom command is rejected without aborting the tick");
        assert_eq!(app.engine.game_tick_delay_ms(), initial_delay);

        app.mode = AppMode::Running;
        app.apply_ready_controls(12, vec![command])
            .expect("running custom command executes at its ready tick");
        assert_eq!(app.engine.game_tick_delay_ms(), 10);

        app.engine.set_debug_mode(true);
        let disabled_speed = NetworkControl::CustomCommand(lc_engine::CustomCommandControlData {
            command: lc_engine::LegacyCString::from_bytes(b"speed".to_vec())
                .expect("command is NUL-free"),
            argument: lc_engine::LegacyCString::from_bytes(b"50".to_vec())
                .expect("argument is NUL-free"),
            player: -1,
            by_client: 91,
        });
        app.apply_ready_controls(
            13,
            vec![
                NetworkControl::Set(lc_network::LegacyControlSet {
                    value_type: 1,
                    data: 0,
                    by_client: 7,
                }),
                disabled_speed,
            ],
        )
        .expect("DisableDebug precedes the later custom command in the same batch");
        assert_eq!(
            app.engine.game_tick_delay_ms(),
            10,
            "DisableDebug removes /speed before the following packet executes"
        );
        assert_eq!(app.executing_ready_tick, None);
    }

    #[test]
    fn message_board_query_opens_on_tick35_and_routes_ui_answer_at_ready_tick() {
        let mut app = new_synthetic_running_sandbox_app();
        let player = app.local_owner;
        app.engine
            .player_mut(player)
            .expect("local player remains")
            .set_at_client(lc_engine::PlayerAtClient::HOST);
        app.engine
            .register_definition(
                Definition::from_script(
                    "MBUI",
                    "Message-board UI target",
                    r#"#strict 2
local callback_answer, callback_count;
public func Open(int player) { return CallMessageBoard(this(), true, "Exact prompt", player); }
protected func InputCallback(string answer, int player)
{
    callback_answer = answer;
    callback_count = callback_count + 1;
    return 1;
}
"#,
                )
                .expect("message-board target compiles"),
            )
            .expect("message-board target registers");
        let target = app
            .engine
            .spawn_object(SpawnConfig::new("MBUI"))
            .expect("message-board target spawns");
        let target_index = app
            .engine
            .find_object_index(target)
            .expect("message-board target is live");
        assert_eq!(
            app.engine
                .call_object_function(target_index, "Open", vec![Value::Int(player)])
                .expect("query opens"),
            Value::Bool(true)
        );

        let updates_to_tick35 = 35 - app.engine.frame() % 35;
        for update in 1..updates_to_tick35 {
            app.update().unwrap_or_else(|error| {
                panic!("pre-activation update {update} succeeds: {error}")
            });
            assert!(app.engine.active_message_board_input().is_none());
            assert!(app.running_chat_controller().is_none());
        }
        app.update().expect("Tick35 update activates query");
        assert_eq!(app.engine.frame() % 35, 0);
        assert_eq!(
            app.engine
                .active_message_board_input()
                .expect("engine query activates")
                .prompt,
            "Exact prompt"
        );
        let controller = app
            .running_chat_controller()
            .expect("the same Tick35 update opens the input dialog");
        assert_eq!(controller.message(), "Exact prompt");
        assert_eq!(controller.text(), "");

        let (manager, _events, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(0);
        app.network = Some(manager);
        for character in "mixed".chars() {
            app.handle_text_input(character)
                .expect("type message-board answer");
        }
        let submission_tick = app.local_control_submission_tick();
        app.handle_key(VirtualKeyCode::Return, ElementState::Pressed)
            .expect("submit message-board answer");
        assert!(app.running_chat_controller().is_none());
        assert!(app.engine.active_message_board_input().is_none());
        let target_before_ready = app
            .engine
            .object_snapshot(target)
            .expect("target remains live before the ready tick");
        assert_ne!(
            target_before_ready.local_vars.get("callback_count"),
            Some(&Value::Int(1)),
            "submission closes the local UI without running the callback"
        );
        let mut submitted = commands.take_submitted_message_board_answers();
        assert_eq!(submitted.len(), 1);
        let (queued_tick, answer) = submitted
            .pop()
            .expect("network worker receives the UI answer");
        assert_eq!(queued_tick, submission_tick);
        assert_eq!(answer.answer.as_bytes(), b"MIXED");
        assert_eq!(answer.by_client, 0);

        app.apply_ready_controls(
            queued_tick,
            vec![NetworkControl::MessageBoardAnswer(answer)],
        )
        .expect("message-board answer executes at its ready tick");
        let target_after_ready = app
            .engine
            .object_snapshot(target)
            .expect("target remains live after the ready tick");
        assert_eq!(
            target_after_ready.local_vars.get("callback_answer"),
            Some(&Value::String("MIXED".to_string().into()))
        );
        assert_eq!(
            target_after_ready.local_vars.get("callback_count"),
            Some(&Value::Int(1))
        );

        app.network = None;
        assert_eq!(
            app.engine
                .call_object_function(target_index, "Open", vec![Value::Int(player)])
                .expect("second query opens"),
            Value::Bool(true)
        );
        let updates_to_tick35 = 35 - app.engine.frame() % 35;
        for _ in 0..updates_to_tick35 {
            app.update().expect("second query reaches Tick35");
        }
        assert!(app.running_chat_controller().is_some());
        let (manager, _events, mut commands) =
            NetworkManager::test_stub_with_commands_for_client_id(0);
        app.network = Some(manager);
        let cancel_tick = app.local_control_submission_tick();
        app.handle_key(VirtualKeyCode::F2, ElementState::Pressed)
            .expect("F2 cancels the script query");
        let mut submitted = commands.take_submitted_message_board_answers();
        assert_eq!(submitted.len(), 1);
        let (queued_tick, answer) = submitted.pop().expect("F2 queues an empty answer");
        assert_eq!(queued_tick, cancel_tick);
        assert!(answer.answer.is_empty());
        app.apply_ready_controls(
            queued_tick,
            vec![NetworkControl::MessageBoardAnswer(answer)],
        )
        .expect("empty answer removes the query at its ready tick");
        assert!(app.running_chat_controller().is_none());
        assert!(app.engine.active_message_board_input().is_none());
        assert!(
            app.engine
                .player(player)
                .expect("local player remains after cancellation")
                .message_board_queries()
                .is_empty()
        );
        let target_after_cancel = app
            .engine
            .object_snapshot(target)
            .expect("target remains live after cancellation");
        assert_eq!(
            target_after_cancel.local_vars.get("callback_count"),
            Some(&Value::Int(1)),
            "an empty answer removes the query without invoking InputCallback"
        );
    }

    #[test]
    fn goal_rule_activation_on_unresolved_definition_returns_typed_boundary() {
        let mut app = new_running_sandbox_app();
        let player = app.local_owner;

        for (action, child) in [
            (
                MenuAction::GoalInfo("MISS".to_string()),
                ClassicIngameMenuChild::GoalInfo("MISS".to_string()),
            ),
            (
                MenuAction::RuleInfo("MISS".to_string()),
                ClassicIngameMenuChild::RuleInfo("MISS".to_string()),
            ),
        ] {
            let error = app
                .apply_ingame_menu_action_for_player(player, action)
                .expect_err("an unresolved goal/rule must reach its typed menu boundary");
            let EngineError::ClassicMenuParityBoundary { detail } = error else {
                panic!("unexpected unresolved goal/rule error: {error:?}");
            };
            assert_eq!(
                detail,
                format!(
                    "classic in-game menu child {child:?} is not implemented; refusing status/no-op substitute"
                )
            );
        }
    }

    #[test]
    fn cache_definition_icons_distinguishes_blank_from_malformed_picture() {
        let mut app = new_running_sandbox_app();
        let mut blank = Definition::from_script("BLNK", "Blank rule", "#strict 3\n")
            .expect("blank definition compiles");
        blank.set_category(C4D_RULE);
        app.engine
            .register_definition(blank)
            .expect("blank definition registers");
        let blank_entry = GoalRuleEntry {
            definition_id: "BLNK".to_string(),
            name: "Blank rule".to_string(),
            description: None,
            fulfilled: false,
        };
        app.cache_definition_icons(std::slice::from_ref(&blank_entry))
            .expect("a loaded definition with a blank facet is valid");
        assert!(
            !app
                .ingame_menu_gfx
                .as_ref()
                .expect("blank cache initializes menu graphics")
                .definition_icons
                .contains_key("BLNK")
        );

        let temp = tempdir().expect("tempdir");
        let valid_dir = temp.path().join("Valid.c4d");
        fs::create_dir(&valid_dir).expect("valid definition directory");
        fs::write(
            valid_dir.join("DefCore.txt"),
            b"[DefCore]\nid=PCTR\nPicture=0,0,1,1\n",
        )
        .expect("valid DefCore");
        image::RgbaImage::from_pixel(1, 1, image::Rgba([10, 20, 30, 255]))
            .save(valid_dir.join("Graphics.png"))
            .expect("valid preferred graphics");
        let valid_resource = ResourceDefinitionData::load(
            &Group::open(&valid_dir).expect("open valid definition"),
        )
        .expect("valid definition resource loads");
        let mut valid = Definition::from_resource(&valid_resource)
            .expect("valid definition converts to engine data");
        valid.set_category(C4D_RULE);
        app.engine
            .register_definition(valid)
            .expect("valid definition registers");
        assert!(app
            .engine
            .try_definition_picture_image("PCTR")
            .expect("valid definition resolves")
            .is_some());
        let valid_entry = GoalRuleEntry {
            definition_id: "PCTR".to_string(),
            name: "Pictured rule".to_string(),
            description: None,
            fulfilled: false,
        };

        let malformed_dir = temp.path().join("Malformed.c4d");
        fs::create_dir(&malformed_dir).expect("malformed definition directory");
        fs::write(
            malformed_dir.join("DefCore.txt"),
            b"[DefCore]\nid=BADG\nWidth=1\nHeight=1\n",
        )
        .expect("malformed DefCore");
        fs::write(malformed_dir.join("Graphics.png"), b"not a png")
            .expect("malformed preferred graphics");
        image::RgbaImage::from_pixel(1, 1, image::Rgba([10, 20, 30, 255]))
            .save(malformed_dir.join("Graphics.bmp"))
            .expect("valid losing BMP");
        let malformed_group = Group::open(&malformed_dir).expect("open malformed definition");
        assert!(matches!(
            ResourceDefinitionData::load(&malformed_group),
            Err(ResourceDefinitionError::Graphics { path, reason })
                if path == Path::new("Graphics.png") && !reason.is_empty()
        ));

        let malformed_entry = GoalRuleEntry {
            definition_id: "BADG".to_string(),
            name: "Malformed rule".to_string(),
            description: None,
            fulfilled: false,
        };
        let error = app
            .cache_definition_icons(&[valid_entry, blank_entry, malformed_entry])
            .expect_err("a rejected graphics definition must not become a blank menu symbol");
        let EngineError::ClassicMenuParityBoundary { detail } = error else {
            panic!("unexpected malformed definition error: {error:?}");
        };
        assert_eq!(
            detail,
            "classic in-game goal/rule symbol definition `BADG` is unavailable: unknown definition `BADG`; refusing a blank symbol substitute"
        );
        assert!(
            app.ingame_menu_gfx
                .as_ref()
                .expect("menu graphics remain allocated")
                .definition_icons
                .is_empty(),
            "validation must complete before mutating the icon cache"
        );
    }

