    #[test]
    fn network_host_without_control_host_still_runs_client_part_updates() {
        // OnClientPart's attribute/gain/send guard is network-host ownership;
        // only the nested random-team recheck requires control-host status
        // (src/C4Network2Players.cpp:449-459; src/C4Teams.cpp:688-692).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.engine.set_control_host(false);
        app.control_clients.register(3, true, false);
        app.control_player_infos.replace_snapshot(
            40,
            [
                lc_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![set_control_test_player(30, 0, 0)],
                    ..Default::default()
                },
                lc_engine::PlayerInfoControlData {
                    client_id: 4,
                    players: vec![lc_engine::ControlPlayerInfoEntry {
                        id: 40,
                        flags: lc_engine::PLAYER_INFO_FLAG_JOINED
                            | lc_engine::PLAYER_INFO_FLAG_REMOVED,
                        league_projected_gain: 5,
                        ..Default::default()
                    }],
                    ..Default::default()
                },
            ],
        );

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientRemove(
                lc_engine::ClientRemoveControlData {
                    client_id: 3,
                    reason: lc_engine::LegacyCString::default(),
                    by_client: 0,
                },
            )],
        )
        .expect("execute non-control-host client removal");

        assert_eq!(
            app.control_player_infos
                .get(40)
                .unwrap()
                .league_projected_gain,
            -1,
        );
        let broadcasts = commands.take_broadcast_player_infos();
        let [update] = broadcasts.as_slice() else {
            panic!("expected one gain-reset packet, got {broadcasts:?}");
        };
        assert_eq!(update.client_id, 4);
        assert_eq!(update.players[0].league_projected_gain, -1);
    }

    #[test]
    fn synchronized_client_remove_rebalances_random_teams_and_broadcasts_changed_packet() {
        // OnClientPart first drops the departing client's unjoined infos and
        // rechecks memberships. The host then redistributes the first
        // relocatable member from the resulting 3/0 split and sends its
        // owner's updated packet (src/C4Network2Players.cpp:425-459;
        // src/C4Teams.cpp:688-730).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(host_network_settings()));
        app.control_clients.register(4, true, false);

        let mut metadata = set_control_test_metadata(
            false,
            vec![
                set_control_test_team(1, vec![10, 20, 30], 0),
                set_control_test_team(2, vec![40], 0),
            ],
        );
        metadata.team_distribution = lc_engine::InitialNetworkTeamDistribution::Random;
        app.engine
            .set_teams(runtime_teams_from_initial_metadata(&metadata));
        app.network_team_assignment = Some(NetworkTeamAssignmentState::from_prepared_host(
            metadata,
        ));
        let player = |id, team, color, original_color, projected_gain, name: &[u8], forced: &[u8]| {
            let mut player = set_control_test_player(id, team, 0);
            player.color = color;
            player.original_color = original_color;
            player.league_projected_gain = projected_gain;
            player.name = lc_engine::LegacyCString::from_bytes(name.to_vec()).unwrap();
            player.forced_name = lc_engine::LegacyCString::from_bytes(forced.to_vec()).unwrap();
            player
        };
        let mut gain_only = player(50, 0, 0x0000_00f4, 0x0000_00f4, 4, b"History", b"");
        gain_only.flags =
            lc_engine::PLAYER_INFO_FLAG_JOINED | lc_engine::PLAYER_INFO_FLAG_REMOVED;
        app.control_player_infos.replace_snapshot(
            50,
            [
                lc_engine::PlayerInfoControlData {
                    client_id: 3,
                    players: vec![
                        player(
                            10,
                            1,
                            0x0000_f400,
                            0x00f4_0000,
                            6,
                            b"Alice",
                            b"Alice (2)",
                        ),
                        player(20, 1, 0x0000_00f4, 0x0000_00f4, -1, b"Bob", b""),
                        player(30, 1, 0x00f4_f400, 0x00f4_f400, 0, b"Cara", b""),
                    ],
                    ..Default::default()
                },
                lc_engine::PlayerInfoControlData {
                    client_id: 4,
                    players: vec![player(
                        40,
                        2,
                        0x00f4_0000,
                        0x00f4_0000,
                        9,
                        b"Alice",
                        b"",
                    )],
                    ..Default::default()
                },
                lc_engine::PlayerInfoControlData {
                    client_id: 5,
                    players: vec![gain_only],
                    ..Default::default()
                },
            ],
        );

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientRemove(
                lc_engine::ClientRemoveControlData {
                    client_id: 4,
                    reason: lc_engine::LegacyCString::default(),
                    by_client: 0,
                },
            )],
        )
        .expect("execute synchronized client removal");

        assert!(!app.control_clients.contains(4));
        assert!(app.control_player_infos.get(40).is_none());
        let teams = app
            .network_team_assignment
            .as_ref()
            .expect("host team assignment remains installed")
            .teams();
        assert_eq!(teams.teams[0].player_ids, vec![20, 30]);
        assert_eq!(teams.teams[1].player_ids, vec![10]);
        assert_eq!(app.control_player_infos.get(10).unwrap().team, 2);
        assert_eq!(app.control_player_infos.get(10).unwrap().color, 0x00f4_0000);
        assert!(app
            .control_player_infos
            .get(10)
            .unwrap()
            .forced_name
            .is_empty());
        assert_eq!(
            app.control_player_infos
                .client_packet(3)
                .unwrap()
                .players
                .iter()
                .map(|player| player.league_projected_gain)
                .collect::<Vec<_>>(),
            vec![-1, -1, -1],
        );

        let broadcasts = commands.take_broadcast_player_infos();
        let [updated, gain_only] = broadcasts.as_slice() else {
            panic!("expected two final PlayerInfo packets, got {broadcasts:?}");
        };
        assert_eq!((updated.client_id, updated.by_client), (3, 0));
        assert_eq!(
            updated.flags
                & (lc_engine::CLIENT_PLAYER_INFO_FLAG_ADD_PLAYERS
                    | lc_engine::CLIENT_PLAYER_INFO_FLAG_UPDATED),
            0,
        );
        assert_eq!(
            updated
                .players
                .iter()
                .map(|player| {
                    (
                        player.id,
                        player.team,
                        player.color,
                        player.forced_name.as_bytes().to_vec(),
                        player.league_projected_gain,
                    )
                })
                .collect::<Vec<_>>(),
            vec![
                (10, 2, 0x00f4_0000, Vec::new(), -1),
                (20, 1, 0x0000_00f4, Vec::new(), -1),
                (30, 1, 0x00f4_f400, Vec::new(), -1),
            ],
        );
        assert_eq!((gain_only.client_id, gain_only.by_client), (5, 0));
        assert_eq!(gain_only.flags & lc_engine::CLIENT_PLAYER_INFO_FLAG_UPDATED, 0);
        assert_eq!(gain_only.players.len(), 1);
        assert_eq!(gain_only.players[0].id, 50);
        assert_eq!(gain_only.players[0].league_projected_gain, -1);
    }

    #[test]
    fn client_host_socket_loss_continues_the_running_round_locally() {
        // When a client's only host connection is gone, OnClientDisconnect
        // clears C4Network2 and thereby executes C4GameControl::ChangeToLocal;
        // it does not abort or return to startup (pristine 9ffa0a5d
        // src/C4Network2.cpp:1758-1765,1786-1817;
        // src/C4GameControl.cpp:93-127).
        let mut app = new_running_sandbox_app();
        let local_player = app.local_owner;
        let local_client = 7;
        let remote_player = 17;
        let remote_info = 73;
        app.engine
            .player_mut(local_player)
            .expect("local runtime player")
            .set_at_client(lc_engine::PlayerAtClient::new(local_client));
        app.engine
            .register_player(
                PlayerConfig::new(remote_player, "Host player").with_player_info_id(remote_info),
            )
            .expect("register host runtime player");
        app.engine
            .player_mut(remote_player)
            .expect("host runtime player")
            .set_at_client(lc_engine::PlayerAtClient::HOST);
        app.engine.set_network_game(true);
        app.engine.initialize_network_control_timing(
            lc_engine::NetworkControlTiming::new(31, 4).expect("valid network timing"),
        );
        app.snapshot = app.engine.snapshot();

        let (manager, event_tx) = NetworkManager::test_stub_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.network_control_clock = Some(NetworkControlClock::new(31, 4));
        app.network_max_players = 9;
        app.network_is_league = true;
        app.control_clients = ControlClientRegistry::default();
        app.control_clients.register(0, true, false);
        app.control_clients.register(local_client, true, false);
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 0,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: remote_info,
                    flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                    ..Default::default()
                }],
                ..Default::default()
            });
        app.apply_ingame_menu_action(MenuAction::ActivateOptions)
            .expect("open options menu");
        let frame_before = app.engine.frame();
        let control_tick_before = app.engine.sync_check(local_client).control_tick;

        event_tx
            .send(NetworkEvent::PeerDisconnected {
                client_id: 0,
                reason: Some("connection lost".to_string()),
            })
            .expect("queue host socket loss");
        app.process_network_events().expect("process host loss");

        assert!(matches!(app.mode, AppMode::Running));
        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert_eq!(app.engine.frame(), frame_before);
        assert_eq!(
            app.engine.sync_check(local_client).control_tick,
            control_tick_before
        );
        assert_eq!(app.engine.control_rate, 1);
        assert_eq!(app.network_max_players, 9);
        assert!(app.network_is_league);
        assert!(app.engine.player(local_player).is_some());
        assert!(app.engine.player(remote_player).is_none());
        assert_eq!(
            app.ingame_menu.as_ref().map(IngameMenuState::page),
            Some(ingame_menu::MenuPage::Options)
        );
    }

    #[test]
    fn client_non_host_peer_loss_keeps_the_network_session() {
        // OnClientDisconnect clears a client's network only when the lost
        // C4Network2Client is the host. Another peer's eventual synchronized
        // removal remains host-owned (pristine 9ffa0a5d
        // src/C4Network2.cpp:1786-1817).
        let mut app = new_state_only_running_sandbox_app();
        let local_client = 7;
        let peer_client = 9;
        let peer_player = 17;
        app.engine
            .register_player(PlayerConfig::new(peer_player, "Peer"))
            .expect("register peer runtime player");
        app.engine
            .player_mut(peer_player)
            .expect("peer runtime player")
            .set_at_client(lc_engine::PlayerAtClient::new(peer_client));
        app.snapshot = app.engine.snapshot();
        let (manager, event_tx) = NetworkManager::test_stub_for_client_id(local_client as u32);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11_112)),
            "Client",
        )));
        app.control_clients.register(0, true, false);
        app.control_clients.register(local_client, true, false);
        app.control_clients.register(peer_client, true, false);

        event_tx
            .send(NetworkEvent::PeerDisconnected {
                client_id: peer_client as u32,
                reason: Some("peer transport lost".to_string()),
            })
            .expect("queue peer loss");
        app.process_network_events().expect("process peer loss");

        assert!(app.network.is_some());
        assert!(matches!(app.network_mode, Some(NetworkMode::Client(_))));
        assert!(matches!(app.mode, AppMode::Running));
        assert!(app.engine.player(peer_player).is_some());
    }

    #[test]
    fn observer_soft_kicks_players_but_plain_deactivation_does_not() {
        // CUT_Activate(false) preserves existing players. CUT_SetObserver is
        // the soft-kick path: deactivate, keep the client, remove its runtime
        // players, and mark history joined, removed, and disconnected
        // (src/C4Control.cpp:588-620; src/C4PlayerList.cpp:219-239).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.control_clients.register(3, true, false);
        app.engine
            .register_player(PlayerConfig::new(17, "Remote").with_player_info_id(7))
            .expect("register remote runtime player");
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 7,
                    flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                    ..Default::default()
                }],
                ..Default::default()
            });

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientUpdate(
                lc_engine::ClientUpdateControlData {
                    update_type: lc_engine::CLIENT_UPDATE_ACTIVATE,
                    client_id: 3,
                    data: 0,
                    by_client: 0,
                },
            )],
        )
        .expect("execute deactivation");
        assert!(app
            .engine
            .snapshot()
            .players
            .iter()
            .any(|player| player.player_info_id == 7));

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientUpdate(
                lc_engine::ClientUpdateControlData {
                    update_type: lc_engine::CLIENT_UPDATE_SET_OBSERVER,
                    client_id: 3,
                    data: 0,
                    by_client: 0,
                },
            )],
        )
        .expect("execute observer soft kick");

        assert!(app.control_clients.contains(3));
        assert!(app.control_clients.is_observer(3));
        assert!(!app.control_clients.is_activated(3));
        assert!(app
            .engine
            .snapshot()
            .players
            .iter()
            .all(|player| player.player_info_id != 7));
        let retained = app.control_player_infos.get(7).expect("history remains");
        let expected_flags = lc_engine::PLAYER_INFO_FLAG_JOINED
            | lc_engine::PLAYER_INFO_FLAG_REMOVED
            | lc_engine::PLAYER_INFO_FLAG_DISCONNECTED;
        assert_eq!(retained.flags & expected_flags, expected_flags);
    }

    #[test]
    fn observer_soft_kick_releases_local_control_assignment_for_reuse() {
        // C4PlayerList::GetLocalByKbdSet and MouseControlTaken scan only the
        // live player list. CUT_SetObserver removes the client's players, so a
        // removed local player immediately stops owning its keyboard/mouse set
        // while unrelated assignments remain intact (pristine 9ffa0a5d
        // src/C4Control.cpp:607-619; src/C4PlayerList.cpp:122-128,156-162,
        // 219-268,466-477,556-562).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx) = NetworkManager::test_stub_for_client_id(3);
        app.network = Some(manager);
        app.control_clients.register(3, true, false);
        app.engine
            .register_player(PlayerConfig::new(17, "Local").with_player_info_id(7))
            .expect("register locally controlled runtime player");
        app.engine
            .register_player(PlayerConfig::new(18, "Remote").with_player_info_id(8))
            .expect("register unassigned runtime player");
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![
                    lc_engine::ControlPlayerInfoEntry {
                        id: 7,
                        flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                        ..Default::default()
                    },
                    lc_engine::ControlPlayerInfoEntry {
                        id: 8,
                        flags: lc_engine::PLAYER_INFO_FLAG_JOINED,
                        ..Default::default()
                    },
                ],
                ..Default::default()
            });
        app.local_controls = LocalControlRegistry::default();
        let removed = app.local_controls.initialize(LocalControlInit {
            owner: 17,
            preferred_set: 2,
            prefers_mouse: true,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
        let retained = app.local_controls.initialize(LocalControlInit {
            owner: 99,
            preferred_set: 3,
            prefers_mouse: false,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
        assert_eq!((removed.set, removed.mouse), (2, true));
        assert_eq!((retained.set, retained.mouse), (3, false));

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientUpdate(
                lc_engine::ClientUpdateControlData {
                    update_type: lc_engine::CLIENT_UPDATE_SET_OBSERVER,
                    client_id: 3,
                    data: 0,
                    by_client: 0,
                },
            )],
        )
        .expect("execute observer soft kick");

        assert_eq!(app.local_controls.owner_for_set(2), None);
        assert_eq!(app.local_controls.owner_for_set(3), Some(99));
        assert_eq!(app.local_controls.mouse_owner(), None);
        let replacement = app.local_controls.initialize(LocalControlInit {
            owner: 20,
            preferred_set: 2,
            prefers_mouse: true,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
        assert_eq!((replacement.set, replacement.mouse), (2, true));
    }

    #[test]
    fn removing_local_network_client_changes_to_local_control() {
        // C4ControlClientRemove never deletes the local client. It invokes
        // C4GameControl::ChangeToLocal, which clears networking, removes
        // remote client records, and activates the local client
        // (src/C4Control.cpp:651-660; src/C4GameControl.cpp:94-128).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx) = NetworkManager::test_stub_for_client_id(3);
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Client(ClientSettings::new(
            SocketAddr::from(([127, 0, 0, 1], 11112)),
            "Client",
        )));
        app.control_clients = ControlClientRegistry::default();
        app.control_clients.register(0, true, false);
        app.control_clients.register(3, false, false);

        app.apply_ready_controls(
            0,
            vec![NetworkControl::ClientRemove(
                lc_engine::ClientRemoveControlData {
                    client_id: 3,
                    reason: lc_engine::LegacyCString::from_bytes(b"Removed".to_vec())
                        .expect("valid reason"),
                    by_client: 0,
                },
            )],
        )
        .expect("execute local client removal");

        assert!(app.network.is_none());
        assert!(app.network_mode.is_none());
        assert!(app.network_lobby.is_none());
        assert!(app.control_clients.contains(3));
        assert!(app.control_clients.is_activated(3));
        assert!(!app.control_clients.contains(0));
    }

    #[test]
    fn final_go_applies_lifecycle_sync_before_active_client_sweep() {
        // CheckStatusAck executes pending sync controls before
        // OnStatusGoReached scans every active client, then starts control.
        // PID_ExecSyncCtrl tick 3 must remain valid when ControlRate 2 has
        // already advanced FrameCounter to 6 (src/C4Network2.cpp:2062-2110;
        // src/C4Network2Players.cpp:465-482).
        let directory = tempdir().expect("record directory");
        let mut app = new_state_only_running_sandbox_app();
        install_test_recording_template(
            &mut app,
            directory.path().join("001-FinalGoSync.c4s"),
        );
        app.network_control_clock = Some(NetworkControlClock::new(3, 2));
        app.engine.initialize_network_control_timing(
            lc_engine::NetworkControlTiming::new(0, 2).expect("valid network timing"),
        );
        for _ in 0..6 {
            app.engine.tick().expect("advance to frame 6");
        }
        assert_eq!(app.engine.frame(), 6);
        assert_eq!(app.expected_network_control_tick(), 3);
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_mode = Some(NetworkMode::Host(HostSettings {
            bind_addr: SocketAddr::from(([127, 0, 0, 1], 0)),
            player_name: "Host".to_string(),
            prepared: None,
        }));
        app.network_control_running = false;
        app.control_clients.register(3, false, false);
        app.control_clients.register(4, true, false);
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 3,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 31,
                    player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                    ..Default::default()
                }],
                ..Default::default()
            });
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 4,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    id: 41,
                    player_type: lc_engine::PLAYER_INFO_TYPE_SCRIPT,
                    ..Default::default()
                }],
                ..Default::default()
            });

        event_tx
            .send(NetworkEvent::ScheduledSync {
                tick: 3,
                controls: vec![
                    NetworkControl::Synchronize(lc_engine::SynchronizeControlData {
                        save_player_files: false,
                        sync_clearance: true,
                        by_client: 0,
                    }),
                    NetworkControl::ClientUpdate(lc_engine::ClientUpdateControlData {
                        update_type: lc_engine::CLIENT_UPDATE_ACTIVATE,
                        client_id: 3,
                        data: 1,
                        by_client: 0,
                    }),
                    NetworkControl::ClientRemove(lc_engine::ClientRemoveControlData {
                        client_id: 4,
                        reason: lc_engine::LegacyCString::default(),
                        by_client: 0,
                    }),
                ],
            })
            .expect("queue released lifecycle controls");
        event_tx
            .send(NetworkEvent::StatusCommitted(lc_network::NetworkStatus {
                state: lc_network::NETWORK_STATE_GO,
                control_mode: 1,
                target_tick: 3,
            }))
            .expect("queue final Go commit");

        app.process_network_events().expect("commit final Go");

        assert!(app.control_clients.is_activated(3));
        assert!(!app.control_clients.contains(4));
        assert!(app.control_player_infos.get(41).is_none());
        let joins = commands.take_submitted_join_players();
        assert_eq!(joins.len(), 1);
        assert_eq!(joins[0].0, 3);
        assert_eq!((joins[0].1.at_client, joins[0].1.info_id), (3, 31));
        assert!(app.network_control_running);
        assert!(app.recording.is_none());
        assert!(app.recording_template.is_some());
    }

    #[test]
    fn completed_network_resource_enters_the_control_resource_registry() {
        // C4Network2Res::EndLoad calls OnResComplete; later synchronized
        // controls resolve the resource strictly by ID and use getFile()
        // (src/C4Network2Res.cpp:1113-1122,1701-1707;
        // src/C4Control.cpp:758-764).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let resource_id = 61;
        let path = PathBuf::from(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../lc-engine/tests/fixtures/embedded_player.c4p"
        ));
        let core = lc_engine::NetworkResourceCore {
            resource_type: 3,
            id: resource_id,
            loadable: true,
            filename: lc_engine::LegacyCString::from_bytes(b"Player.c4p".to_vec()).unwrap(),
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id,
                core,
                path: path.clone(),
                local: false,
            })
            .unwrap();

        app.process_network_events().unwrap();

        assert_eq!(
            app.admission_resources.complete_path(resource_id),
            Some(path.as_path())
        );
    }

    #[test]
    fn queued_derive_completion_keeps_the_registered_mutable_player_source() {
        // FinishDerive returns on the main thread before its forwarded
        // ResourceComplete event is drained. That later event describes the
        // serving standalone, while C4Network2Res::getFile still resolves the
        // mutable player file used by the next Save
        // (src/C4Player.cpp:452-461; src/C4Network2Res.cpp:718-823).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let mutable_path = PathBuf::from("Network/Bob.c4p");
        let serving_path = PathBuf::from("Network/Bob_2.c4p");
        let core = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: 62,
            derived_id: 61,
            loadable: true,
            ..Default::default()
        };
        app.admission_resources.register_finished_derivation(
            &core,
            mutable_path.clone(),
            lc_network::ResourceFileOwnership::Temporary,
        );
        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id: core.id,
                core: core.clone(),
                path: serving_path,
                local: true,
            })
            .expect("queue forwarded derive completion");

        app.process_network_events()
            .expect("apply forwarded derive completion");

        assert_eq!(
            app.admission_resources.status(core.id),
            Some(&AdmissionResourceState::Complete {
                path: mutable_path,
                removed: false,
                local: false,
            })
        );
    }

    #[test]
    fn unknown_loadable_resource_join_stalls_until_resource_completion() {
        let mut app = new_synthetic_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        let info_id = 18;
        let resource_id = 62;
        let path = PathBuf::from(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../lc-engine/tests/fixtures/embedded_player.c4p"
        ));
        let core = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: resource_id,
            loadable: true,
            filename: lc_engine::LegacyCString::from_bytes(b"Player.c4p".to_vec()).unwrap(),
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: 1,
                        players: vec![lc_engine::ControlPlayerInfoEntry {
                            id: info_id,
                            name: lc_engine::LegacyCString::from_bytes(
                                b"Delayed resource".to_vec(),
                            )
                            .unwrap(),
                            flags: lc_engine::PLAYER_INFO_FLAG_HAS_RESOURCE,
                            resource: Some(core.clone()),
                            ..Default::default()
                        }],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(lc_engine::JoinPlayerControlData {
                        at_client: 0,
                        info_id,
                        source: lc_engine::JoinPlayerSource::Resource(core.clone()),
                        by_client: 1,
                        ..Default::default()
                    }),
                ],
            })
            .expect("queue resource-backed join before completion");

        app.update().expect("pending resource stalls the control tick");

        assert_eq!(app.engine.frame(), initial_frame);
        assert!(app.network_ticks.ready.contains_key(&tick));
        assert!(app.control_player_infos.get(info_id).is_none());
        assert_eq!(
            app.admission_resources.status(resource_id),
            Some(&AdmissionResourceState::Loading { removed: false })
        );
        let wait = app
            .blocking_resource_wait
            .as_ref()
            .expect("resource-backed JoinPlayer opens the progress wait");
        assert_eq!(wait.scope, BlockingResourceScope::PlayerJoin);
        assert_eq!(wait.resource_id, resource_id);
        assert_eq!(wait.display_name, "player file for Delayed resource");
        let progress = app
            .message_dialogs
            .iter()
            .find(|dialog| {
                matches!(
                    dialog.continuation,
                    MessageDialogContinuation::BlockingResourceWait {
                        scope: BlockingResourceScope::PlayerJoin,
                        resource_id: 62,
                    }
                )
            })
            .expect("player resource progress dialog");
        assert_eq!(progress.state.progress(), Some(0));
        assert_eq!(progress.state.message(), "Waiting for player file for Delayed resource...");

        event_tx
            .send(NetworkEvent::ResourceProgress {
                resource_id,
                present_percent: 47,
            })
            .expect("advance delayed player resource");
        app.update().expect("updated progress still stalls the control tick");
        assert_eq!(app.engine.frame(), initial_frame);
        assert_eq!(
            app.blocking_resource_wait
                .as_ref()
                .expect("wait remains active")
                .present_percent(),
            47
        );
        assert_eq!(
            app.message_dialogs
                .iter()
                .find(|dialog| matches!(
                    dialog.continuation,
                    MessageDialogContinuation::BlockingResourceWait { .. }
                ))
                .and_then(|dialog| dialog.state.progress()),
            Some(47)
        );

        event_tx
            .send(NetworkEvent::ResourceComplete {
                resource_id,
                core,
                path: path.clone(),
                local: false,
            })
            .expect("complete delayed player resource");
        app.update().expect("completed resource releases control tick");

        assert_eq!(app.engine.frame(), initial_frame + 1);
        assert!(!app.network_ticks.ready.contains_key(&tick));
        assert_eq!(
            app.admission_resources.complete_path(resource_id),
            Some(path.as_path())
        );
        assert!(app
            .snapshot
            .players
            .iter()
            .any(|player| player.player_info_id == info_id));
        assert!(app.blocking_resource_wait.is_none());
        assert!(!app.message_dialogs.iter().any(|dialog| matches!(
            dialog.continuation,
            MessageDialogContinuation::BlockingResourceWait { .. }
        )));
    }

    #[test]
    fn failed_loadable_resource_releases_the_stalled_tick_as_a_noop() {
        let mut app = new_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        let resource_id = 63;
        let core = lc_engine::NetworkResourceCore {
            resource_type: lc_network::HostResourceType::Player as u8,
            id: resource_id,
            loadable: true,
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![NetworkControl::JoinPlayer(
                    lc_engine::JoinPlayerControlData {
                        at_client: 0,
                        info_id: 99,
                        source: lc_engine::JoinPlayerSource::Resource(core),
                        by_client: 1,
                        ..Default::default()
                    },
                )],
            })
            .expect("queue resource-backed join before failure");

        app.update().expect("pending resource stalls the control tick");
        assert_eq!(app.engine.frame(), initial_frame);
        assert_eq!(
            app.admission_resources.status(resource_id),
            Some(&AdmissionResourceState::Loading { removed: false })
        );

        event_tx
            .send(NetworkEvent::ResourceLoadFailed { resource_id })
            .expect("fail delayed player resource");
        app.update().expect("failed resource releases control tick");

        assert_eq!(app.engine.frame(), initial_frame + 1);
        assert_eq!(
            app.admission_resources.status(resource_id),
            Some(&AdmissionResourceState::Unavailable(
                AdmissionResourceUnavailable::TransferFailed
            ))
        );
    }

    #[test]
    fn unloadable_resource_join_is_unavailable_and_does_not_stall_tick() {
        // AddByCore returns null for an unloadable absent resource; PreExecute
        // therefore reports ready and JoinPlr later no-ops, without blocking
        // following controls (src/C4Network2Res.cpp:1499-1515;
        // src/C4Control.cpp:73-109,758-764,811-825).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        let info_id = 17;
        let resource_id = 61;
        let local_owner = app.local_owner;
        let resource = lc_engine::NetworkResourceCore {
            resource_type: 3,
            id: resource_id,
            loadable: false,
            filename: lc_engine::LegacyCString::from_bytes(b"Missing.c4p".to_vec())
                .expect("valid resource filename"),
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: 1,
                        players: vec![lc_engine::ControlPlayerInfoEntry {
                            id: info_id,
                            ..Default::default()
                        }],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(lc_engine::JoinPlayerControlData {
                        at_client: 0,
                        info_id,
                        source: lc_engine::JoinPlayerSource::Resource(resource),
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::Player {
                        owner: local_owner,
                        event: ControlEvent::Press(ControlButton::Right),
                    },
                ],
            })
            .expect("queue unloadable resource join");

        app.update().expect("execute nonblocking resource tick");

        assert_eq!(
            app.admission_resources.status(resource_id),
            Some(&AdmissionResourceState::Unavailable(
                AdmissionResourceUnavailable::Unloadable
            ))
        );
        assert!(
            app.snapshot
                .players
                .iter()
                .all(|player| player.player_info_id != info_id),
            "an unavailable resource cannot create a player"
        );
        assert_ne!(
            app.engine
                .player(local_owner)
                .expect("local player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_RIGHT),
            0,
            "the later control still executes"
        );
        assert_eq!(app.engine.frame(), initial_frame + 1);
    }

    #[test]
    fn complete_resource_join_uses_registry_path() {
        // Rust resolves resource-backed execution by resource ID, including on
        // the authoring host when issuance preceded resource completion. Use
        // the registry path, not packet Filename or the core filename
        // (src/C4Control.cpp:758-764; src/C4Network2Res.cpp:1388-1412).
        let mut app = new_synthetic_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let info_id = 18;
        let resource_id = 62;
        let resolved_path = PathBuf::from(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../lc-engine/tests/fixtures/embedded_player.c4p"
        ));
        app.admission_resources.resources.insert(
            resource_id,
            AdmissionResourceState::Complete {
                path: resolved_path,
                removed: false,
                local: true,
            },
        );
        let resource = lc_engine::NetworkResourceCore {
            resource_type: 3,
            id: resource_id,
            loadable: true,
            filename: lc_engine::LegacyCString::from_bytes(b"WrongCorePath.c4p".to_vec())
                .expect("valid resource filename"),
            ..Default::default()
        };
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: 1,
                        players: vec![lc_engine::ControlPlayerInfoEntry {
                            name: lc_engine::LegacyCString::from_bytes(b"Resource Tyler".to_vec())
                                .expect("valid player name"),
                            id: info_id,
                            ..Default::default()
                        }],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(lc_engine::JoinPlayerControlData {
                        filename: lc_engine::LegacyCString::from_bytes(
                            b"WrongPacketPath.c4p".to_vec(),
                        )
                        .expect("valid packet filename"),
                        at_client: 0,
                        info_id,
                        source: lc_engine::JoinPlayerSource::Resource(resource),
                        by_client: 0,
                    }),
                ],
            })
            .expect("queue complete resource join");

        app.update().expect("execute complete resource tick");

        let joined = app
            .snapshot
            .players
            .iter()
            .find(|player| player.player_info_id == info_id)
            .expect("completed resource player joined");
        assert_eq!(joined.name, "Resource Tyler");
        assert_eq!((joined.score, joined.total_playing_time), (42, 99));
    }

    #[test]
    fn network_tick_waits_for_exact_ready_batch_and_ignores_duplicate() {
        // C4Game::Execute returns before simulation when control preparation
        // is not ready (src/C4Game.cpp:786-787), then executes the retrieved
        // control before game ticks (src/C4Game.cpp:797-805).
        let mut app = new_running_sandbox_app();
        let remote_owner = app.local_owner + 1;
        app.engine
            .register_player(PlayerConfig::new(remote_owner, "Remote"))
            .expect("register remote player");
        app.engine
            .player_mut(app.local_owner)
            .expect("local player")
            .control
            .control_style = true;
        app.engine
            .player_mut(remote_owner)
            .expect("remote player")
            .control
            .control_style = true;
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);

        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        app.dispatch_control_event(ControlEvent::Press(ControlButton::Right))
            .expect("submit local input");
        assert_eq!(
            app.engine
                .player(app.local_owner)
                .expect("local player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_RIGHT),
            0,
            "network input is submitted but not dispatched immediately"
        );

        app.update().expect("wait without ready batch");
        assert_eq!(
            app.engine.frame(),
            initial_frame,
            "simulation cannot advance before its exact ready tick"
        );

        let controls = vec![
            NetworkControl::Player {
                owner: app.local_owner,
                event: ControlEvent::Press(ControlButton::Right),
            },
            NetworkControl::Player {
                owner: remote_owner,
                event: ControlEvent::Press(ControlButton::Left),
            },
        ];
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: controls.clone(),
            })
            .expect("queue ready aggregate");
        app.update().expect("execute ready batch");
        assert_eq!(app.engine.frame(), initial_frame + 1);
        assert_ne!(
            app.engine
                .player(app.local_owner)
                .expect("local player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_RIGHT),
            0,
            "local aggregate control is applied"
        );
        assert_ne!(
            app.engine
                .player(remote_owner)
                .expect("remote player")
                .control
                .pressed_coms
                & (1 << lc_engine::COM_LEFT),
            0,
            "remote aggregate control is applied"
        );
        let local_last_com = app
            .engine
            .player(app.local_owner)
            .expect("local player")
            .control
            .last_com;

        event_tx
            .send(NetworkEvent::ReadyTick { tick, controls })
            .expect("queue duplicate aggregate");
        app.update().expect("ignore duplicate ready batch");
        assert_eq!(
            app.engine.frame(),
            initial_frame + 1,
            "a stale duplicate cannot advance simulation twice"
        );
        assert_eq!(
            app.engine
                .player(app.local_owner)
                .expect("local player")
                .control
                .last_com,
            local_last_com,
            "a stale duplicate cannot dispatch its controls twice"
        );
    }

    #[test]
    fn network_update_uses_join_control_tick_and_cpp_control_rate() {
        // Network control starts at JoinData::iStartCtrlTick and gates only
        // frames divisible by Parameters.ControlRate. A missing aggregate
        // retries that same frame/tick; non-control frames simulate without a
        // control packet (pristine 9ffa0a5d src/C4GameControl.cpp:245-329;
        // src/C4GameControlNetwork.cpp:48-60).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.network_control_clock = Some(network::NetworkControlClock::new(9, 2));
        assert_eq!(app.engine.frame(), 0);

        event_tx
            .send(NetworkEvent::ReadyTick {
                tick: 9,
                controls: Vec::new(),
            })
            .expect("queue start control tick");
        app.update().expect("execute start control tick");
        assert_eq!(app.engine.frame(), 1);

        app.update().expect("simulate non-control frame");
        assert_eq!(app.engine.frame(), 2);

        app.update().expect("wait for next control tick");
        assert_eq!(app.engine.frame(), 2, "stalled control frame is retried");
        assert_eq!(
            app.network_control_clock.map(|clock| clock.current_tick()),
            Some(10)
        );

        event_tx
            .send(NetworkEvent::ReadyTick {
                tick: 10,
                controls: Vec::new(),
            })
            .expect("queue next control tick");
        app.update().expect("execute next control tick");
        assert_eq!(app.engine.frame(), 3);
    }

    #[test]
    fn network_presends_next_tick_on_the_frame_before_execution() {
        // With ControlRate 2 and the default one-frame PreSend, tick 10 is
        // transmitted on non-control frame 1 so a one-frame network trip can
        // return the complete packet before frame 2 executes it
        // (src/C4GameControl.cpp:253-258;
        // src/C4GameControlNetwork.cpp:145-176).
        let mut app = new_running_sandbox_app();
        let (manager, event_tx, mut commands) = NetworkManager::test_stub_with_commands();
        app.network = Some(manager);
        app.network_control_clock = Some(network::NetworkControlClock::new(9, 2));
        app.engine.initialize_network_control_timing(
            lc_engine::NetworkControlTiming::new(9, 2).expect("valid network timing"),
        );

        event_tx
            .send(NetworkEvent::ReadyTick {
                tick: 9,
                controls: Vec::new(),
            })
            .expect("queue initial ready tick");
        app.update().expect("execute initial control frame");
        assert_eq!(app.engine.frame(), 1);
        assert_eq!(commands.take_finalized_ticks(), vec![9]);

        app.update().expect("presend from the intervening frame");
        assert_eq!(app.engine.frame(), 2);
        assert_eq!(
            commands.take_finalized_ticks(),
            vec![10],
            "tick 10 must leave one frame before its execution frame"
        );

        // Deliver the echoed aggregate after that one-frame delay. Frame 2
        // must execute immediately rather than first submitting tick 10 and
        // stalling for another round trip.
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick: 10,
                controls: Vec::new(),
            })
            .expect("return the presend aggregate");
        app.update().expect("execute the already-ready tick");
        assert_eq!(app.engine.frame(), 3);
        assert_eq!(
            app.network_control_clock
                .map(network::NetworkControlClock::current_tick),
            Some(11)
        );
        assert!(commands.take_finalized_ticks().is_empty());
    }

    #[test]
    fn l052_ready_tick_local_join_opens_one_viewport_with_feedback() {
        // C4Control executes the complete list in packet order, so PlrInfo is
        // visible to the following JoinPlr; only then does C4Game advance the
        // simulation (src/C4Control.cpp:93-109; src/C4Game.cpp:797-805).
        let mut app = new_lightweight_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let initial_frame = app.engine.frame();
        let info = lc_engine::ControlPlayerInfoEntry {
            name: lc_engine::LegacyCString::from_bytes(b"Network Tyler".to_vec())
                .expect("valid legacy name"),
            id: 7,
            color: 0x0011_2233,
            ..Default::default()
        };
        let join = lc_engine::JoinPlayerControlData {
            filename: lc_engine::LegacyCString::from_bytes(
                b"/definitely/missing/RemotePlayer.c4p".to_vec(),
            )
            .expect("valid legacy filename"),
            at_client: 0,
            info_id: 7,
            source: lc_engine::JoinPlayerSource::Embedded(
                include_bytes!("../../lc-engine/tests/fixtures/embedded_player.c4p").to_vec(),
            ),
            by_client: 1,
        };
        app.set_runtime_flash_message("Join clears me", RuntimeHelpCharset::Windows1252)
            .expect("install pre-viewport flash");
        assert!(app.runtime_flash_message.is_some());
        app.ui_sound_log.clear();
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: 0,
                        players: vec![info],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(join),
                ],
            })
            .expect("queue admission controls");

        app.update().expect("execute admission tick");

        assert_eq!(app.engine.frame(), initial_frame + 1);
        let joined = app
            .snapshot
            .players
            .iter()
            .find(|player| player.player_info_id == 7)
            .expect("embedded player joined before the simulation tick");
        assert_eq!(joined.name, "Network Tyler");
        assert_eq!((joined.score, joined.total_playing_time), (42, 99));
        // AtClient, independently of the remote ByClient source selection,
        // makes this user player local (src/C4Player.cpp:1871-1877).
        assert!(
            app.snapshot.hud.local_players.contains(&joined.id),
            "a user player targeted at the local client is locally controlled"
        );
        assert!(
            app.runtime_flash_message.is_none(),
            "owned C4Viewport::Init clears the process-global flash"
        );
        assert_eq!(
            app.ui_sound_log
                .iter()
                .filter(|sound| sound.as_str() == "CloseViewport")
                .count(),
            1,
            "one successful local join creates one non-silent viewport"
        );
    }

    #[test]
    fn l052_synchronized_remote_join_has_no_local_viewport_feedback() {
        // C4ControlJoinPlayer passes iAtClient through C4Game::JoinPlayer and
        // C4PlayerList::Join; C4Player::Init then stores it in AtClient
        // (pristine 9ffa0a5d src/C4Control.cpp:710-764;
        // src/C4Game.cpp:3505-3514; src/C4PlayerList.cpp:271-317;
        // src/C4Player.cpp:246-265).
        let mut app = new_lightweight_running_sandbox_app();
        let (manager, event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let tick = u32::try_from(app.engine.frame()).expect("test tick fits u32");
        let info_id = 73;
        let at_client = 3;
        app.ui_sound_log.clear();
        app.control_clients.replace_snapshot([
            lc_engine::ClientCoreControlData {
                client_id: 0,
                name: lc_engine::LegacyCString::from_bytes(b"Host Client".to_vec())
                    .expect("valid host client name"),
                ..Default::default()
            },
            lc_engine::ClientCoreControlData {
                client_id: at_client,
                name: lc_engine::LegacyCString::from_bytes(b"Remote Andr\xe9".to_vec())
                    .expect("valid remote client name"),
                ..Default::default()
            },
        ]);
        event_tx
            .send(NetworkEvent::ReadyTick {
                tick,
                controls: vec![
                    NetworkControl::PlayerInfo(lc_engine::PlayerInfoControlData {
                        client_id: at_client,
                        players: vec![lc_engine::ControlPlayerInfoEntry {
                            name: lc_engine::LegacyCString::from_bytes(b"Remote Ren\xe9".to_vec())
                                .expect("valid legacy name"),
                            id: info_id,
                            ..Default::default()
                        }],
                        by_client: 1,
                        ..Default::default()
                    }),
                    NetworkControl::JoinPlayer(lc_engine::JoinPlayerControlData {
                        filename: lc_engine::LegacyCString::from_bytes(
                            b"RemotePlayer.c4p".to_vec(),
                        )
                        .expect("valid legacy filename"),
                        at_client,
                        info_id,
                        source: lc_engine::JoinPlayerSource::Embedded(
                            include_bytes!("../../lc-engine/tests/fixtures/embedded_player.c4p")
                                .to_vec(),
                        ),
                        by_client: 1,
                    }),
                ],
            })
            .expect("queue remote admission controls");

        app.update().expect("execute remote admission tick");

        let joined = app
            .snapshot
            .players
            .iter()
            .find(|player| player.player_info_id == info_id)
            .expect("remote player joined");
        assert_eq!(
            app.engine
                .player(joined.id)
                .expect("runtime remote player")
                .at_client(),
            lc_engine::PlayerAtClient::new(at_client)
        );
        let player = app.engine.player(joined.id).expect("runtime remote player");
        assert_eq!(
            lc_script::c4_string_bytes(player.at_client_name()),
            b"Remote Andr\xe9"
        );
        assert_eq!(lc_script::c4_string_bytes(player.name()), b"Remote Ren\xe9");
        assert!(
            app.ui_sound_log
                .iter()
                .all(|sound| sound != "CloseViewport"),
            "a remote player never creates a viewport on this process"
        );
    }

    #[test]
    fn synchronized_join_for_a_missing_client_is_ignored() {
        // C4ControlJoinPlayer resolves AtClient before joining and returns
        // immediately when that client has already disappeared
        // (C4Control.cpp:714-716).
        let mut app = new_state_only_running_sandbox_app();
        let (manager, _event_tx) = NetworkManager::test_stub();
        app.network = Some(manager);
        app.engine.set_network_game(true);
        let info_id = 74;
        app.control_player_infos
            .apply(lc_engine::PlayerInfoControlData {
                client_id: 9,
                players: vec![lc_engine::ControlPlayerInfoEntry {
                    name: lc_engine::LegacyCString::from_bytes(b"Gone Owner".to_vec())
                        .expect("valid player name"),
                    id: info_id,
                    ..Default::default()
                }],
                by_client: 1,
                ..Default::default()
            });

        app.apply_join_player_control(lc_engine::JoinPlayerControlData {
            filename: lc_engine::LegacyCString::from_bytes(b"RemotePlayer.c4p".to_vec())
                .expect("valid legacy filename"),
            at_client: 9,
            info_id,
            source: lc_engine::JoinPlayerSource::Embedded(
                include_bytes!("../../lc-engine/tests/fixtures/embedded_player.c4p").to_vec(),
            ),
            by_client: 1,
        })
        .expect("missing-client join is ignored");

        assert!(
            app.engine
                .players()
                .all(|player| player.player_info_id() != info_id)
        );
    }

