    #[test]
    fn stale_menu_game_over_fails_typed_on_all_startup_roots_before_lower_boundaries() {
        let mut app = new_real_classic_menu_app(640, 480);

        // Retain three recursive child states so their own typed boundaries
        // are also known to be lower priority than the invalid lifecycle.
        for child in [
            RetainedStartupChild::Unported(ClassicStartupSubscreen::Options(
                lc_frontend::startup_options_dlg::OptionsSheet::Graphics,
            )),
            RetainedStartupChild::AboutLicenses,
        ] {
            enter_retained_startup_child(&mut app, child);
            app.show_main_menu();
        }
        app.open_network_game_dialog();
        activate_startup_network_chat(&mut app);
        app.show_main_menu();
        app.open_player_selection_dialog();
        app.show_main_menu();
        assert_eq!(
            app.startup_options_dialog
                .as_ref()
                .expect("retained Options model")
                .active_sheet(),
            lc_frontend::startup_options_dlg::OptionsSheet::Graphics
        );
        assert_eq!(
            app.startup_about_dialog
                .as_ref()
                .expect("retained About model")
                .current_page(),
            lc_frontend::startup_about_dlg::AboutPage::Licenses
        );
        assert_eq!(
            app.startup_network_dialog
                .as_ref()
                .expect("retained Network model")
                .mode(),
            lc_frontend::startup_netdlg::NetDlgMode::Chat
        );
        assert!(app.startup_player_dialog.is_some());
        app.handle_game_over()
            .expect("forge stale menu evaluation state");
        app.assets
            .require_classic_game_over_resources()
            .expect("fixture has the complete running evaluation bundle");

        for (index, view) in StartupView::ALL.into_iter().enumerate() {
            // Exhaustive arms force future startup roots into this lifecycle
            // invariant instead of silently omitting the evaluation dialog.
            match view {
                StartupView::MainMenu => app.startup_view = StartupView::MainMenu,
                StartupView::ScenarioBrowser => {
                    app.startup_view = StartupView::ScenarioBrowser;
                }
                StartupView::NetworkLobby => {
                    app.startup_view = StartupView::NetworkLobby;
                    app.classic_host_lobby = None;
                }
                StartupView::NetworkGame => app.startup_view = StartupView::NetworkGame,
                StartupView::Options => app.startup_view = StartupView::Options,
                StartupView::About => app.startup_view = StartupView::About,
                StartupView::PlayerSelection => {
                    app.startup_view = StartupView::PlayerSelection;
                }
            }
            app.status_text = format!("lower-priority status for {view:?}");
            let cached = vec![0x20 + index as u8; 640 * 480 * 4];
            app.menu_frame_cache = Some(MenuFrameCache {
                view,
                version: app.menu_render_version,
                width: 640,
                height: 480,
                native_text_deferred: false,
                frame: cached.clone(),
            });

            let mut frame = vec![0xc3; 640 * 480 * 4];
            let error = app
                .render(&mut frame)
                .expect_err("stale evaluation must precede startup cache or pixels");
            assert_startup_game_over_boundary(&error, view);
            assert!(frame.iter().all(|byte| *byte == 0xc3));
            assert_eq!(
                app.menu_frame_cache.as_ref().expect("cache retained").frame,
                cached
            );

            let mut native = vec![0x6d; 1280 * 960 * 4];
            let error = app
                .render_native_main_menu_text(&mut native, 1280, 960)
                .expect_err("native pass must enforce the same lifecycle boundary");
            assert_startup_game_over_boundary(&error, view);
            assert!(native.iter().all(|byte| *byte == 0x6d));
        }
    }

    #[test]
    fn stale_menu_game_over_lifecycle_boundary_precedes_missing_resources() {
        let mut app = new_real_classic_menu_app(320, 200);
        let mut cached = vec![0_u8; 320 * 200 * 4];
        app.render(&mut cached)
            .expect("populate startup frame cache");
        assert!(app.menu_frame_cache.is_some());
        app.handle_game_over().expect("show stale game-over dialog");
        app.status_text.clear();
        app.assets = Arc::new(FrontendAssets::load(None));
        let mut frame = vec![0xc3; 320 * 200 * 4];
        let sentinel = frame.clone();

        let error = app
            .render(&mut frame)
            .expect_err("invalid lifecycle must win without resource lookup");
        assert_startup_game_over_boundary(&error, StartupView::MainMenu);
        assert_eq!(
            frame, sentinel,
            "startup preflight must precede every pixel"
        );
        assert_eq!(
            app.menu_frame_cache.as_ref().expect("cache retained").frame,
            cached
        );

        let mut native = vec![0x47; 640 * 400 * 4];
        let error = app
            .render_native_main_menu_text(&mut native, 640, 400)
            .expect_err("native pass must reject stale evaluation before resources");
        assert_startup_game_over_boundary(&error, StartupView::MainMenu);
        assert!(native.iter().all(|byte| *byte == 0x47));
    }

    #[derive(Debug, PartialEq, Eq)]
    struct RuntimeGlobalUiSnapshot {
        menu_render_version: u64,
        mode: AppMode,
        startup_view: StartupView,
        exit_requested: bool,
        status_text: String,
        message_dialogs: Vec<(String, String)>,
        game_over_open: bool,
        game_over_hovered_action: Option<GameOverAction>,
        game_over_focus: Option<GameOverFocus>,
        ingame_page: Option<ingame_menu::MenuPage>,
        object_menu_open: bool,
        engine_menu_style: Option<i32>,
        context_menu_open: bool,
        definition_selector_open: bool,
        game_option_input_open: bool,
        save_browser_open: bool,
        game_over_handled: bool,
        runtime_help_visible: bool,
        runtime_flash_message: Option<RuntimeFlashMessage>,
        runtime_client_list_open: bool,
        scoreboard_dialog: Option<ScoreboardPresentationRequest>,
        scoreboard: lc_engine::ScoreboardState,
        scoreboard_initial_reconcile_pending: bool,
        scoreboard_close_pointer_capture: bool,
        pressed_engine_keys: HashSet<VirtualKeyCode>,
        message_dialog_consumed_keys: HashSet<VirtualKeyCode>,
    }

    fn runtime_global_ui_snapshot(app: &GameApp) -> RuntimeGlobalUiSnapshot {
        RuntimeGlobalUiSnapshot {
            menu_render_version: app.menu_render_version,
            mode: app.mode,
            startup_view: app.startup_view,
            exit_requested: app.exit_requested,
            status_text: app.status_text.clone(),
            message_dialogs: app
                .message_dialogs
                .iter()
                .map(|dialog| {
                    (
                        dialog.state.caption().to_string(),
                        dialog.state.message().to_string(),
                    )
                })
                .collect(),
            game_over_open: app.game_over_dialog.is_some(),
            game_over_hovered_action: app
                .game_over_dialog
                .as_ref()
                .and_then(GameOverState::hovered_action),
            game_over_focus: app
                .game_over_dialog
                .as_ref()
                .and_then(GameOverState::focused),
            ingame_page: app.ingame_menu.as_ref().map(IngameMenuState::page),
            object_menu_open: app.object_menu.is_some(),
            engine_menu_style: app
                .engine
                .cursor_object_menu(app.local_owner)
                .map(|(_, menu)| menu.style),
            context_menu_open: app.context_menu.is_some(),
            definition_selector_open: app.definition_selector.is_some(),
            game_option_input_open: app.game_option_input_dialog.is_some(),
            save_browser_open: app.save_browser.is_some(),
            game_over_handled: app.game_over_handled,
            runtime_help_visible: app.runtime_help_visible,
            runtime_flash_message: app.runtime_flash_message.clone(),
            runtime_client_list_open: app.runtime_client_list.is_some(),
            scoreboard_dialog: app.scoreboard_dialog.clone(),
            scoreboard: app.snapshot.hud.scoreboard.clone(),
            scoreboard_initial_reconcile_pending: app.scoreboard_initial_reconcile_pending,
            scoreboard_close_pointer_capture: app.scoreboard_close_pointer_capture,
            pressed_engine_keys: app.pressed_engine_keys.clone(),
            message_dialog_consumed_keys: app.message_dialog_consumed_keys.clone(),
        }
    }

    fn expect_runtime_global_boundary_unchanged(
        app: &mut GameApp,
        key: VirtualKeyCode,
        expected: ClassicParityBoundary,
    ) {
        let before = runtime_global_ui_snapshot(app);
        let expected = expected.to_string();
        let error = app
            .handle_key(key, ElementState::Pressed)
            .expect_err("unported runtime-global route must fail typed");
        let detail = match error {
            EngineError::ClassicMenuParityBoundary { detail } => detail,
            other => panic!("runtime-global route returned the wrong error: {other}"),
        };
        assert_eq!(detail, expected);
        assert_eq!(
            runtime_global_ui_snapshot(app),
            before,
            "runtime-global boundary must precede all app/UI mutation"
        );
    }

    fn new_scoreboard_test_app(script: &str) -> GameApp {
        configure_scoreboard_test_app(new_running_sandbox_app(), script)
    }

    fn new_classic_scoreboard_test_app(script: &str) -> GameApp {
        configure_scoreboard_test_app(new_classic_running_sandbox_app(), script)
    }

    fn configure_scoreboard_test_app(mut app: GameApp, script: &str) -> GameApp {
        app.reconcile_initial_scoreboard();
        app.status_text.clear();
        app.snapshot.hud.messages.clear();
        if !script.is_empty() {
            app.engine
                .install_scenario_script_with_convention("ScoreboardBoundary", script, true)
                .expect("install scoreboard fixture script");
            app.snapshot = app.engine.snapshot();
            app.snapshot.hud.messages.clear();
        }
        app
    }

    fn toggle_scoreboard(app: &mut GameApp, modifiers: ModifiersState) {
        app.handle_modifiers_changed(modifiers)
            .expect("set keyboard modifiers");
        app.handle_key(VirtualKeyCode::Tab, ElementState::Pressed)
            .expect("toggle the classic scoreboard");
        app.handle_key(VirtualKeyCode::Tab, ElementState::Released)
            .expect("release the scoreboard key");
    }

    fn route_primary_gamepad_to_local_owner(app: &mut GameApp) {
        let mut config = Config::new();
        config.set_in(
            Some("Gamepad0"),
            "Button9",
            input::legacy_gamepad_axis_key(0, 0, true)
                .expect("primary right-axis key")
                .to_string(),
        );
        app.gamepad_bindings = GamepadBindings::from_config(&config);
        app.local_controls.remove(app.local_owner);
        app.local_controls.initialize(LocalControlInit {
            owner: app.local_owner,
            preferred_set: GamepadSlot::new(0).control_set(),
            prefers_mouse: false,
            gamepads_enabled: true,
            replay: false,
            disable_mouse: false,
        });
    }

