        paths.ensure_user_dirs().expect("create fixture user dirs");
        app.app_paths = Some(paths);
        app.configure_running_state("First game".to_string(), DEFAULT_GROUND_HEIGHT);

        let extra = install.path().join("planet/Extra.c4g");
